-- Formulas
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_4211ece0122b59', 'subj_math', 'percent-change', 'Percent change', '\text{percent change} = \frac{\text{new} - \text{original}}{\text{original}} \times 100\%', 'Relative change from an original value. A positive result is an increase and a negative result is a decrease. The original value must not be zero.', '[{"symbol":"\\text{original}","meaning":"starting value"},{"symbol":"\\text{new}","meaning":"ending value"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_588b11083b4d2f', 'subj_math', 'triangle-area', 'Area of a triangle', 'A = \tfrac{1}{2}bh', 'Area of any triangle, where the height h is measured perpendicular to the chosen base b.', '[{"symbol":"b","meaning":"base"},{"symbol":"h","meaning":"height perpendicular to the base"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_3fc622e834421b', 'subj_math', 'trapezoid-area', 'Area of a trapezoid', 'A = \tfrac{1}{2}(b_1 + b_2)h', 'Area of a trapezoid with parallel bases b₁ and b₂ and perpendicular height h between them.', '[{"symbol":"b_1, b_2","meaning":"parallel bases"},{"symbol":"h","meaning":"distance between the bases"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_13a8ca4baa345c', 'subj_math', 'circle-area', 'Area and circumference of a circle', 'A = \pi r^2, \quad C = 2\pi r = \pi d', 'Area and circumference of a circle with radius r (diameter d = 2r).', '[{"symbol":"r","meaning":"radius"},{"symbol":"d","meaning":"diameter"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_6008a925364fcf', 'subj_math', 'prism-cylinder-volume', 'Volume of a prism or cylinder', 'V = Bh, \quad V_{\text{cylinder}} = \pi r^2 h', 'Volume of a right or oblique prism or cylinder: base area B times the perpendicular height h.', '[{"symbol":"B","meaning":"area of the base"},{"symbol":"h","meaning":"height perpendicular to the base"},{"symbol":"r","meaning":"radius of a cylinder''s base"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_5f00f7a0a9f5e5', 'subj_math', 'mean', 'Mean (average)', '\bar{x} = \frac{x_1 + x_2 + \cdots + x_n}{n} = \frac{\sum x_i}{n}', 'The arithmetic mean of n data values: their sum divided by how many there are.', '[{"symbol":"x_i","meaning":"data values"},{"symbol":"n","meaning":"number of values"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_a12c6f30803d0d', 'subj_math', 'standard-form-line', 'Standard form of a line', 'Ax + By = C', 'Equation of any line, with A and B not both zero. Usually A, B and C are integers with A ≥ 0. The slope is −A/B when B ≠ 0.', '[{"symbol":"A, B, C","meaning":"constants"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_d232490dc6d96f', 'subj_math', 'arithmetic-sequence', 'Arithmetic sequence', 'a_n = a_1 + (n - 1)d', 'The nth term of a sequence that adds the same common difference d each step.', '[{"symbol":"a_1","meaning":"first term"},{"symbol":"d","meaning":"common difference"},{"symbol":"n","meaning":"term number (1, 2, 3, …)"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_6217fd1f6ef799', 'subj_math', 'geometric-sequence', 'Geometric sequence', 'a_n = a_1 \cdot r^{\,n-1}', 'The nth term of a sequence that multiplies by the same common ratio r each step (r ≠ 0).', '[{"symbol":"a_1","meaning":"first term"},{"symbol":"r","meaning":"common ratio"},{"symbol":"n","meaning":"term number"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_79fd3b64a574fc', 'subj_math', 'exponential-function', 'Exponential function', 'y = a \cdot b^x, \quad b = 1 + r \text{ (growth) or } 1 - r \text{ (decay)}', 'Exponential model with initial value a and growth factor b > 0, b ≠ 1. r is the percent rate per unit of x, written as a decimal.', '[{"symbol":"a","meaning":"initial value (y when x = 0)"},{"symbol":"b","meaning":"growth or decay factor"},{"symbol":"r","meaning":"rate per step, as a decimal"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_1f00e6e426f079', 'subj_math', 'exponent-rules', 'Properties of exponents', 'a^m a^n = a^{m+n}, \; \frac{a^m}{a^n} = a^{m-n}, \; (a^m)^n = a^{mn}, \; a^0 = 1, \; a^{-n} = \frac{1}{a^n}', 'Rules for integer exponents, valid for a ≠ 0 (and for rational exponents when a > 0).', '[{"symbol":"a","meaning":"nonzero base"},{"symbol":"m, n","meaning":"exponents"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_eb1b014f707879', 'subj_math', 'special-products', 'Special products', '(a + b)^2 = a^2 + 2ab + b^2, \; (a - b)^2 = a^2 - 2ab + b^2, \; (a + b)(a - b) = a^2 - b^2', 'Perfect-square trinomials and the difference of two squares. Read right to left, they are factoring patterns.', '[{"symbol":"a, b","meaning":"any expressions"}]', 'published');

-- Lesson: absolute-value-equations-inequalities
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_48ad36205a2565', 'absolute-value-equations-inequalities', 'Absolute value equations and inequalities', 'Solve |ax + b| = c and |ax + b| < c or > c by reading absolute value as distance, and handle cases with no solution.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5c4ac29d0c95a9', 'les_48ad36205a2565', 1, 'Interpret |x − a| as the distance between x and a on the number line.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_41b01e27aa9c9b', 'les_48ad36205a2565', 2, 'Solve absolute value equations by splitting into two linear equations, and check for extraneous cases.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a4a125ae93410c', 'les_48ad36205a2565', 3, 'Solve absolute value inequalities as ''and'' (less than) or ''or'' (greater than) compound inequalities.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5c4ac29d0c95a9', 'les_48ad36205a2565', 'learn', 1, 'text', '{"body":"$|x|$ is the distance from $x$ to 0, and more generally $|x - a|$ is the distance between $x$ and $a$. So $|x - 3| = 5$ asks, \"Which numbers are 5 units from 3?\" There are two: 8 and $-2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_41b01e27aa9c9b', 'les_48ad36205a2565', 'learn', 2, 'definition', '{"term":"Absolute value equation","body":"For $c \\ge 0$, $|A| = c$ means $A = c$ or $A = -c$. For $c < 0$, $|A| = c$ has no solution, because a distance can''t be negative."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a4a125ae93410c', 'les_48ad36205a2565', 'learn', 3, 'worked_example', '{"title":"Solve $|2x - 5| = 9$","steps":[{"latex":"2x - 5 = 9 \\quad \\text{or} \\quad 2x - 5 = -9","explanation":"The quantity inside is 9 units from 0."},{"latex":"2x = 14 \\quad \\text{or} \\quad 2x = -4","explanation":""},{"latex":"x = 7 \\quad \\text{or} \\quad x = -2","explanation":""}],"check":"Check: $|14 - 5| = 9$ ✓ and $|-4 - 5| = 9$ ✓."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f85773397dd465', 'les_48ad36205a2565', 'learn', 4, 'worked_example', '{"title":"Solve $3|x + 1| - 4 = 11$","steps":[{"latex":"3|x + 1| = 15 \\Rightarrow |x + 1| = 5","explanation":"Isolate the absolute value first."},{"latex":"x + 1 = 5 \\quad \\text{or} \\quad x + 1 = -5","explanation":""},{"latex":"x = 4 \\quad \\text{or} \\quad x = -6","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1e6f99ef6de17a', 'les_48ad36205a2565', 'learn', 5, 'callout', '{"tone":"warning","title":"Isolate before splitting","body":"In $3|x + 1| - 4 = 11$, writing $3(x + 1) - 4 = \\pm 11$ is wrong. Get the absolute value alone first. And if it equals a negative number, as in $|x + 1| = -2$, stop: there''s no solution."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_43e85882833cea', 'les_48ad36205a2565', 'learn', 6, 'definition', '{"term":"Absolute value inequalities","body":"For $c > 0$: $|A| < c$ means $-c < A < c$ (within $c$ of 0: an \"and\"). $|A| > c$ means $A < -c$ or $A > c$ (farther than $c$ from 0: an \"or\"). The same holds with $\\le$ and $\\ge$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_79a961f8b9ef16', 'les_48ad36205a2565', 'learn', 7, 'worked_example', '{"title":"Solve $|x - 4| \\le 3$","steps":[{"latex":"-3 \\le x - 4 \\le 3","explanation":"Within 3 units of 4."},{"latex":"1 \\le x \\le 7","explanation":"Add 4 to every part."}],"check":"The solution is the interval [1, 7], centered at 4 with radius 3."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_850865a94b7e8d', 'les_48ad36205a2565', 'experiment', 8, 'activity', '{"activity":"inequality-line","title":"Graph |x − 4| ≤ 3 as an ''and''","params":{"rel":"≥","c":1,"mode":"and","rel2":"≤","c2":7}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5e746e615e6897', 'les_48ad36205a2565', 'learn', 9, 'worked_example', '{"title":"Solve $|2x + 1| > 7$","steps":[{"latex":"2x + 1 < -7 \\quad \\text{or} \\quad 2x + 1 > 7","explanation":"Farther than 7 from 0."},{"latex":"x < -4 \\quad \\text{or} \\quad x > 3","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_05dd79c0abb097', 'les_48ad36205a2565', 'experiment', 10, 'callout', '{"tone":"tip","title":"Try this","body":"Change the simulation to show $|2x + 1| > 7$: use \"Or\" with $x < -4$ and $x > 3$. Then test $x = 0$ in $|2x + 1|$ by hand: is it more than 7?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_694b726f039961', 'les_48ad36205a2565', 'learn', 11, 'callout', '{"tone":"note","title":"Special cases","body":"$|A| < -2$ has no solution. $|A| > -2$ is true for every real number, because an absolute value is always at least 0."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_553c1ad0bc7c4d', 'les_48ad36205a2565', 'learn', 12, 'callout', '{"tone":"application","title":"Where this shows up","body":"Manufacturing tolerance: a bolt must be 25 mm long within 0.2 mm, so $|L - 25| \\le 0.2$, which means $24.8 \\le L \\le 25.2$. Polls report a margin of error in the same form."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5c4ac29d0c95a9', 'les_48ad36205a2565', 1, 'practice', 'short_text', 1, 'Solve $|x| = 6$. Enter both solutions separated by a comma, smaller first.', '{"accept":["-6,6"]}', '["Which numbers are 6 units from 0?"]', '$x = -6$ or $x = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_41b01e27aa9c9b', 'les_48ad36205a2565', 2, 'practice', 'short_text', 2, 'Solve $|x + 2| = 5$. Enter both solutions, smaller first.', '{"accept":["-7,3"]}', '["$x + 2 = 5$ or $x + 2 = -5$."]', '$x = 3$ or $x = -7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a4a125ae93410c', 'les_48ad36205a2565', 3, 'practice', 'short_text', 2, 'Solve $2|x - 1| + 3 = 13$. Enter both solutions, smaller first.', '{"accept":["-4,6"]}', '["Isolate: $|x - 1| = 5$."]', '$x - 1 = \pm 5$, so $x = 6$ or $x = -4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f85773397dd465', 'les_48ad36205a2565', 4, 'practice', 'multiple_choice', 2, 'How many solutions does $|3x - 7| + 5 = 2$ have?', '{"choices":["0","1","2","Infinitely many"],"answer":0}', '["Isolate the absolute value."]', '$|3x - 7| = -3$ is impossible because absolute values are never negative. No solution.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1e6f99ef6de17a', 'les_48ad36205a2565', 5, 'practice', 'short_text', 2, 'Solve $|x - 5| < 2$. Write it like a<x<b.', '{"accept":["3<x<7"]}', '["Within 2 units of 5."]', '$-2 < x - 5 < 2$, so $3 < x < 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_43e85882833cea', 'les_48ad36205a2565', 6, 'practice', 'multiple_choice', 2, 'Solve $|x + 3| \ge 4$.', '{"choices":["$-7 \\le x \\le 1$","$x \\le -7$ or $x \\ge 1$","$x \\le -1$ or $x \\ge 7$","$x \\ge 1$"],"answer":1}', '["Greater than means ''or''."]', '$x + 3 \le -4$ or $x + 3 \ge 4$, so $x \le -7$ or $x \ge 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_79a961f8b9ef16', 'les_48ad36205a2565', 7, 'review', 'multiple_choice', 3, 'Which inequality describes all numbers within 0.5 of 12?', '{"choices":["$|x - 0.5| \\le 12$","$|x - 12| \\le 0.5$","$|x + 12| \\le 0.5$","$|x - 12| \\ge 0.5$"],"answer":1}', '["$|x - a|$ is the distance from x to a."]', 'The distance from $x$ to 12 is at most 0.5: $|x - 12| \le 0.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_850865a94b7e8d', 'les_48ad36205a2565', 8, 'review', 'short_text', 3, 'Solve $|4 - 2x| \le 10$. Write it like a<=x<=b.', '{"accept":["-3<=x<=7","-3≤x≤7"]}', '["−10 ≤ 4 − 2x ≤ 10.","Subtract 4, divide by −2, reverse."]', '$-14 \le -2x \le 6$, so $7 \ge x \ge -3$: $-3 \le x \le 7$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a359f5dece460d', 'subj_math', 'absolute-value', 'Absolute value', 'The distance of a number from zero on the number line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_48ad36205a2565', (SELECT id FROM concepts WHERE slug = 'absolute-value'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a44aeab44fa3c6', 'subj_math', 'compound-inequalities', 'Compound inequalities', 'Two inequalities joined by ''and'' or ''or''.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_48ad36205a2565', (SELECT id FROM concepts WHERE slug = 'compound-inequalities'));

-- Lesson: adding-subtracting-integers
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d38adf721186cf', 'adding-subtracting-integers', 'Adding and subtracting integers', 'Add integers as moves on a number line, use rules for like and unlike signs, and subtract by adding the opposite.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0d014e9b6f042b', 'les_d38adf721186cf', 1, 'Model integer addition as movement on a number line.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bd982e116d46c0', 'les_d38adf721186cf', 2, 'Add integers with the same sign and with different signs using absolute values.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a226bc83ef80a3', 'les_d38adf721186cf', 3, 'Rewrite subtraction as addition of the opposite and evaluate integer expressions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d014e9b6f042b', 'les_d38adf721186cf', 'learn', 1, 'text', '{"body":"Think of every integer as a move on the number line: a positive number moves right and a negative number moves left. To find $3 + (-7)$, start at 3 and move 7 to the left. You land on $-4$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bd982e116d46c0', 'les_d38adf721186cf', 'watch', 2, 'activity', '{"activity":"number-line","title":"Walkthrough: three kinds of moves","steps":[{"title":"Same signs","body":"−3 + (−5): start at −3 and move 5 more to the left. Two moves in the same direction combine, so you land 8 units left of 0, at −8.","params":{"a":-3,"b":-5,"op":"add"}},{"title":"Different signs","body":"6 + (−9): start at 6 and move 9 left. The moves partly cancel. The larger move (9 left) wins by 3, so the result is −3.","params":{"a":6,"b":-9,"op":"add"}},{"title":"Subtracting a negative","body":"2 − (−5): subtracting means moving the opposite way from adding. Adding −5 would move left, so subtracting −5 moves right. The result is 2 + 5 = 7.","params":{"a":2,"b":-5,"op":"subtract"}}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a226bc83ef80a3', 'les_d38adf721186cf', 'learn', 3, 'definition', '{"term":"Adding with the same sign","body":"Add the absolute values and keep the common sign. $-4 + (-9) = -13$ and $4 + 9 = 13$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_101aeb3b8e2284', 'les_d38adf721186cf', 'learn', 4, 'definition', '{"term":"Adding with different signs","body":"Subtract the smaller absolute value from the larger and keep the sign of the number with the larger absolute value. $-12 + 5 = -7$ because $12 - 5 = 7$ and $-12$ has the larger absolute value."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6934f99b38e87c', 'les_d38adf721186cf', 'learn', 5, 'definition', '{"term":"Subtraction as adding the opposite","body":"For any numbers $a$ and $b$, $a - b = a + (-b)$. So $5 - 8 = 5 + (-8) = -3$ and $-6 - (-10) = -6 + 10 = 4$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_62b6613ddd7236', 'les_d38adf721186cf', 'learn', 6, 'text', '{"body":"A number plus its opposite is always 0: $7 + (-7) = 0$. This \"zero pair\" idea explains the different-signs rule. In $-12 + 5$, five of the negative units cancel the five positive ones, leaving seven negative units."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_edc395e9cec937', 'les_d38adf721186cf', 'learn', 7, 'worked_example', '{"title":"Evaluate $-8 - 3 + 15 - (-4)$","steps":[{"latex":"-8 + (-3) + 15 + 4","explanation":"Rewrite each subtraction as adding the opposite."},{"latex":"-11 + 15 + 4","explanation":"Same signs: −8 and −3 combine to −11."},{"latex":"4 + 4 = 8","explanation":"Different signs: 15 − 11 = 4, positive because 15 is larger. Then add 4."}],"check":"Group the positives (15 + 4 = 19) and the negatives (−8 − 3 = −11), then combine: 19 − 11 = 8. Same answer."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_62d22696236fe4', 'les_d38adf721186cf', 'learn', 8, 'worked_example', '{"title":"A submarine at $-120$ m rises 45 m and then dives 70 m. Where is it?","steps":[{"latex":"-120 + 45 + (-70)","explanation":"Rising is positive, diving is negative."},{"latex":"-75 + (-70)","explanation":"−120 + 45: different signs, 120 − 45 = 75, keep the negative sign."},{"latex":"-145","explanation":"Same signs: add 75 and 70 and keep the negative sign."}],"check":"The submarine ends deeper than it started, which makes sense because it dove more than it rose."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b45d5a4dce61b2', 'les_d38adf721186cf', 'learn', 9, 'callout', '{"tone":"warning","title":"Two signs in a row","body":"In $4 - (-6)$ the first sign is the operation and the second belongs to the number. Rewrite before you compute: $4 + 6 = 10$. Writing $4 - 6$ by mistake gives $-2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d295bcd63dfc7a', 'les_d38adf721186cf', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Banks track deposits as positive and withdrawals as negative. A balance of 35 dollars followed by a 60-dollar purchase is $35 + (-60) = -25$, an overdraft of 25 dollars."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8f9daecdbbed75', 'les_d38adf721186cf', 'experiment', 11, 'activity', '{"activity":"number-line","title":"Experiment with subtraction","params":{"a":-3,"b":-6,"op":"subtract"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7e262c4152539e', 'les_d38adf721186cf', 'experiment', 12, 'callout', '{"tone":"tip","title":"Try this","body":"Keep the start at $-3$. Compare subtracting 6 with adding $-6$, then subtracting $-6$ with adding 6. Which pairs give the same arrow?"}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d014e9b6f042b', 'les_d38adf721186cf', 1, 'practice', 'numeric', 1, 'Evaluate $-9 + (-6)$.', '{"answer":-15}', '["Same signs: add the absolute values and keep the sign."]', '$9 + 6 = 15$, and both are negative, so $-15$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bd982e116d46c0', 'les_d38adf721186cf', 2, 'practice', 'numeric', 1, 'Evaluate $-14 + 9$.', '{"answer":-5}', '["Different signs: subtract the absolute values.","Which number has the larger absolute value?"]', '$14 - 9 = 5$. $-14$ has the larger absolute value, so the sum is $-5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a226bc83ef80a3', 'les_d38adf721186cf', 3, 'practice', 'numeric', 1, 'Evaluate $7 - 12$.', '{"answer":-5}', '["Rewrite as $7 + (-12)$."]', '$7 + (-12) = -5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_101aeb3b8e2284', 'les_d38adf721186cf', 4, 'practice', 'numeric', 2, 'Evaluate $-5 - (-13)$.', '{"answer":8}', '["Subtracting a negative is adding a positive."]', '$-5 + 13 = 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6934f99b38e87c', 'les_d38adf721186cf', 5, 'practice', 'numeric', 2, 'Evaluate $-20 - 7 + 11$.', '{"answer":-16}', '["$-20 - 7 = -27$."]', '$-20 + (-7) = -27$, then $-27 + 11 = -16$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_62b6613ddd7236', 'les_d38adf721186cf', 6, 'practice', 'multiple_choice', 2, 'Which expression has the same value as $-4 - 9$?', '{"choices":["$-4 + 9$","$4 + 9$","$-4 + (-9)$","$4 - 9$"],"answer":2}', '["Subtraction means adding the opposite of the second number."]', '$-4 - 9 = -4 + (-9) = -13$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_edc395e9cec937', 'les_d38adf721186cf', 7, 'practice', 'numeric', 2, 'The temperature was $-6^\circ$C at midnight and dropped $8^\circ$ by 4 a.m. What was the temperature at 4 a.m.?', '{"answer":-14,"unit":"°C"}', '["A drop means adding a negative."]', '$-6 + (-8) = -14^\circ$C.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_62d22696236fe4', 'les_d38adf721186cf', 8, 'practice', 'numeric', 3, 'A hiker starts 35 m below the rim of a canyon ($-35$), climbs down 80 m, then climbs up 52 m. What is the hiker''s final position relative to the rim?', '{"answer":-63,"unit":"m"}', '["Down is negative, up is positive.","Compute $-35 + (-80) + 52$."]', '$-35 - 80 = -115$, then $-115 + 52 = -63$ m, 63 m below the rim.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b45d5a4dce61b2', 'les_d38adf721186cf', 9, 'review', 'short_text', 3, 'Find the missing number: $-7 - \square = 3$.', '{"accept":["-10"]}', '["Subtracting $\\square$ is adding $-\\square$. What do you add to $-7$ to get 3?"]', '$-7 + 10 = 3$, so $-\square = 10$ and $\square = -10$. Check: $-7 - (-10) = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d295bcd63dfc7a', 'les_d38adf721186cf', 10, 'review', 'numeric', 2, 'Evaluate $|-8 + 3| - |-8| + |3|$.', '{"answer":0}', '["$-8 + 3 = -5$, so the first term is 5."]', '$|-5| - 8 + 3 = 5 - 8 + 3 = 0$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_5c9bbd44ea86f6', 'subj_math', 'integer-addition', 'Integer addition and subtraction', 'Combining signed numbers; subtraction is adding the opposite.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d38adf721186cf', (SELECT id FROM concepts WHERE slug = 'integer-addition'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_e68e8f5eb269a0', 'subj_math', 'additive-inverse', 'Additive inverse', 'A number and its opposite add to zero: a + (−a) = 0.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d38adf721186cf', (SELECT id FROM concepts WHERE slug = 'additive-inverse'));

-- Lesson: adding-subtracting-polynomials
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e89e53d697a68f', 'adding-subtracting-polynomials', 'Adding and subtracting polynomials', 'Name polynomials by degree and number of terms, write them in standard form, and add and subtract them by combining like terms.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_974b103cb13b42', 'les_e89e53d697a68f', 1, 'Identify a polynomial, its terms, degree, leading coefficient and standard form.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b77285c2aba6a6', 'les_e89e53d697a68f', 2, 'Classify polynomials by degree and by number of terms.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d38c123c9cf13f', 'les_e89e53d697a68f', 3, 'Add and subtract polynomials, distributing the subtraction to every term.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_974b103cb13b42', 'les_e89e53d697a68f', 'learn', 1, 'definition', '{"term":"Polynomial","body":"A sum of monomials, terms like $ax^n$ where $a$ is a number and $n$ is a whole number (0, 1, 2, …). $4x^3 - 2x + 7$ is a polynomial; $\\frac{1}{x}$ and $\\sqrt{x}$ are not, because their exponents are negative or fractional."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b77285c2aba6a6', 'les_e89e53d697a68f', 'learn', 2, 'definition', '{"term":"Degree and standard form","body":"The degree of a term is its exponent (add the exponents if there are several variables). The degree of the polynomial is the highest term degree. Standard form lists terms from highest degree to lowest; the first coefficient is the leading coefficient."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d38c123c9cf13f', 'les_e89e53d697a68f', 'learn', 3, 'text', '{"body":"Polynomials are named by degree (constant 0, linear 1, quadratic 2, cubic 3, quartic 4) and by number of terms (monomial 1, binomial 2, trinomial 3). So $5x^2 - 3$ is a quadratic binomial, and $-x^3 + 2x^2 + x$ is a cubic trinomial with leading coefficient $-1$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_26b8e30d0940d3', 'les_e89e53d697a68f', 'learn', 4, 'worked_example', '{"title":"Add $(3x^2 - 5x + 4) + (-x^2 + 7x - 9)$","steps":[{"latex":"(3x^2 - x^2) + (-5x + 7x) + (4 - 9)","explanation":"Group like terms."},{"latex":"2x^2 + 2x - 5","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a620779a6e5f5d', 'les_e89e53d697a68f', 'learn', 5, 'worked_example', '{"title":"Subtract $(4a^3 - 2a + 6) - (a^3 + 3a^2 - 2a - 1)$","steps":[{"latex":"4a^3 - 2a + 6 - a^3 - 3a^2 + 2a + 1","explanation":"Distribute the minus sign to every term of the second polynomial."},{"latex":"3a^3 - 3a^2 + 0a + 7","explanation":"Combine like terms."},{"latex":"3a^3 - 3a^2 + 7","explanation":""}],"check":"Check with $a = 1$: original $(4 - 2 + 6) - (1 + 3 - 2 - 1) = 8 - 1 = 7$; result $3 - 3 + 7 = 7$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a3632401243e9c', 'les_e89e53d697a68f', 'learn', 6, 'callout', '{"tone":"warning","title":"Subtract every term","body":"The most common error is changing only the first sign: $(x^2 + 3x) - (x^2 - 5x)$ is $x^2 + 3x - x^2 + 5x = 8x$, not $-2x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_258227675780b8', 'les_e89e53d697a68f', 'learn', 7, 'callout', '{"tone":"tip","title":"Vertical format","body":"For long polynomials, line up like terms in columns, leaving gaps for missing powers. Then add each column, or change all the signs of the bottom row and add when subtracting."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_69273effe59173', 'les_e89e53d697a68f', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"A company''s profit is revenue minus cost. If revenue is $-2x^2 + 90x$ and cost is $15x + 300$, profit is $-2x^2 + 75x - 300$. Polynomial arithmetic is how such formulas are combined."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_974b103cb13b42', 'les_e89e53d697a68f', 1, 'practice', 'numeric', 1, 'What is the degree of $6x^4 - x^2 + 9$?', '{"answer":4}', '["The highest exponent."]', '4.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b77285c2aba6a6', 'les_e89e53d697a68f', 2, 'practice', 'multiple_choice', 1, 'Classify $-3x^2 + 8$.', '{"choices":["Linear binomial","Quadratic binomial","Quadratic trinomial","Cubic monomial"],"answer":1}', '["Degree 2, two terms."]', 'Degree 2 with two terms: a quadratic binomial.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d38c123c9cf13f', 'les_e89e53d697a68f', 3, 'practice', 'short_text', 2, 'Add $(2x^2 + 3x - 1) + (x^2 - 5x + 4)$.', '{"accept":["3x^2-2x+3"]}', '["Combine x², x and constant terms."]', '$3x^2 - 2x + 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_26b8e30d0940d3', 'les_e89e53d697a68f', 4, 'practice', 'short_text', 2, 'Subtract $(5y^2 - 2y + 3) - (2y^2 + 4y - 1)$.', '{"accept":["3y^2-6y+4"]}', '["Change every sign in the second polynomial."]', '$5y^2 - 2y + 3 - 2y^2 - 4y + 1 = 3y^2 - 6y + 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a620779a6e5f5d', 'les_e89e53d697a68f', 5, 'practice', 'short_text', 2, 'Write $7 - 2x^3 + x - 4x^2$ in standard form.', '{"accept":["-2x^3-4x^2+x+7"]}', '["Order from highest degree to lowest."]', '$-2x^3 - 4x^2 + x + 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a3632401243e9c', 'les_e89e53d697a68f', 6, 'review', 'short_text', 3, 'A triangle has sides $2x^2 + 1$, $x^2 - 3x$ and $4x + 5$. Write its perimeter in standard form.', '{"accept":["3x^2+x+6"]}', '["Add all three."]', '$3x^2 + x + 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_258227675780b8', 'les_e89e53d697a68f', 7, 'review', 'short_text', 3, 'What polynomial added to $x^2 - 4x + 2$ gives $3x^2 + x - 5$?', '{"accept":["2x^2+5x-7"]}', '["Subtract: (3x² + x − 5) − (x² − 4x + 2)."]', '$2x^2 + 5x - 7$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_4bafbcd5e3010f', 'subj_math', 'polynomials', 'Polynomials', 'Sums of terms of the form axⁿ with whole-number exponents.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e89e53d697a68f', (SELECT id FROM concepts WHERE slug = 'polynomials'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7927ef860f1bc4', 'subj_math', 'like-terms', 'Like terms', 'Terms with exactly the same variables raised to the same powers.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e89e53d697a68f', (SELECT id FROM concepts WHERE slug = 'like-terms'));

-- Lesson: area-2d-shapes
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_96dff1777dbec2', 'area-2d-shapes', 'Area of triangles, quadrilaterals and circles', 'Derive and use area formulas for parallelograms, triangles, trapezoids and circles, and find areas of composite figures.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_99f8745b4301c3', 'les_96dff1777dbec2', 1, 'Explain how the parallelogram, triangle and trapezoid formulas come from the rectangle formula.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_be34308e208ebe', 'les_96dff1777dbec2', 2, 'Find the area and circumference of a circle from its radius or diameter.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0f7ce81ef76474', 'les_96dff1777dbec2', 3, 'Find the area of composite figures by adding and subtracting simpler shapes.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_99f8745b4301c3', 'les_96dff1777dbec2', 'learn', 1, 'definition', '{"term":"Area","body":"The number of unit squares that cover a flat region, measured in square units such as cm² or ft²."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_be34308e208ebe', 'les_96dff1777dbec2', 'learn', 2, 'text', '{"body":"Every formula here starts from the rectangle, $A = bh$. Cut a triangle off one end of a parallelogram and slide it to the other end: you get a rectangle with the same base and height, so a parallelogram''s area is also $bh$. Two copies of any triangle fit together into a parallelogram, so a triangle''s area is $\\frac{1}{2}bh$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0f7ce81ef76474', 'les_96dff1777dbec2', 'learn', 3, 'text', '{"body":"Two copies of a trapezoid, one flipped, also form a parallelogram, with base $b_1 + b_2$. Halving gives $A = \\frac{1}{2}(b_1 + b_2)h$. That is the average of the bases times the height."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5f91eb4de61889', 'les_96dff1777dbec2', 'learn', 4, 'callout', '{"tone":"warning","title":"Height is perpendicular","body":"The height is the perpendicular distance between the base and the opposite side (or vertex), not the length of a slanted side. In obtuse triangles the height may fall outside the triangle."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_29ddda502f15f3', 'les_96dff1777dbec2', 'experiment', 5, 'activity', '{"activity":"area-volume","title":"Shapes and their formulas","params":{"shape":"triangle"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f78821065ad601', 'les_96dff1777dbec2', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"On the triangle, compare the area with the dashed rectangle''s area (the readout). The triangle is always exactly half. Switch to the trapezoid and set $b_2 = b_1$. Which shape does it become, and does the formula agree?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6ce903a2d95c8e', 'les_96dff1777dbec2', 'learn', 7, 'text', '{"body":"For a circle, the circumference is $C = 2\\pi r$ and the area is $A = \\pi r^2$, where $\\pi \\approx 3.14159$. If you slice a circle into many thin wedges and arrange them alternately, they form a shape close to a parallelogram with base $\\pi r$ (half the circumference) and height $r$, which gives area $\\pi r \\cdot r = \\pi r^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2ce6fa6db1453b', 'les_96dff1777dbec2', 'learn', 8, 'worked_example', '{"title":"A trapezoid has bases 9 cm and 15 cm and height 6 cm. Find its area.","steps":[{"latex":"A = \\tfrac{1}{2}(9 + 15)(6)","explanation":""},{"latex":"= \\tfrac{1}{2}(24)(6) = 72 \\text{ cm}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bc1a0642d6a299', 'les_96dff1777dbec2', 'learn', 9, 'worked_example', '{"title":"A circle has diameter 10 in. Find its area and circumference.","steps":[{"latex":"r = 5 \\text{ in}","explanation":"The radius is half the diameter."},{"latex":"A = \\pi(5)^2 = 25\\pi \\approx 78.54 \\text{ in}^2","explanation":"Square the radius, not the diameter."},{"latex":"C = \\pi d = 10\\pi \\approx 31.42 \\text{ in}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1115ae42db70dd', 'les_96dff1777dbec2', 'learn', 10, 'worked_example', '{"title":"A 10 m by 6 m rectangular lawn has a circular flower bed of radius 1.5 m cut out. Find the area of grass.","steps":[{"latex":"10 \\times 6 = 60 \\text{ m}^2","explanation":"Whole rectangle."},{"latex":"\\pi(1.5)^2 = 2.25\\pi \\approx 7.07 \\text{ m}^2","explanation":"Flower bed."},{"latex":"60 - 7.07 \\approx 52.93 \\text{ m}^2","explanation":"Subtract the hole."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a6c6d38117953a', 'les_96dff1777dbec2', 'learn', 11, 'callout', '{"tone":"application","title":"Where this shows up","body":"Buying carpet, paint, sod or tiles; calculating a pizza''s size (a 16-inch pizza has $64\\pi \\approx 201$ in², almost twice the 113 in² of a 12-inch one); and land surveying all depend on area."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_99f8745b4301c3', 'les_96dff1777dbec2', 1, 'practice', 'numeric', 1, 'Find the area of a triangle with base 12 ft and height 7 ft.', '{"answer":42,"unit":"ft²"}', '["$\\frac{1}{2}bh$."]', '$\frac{1}{2}(12)(7) = 42$ ft².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_be34308e208ebe', 'les_96dff1777dbec2', 2, 'practice', 'numeric', 1, 'Find the area of a parallelogram with base 8 m and height 5.5 m.', '{"answer":44,"unit":"m²"}', '["Base times height."]', '$8 \times 5.5 = 44$ m².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0f7ce81ef76474', 'les_96dff1777dbec2', 3, 'practice', 'numeric', 2, 'Find the area of a trapezoid with bases 4 in and 10 in and height 5 in.', '{"answer":35,"unit":"in²"}', '["Average of the bases times the height."]', '$\frac{1}{2}(14)(5) = 35$ in².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5f91eb4de61889', 'les_96dff1777dbec2', 4, 'practice', 'numeric', 2, 'Find the area of a circle with radius 3 cm. Round to the nearest hundredth.', '{"answer":28.27,"unit":"cm²","tolerance":0.01}', '["$A = \\pi r^2 = 9\\pi$."]', '$9\pi \approx 28.27$ cm².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_29ddda502f15f3', 'les_96dff1777dbec2', 5, 'practice', 'numeric', 2, 'A circular track has a diameter of 70 m. How far is one lap? Round to the nearest meter.', '{"answer":220,"unit":"m","tolerance":0.5}', '["$C = \\pi d$."]', '$70\pi \approx 219.9$, about 220 m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f78821065ad601', 'les_96dff1777dbec2', 6, 'practice', 'multiple_choice', 2, 'A triangle has sides 5, 5 and 8 and a height of 3 to the side of length 8. What is its area?', '{"choices":["12","20","24","15"],"answer":0}', '["Use the base that matches the given height."]', '$\frac{1}{2}(8)(3) = 12$ square units. The slanted sides of length 5 are not heights.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6ce903a2d95c8e', 'les_96dff1777dbec2', 7, 'review', 'numeric', 3, 'A window is a 4 ft by 3 ft rectangle topped by a semicircle with diameter 4 ft. Find its total area to the nearest hundredth.', '{"answer":18.28,"unit":"ft²","tolerance":0.01}', '["Rectangle: 12 ft².","Semicircle: $\\frac{1}{2}\\pi(2)^2 = 2\\pi$."]', '$12 + 2\pi \approx 12 + 6.28 = 18.28$ ft².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2ce6fa6db1453b', 'les_96dff1777dbec2', 8, 'review', 'numeric', 3, 'If the radius of a circle is doubled, by what factor does its area increase?', '{"answer":4}', '["Compare $\\pi(2r)^2$ with $\\pi r^2$."]', '$\pi(2r)^2 = 4\pi r^2$: four times the area.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_699e8ae92ca31d', 'subj_math', 'area', 'Area', 'The number of unit squares needed to cover a region.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_96dff1777dbec2', (SELECT id FROM concepts WHERE slug = 'area'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_96dff1777dbec2', (SELECT id FROM formulas WHERE slug = 'triangle-area'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_96dff1777dbec2', (SELECT id FROM formulas WHERE slug = 'trapezoid-area'), 2);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_96dff1777dbec2', (SELECT id FROM formulas WHERE slug = 'circle-area'), 3);

-- Lesson: arithmetic-sequences
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5662d0926d4780', 'arithmetic-sequences', 'Arithmetic sequences as functions', 'Recognize arithmetic sequences, write explicit and recursive rules, find any term, and connect sequences to linear functions with whole-number domains.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2a2ddb8c7252ac', 'les_5662d0926d4780', 1, 'Identify an arithmetic sequence and its common difference.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ec2663de66ed01', 'les_5662d0926d4780', 2, 'Write explicit and recursive rules and use them to find terms.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7bb12e58e1ea95', 'les_5662d0926d4780', 3, 'Explain an arithmetic sequence as a linear function whose domain is the positive integers.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2a2ddb8c7252ac', 'les_5662d0926d4780', 'learn', 1, 'definition', '{"term":"Arithmetic sequence","body":"A list of numbers in which each term after the first is found by adding the same number $d$, the common difference. Example: 5, 9, 13, 17, … has $d = 4$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ec2663de66ed01', 'les_5662d0926d4780', 'learn', 2, 'formula', '{"latex":"a_n = a_1 + (n - 1)d","title":"Explicit rule","note":"The nth term: start at $a_1$ and add $d$ a total of $n - 1$ times."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7bb12e58e1ea95', 'les_5662d0926d4780', 'learn', 3, 'definition', '{"term":"Recursive rule","body":"Gives the first term and how to get each term from the one before: $a_1 = 5$, $a_n = a_{n-1} + 4$. Good for describing the process; slow for finding the 100th term."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a15641506d4e88', 'les_5662d0926d4780', 'learn', 4, 'worked_example', '{"title":"Find the 40th term of 7, 4, 1, −2, …","steps":[{"latex":"d = 4 - 7 = -3","explanation":"Subtract any term from the next one."},{"latex":"a_{40} = 7 + (40 - 1)(-3)","explanation":"Use the explicit rule."},{"latex":"= 7 - 117 = -110","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_edb76e3a984afe', 'les_5662d0926d4780', 'learn', 5, 'worked_example', '{"title":"An arithmetic sequence has $a_3 = 14$ and $a_8 = 39$. Find the rule.","steps":[{"latex":"a_8 - a_3 = 5d = 25 \\Rightarrow d = 5","explanation":"Five steps take you from term 3 to term 8."},{"latex":"a_1 = a_3 - 2d = 14 - 10 = 4","explanation":"Step back two terms."},{"latex":"a_n = 4 + (n - 1)5 = 5n - 1","explanation":""}],"check":"Check: $a_8 = 40 - 1 = 39$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8cd870277e6d91', 'les_5662d0926d4780', 'learn', 6, 'text', '{"body":"Plot the points $(n, a_n)$ and they lie on a line with slope $d$. The rule $a_n = 5n - 1$ is the linear function $f(n) = 5n - 1$, restricted to the inputs $n = 1, 2, 3, \\dots$. That''s why the graph is a row of dots rather than a solid line."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3c0008da997de5', 'les_5662d0926d4780', 'experiment', 7, 'activity', '{"activity":"linear-graph","title":"A sequence on a line","params":{"m":2,"b":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_08ea5f9b126936', 'les_5662d0926d4780', 'experiment', 8, 'callout', '{"tone":"tip","title":"Try this","body":"The line $y = 2x + 1$ passes through the terms of 3, 5, 7, 9, … at $x = 1, 2, 3, 4$. Which slider is the common difference? What would $a_0$ be, and where is it on the graph?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_edfe483cf93a3c', 'les_5662d0926d4780', 'learn', 9, 'callout', '{"tone":"warning","title":"Off by one","body":"The 10th term is the first term plus 9 steps, not 10. That''s why the formula has $n - 1$. Many people write $a_n = a_1 + nd$ by mistake."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a83e3c07b9f9be', 'les_5662d0926d4780', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Stadium seating (each row has 2 more seats), a savings jar with a fixed weekly deposit, and a taxi meter''s charges all form arithmetic sequences."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2a2ddb8c7252ac', 'les_5662d0926d4780', 1, 'practice', 'numeric', 1, 'What is the common difference of 12, 9, 6, 3, …?', '{"answer":-3}', '["Subtract a term from the next one."]', '$9 - 12 = -3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ec2663de66ed01', 'les_5662d0926d4780', 2, 'practice', 'numeric', 1, 'Find the next term of 2.5, 4, 5.5, 7, …', '{"answer":8.5}', '["The common difference is 1.5."]', '$7 + 1.5 = 8.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7bb12e58e1ea95', 'les_5662d0926d4780', 3, 'practice', 'numeric', 2, 'Find $a_{25}$ for $a_n = 3 + (n - 1)6$.', '{"answer":147}', '["Substitute n = 25."]', '$3 + 24 \cdot 6 = 147$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a15641506d4e88', 'les_5662d0926d4780', 4, 'practice', 'short_text', 2, 'Write an explicit rule for 8, 13, 18, 23, … in the form a_n=…n+…', '{"accept":["a_n=5n+3","an=5n+3","a_n=3+5n"]}', '["$a_n = 8 + (n - 1)5$.","Simplify."]', '$a_n = 8 + 5n - 5 = 5n + 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_edb76e3a984afe', 'les_5662d0926d4780', 5, 'practice', 'multiple_choice', 2, 'Which sequence is arithmetic?', '{"choices":["1, 2, 4, 8, …","3, 6, 9, 15, …","−4, −1, 2, 5, …","1, 4, 9, 16, …"],"answer":2}', '["Check that the differences are all equal."]', '$-4, -1, 2, 5$ has a constant difference of 3.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8cd870277e6d91', 'les_5662d0926d4780', 6, 'practice', 'numeric', 2, 'Stadium rows: row 1 has 22 seats and each row has 3 more than the one before. How many seats are in row 15?', '{"answer":64}', '["$a_{15} = 22 + 14 \\cdot 3$."]', '$22 + 42 = 64$ seats.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3c0008da997de5', 'les_5662d0926d4780', 7, 'review', 'numeric', 3, 'In an arithmetic sequence, $a_4 = 10$ and $a_{10} = -8$. Find $a_1$.', '{"answer":19}', '["Six steps from term 4 to term 10.","$6d = -18$."]', '$d = -3$ and $a_1 = a_4 - 3d = 10 + 9 = 19$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_08ea5f9b126936', 'les_5662d0926d4780', 8, 'review', 'numeric', 3, 'Which term of 5, 12, 19, 26, … equals 201?', '{"answer":29}', '["Solve $5 + (n - 1)7 = 201$."]', '$(n - 1)7 = 196$, so $n - 1 = 28$ and $n = 29$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_5662d0926d4780', 'subj_math', 'arithmetic-sequences', 'Arithmetic sequences', 'Sequences with a constant difference between consecutive terms.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5662d0926d4780', (SELECT id FROM concepts WHERE slug = 'arithmetic-sequences'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_5662d0926d4780', (SELECT id FROM formulas WHERE slug = 'arithmetic-sequence'), 1);

-- Lesson: box-plots-histograms
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9b0e22e1a67f0d', 'box-plots-histograms', 'Box plots and histograms', 'Construct box plots and histograms, read shape, center, spread and outliers from them, and compare two distributions side by side.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b19b4dab6c7565', 'les_9b0e22e1a67f0d', 1, 'Build a box plot from the five-number summary, marking outliers with the 1.5 × IQR rule.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_db2130f0918e4e', 'les_9b0e22e1a67f0d', 2, 'Build a histogram with sensible bins and describe the shape of the distribution.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_98324485086d51', 'les_9b0e22e1a67f0d', 3, 'Compare two distributions using parallel box plots or histograms, discussing center, spread and shape.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b19b4dab6c7565', 'les_9b0e22e1a67f0d', 'learn', 1, 'text', '{"body":"Box plots and histograms summarize the same numerical data in different ways. A histogram shows shape in detail: peaks, gaps and tails. A box plot shows the five-number summary and outliers compactly, which makes it ideal for comparing several groups side by side."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_db2130f0918e4e', 'les_9b0e22e1a67f0d', 'learn', 2, 'definition', '{"term":"Modified box plot","body":"Whiskers extend only to the most extreme values that are not outliers. Values beyond $Q_1 - 1.5 \\cdot \\text{IQR}$ or $Q_3 + 1.5 \\cdot \\text{IQR}$ are plotted as separate points."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_98324485086d51', 'les_9b0e22e1a67f0d', 'learn', 3, 'worked_example', '{"title":"Make a box plot of: 4, 7, 8, 9, 10, 11, 12, 12, 14, 27","steps":[{"latex":"\\text{median} = \\tfrac{10 + 11}{2} = 10.5","explanation":"Ten values: average the 5th and 6th."},{"latex":"Q_1 = 8,\\ Q_3 = 12","explanation":"Medians of 4, 7, 8, 9, 10 and 11, 12, 12, 14, 27."},{"latex":"\\text{IQR} = 4;\\ \\text{fences } 8 - 6 = 2,\\ 12 + 6 = 18","explanation":""},{"latex":"27 > 18 \\Rightarrow \\text{outlier}","explanation":"The upper whisker stops at 14; 27 is a separate point."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_874bf696cd49c4', 'les_9b0e22e1a67f0d', 'experiment', 4, 'activity', '{"activity":"data-explorer","title":"Box plot and histogram of the same data","params":{"dataset":"sleep","view":"histogram"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b97d6fd112c5d6', 'les_9b0e22e1a67f0d', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Switch between histogram and box plot. Change the bin width from 1 to 4. A good bin width shows the shape without hiding it in one big bar or scattering it into many tiny ones. Drag a value far right: how does each display show the outlier?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3700cb69fa331a', 'les_9b0e22e1a67f0d', 'learn', 6, 'definition', '{"term":"Describing shape","body":"Symmetric, skewed left (long tail to the left) or skewed right (long tail to the right); unimodal or bimodal; any gaps or clusters. In a box plot, skew shows as a longer whisker and a median off-center in the box."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_58c5ad30649cfd', 'les_9b0e22e1a67f0d', 'learn', 7, 'worked_example', '{"title":"Compare two classes'' test scores from box plots","steps":[{"latex":"\\text{A: } 55, 68, 74, 80, 92 \\quad \\text{B: } 62, 70, 78, 83, 88","explanation":"Five-number summaries."},{"latex":"\\text{median: } 74 \\text{ vs } 78","explanation":"Class B''s typical score is higher."},{"latex":"\\text{IQR: } 12 \\text{ vs } 13;\\ \\text{range: } 37 \\text{ vs } 26","explanation":"Similar middle spread, but A has a wider overall spread."}],"check":"A full comparison mentions center, spread, shape and outliers, in context."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_349bf8e1c716bf', 'les_9b0e22e1a67f0d', 'learn', 8, 'callout', '{"tone":"warning","title":"Box plots hide sample size and gaps","body":"A box plot of 10 values and one of 10,000 values can look the same, and a bimodal distribution can look like a plain box. Look at a histogram or dot plot when shape matters."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1d30ea728d1d76', 'les_9b0e22e1a67f0d', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Doctors compare patient groups with parallel box plots, quality engineers check machine output with histograms, and sports analysts compare players'' scoring distributions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b19b4dab6c7565', 'les_9b0e22e1a67f0d', 1, 'practice', 'numeric', 2, 'Find $Q_1$ for 3, 5, 6, 8, 9, 11, 14, 15.', '{"answer":5.5}', '["Lower half: 3, 5, 6, 8."]', '$\frac{5 + 6}{2} = 5.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_db2130f0918e4e', 'les_9b0e22e1a67f0d', 2, 'practice', 'numeric', 2, 'For the same data, find $Q_3$.', '{"answer":12.5}', '["Upper half: 9, 11, 14, 15."]', '$\frac{11 + 14}{2} = 12.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_98324485086d51', 'les_9b0e22e1a67f0d', 3, 'practice', 'multiple_choice', 2, 'In a box plot, the right whisker is much longer than the left and the median is near the left of the box. The distribution is…', '{"choices":["Symmetric","Skewed left","Skewed right","Uniform"],"answer":2}', '["Which side has the long tail?"]', 'The long tail is on the right, so it is skewed right.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_874bf696cd49c4', 'les_9b0e22e1a67f0d', 4, 'practice', 'multiple_choice', 2, 'What fraction of the data lies between $Q_1$ and the median?', '{"choices":["About 10%","About 25%","About 50%","About 75%"],"answer":1}', '["Quartiles split the data into four equal parts."]', 'About a quarter of the values.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b97d6fd112c5d6', 'les_9b0e22e1a67f0d', 5, 'practice', 'multiple_choice', 2, 'Which display best shows that a data set has two peaks?', '{"choices":["Box plot","Histogram","Five-number summary","Mean and standard deviation"],"answer":1}', '["Which display shows shape in detail?"]', 'A histogram shows both peaks; a box plot can hide them.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3700cb69fa331a', 'les_9b0e22e1a67f0d', 6, 'review', 'numeric', 3, 'Data have $Q_1 = 40$, median 46, $Q_3 = 52$, minimum 30 and maximum 75. What is the largest value the upper whisker could reach in a modified box plot?', '{"answer":70}', '["Upper fence: $Q_3 + 1.5 \\cdot \\text{IQR}$."]', 'IQR = 12 and the fence is $52 + 18 = 70$. The maximum 75 is an outlier; the whisker extends to the largest value at most 70.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_dacabe71c2adb0', 'subj_math', 'data-displays', 'Data displays', 'Dot plots, histograms and box plots for one numerical variable.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9b0e22e1a67f0d', (SELECT id FROM concepts WHERE slug = 'data-displays'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d7416f96cb4a99', 'subj_math', 'five-number-summary', 'Five-number summary', 'Minimum, first quartile, median, third quartile and maximum.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9b0e22e1a67f0d', (SELECT id FROM concepts WHERE slug = 'five-number-summary'));

-- Lesson: classifying-real-numbers
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8c51fda24110f7', 'classifying-real-numbers', 'Classifying real numbers', 'Sort numbers into natural, whole, integer, rational and irrational sets, see how the sets nest, and order real numbers including square roots.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2e0e18ba62a940', 'les_8c51fda24110f7', 1, 'Name the subsets of the real numbers and describe how they are nested.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5318d0ab88b76f', 'les_8c51fda24110f7', 2, 'Classify a number as rational or irrational, including square roots and repeating decimals.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8904b9986063b4', 'les_8c51fda24110f7', 3, 'Order and compare real numbers, using estimates for irrational values.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2e0e18ba62a940', 'les_8c51fda24110f7', 'learn', 1, 'text', '{"body":"Every point on the number line is a real number. Mathematicians group real numbers into sets, and each set grew out of a need the previous one couldn''t meet: counting needed the natural numbers, \"none\" needed zero, debts needed negatives, sharing needed fractions, and measuring the diagonal of a square needed irrational numbers."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5318d0ab88b76f', 'les_8c51fda24110f7', 'learn', 2, 'definition', '{"term":"Subsets of the real numbers","body":"Natural numbers $\\mathbb{N}$: 1, 2, 3, … Whole numbers: 0, 1, 2, 3, … Integers $\\mathbb{Z}$: …, −2, −1, 0, 1, 2, … Rational numbers $\\mathbb{Q}$: numbers $\\frac{a}{b}$ with integers $a, b$ and $b \\ne 0$. Irrational numbers: real numbers that are not rational."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8904b9986063b4', 'les_8c51fda24110f7', 'learn', 3, 'text', '{"body":"The sets nest inside each other: every natural number is whole, every whole number is an integer, and every integer is rational. The rationals and the irrationals don''t overlap; together they make up all the real numbers $\\mathbb{R}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_90f331e8069146', 'les_8c51fda24110f7', 'learn', 4, 'callout', '{"tone":"tip","title":"Spotting irrational numbers","body":"$\\sqrt{n}$ is irrational unless $n$ is a perfect square (or a ratio of perfect squares, like $\\sqrt{\\frac{4}{9}} = \\frac{2}{3}$). $\\pi$ and $e$ are irrational. A decimal that ends or repeats is rational; one that never ends and never repeats is irrational."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eaf92c639d7d30', 'les_8c51fda24110f7', 'learn', 5, 'worked_example', '{"title":"Classify each number: $-7$, $0.\\overline{45}$, $\\sqrt{49}$, $\\sqrt{50}$, $\\frac{\\pi}{2}$, $0$","steps":[{"latex":"-7","explanation":"Integer and rational (not whole, because it is negative)."},{"latex":"0.\\overline{45} = \\tfrac{5}{11}","explanation":"Repeating decimal: rational."},{"latex":"\\sqrt{49} = 7","explanation":"Natural, whole, integer and rational."},{"latex":"\\sqrt{50} \\approx 7.071\\ldots","explanation":"50 isn''t a perfect square: irrational."},{"latex":"\\tfrac{\\pi}{2}","explanation":"An irrational number divided by 2 stays irrational."},{"latex":"0","explanation":"Whole, integer and rational, but not natural."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aa5f1dbae46857', 'les_8c51fda24110f7', 'learn', 6, 'worked_example', '{"title":"Order from least to greatest: $\\sqrt{10},\\ 3.1,\\ \\pi,\\ \\tfrac{19}{6}$","steps":[{"latex":"\\sqrt{10} \\approx 3.162","explanation":"Estimate: between 3 and 4, and $3.16^2 approx 9.99$."},{"latex":"\\pi \\approx 3.1416,\\quad \\tfrac{19}{6} = 3.1\\overline{6}","explanation":""},{"latex":"3.1 < \\pi < \\sqrt{10} < \\tfrac{19}{6}","explanation":"Compare decimals place by place."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_45e016e6cba93b', 'les_8c51fda24110f7', 'learn', 7, 'callout', '{"tone":"warning","title":"Calculators round","body":"A calculator shows $\\sqrt{2} \\approx 1.414213562$, but the true decimal never ends or repeats. A displayed decimal is an approximation, not proof that a number is rational."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5a58c1befd9972', 'les_8c51fda24110f7', 'learn', 8, 'callout', '{"tone":"note","title":"Why √2 is irrational","body":"Suppose $\\sqrt{2} = \\frac{a}{b}$ in lowest terms. Then $a^2 = 2b^2$, so $a^2$ is even, which makes $a$ even: $a = 2k$. Then $4k^2 = 2b^2$, so $b^2 = 2k^2$ and $b$ is even too. Both being even contradicts \"lowest terms,\" so no such fraction exists."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_313acd9782e79b', 'les_8c51fda24110f7', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"The diagonal of a 1 m square tile is $\\sqrt{2}$ m, and a circle''s circumference involves $\\pi$. Builders use rational approximations such as 1.414 m, but the exact lengths are irrational."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2e0e18ba62a940', 'les_8c51fda24110f7', 1, 'practice', 'multiple_choice', 1, 'Which number is irrational?', '{"choices":["$\\sqrt{81}$","$-\\frac{3}{4}$","$\\sqrt{12}$","$0.\\overline{3}$"],"answer":2}', '["Which square root is of a non-perfect square?"]', '12 is not a perfect square, so $\sqrt{12}$ is irrational. $\sqrt{81} = 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5318d0ab88b76f', 'les_8c51fda24110f7', 2, 'practice', 'multiple_choice', 1, 'Which set contains both $-15$ and $15$?', '{"choices":["Natural numbers","Integers","Whole numbers","Irrational numbers"],"answer":1}', '["Negative numbers are not natural or whole."]', 'Both $-15$ and $15$ are integers. Only $15$ is natural and whole.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8904b9986063b4', 'les_8c51fda24110f7', 3, 'practice', 'multiple_choice', 2, 'Which statement is always true?', '{"choices":["Every integer is a whole number.","Every rational number is an integer.","Every whole number is rational.","Every square root is irrational."],"answer":2}', '["Use the nesting of the sets."]', 'Whole numbers are integers, and every integer $n = \frac{n}{1}$ is rational. The other statements have counterexamples: $-1$, $\frac{1}{2}$ and $\sqrt{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_90f331e8069146', 'les_8c51fda24110f7', 4, 'practice', 'multiple_choice', 2, 'Between which two consecutive integers does $-\sqrt{30}$ lie?', '{"choices":["−5 and −4","−6 and −5","5 and 6","−31 and −30"],"answer":1}', '["$5 < \\sqrt{30} < 6$."]', 'Since $25 < 30 < 36$, $5 < \sqrt{30} < 6$, so $-6 < -\sqrt{30} < -5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eaf92c639d7d30', 'les_8c51fda24110f7', 5, 'practice', 'numeric', 2, 'How many of these are rational? $\ \sqrt{16},\ \sqrt{17},\ 2.\overline{7},\ \pi,\ -\frac{8}{2},\ 0$', '{"answer":4}', '["Check each one: does it end, repeat or simplify to a fraction?"]', '$\sqrt{16} = 4$, $2.\overline{7}$, $-\frac{8}{2} = -4$ and $0$ are rational. $\sqrt{17}$ and $\pi$ are not. That makes 4.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aa5f1dbae46857', 'les_8c51fda24110f7', 6, 'review', 'short_text', 3, 'Name the greatest of $\sqrt{8},\ 2.8,\ \frac{17}{6}$. Enter it exactly as written (sqrt8, 2.8 or 17/6).', '{"accept":["17/6"]}', '["$\\sqrt{8} \\approx 2.828$; $\\frac{17}{6} \\approx 2.833$."]', '$2.8 < 2.828 < 2.8\overline{3}$, so $\frac{17}{6}$ is greatest.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_45e016e6cba93b', 'les_8c51fda24110f7', 7, 'review', 'multiple_choice', 3, 'Is the sum of two irrational numbers always irrational?', '{"choices":["Yes, always","No; for example √2 + (−√2) = 0","No; it is always rational","Only if both are square roots"],"answer":1}', '["Try a number and its opposite."]', '$\sqrt{2} + (-\sqrt{2}) = 0$, which is rational. So the sum of two irrationals can be rational. (A rational plus an irrational, though, is always irrational.)');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_cc5eaad50a5661', 'subj_math', 'real-numbers', 'Real numbers', 'All rational and irrational numbers; every point on the number line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8c51fda24110f7', (SELECT id FROM concepts WHERE slug = 'real-numbers'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_72e185817fb626', 'subj_math', 'irrational-numbers', 'Irrational numbers', 'Real numbers that cannot be written as a ratio of integers; their decimals never end or repeat.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8c51fda24110f7', (SELECT id FROM concepts WHERE slug = 'irrational-numbers'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36a6777463a5e2', 'subj_math', 'rational-numbers', 'Rational numbers', 'Numbers that can be written as a ratio of two integers with a nonzero denominator.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8c51fda24110f7', (SELECT id FROM concepts WHERE slug = 'rational-numbers'));

-- Lesson: combining-like-terms
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_fc1bafa3d09369', 'combining-like-terms', 'Combining like terms', 'Identify like terms and simplify expressions by combining them, including after distributing.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0c263b25894adc', 'les_fc1bafa3d09369', 1, 'Identify like terms by their variable parts.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_10d569fd3f1e0f', 'les_fc1bafa3d09369', 2, 'Combine like terms by adding or subtracting their coefficients.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_888fc17c5d3acc', 'les_fc1bafa3d09369', 3, 'Simplify expressions that require distributing first, including subtracting a group.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0c263b25894adc', 'les_fc1bafa3d09369', 'learn', 1, 'definition', '{"term":"Like terms","body":"Terms whose variable parts are identical: same variables, same exponents. $5x$ and $-2x$ are like terms. $3x^2$ and $3x$ are not, and neither are $4xy$ and $4x$. All constants are like terms with each other."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_10d569fd3f1e0f', 'les_fc1bafa3d09369', 'learn', 2, 'text', '{"body":"Combining like terms is the distributive property in reverse: $5x + 3x = (5 + 3)x = 8x$. Think of $x$ as a unit, like \"apples\": 5 apples plus 3 apples is 8 apples. But 5 apples plus 3 oranges stays $5a + 3o$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_888fc17c5d3acc', 'les_fc1bafa3d09369', 'learn', 3, 'worked_example', '{"title":"Simplify $7x + 4 - 2x + 9$","steps":[{"latex":"(7x - 2x) + (4 + 9)","explanation":"Group like terms, keeping each term''s sign with it."},{"latex":"5x + 13","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_22703d28b09bd2', 'les_fc1bafa3d09369', 'learn', 4, 'worked_example', '{"title":"Simplify $3a^2 - 5a + a^2 + 8a - 6$","steps":[{"latex":"(3a^2 + a^2) + (-5a + 8a) - 6","explanation":"$a^2$ means $1a^2$."},{"latex":"4a^2 + 3a - 6","explanation":"Write the highest power first by convention."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_310c90e797f1d5', 'les_fc1bafa3d09369', 'learn', 5, 'worked_example', '{"title":"Simplify $5(2y - 3) - (4y - 7)$","steps":[{"latex":"10y - 15 - 4y + 7","explanation":"Distribute 5 and −1. Subtracting the group changes the sign of every term in it."},{"latex":"6y - 8","explanation":"Combine: 10y − 4y and −15 + 7."}],"check":"Check with $y = 2$: $5(1) - (1) = 4$ and $6(2) - 8 = 4$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_af483d9bae8699', 'les_fc1bafa3d09369', 'learn', 6, 'callout', '{"tone":"warning","title":"Exponents don''t change when combining","body":"$4x^2 + 3x^2 = 7x^2$, not $7x^4$. You add the coefficients; the variable part stays the same. Also, $x + x = 2x$, while $x \\cdot x = x^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b846c0c975ff2b', 'les_fc1bafa3d09369', 'learn', 7, 'callout', '{"tone":"tip","title":"Check by substituting","body":"Pick an easy value like $x = 2$ and evaluate both the original and your simplified expression. If they disagree, there is an error. (If they agree, you are very likely right.)"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bc403807f1c4cd', 'les_fc1bafa3d09369', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"A rectangle with length $2x + 5$ and width $x - 1$ has perimeter $2(2x + 5) + 2(x - 1) = 4x + 10 + 2x - 2 = 6x + 8$. Simplifying makes formulas easier to use and compare."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0c263b25894adc', 'les_fc1bafa3d09369', 1, 'practice', 'short_text', 1, 'Simplify $9m + 4m - 3m$.', '{"accept":["10m"]}', '["Add and subtract the coefficients."]', '$(9 + 4 - 3)m = 10m$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_10d569fd3f1e0f', 'les_fc1bafa3d09369', 2, 'practice', 'short_text', 1, 'Simplify $6x + 5 - 2x - 8$.', '{"accept":["4x-3","-3+4x"]}', '["Combine the x-terms and the constants separately."]', '$4x - 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_888fc17c5d3acc', 'les_fc1bafa3d09369', 3, 'practice', 'multiple_choice', 1, 'Which pair are like terms?', '{"choices":["$3x$ and $3y$","$5x^2$ and $5x$","$-7ab$ and $2ab$","$4$ and $4x$"],"answer":2}', '["Look for identical variable parts."]', '$-7ab$ and $2ab$ both have the variable part $ab$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_22703d28b09bd2', 'les_fc1bafa3d09369', 4, 'practice', 'short_text', 2, 'Simplify $2p^2 + 3p - 5p^2 + p$.', '{"accept":["-3p^2+4p","4p-3p^2"]}', '["$2p^2 - 5p^2 = -3p^2$.","$3p + p = 4p$."]', '$-3p^2 + 4p$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_310c90e797f1d5', 'les_fc1bafa3d09369', 5, 'practice', 'short_text', 2, 'Simplify $4(x + 2) + 3(x - 1)$.', '{"accept":["7x+5","5+7x"]}', '["Distribute both, then combine."]', '$4x + 8 + 3x - 3 = 7x + 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_af483d9bae8699', 'les_fc1bafa3d09369', 6, 'practice', 'short_text', 2, 'Simplify $8 - (3n - 2)$.', '{"accept":["10-3n","-3n+10"]}', '["$-(3n - 2) = -3n + 2$."]', '$8 - 3n + 2 = 10 - 3n$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b846c0c975ff2b', 'les_fc1bafa3d09369', 7, 'review', 'short_text', 3, 'Simplify $\tfrac{1}{2}(4a - 6) - 2(a - 5)$.', '{"accept":["7"]}', '["$2a - 3 - 2a + 10$."]', 'The $a$-terms cancel: $2a - 2a = 0$, leaving $-3 + 10 = 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bc403807f1c4cd', 'les_fc1bafa3d09369', 8, 'review', 'short_text', 3, 'A triangle has sides $x + 3$, $2x - 1$ and $3x$. Write its perimeter in simplest form.', '{"accept":["6x+2","2+6x"]}', '["Add all three sides."]', '$(x + 2x + 3x) + (3 - 1) = 6x + 2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7927ef860f1bc4', 'subj_math', 'like-terms', 'Like terms', 'Terms with exactly the same variables raised to the same powers.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_fc1bafa3d09369', (SELECT id FROM concepts WHERE slug = 'like-terms'));

-- Lesson: comparing-linear-exponential
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ef50d2aca13dbb', 'comparing-linear-exponential', 'Comparing linear and exponential models', 'Tell linear from exponential patterns using differences and ratios, write either model from two points, and see why exponential growth eventually overtakes linear growth.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_251a20a1fa760e', 'les_ef50d2aca13dbb', 1, 'Classify a table as linear (constant differences) or exponential (constant ratios).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ca0309a01ad24c', 'les_ef50d2aca13dbb', 2, 'Write a linear or exponential model from data.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ee7a536987a988', 'les_ef50d2aca13dbb', 3, 'Explain why an increasing exponential function eventually exceeds any increasing linear function.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_251a20a1fa760e', 'les_ef50d2aca13dbb', 'learn', 1, 'text', '{"body":"Linear functions change by equal differences over equal intervals; exponential functions change by equal factors (ratios) over equal intervals. To classify a table with evenly spaced inputs, compute the differences of the outputs. If they''re constant, it''s linear. If not, compute the ratios. If those are constant, it''s exponential."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ca0309a01ad24c', 'les_ef50d2aca13dbb', 'learn', 2, 'worked_example', '{"title":"Classify: $x$ = 0, 1, 2, 3 and $y$ = 6, 9, 13.5, 20.25","steps":[{"latex":"\\text{differences: } 3,\\ 4.5,\\ 6.75","explanation":"Not constant: not linear."},{"latex":"\\text{ratios: } \\tfrac{9}{6} = \\tfrac{13.5}{9} = \\tfrac{20.25}{13.5} = 1.5","explanation":"Constant ratio."},{"latex":"y = 6(1.5)^x","explanation":"Exponential with a = 6 and b = 1.5."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ee7a536987a988', 'les_ef50d2aca13dbb', 'experiment', 3, 'activity', '{"activity":"growth-models","title":"Race a line against an exponential","params":{"a":2,"b":1.5,"d":6,"compare":true}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa51aa6a7a6180', 'les_ef50d2aca13dbb', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"The line starts ahead by adding 6 each step. Find where the exponential passes it. Then raise $d$ to 10: the crossing moves later but still happens. Can you make a line the exponential never catches with $b > 1$?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d84d9a2e3217ca', 'les_ef50d2aca13dbb', 'learn', 5, 'worked_example', '{"title":"Two salary offers: A pays 40,000 dollars and rises 2,500 dollars per year. B pays 36,000 dollars and rises 6% per year. When does B pay more?","steps":[{"latex":"A(t) = 40000 + 2500t,\\quad B(t) = 36000(1.06)^t","explanation":""},{"latex":"t = 5: A = 52{,}500,\\ B \\approx 48{,}176","explanation":"A is still ahead."},{"latex":"t = 12: A = 70{,}000,\\ B \\approx 72{,}440","explanation":"B has overtaken A."},{"latex":"t = 11: A = 67{,}500,\\ B \\approx 68{,}340","explanation":"Check the year before: B already leads."}],"check":"Year 10: $A = 65{,}000$ and $B \\approx 64{,}470$. So B first pays more in year 11."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e022e849c07a3c', 'les_ef50d2aca13dbb', 'learn', 6, 'worked_example', '{"title":"Write an exponential model through $(0, 4)$ and $(3, 32)$","steps":[{"latex":"a = 4","explanation":"The point at x = 0 gives a."},{"latex":"32 = 4b^3 \\Rightarrow b^3 = 8 \\Rightarrow b = 2","explanation":""},{"latex":"y = 4 \\cdot 2^x","explanation":"Compare with the line through the same points: $y = \\frac{28}{3}x + 4$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2c0ba377ca1461', 'les_ef50d2aca13dbb', 'learn', 7, 'callout', '{"tone":"warning","title":"Equal intervals only","body":"Differences and ratios only reveal the pattern if the inputs are evenly spaced. If $x$ jumps from 1 to 2 to 5, compare changes per unit of $x$ instead."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3d4e144a184f55', 'les_ef50d2aca13dbb', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Investments, social media followers and early epidemics grow exponentially, while hourly pay and constant-speed travel grow linearly. Planning for the long term means knowing which one you''re dealing with."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_251a20a1fa760e', 'les_ef50d2aca13dbb', 1, 'practice', 'multiple_choice', 1, 'Which table is exponential? (Inputs 0, 1, 2, 3.)', '{"choices":["y: 5, 10, 15, 20","y: 3, 6, 12, 24","y: 1, 4, 9, 16","y: 10, 8, 6, 4"],"answer":1}', '["Look for a constant ratio."]', '3, 6, 12, 24 doubles each step: ratio 2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ca0309a01ad24c', 'les_ef50d2aca13dbb', 2, 'practice', 'multiple_choice', 1, 'Which table is linear? (Inputs 0, 1, 2, 3.)', '{"choices":["y: 2, 6, 18, 54","y: 100, 50, 25, 12.5","y: 7, 4, 1, −2","y: 1, 2, 4, 7"],"answer":2}', '["Look for a constant difference."]', '7, 4, 1, −2 decreases by 3 each step.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ee7a536987a988', 'les_ef50d2aca13dbb', 3, 'practice', 'short_text', 2, 'Write an exponential model for $x$ = 0, 1, 2 and $y$ = 50, 40, 32. Use the format y=a(b)^x.', '{"accept":["y=50(0.8)^x","y=50*0.8^x","y=50(4/5)^x"]}', '["a is y at x = 0.","Ratio 40/50."]', '$a = 50$ and $b = 0.8$: $y = 50(0.8)^x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fa51aa6a7a6180', 'les_ef50d2aca13dbb', 4, 'practice', 'numeric', 2, 'An exponential function passes through $(0, 3)$ and $(2, 75)$ and is increasing. What is $b$?', '{"answer":5}', '["$75 = 3b^2$."]', '$b^2 = 25$, so $b = 5$ (it''s positive).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d84d9a2e3217ca', 'les_ef50d2aca13dbb', 5, 'practice', 'multiple_choice', 2, 'Which grows faster in the long run?', '{"choices":["$f(x) = 1000x$","$g(x) = 0.01(1.1)^x$","They grow at the same rate","It depends only on the starting values"],"answer":1}', '["Increasing exponentials eventually beat any line."]', '$g$ grows by a factor of 1.1 each step and eventually exceeds any linear function, even one with slope 1000.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e022e849c07a3c', 'les_ef50d2aca13dbb', 6, 'review', 'numeric', 3, 'Option A gives 100 dollars a day. Option B gives 1 cent on day 1 and doubles daily (day n pays $0.01 \cdot 2^{n-1}$). On what day does B''s daily payment first exceed 100 dollars?', '{"answer":15}', '["Solve $0.01 \\cdot 2^{n-1} > 100$, so $2^{n-1} > 10{,}000$.","$2^{13} = 8192$, $2^{14} = 16{,}384$."]', '$n - 1 = 14$, so day 15 pays 163.84 dollars.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_995fc7b1dd6d9d', 'subj_math', 'exponential-functions', 'Exponential functions', 'Functions of the form y = a·bˣ that change by a constant factor.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ef50d2aca13dbb', (SELECT id FROM concepts WHERE slug = 'exponential-functions'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_6a3ec2dbe14a2b', 'subj_math', 'linear-models', 'Linear models', 'Using y = mx + b to describe a quantity that changes at a constant rate.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ef50d2aca13dbb', (SELECT id FROM concepts WHERE slug = 'linear-models'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ef50d2aca13dbb', (SELECT id FROM formulas WHERE slug = 'exponential-function'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ef50d2aca13dbb', (SELECT id FROM formulas WHERE slug = 'slope-intercept-form'), 2);

-- Lesson: completing-the-square
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1caac7a98db508', 'completing-the-square', 'Completing the square', 'Rewrite x² + bx as a perfect square by adding (b/2)², solve quadratics with it, and convert standard form to vertex form.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_982253b874f8b4', 'les_1caac7a98db508', 1, 'Explain completing the square with an area model.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_531e417ec99771', 'les_1caac7a98db508', 2, 'Solve quadratic equations by completing the square, including when a ≠ 1.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e41de4f543db67', 'les_1caac7a98db508', 3, 'Convert y = ax² + bx + c to vertex form y = a(x − h)² + k.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_982253b874f8b4', 'les_1caac7a98db508', 'learn', 1, 'text', '{"body":"Picture $x^2 + 6x$ as an $x$-by-$x$ square plus a $6$-by-$x$ rectangle. Cut the rectangle in half and put one $3x$ strip on each side of the square. The shape is almost a big square of side $x + 3$; it''s missing a $3$-by-$3$ corner. Adding 9 completes it: $x^2 + 6x + 9 = (x + 3)^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_531e417ec99771', 'les_1caac7a98db508', 'experiment', 2, 'activity', '{"activity":"area-model","title":"The missing corner","params":{"a":1,"b":3,"c":1,"d":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e41de4f543db67', 'les_1caac7a98db508', 'experiment', 3, 'callout', '{"tone":"tip","title":"Try this","body":"The model shows $(x + 3)^2$. The two $3x$ strips are the halves of $6x$ and the 9 is the corner you add. Set $b = d = 5$: which number completes $x^2 + 10x$?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f3dae8caea750a', 'les_1caac7a98db508', 'learn', 4, 'text', '{"body":"In general, to complete $x^2 + bx$, add $\\left(\\frac{b}{2}\\right)^2$: $x^2 + bx + \\left(\\frac{b}{2}\\right)^2 = \\left(x + \\frac{b}{2}\\right)^2$. This only works directly when the coefficient of $x^2$ is 1."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6177765f3da2f4', 'les_1caac7a98db508', 'learn', 5, 'worked_example', '{"title":"Solve $x^2 + 6x - 7 = 0$ by completing the square","steps":[{"latex":"x^2 + 6x = 7","explanation":"Move the constant."},{"latex":"x^2 + 6x + 9 = 7 + 9","explanation":"Add (6/2)² = 9 to both sides."},{"latex":"(x + 3)^2 = 16","explanation":""},{"latex":"x + 3 = \\pm 4 \\Rightarrow x = 1 \\text{ or } x = -7","explanation":""}],"check":"Factoring gives the same answer: (x + 7)(x − 1) = 0."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_746b6bf15219ec', 'les_1caac7a98db508', 'learn', 6, 'worked_example', '{"title":"Solve $2x^2 - 8x - 3 = 0$","steps":[{"latex":"x^2 - 4x = \\tfrac{3}{2}","explanation":"Divide every term by 2, then move the constant."},{"latex":"x^2 - 4x + 4 = \\tfrac{3}{2} + 4 = \\tfrac{11}{2}","explanation":"Add (−4/2)² = 4."},{"latex":"(x - 2)^2 = \\tfrac{11}{2}","explanation":""},{"latex":"x = 2 \\pm \\sqrt{\\tfrac{11}{2}} \\approx 4.35 \\text{ or } -0.35","explanation":"$\\sqrt{5.5} \\approx 2.345$."}],"check":"Check $x \\approx 4.345$: $2(18.88) - 34.76 - 3 \\approx 0$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a9e7b72026556a', 'les_1caac7a98db508', 'learn', 7, 'worked_example', '{"title":"Write $y = x^2 - 10x + 18$ in vertex form","steps":[{"latex":"y = (x^2 - 10x + 25) - 25 + 18","explanation":"Add and subtract 25 on the same side to keep it equal."},{"latex":"y = (x - 5)^2 - 7","explanation":"Vertex (5, −7)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_737317b0fa20b8', 'les_1caac7a98db508', 'learn', 8, 'callout', '{"tone":"warning","title":"Keep the equation balanced","body":"When solving, add $\\left(\\frac{b}{2}\\right)^2$ to both sides. When rewriting a function, add and subtract it on the same side. Forgetting to balance is the most common mistake."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a16194f7ce020a', 'les_1caac7a98db508', 'learn', 9, 'callout', '{"tone":"note","title":"Why it matters","body":"Completing the square on $ax^2 + bx + c = 0$ in general produces the quadratic formula. It''s also how circles'' equations are put into center-radius form in geometry and Algebra 2."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f2a4f3aecae858', 'les_1caac7a98db508', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Vertex form reveals a maximum or minimum directly. A company''s profit $P = -x^2 + 40x - 300$ becomes $-(x - 20)^2 + 100$: the best price is 20 dollars, with a maximum profit of 100 dollars."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_982253b874f8b4', 'les_1caac7a98db508', 1, 'practice', 'numeric', 1, 'What number completes the square for $x^2 + 14x$?', '{"answer":49}', '["$(14/2)^2$."]', '$7^2 = 49$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_531e417ec99771', 'les_1caac7a98db508', 2, 'practice', 'numeric', 1, 'What number completes the square for $x^2 - 5x$? Enter a fraction or decimal.', '{"answer":6.25}', '["$(-5/2)^2$."]', '$\frac{25}{4} = 6.25$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e41de4f543db67', 'les_1caac7a98db508', 3, 'practice', 'short_text', 2, 'Solve $x^2 + 8x + 7 = 0$ by completing the square. Enter both solutions, smaller first.', '{"accept":["-7,-1"]}', '["$x^2 + 8x + 16 = 9$."]', '$(x + 4)^2 = 9$, so $x = -4 \pm 3$: $x = -7$ or $x = -1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f3dae8caea750a', 'les_1caac7a98db508', 4, 'practice', 'short_text', 2, 'Write $y = x^2 + 6x + 2$ in vertex form. Use the format y=(x+h)^2+k.', '{"accept":["y=(x+3)^2-7"]}', '["Add and subtract 9."]', '$(x + 3)^2 - 9 + 2 = (x + 3)^2 - 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6177765f3da2f4', 'les_1caac7a98db508', 5, 'practice', 'numeric', 3, 'Solve $x^2 - 2x - 4 = 0$. Give the larger solution to two decimal places.', '{"answer":3.24,"tolerance":0.006}', '["$(x - 1)^2 = 5$."]', '$x = 1 \pm \sqrt{5}$; the larger is $1 + 2.236 \approx 3.24$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_746b6bf15219ec', 'les_1caac7a98db508', 6, 'review', 'multiple_choice', 3, 'What is the vertex of $y = 2x^2 + 12x + 11$?', '{"choices":["$(3, -7)$","$(-3, -7)$","$(-6, 11)$","$(-3, 11)$"],"answer":1}', '["Factor 2 from the first two terms: $2(x^2 + 6x) + 11$.","$2(x^2 + 6x + 9) - 18 + 11$."]', '$y = 2(x + 3)^2 - 7$, so the vertex is $(-3, -7)$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1caac7a98db508', 'subj_math', 'completing-the-square', 'Completing the square', 'Adding (b/2)² to x² + bx to form a perfect-square trinomial.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1caac7a98db508', (SELECT id FROM concepts WHERE slug = 'completing-the-square'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_eb1b014f707879', 'subj_math', 'special-products', 'Special products', 'Perfect-square trinomials and the difference of two squares.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1caac7a98db508', (SELECT id FROM concepts WHERE slug = 'special-products'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_1caac7a98db508', (SELECT id FROM formulas WHERE slug = 'vertex-form'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_1caac7a98db508', (SELECT id FROM formulas WHERE slug = 'special-products'), 2);

-- Lesson: compound-inequalities
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a44aeab44fa3c6', 'compound-inequalities', 'Compound inequalities', 'Solve and graph ''and'' and ''or'' inequalities, including three-part inequalities, and describe their solutions as intersections and unions.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2b0b1347e2b9d0', 'les_a44aeab44fa3c6', 1, 'Distinguish between ''and'' (intersection) and ''or'' (union) compound inequalities.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3eee90b6a9ecab', 'les_a44aeab44fa3c6', 2, 'Solve three-part inequalities by applying each step to all three parts.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d7d06c09128b9f', 'les_a44aeab44fa3c6', 3, 'Graph compound inequalities and write them in interval notation, recognizing empty and all-real solution sets.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2b0b1347e2b9d0', 'les_a44aeab44fa3c6', 'learn', 1, 'definition', '{"term":"And (intersection)","body":"A value is a solution of \"$A$ and $B$\" if it satisfies both. On the number line, keep only the overlap. $x > -2$ and $x \\le 3$ is often written as one three-part inequality, $-2 < x \\le 3$, or $(-2, 3]$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3eee90b6a9ecab', 'les_a44aeab44fa3c6', 'learn', 2, 'definition', '{"term":"Or (union)","body":"A value is a solution of \"$A$ or $B$\" if it satisfies at least one. Keep everything either inequality shades. $x < -1$ or $x \\ge 4$ is $(-\\infty, -1) \\cup [4, \\infty)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d7d06c09128b9f', 'les_a44aeab44fa3c6', 'experiment', 3, 'activity', '{"activity":"inequality-line","title":"And versus or","params":{"rel":">","c":-2,"mode":"and","rel2":"≤","c2":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fc4d5f92a7fa11', 'les_a44aeab44fa3c6', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Switch the type between \"And\" and \"Or\" without changing the boundaries. Then make the first statement $x > 4$ and the second $x < 1$. What happens to the \"and\" solution, and why?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_963a338d13ca86', 'les_a44aeab44fa3c6', 'learn', 5, 'worked_example', '{"title":"Solve $-7 \\le 2x - 3 < 5$","steps":[{"latex":"-4 \\le 2x < 8","explanation":"Add 3 to all three parts."},{"latex":"-2 \\le x < 4","explanation":"Divide all three parts by 2."}],"check":"Interval: $[-2, 4)$. Check $x = -2$: $2(-2) - 3 = -7$, and $-7 \\le -7$ ✓. Check $x = 4$: $5 < 5$ is false, so 4 is excluded ✓."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f89614761789ec', 'les_a44aeab44fa3c6', 'learn', 6, 'worked_example', '{"title":"Solve $1 < 5 - 2x \\le 9$","steps":[{"latex":"-4 < -2x \\le 4","explanation":"Subtract 5 from every part."},{"latex":"2 > x \\ge -2","explanation":"Divide every part by −2 and reverse both symbols."},{"latex":"-2 \\le x < 2","explanation":"Rewrite with the smaller number on the left: [−2, 2)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cd4d8b616cc5a6', 'les_a44aeab44fa3c6', 'learn', 7, 'worked_example', '{"title":"Solve $3x + 1 < -8$ or $4 - x \\le 1$","steps":[{"latex":"3x < -9 \\Rightarrow x < -3","explanation":"Solve the first inequality."},{"latex":"-x \\le -3 \\Rightarrow x \\ge 3","explanation":"Solve the second (reverse when dividing by −1)."},{"latex":"(-\\infty, -3) \\cup [3, \\infty)","explanation":"Union of the two rays."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7bffc70c3617c8', 'les_a44aeab44fa3c6', 'learn', 8, 'callout', '{"tone":"warning","title":"Empty and full solution sets","body":"\"$x < 1$ and $x > 4$\" has no solution: no number is both. \"$x > 1$ or $x < 4$\" includes every real number. A three-part inequality like $5 < x < 2$ is never true, so don''t write one."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_74ecca171209b4', 'les_a44aeab44fa3c6', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Healthy ranges are \"and\" statements: a normal body temperature is about $36.1 \\le T \\le 37.2$ °C. Warnings are often \"or\" statements: a sensor alarms if the pressure is below 20 or above 35."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2b0b1347e2b9d0', 'les_a44aeab44fa3c6', 1, 'practice', 'short_text', 1, 'Solve $-3 < x + 4 < 6$. Write it like a<x<b.', '{"accept":["-7<x<2"]}', '["Subtract 4 from all three parts."]', '$-7 < x < 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3eee90b6a9ecab', 'les_a44aeab44fa3c6', 2, 'practice', 'short_text', 2, 'Solve $-6 \le 3x \le 12$.', '{"accept":["-2<=x<=4","-2≤x≤4"]}', '["Divide every part by 3."]', '$-2 \le x \le 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d7d06c09128b9f', 'les_a44aeab44fa3c6', 3, 'practice', 'short_text', 2, 'Solve $-5 < 1 - 2x < 7$.', '{"accept":["-3<x<3"]}', '["Subtract 1: −6 < −2x < 6.","Divide by −2 and reverse both symbols."]', '$3 > x > -3$, which is $-3 < x < 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fc4d5f92a7fa11', 'les_a44aeab44fa3c6', 4, 'practice', 'multiple_choice', 2, 'Which is the solution of $x - 2 < -5$ or $2x \ge 8$?', '{"choices":["$-3 < x \\le 4$","$x < -3$ or $x \\ge 4$","$x < -7$ or $x \\ge 4$","No solution"],"answer":1}', '["Solve each inequality separately."]', '$x < -3$ or $x \ge 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_963a338d13ca86', 'les_a44aeab44fa3c6', 5, 'practice', 'multiple_choice', 2, 'What is the solution of $x \ge 5$ and $x < 2$?', '{"choices":["$2 < x \\le 5$","All real numbers","No solution","$x < 2$"],"answer":2}', '["Can a number be at least 5 and less than 2?"]', 'No number satisfies both, so the solution set is empty.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f89614761789ec', 'les_a44aeab44fa3c6', 6, 'practice', 'multiple_choice', 2, 'Which interval represents $-1 < x \le 6$?', '{"choices":["$[-1, 6)$","$(-1, 6]$","$(-1, 6)$","$[-1, 6]$"],"answer":1}', '["Which endpoint is included?"]', '$-1$ is excluded (parenthesis) and 6 is included (bracket): $(-1, 6]$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cd4d8b616cc5a6', 'les_a44aeab44fa3c6', 7, 'review', 'short_text', 3, 'A thermostat keeps a room between 68°F and 74°F inclusive. Write a compound inequality for the temperature t, like a<=t<=b.', '{"accept":["68<=t<=74","68≤t≤74"]}', '["Inclusive means the endpoints are allowed."]', '$68 \le t \le 74$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7bffc70c3617c8', 'les_a44aeab44fa3c6', 8, 'review', 'short_text', 3, 'Solve $\frac{x + 1}{3} \le 2$ and $x - 4 > -9$. Write it like a<x<=b.', '{"accept":["-5<x<=5"]}', '["First: x + 1 ≤ 6.","Second: x > −5."]', '$x \le 5$ and $x > -5$: $-5 < x \le 5$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a44aeab44fa3c6', 'subj_math', 'compound-inequalities', 'Compound inequalities', 'Two inequalities joined by ''and'' or ''or''.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a44aeab44fa3c6', (SELECT id FROM concepts WHERE slug = 'compound-inequalities'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_26afa03b5cfa25', 'subj_math', 'interval-notation', 'Interval notation', 'Writing sets of real numbers as intervals using brackets and parentheses.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a44aeab44fa3c6', (SELECT id FROM concepts WHERE slug = 'interval-notation'));

-- Lesson: displaying-data
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_59d013c6895e76', 'displaying-data', 'Displaying data', 'Make and read dot plots, histograms and box plots, describe a distribution''s shape, center and spread, and pick a suitable display.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_46263946dfe9b8', 'les_59d013c6895e76', 1, 'Construct and interpret dot plots, histograms and box plots.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_535d7311abb9bc', 'les_59d013c6895e76', 2, 'Find the five-number summary and the interquartile range (IQR).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2bed852f84537d', 'les_59d013c6895e76', 3, 'Describe a distribution''s shape, center and spread, and choose a suitable display for a data set.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_46263946dfe9b8', 'les_59d013c6895e76', 'learn', 1, 'text', '{"body":"A list of numbers is hard to read. A good display shows the distribution at a glance: where the data cluster (center), how spread out they are, and the overall shape."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_535d7311abb9bc', 'les_59d013c6895e76', 'learn', 2, 'definition', '{"term":"Dot plot","body":"One dot for each value above a number line. Good for small data sets; every value stays visible."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2bed852f84537d', 'les_59d013c6895e76', 'learn', 3, 'definition', '{"term":"Histogram","body":"Bars over equal-width intervals (bins) whose heights show how many values fall in each bin. Good for large data sets. Bars touch because the bins cover the number line without gaps."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_85ef70a968a976', 'les_59d013c6895e76', 'learn', 4, 'definition', '{"term":"Box plot","body":"A display of the five-number summary: minimum, first quartile $Q_1$, median, third quartile $Q_3$ and maximum. The box covers the middle half of the data; its length is the interquartile range, $\\text{IQR} = Q_3 - Q_1$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fbd5915fd7ad4e', 'les_59d013c6895e76', 'learn', 5, 'worked_example', '{"title":"Find the five-number summary of 3, 5, 6, 7, 8, 9, 11, 12, 15","steps":[{"latex":"\\text{median} = 8","explanation":"Nine values; the 5th is the middle."},{"latex":"Q_1 = \\text{median of } 3, 5, 6, 7 = 5.5","explanation":"Lower half (the median is left out)."},{"latex":"Q_3 = \\text{median of } 9, 11, 12, 15 = 11.5","explanation":"Upper half."},{"latex":"3,\\ 5.5,\\ 8,\\ 11.5,\\ 15;\\quad \\text{IQR} = 6","explanation":"Min, Q₁, median, Q₃, max."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fc13870fd6466c', 'les_59d013c6895e76', 'experiment', 6, 'activity', '{"activity":"data-explorer","title":"Dot plot, box plot and histogram","params":{"dataset":"skewed","view":"box"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cb30647add58f4', 'les_59d013c6895e76', 'experiment', 7, 'callout', '{"tone":"tip","title":"Try this","body":"This data set is skewed right: most values are small, with a long tail to the right. Look at where the mean sits compared with the median. Switch to the histogram and change the bin width. Which width shows the shape best?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_89adc89be97423', 'les_59d013c6895e76', 'learn', 8, 'text', '{"body":"Common shapes: symmetric (the two sides look like mirror images; mean ≈ median), skewed right (a long tail toward larger values; the mean is usually greater than the median), and skewed left (a long tail toward smaller values). A distribution with one clear peak is unimodal; with two peaks, bimodal."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_592068b822901f', 'les_59d013c6895e76', 'learn', 9, 'callout', '{"tone":"note","title":"Outliers","body":"A common rule flags a value as an outlier if it is more than $1.5 \\times \\text{IQR}$ below $Q_1$ or above $Q_3$. Box plots often show outliers as separate points."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7b810cd33d5a1a', 'les_59d013c6895e76', 'learn', 10, 'callout', '{"tone":"warning","title":"Box plots hide the count","body":"Each part of a box plot holds about a quarter of the data, whether it is long or short. A long whisker means the values are spread out, not that there are more of them."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8e4db4debd8f50', 'les_59d013c6895e76', 'learn', 11, 'callout', '{"tone":"application","title":"Where this shows up","body":"Weather reports use histograms of rainfall, doctors read growth charts based on quartiles, and test reports show percentiles. Choosing the right display is part of telling an honest story with data."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_46263946dfe9b8', 'les_59d013c6895e76', 1, 'practice', 'numeric', 1, 'A box plot shows $Q_1 = 14$ and $Q_3 = 22$. What is the IQR?', '{"answer":8}', '["IQR $= Q_3 - Q_1$."]', '$22 - 14 = 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_535d7311abb9bc', 'les_59d013c6895e76', 2, 'practice', 'numeric', 2, 'Find the median of 2, 4, 4, 5, 7, 9, 10, 12.', '{"answer":6}', '["Eight values: average the 4th and 5th."]', '$\frac{5 + 7}{2} = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2bed852f84537d', 'les_59d013c6895e76', 3, 'practice', 'numeric', 2, 'For 2, 4, 4, 5, 7, 9, 10, 12, find $Q_1$.', '{"answer":4}', '["Lower half: 2, 4, 4, 5."]', 'Median of 2, 4, 4, 5 is $\frac{4 + 4}{2} = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_85ef70a968a976', 'les_59d013c6895e76', 4, 'practice', 'numeric', 2, 'For 2, 4, 4, 5, 7, 9, 10, 12, find $Q_3$.', '{"answer":9.5}', '["Upper half: 7, 9, 10, 12."]', 'Median of 7, 9, 10, 12 is $\frac{9 + 10}{2} = 9.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fbd5915fd7ad4e', 'les_59d013c6895e76', 5, 'practice', 'multiple_choice', 2, 'You surveyed 500 people about how many minutes they commute. Which display is most practical?', '{"choices":["Dot plot","Histogram","A list of all 500 values","A single dot"],"answer":1}', '["Which display groups many values into intervals?"]', 'A histogram groups the 500 values into bins; a dot plot would be crowded.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fc13870fd6466c', 'les_59d013c6895e76', 6, 'practice', 'multiple_choice', 2, 'In a histogram most bars are on the left with a long tail of short bars to the right. How would you describe it?', '{"choices":["Symmetric","Skewed left","Skewed right","Uniform"],"answer":2}', '["Skew is named for the direction of the tail."]', 'The tail points to larger values on the right, so it is skewed right.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cb30647add58f4', 'les_59d013c6895e76', 7, 'review', 'multiple_choice', 3, 'A data set has $Q_1 = 10$, $Q_3 = 18$. Using the 1.5 × IQR rule, which value is an outlier?', '{"choices":["0","25","31","−1"],"answer":2}', '["IQR $= 8$ and $1.5 \\times 8 = 12$.","The fences are $10 - 12 = -2$ and $18 + 12 = 30$."]', 'Values below $-2$ or above $30$ are outliers. Only 31 is outside the fences.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_dacabe71c2adb0', 'subj_math', 'data-displays', 'Data displays', 'Dot plots, histograms and box plots for one numerical variable.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_59d013c6895e76', (SELECT id FROM concepts WHERE slug = 'data-displays'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d7416f96cb4a99', 'subj_math', 'five-number-summary', 'Five-number summary', 'Minimum, first quartile, median, third quartile and maximum.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_59d013c6895e76', (SELECT id FROM concepts WHERE slug = 'five-number-summary'));

-- Lesson: distributive-property
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_862d74cf83941b', 'distributive-property', 'The distributive property', 'Multiply a factor across a sum or difference, handle negative factors, and run the property in reverse to factor out a common factor.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9dbf9e3990f171', 'les_862d74cf83941b', 1, 'State the distributive property and model it with area.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_de9516b40b4ca3', 'les_862d74cf83941b', 2, 'Expand expressions such as −3(2x − 5) correctly, including signs.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ad51d3639c16e9', 'les_862d74cf83941b', 3, 'Factor out the greatest common factor from a simple expression.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9dbf9e3990f171', 'les_862d74cf83941b', 'learn', 1, 'definition', '{"term":"Distributive property","body":"For any numbers $a$, $b$ and $c$: $a(b + c) = ab + ac$ and $a(b - c) = ab - ac$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_de9516b40b4ca3', 'les_862d74cf83941b', 'learn', 2, 'text', '{"body":"Picture a rectangle with width $a$ and length $b + c$. Its area is $a(b + c)$, but you can also split it into two rectangles with areas $ab$ and $ac$. Both descriptions measure the same area, so they are equal."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ad51d3639c16e9', 'les_862d74cf83941b', 'experiment', 3, 'activity', '{"activity":"area-model","title":"See distribution as area","params":{"a":1,"b":4,"c":1,"d":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bbf0f6b6b11b23', 'les_862d74cf83941b', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"The area model shows two binomials multiplied. Treat the side length $x + 3$ as \"the factor being distributed\": the top row is $x \\cdot (x + 4)$ and the bottom row is $3 \\cdot (x + 4)$. Make $d$ negative and watch the bottom row turn red."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e90f67b294539e', 'les_862d74cf83941b', 'learn', 5, 'worked_example', '{"title":"Expand $4(3x + 7)$","steps":[{"latex":"4 \\cdot 3x + 4 \\cdot 7","explanation":"Multiply 4 by each term inside."},{"latex":"12x + 28","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_366846d19122f3', 'les_862d74cf83941b', 'learn', 6, 'worked_example', '{"title":"Expand $-3(2x - 5)$","steps":[{"latex":"(-3)(2x) + (-3)(-5)","explanation":"The −3 multiplies both terms, including the −5."},{"latex":"-6x + 15","explanation":"Negative times negative is positive."}],"check":"Check with $x = 1$: $-3(2 - 5) = -3(-3) = 9$ and $-6 + 15 = 9$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fba9d3dd6d8f7e', 'les_862d74cf83941b', 'learn', 7, 'worked_example', '{"title":"Simplify $-(x - 8)$ and $\\tfrac{1}{2}(6y + 10)$","steps":[{"latex":"-(x - 8) = -1(x - 8) = -x + 8","explanation":"A minus sign in front of parentheses means −1 times."},{"latex":"\\tfrac{1}{2}(6y + 10) = 3y + 5","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a7086c65777578', 'les_862d74cf83941b', 'learn', 8, 'text', '{"body":"Running the property backwards is called factoring out a common factor. In $12x + 18$, both terms are divisible by 6, so $12x + 18 = 6(2x + 3)$. Using the greatest common factor leaves no common factor inside the parentheses."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ade3f7bec63783', 'les_862d74cf83941b', 'learn', 9, 'callout', '{"tone":"warning","title":"Distribute to every term","body":"$5(x + 2) \\ne 5x + 2$. The 5 multiplies the 2 as well: $5x + 10$. And $-2(x - 4) \\ne -2x - 8$; the second term is $(-2)(-4) = +8$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_36ca604e7d3212', 'les_862d74cf83941b', 'learn', 10, 'callout', '{"tone":"application","title":"Mental math","body":"To compute $7 \\times 98$ in your head, think $7(100 - 2) = 700 - 14 = 686$. To find the cost of 6 items at 4.95 dollars, think $6(5 - 0.05) = 30 - 0.30 = 29.70$ dollars."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9dbf9e3990f171', 'les_862d74cf83941b', 1, 'practice', 'short_text', 1, 'Expand $6(x + 4)$.', '{"accept":["6x+24","24+6x"]}', '["Multiply 6 by x and by 4."]', '$6x + 24$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_de9516b40b4ca3', 'les_862d74cf83941b', 2, 'practice', 'short_text', 1, 'Expand $-2(5a - 3)$.', '{"accept":["-10a+6","6-10a"]}', '["$(-2)(-3) = +6$."]', '$-10a + 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ad51d3639c16e9', 'les_862d74cf83941b', 3, 'practice', 'short_text', 2, 'Expand $-(4 - 3y)$.', '{"accept":["-4+3y","3y-4"]}', '["Multiply each term by −1."]', '$-4 + 3y$, or $3y - 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bbf0f6b6b11b23', 'les_862d74cf83941b', 4, 'practice', 'short_text', 2, 'Expand $\tfrac{2}{3}(9m - 12)$.', '{"accept":["6m-8","-8+6m"]}', '["$\\frac{2}{3} \\cdot 9 = 6$ and $\\frac{2}{3} \\cdot 12 = 8$."]', '$6m - 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e90f67b294539e', 'les_862d74cf83941b', 5, 'practice', 'short_text', 2, 'Factor out the greatest common factor: $15x + 25$.', '{"accept":["5(3x+5)","5(5+3x)"]}', '["What is the GCF of 15 and 25?"]', '$5(3x + 5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_366846d19122f3', 'les_862d74cf83941b', 6, 'practice', 'multiple_choice', 2, 'Which expression is equivalent to $-4(x - 2y + 1)$?', '{"choices":["$-4x - 8y - 4$","$-4x + 8y - 4$","$-4x + 2y + 1$","$-4x - 2y - 4$"],"answer":1}', '["Multiply each of the three terms by −4."]', '$(-4)(x) + (-4)(-2y) + (-4)(1) = -4x + 8y - 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fba9d3dd6d8f7e', 'les_862d74cf83941b', 7, 'review', 'short_text', 3, 'Use the distributive property to compute $8 \times 103$ mentally. Enter the product.', '{"accept":["824"]}', '["$8(100 + 3)$."]', '$800 + 24 = 824$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a7086c65777578', 'les_862d74cf83941b', 8, 'review', 'short_text', 3, 'Factor out the GCF, including a negative sign so the first term inside is positive: $-14x - 21$.', '{"accept":["-7(2x+3)","-7(3+2x)"]}', '["The GCF of 14 and 21 is 7.","Factor out −7."]', '$-7(2x + 3)$. Check: $-7 \cdot 2x = -14x$ and $-7 \cdot 3 = -21$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_862d74cf83941b', 'subj_math', 'distributive-property', 'Distributive property', 'a(b + c) = ab + ac: multiplication distributes over addition and subtraction.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_862d74cf83941b', (SELECT id FROM concepts WHERE slug = 'distributive-property'));

-- Lesson: domain-and-range
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ef397d2327021c', 'domain-and-range', 'Domain and range', 'Find the domain and range of functions from sets, graphs, equations and real situations, and write them in interval notation.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_581b994efe07be', 'les_ef397d2327021c', 1, 'Define domain and range and find them for a set of ordered pairs or a graph.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1c089a3863c22e', 'les_ef397d2327021c', 2, 'Identify domain restrictions from equations: division by zero and even roots of negatives.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f33782fad77aa8', 'les_ef397d2327021c', 3, 'Choose a reasonable domain and range for a real-world situation, including discrete domains.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_581b994efe07be', 'les_ef397d2327021c', 'learn', 1, 'definition', '{"term":"Domain","body":"The set of all allowed inputs of a function."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1c089a3863c22e', 'les_ef397d2327021c', 'learn', 2, 'definition', '{"term":"Range","body":"The set of all outputs the function actually produces from its domain."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f33782fad77aa8', 'les_ef397d2327021c', 'learn', 3, 'worked_example', '{"title":"Find the domain and range of $\\{(-2, 5), (0, 3), (1, 5), (4, -1)\\}$","steps":[{"latex":"D = \\{-2, 0, 1, 4\\}","explanation":"List the x-values."},{"latex":"R = \\{-1, 3, 5\\}","explanation":"List the y-values; write 5 only once."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4b1c89ea5e6d2d', 'les_ef397d2327021c', 'learn', 4, 'text', '{"body":"From a graph, the domain is the shadow the graph casts on the $x$-axis and the range is its shadow on the $y$-axis. Arrows mean the graph keeps going; closed dots are included endpoints and open dots are excluded."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9365d8fcf4421d', 'les_ef397d2327021c', 'experiment', 5, 'activity', '{"activity":"vertex-explorer","title":"Range of a parabola","params":{"a":1,"h":1,"k":-3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c0aca1fc447425', 'les_ef397d2327021c', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Every parabola $y = a(x - h)^2 + k$ has domain all real numbers. Drag the vertex and watch: when it opens up, the range is $y \\ge k$; when it opens down, $y \\le k$. What determines which?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_053eb26cffad04', 'les_ef397d2327021c', 'learn', 7, 'worked_example', '{"title":"Find the domain of $f(x) = \\dfrac{5}{x - 3}$ and $g(x) = \\sqrt{x + 4}$","steps":[{"latex":"x - 3 \\ne 0 \\Rightarrow x \\ne 3","explanation":"Division by zero is undefined."},{"latex":"D_f = (-\\infty, 3) \\cup (3, \\infty)","explanation":"Every real number except 3."},{"latex":"x + 4 \\ge 0 \\Rightarrow x \\ge -4","explanation":"A square root of a negative is not a real number."},{"latex":"D_g = [-4, \\infty),\\quad R_g = [0, \\infty)","explanation":"A principal square root is never negative."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_796e4b5239e5e4', 'les_ef397d2327021c', 'learn', 8, 'worked_example', '{"title":"A theater sells tickets at 12 dollars each and has 250 seats. Revenue is $R(n) = 12n$. Give a reasonable domain and range.","steps":[{"latex":"D = \\{0, 1, 2, \\dots, 250\\}","explanation":"You can''t sell a fraction of a ticket or more than 250 tickets."},{"latex":"R = \\{0, 12, 24, \\dots, 3000\\}","explanation":"Multiples of 12 from 0 to 12 · 250."}],"check":"The domain is discrete: separate whole numbers, not an interval. Its graph is a set of dots, not a solid line."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3f139884804324', 'les_ef397d2327021c', 'learn', 9, 'callout', '{"tone":"warning","title":"Range is not just the y-values you see on a grid","body":"For $y = x^2$, the window might show $y$ up to 10, but the range is $[0, \\infty)$. Think about what the function can produce, not what the screen happens to show."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_915cc4674c350a', 'les_ef397d2327021c', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Every app input has a domain: an age field shouldn''t accept $-3$, and a calculator returns an error for $\\sqrt{-1}$ or $1 \\div 0$ because those inputs are outside the domain."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_581b994efe07be', 'les_ef397d2327021c', 1, 'practice', 'short_text', 1, 'What is the domain of $\{(3, 7), (-1, 2), (5, 7)\}$? List the values smallest first, separated by commas.', '{"accept":["-1,3,5"]}', '["The domain is the set of x-values."]', '$\{-1, 3, 5\}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1c089a3863c22e', 'les_ef397d2327021c', 2, 'practice', 'short_text', 1, 'What is the range of $\{(3, 7), (-1, 2), (5, 7)\}$? List the values smallest first.', '{"accept":["2,7"]}', '["List each y-value once."]', '$\{2, 7\}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f33782fad77aa8', 'les_ef397d2327021c', 3, 'practice', 'multiple_choice', 2, 'What is the domain of $f(x) = \frac{1}{x + 6}$?', '{"choices":["All real numbers","$x \\ne 6$","$x \\ne -6$","$x > -6$"],"answer":2}', '["Which input makes the denominator zero?"]', '$x + 6 = 0$ when $x = -6$, so $x \ne -6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4b1c89ea5e6d2d', 'les_ef397d2327021c', 4, 'practice', 'multiple_choice', 2, 'What is the domain of $g(x) = \sqrt{2x - 8}$?', '{"choices":["$x \\ge 4$","$x \\ge 8$","$x > 4$","All real numbers"],"answer":0}', '["Require $2x - 8 \\ge 0$."]', '$2x \ge 8$, so $x \ge 4$: $[4, \infty)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9365d8fcf4421d', 'les_ef397d2327021c', 5, 'practice', 'multiple_choice', 2, 'What is the range of $y = -(x - 2)^2 + 5$?', '{"choices":["$y \\ge 5$","$y \\le 5$","$y \\le 2$","All real numbers"],"answer":1}', '["Which way does the parabola open, and where is its vertex?"]', 'It opens down with vertex $(2, 5)$, so the greatest output is 5: $(-\infty, 5]$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c0aca1fc447425', 'les_ef397d2327021c', 6, 'review', 'multiple_choice', 3, 'A car''s gas tank holds 15 gallons and the car gets 30 miles per gallon. For $d(g) = 30g$, miles driven using $g$ gallons, what is a reasonable domain?', '{"choices":["$g \\ge 0$","$0 \\le g \\le 15$","$0 \\le g \\le 450$","$g = 15$"],"answer":1}', '["How much gas can the tank hold?"]', 'The car can use between 0 and 15 gallons from a full tank, so $0 \le g \le 15$. The range is $0 \le d \le 450$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_053eb26cffad04', 'les_ef397d2327021c', 7, 'review', 'short_text', 3, 'Write the domain of $f(x) = \frac{x}{x^2 - 9}$ by listing the excluded values, smaller first, separated by a comma.', '{"accept":["-3,3"]}', '["$x^2 - 9 = 0$ when $x = \\pm 3$."]', '$x \ne -3$ and $x \ne 3$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_0f4f885c0b63c2', 'subj_math', 'domain-range', 'Domain and range', 'The set of possible inputs and the set of resulting outputs of a function.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ef397d2327021c', (SELECT id FROM concepts WHERE slug = 'domain-range'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_26afa03b5cfa25', 'subj_math', 'interval-notation', 'Interval notation', 'Writing sets of real numbers as intervals using brackets and parentheses.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ef397d2327021c', (SELECT id FROM concepts WHERE slug = 'interval-notation'));

-- Lesson: evaluating-expressions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a2545a9f79e9d1', 'evaluating-expressions', 'Evaluating expressions', 'Substitute values, including negatives and fractions, into expressions and formulas and evaluate them with the order of operations.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0120364f4ded3c', 'les_a2545a9f79e9d1', 1, 'Substitute values for variables using parentheses to protect signs.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_95bdda897c4775', 'les_a2545a9f79e9d1', 2, 'Evaluate expressions with exponents, fractions and several variables.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_61c66ebb6b668a', 'les_a2545a9f79e9d1', 3, 'Evaluate real formulas and interpret the result with units.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0120364f4ded3c', 'les_a2545a9f79e9d1', 'learn', 1, 'text', '{"body":"To evaluate an expression, replace every variable with its value and then simplify using the order of operations. The expression itself doesn''t change; you are simply asking what number it represents for one particular choice of the variables."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_95bdda897c4775', 'les_a2545a9f79e9d1', 'learn', 2, 'callout', '{"tone":"tip","title":"Always substitute in parentheses","body":"Write $x = -4$ as $(-4)$. Then $x^2$ becomes $(-4)^2 = 16$, and $3x$ becomes $3(-4) = -12$. Leaving out the parentheses is the most common source of sign errors."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_61c66ebb6b668a', 'les_a2545a9f79e9d1', 'learn', 3, 'worked_example', '{"title":"Evaluate $x^2 - 5x + 6$ when $x = -3$","steps":[{"latex":"(-3)^2 - 5(-3) + 6","explanation":"Substitute in parentheses."},{"latex":"9 + 15 + 6","explanation":"(−3)² = 9 and −5(−3) = +15."},{"latex":"30","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4fbbe857d92368', 'les_a2545a9f79e9d1', 'learn', 4, 'worked_example', '{"title":"Evaluate $\\dfrac{a - b}{2c}$ when $a = 7$, $b = -5$, $c = \\tfrac{3}{2}$","steps":[{"latex":"\\dfrac{7 - (-5)}{2\\left(\\tfrac{3}{2}\\right)}","explanation":"Substitute every variable."},{"latex":"\\dfrac{12}{3}","explanation":"Numerator: 7 + 5 = 12. Denominator: 2 · 3/2 = 3."},{"latex":"4","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aaebe4b3d2e74f', 'les_a2545a9f79e9d1', 'learn', 5, 'worked_example', '{"title":"The formula $F = \\tfrac{9}{5}C + 32$ converts Celsius to Fahrenheit. Convert $-15^\\circ$C.","steps":[{"latex":"F = \\tfrac{9}{5}(-15) + 32","explanation":"Substitute C = −15."},{"latex":"F = -27 + 32","explanation":"$\\frac{9}{5} \\cdot (-15) = -27$."},{"latex":"F = 5","explanation":"So $-15^\\circ\\text{C} = 5^\\circ\\text{F}$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fb88cf2f97bda5', 'les_a2545a9f79e9d1', 'learn', 6, 'worked_example', '{"title":"A ball is thrown upward. Its height in feet after $t$ seconds is $h = -16t^2 + 48t + 5$. Find $h$ when $t = 2$.","steps":[{"latex":"-16(2)^2 + 48(2) + 5","explanation":""},{"latex":"-64 + 96 + 5 = 37","explanation":"Exponent first: −16 · 4 = −64."}],"check":"After 2 seconds the ball is 37 feet above the ground."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_62323127c22419', 'les_a2545a9f79e9d1', 'learn', 7, 'callout', '{"tone":"warning","title":"Implied multiplication","body":"$3xy$ means $3 \\cdot x \\cdot y$, and $2(x + 1)$ means 2 times the whole sum. With $x = 4$, $2(x + 1) = 2(5) = 10$, not $2 \\cdot 4 + 1 = 9$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d2a2121abe1ae1', 'les_a2545a9f79e9d1', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Formulas are expressions waiting for values: area $A = lw$, distance $d = rt$, simple interest $I = Prt$, and spreadsheet cells like =B2*C2+D2 all work by substitution."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0120364f4ded3c', 'les_a2545a9f79e9d1', 1, 'practice', 'numeric', 1, 'Evaluate $4x - 7$ when $x = -2$.', '{"answer":-15}', '["Substitute (−2) for x."]', '$4(-2) - 7 = -8 - 7 = -15$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_95bdda897c4775', 'les_a2545a9f79e9d1', 2, 'practice', 'numeric', 1, 'Evaluate $3a + 2b$ when $a = 5$ and $b = -4$.', '{"answer":7}', '[]', '$15 + (-8) = 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_61c66ebb6b668a', 'les_a2545a9f79e9d1', 3, 'practice', 'numeric', 2, 'Evaluate $-x^2 + 3x$ when $x = -1$.', '{"answer":-4}', '["$-(-1)^2 = -1$.","$3(-1) = -3$."]', '$-1 - 3 = -4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4fbbe857d92368', 'les_a2545a9f79e9d1', 4, 'practice', 'numeric', 2, 'Evaluate $\dfrac{m^2 - n}{m + n}$ when $m = 4$ and $n = -2$.', '{"answer":9}', '["Numerator: 16 − (−2).","Denominator: 4 + (−2)."]', '$\frac{18}{2} = 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aaebe4b3d2e74f', 'les_a2545a9f79e9d1', 5, 'practice', 'numeric', 2, 'Use $d = rt$ to find the distance in miles traveled at 55 mph for 2.5 hours.', '{"answer":137.5,"unit":"mi"}', '[]', '$55 \times 2.5 = 137.5$ miles.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fb88cf2f97bda5', 'les_a2545a9f79e9d1', 6, 'practice', 'multiple_choice', 2, 'What is the value of $2(x + 3)^2$ when $x = -5$?', '{"choices":["8","−8","16","4"],"answer":0}', '["Inside first: $-5 + 3 = -2$.","$(-2)^2 = 4$."]', '$2(4) = 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_62323127c22419', 'les_a2545a9f79e9d1', 7, 'review', 'numeric', 3, 'The perimeter of a rectangle is $P = 2l + 2w$. Find $P$ when $l = 3\tfrac{1}{4}$ ft and $w = 2\tfrac{1}{2}$ ft.', '{"answer":11.5,"unit":"ft"}', '["$2 \\cdot 3.25 + 2 \\cdot 2.5$."]', '$6.5 + 5 = 11.5$ ft.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d2a2121abe1ae1', 'les_a2545a9f79e9d1', 8, 'review', 'short_text', 3, 'Using $F = \tfrac{9}{5}C + 32$, what Celsius temperature equals $-40^\circ$F? Enter just the number.', '{"accept":["-40"]}', '["Set $-40 = \\tfrac{9}{5}C + 32$ and solve, or try $C = -40$."]', '$\tfrac{9}{5}(-40) + 32 = -72 + 32 = -40$. The two scales agree at $-40$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a6288710b74b75', 'subj_math', 'substitution', 'Substitution', 'Replacing a variable with a value to evaluate an expression.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a2545a9f79e9d1', (SELECT id FROM concepts WHERE slug = 'substitution'));

-- Lesson: exponential-growth-decay
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6970e3e2c814da', 'exponential-growth-decay', 'Exponential growth and decay', 'Model quantities that change by a constant percent with y = a·bˣ, identify growth and decay factors, and apply them to populations, money and depreciation.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e4e6251114b539', 'les_6970e3e2c814da', 1, 'Identify the initial value and growth or decay factor in y = a·bˣ.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_760eb8705c560d', 'les_6970e3e2c814da', 2, 'Convert between a percent rate and a growth or decay factor.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_36ca1d4bb61704', 'les_6970e3e2c814da', 3, 'Write and use exponential models, including compound interest and half-life.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e4e6251114b539', 'les_6970e3e2c814da', 'learn', 1, 'text', '{"body":"A linear function adds the same amount each step. An exponential function multiplies by the same factor each step. A town of 5,000 people growing 4% a year gains 200 people the first year, 208 the next, then 216.32: the amount added keeps growing because each 4% is taken of a larger population."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_760eb8705c560d', 'les_6970e3e2c814da', 'learn', 2, 'formula', '{"latex":"y = a \\cdot b^x","title":"Exponential function","note":"$a$ is the initial value ($y$ at $x = 0$) and $b > 0$, $b \\neq 1$, is the factor for each unit of $x$. $b > 1$: growth. $0 < b < 1$: decay."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_36ca1d4bb61704', 'les_6970e3e2c814da', 'learn', 3, 'definition', '{"term":"Percent rate and factor","body":"Growth by $r$ (as a decimal) per step: $b = 1 + r$. Decay by $r$ per step: $b = 1 - r$. A 4% increase is $b = 1.04$; a 15% decrease is $b = 0.85$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bcd2ceee8ecaa5', 'les_6970e3e2c814da', 'experiment', 4, 'activity', '{"activity":"growth-models","title":"Change the factor","params":{"a":5,"b":1.2,"d":2,"compare":false}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4623bf295cd603', 'les_6970e3e2c814da', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Start at 5 with factor 1.2. Then try 0.8. Which values of $b$ make the curve rise and which make it fall? What happens exactly at $b = 1$?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1b45b2e4a35029', 'les_6970e3e2c814da', 'learn', 6, 'worked_example', '{"title":"A town has 5,000 people and grows 4% per year. Model the population and find it after 10 years.","steps":[{"latex":"P(t) = 5000(1.04)^t","explanation":"a = 5000, b = 1 + 0.04."},{"latex":"P(10) = 5000(1.04)^{10} \\approx 7401","explanation":"$1.04^{10} \\approx 1.4802$."}],"check":"Linear growth of 200 per year would give only 7,000. The extra 401 comes from growth on growth."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3ee482730e9166', 'les_6970e3e2c814da', 'learn', 7, 'worked_example', '{"title":"A car bought for 28,000 dollars loses 15% of its value each year. What is it worth after 4 years?","steps":[{"latex":"V(t) = 28000(0.85)^t","explanation":"Decay factor 1 − 0.15."},{"latex":"V(4) = 28000(0.85)^4 \\approx 14{,}616","explanation":"$0.85^4 \\approx 0.5220$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4cccdcdef02b98', 'les_6970e3e2c814da', 'learn', 8, 'worked_example', '{"title":"A 1,000-dollar deposit earns 6% interest compounded monthly. Find the balance after 5 years.","steps":[{"latex":"A = 1000\\left(1 + \\tfrac{0.06}{12}\\right)^{12 \\cdot 5}","explanation":"Rate per month is 0.06/12 = 0.005, and there are 60 months."},{"latex":"= 1000(1.005)^{60} \\approx 1348.85","explanation":""}],"check":"Simple interest at 6% would give 1,300 dollars; compounding adds 48.85 dollars."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1248f3f679d7db', 'les_6970e3e2c814da', 'learn', 9, 'worked_example', '{"title":"A medicine has a half-life of 6 hours. Of a 400 mg dose, how much remains after 24 hours?","steps":[{"latex":"M(t) = 400\\left(\\tfrac{1}{2}\\right)^{t/6}","explanation":"It halves once every 6 hours."},{"latex":"M(24) = 400\\left(\\tfrac{1}{2}\\right)^4 = 25 \\text{ mg}","explanation":"24 hours is 4 half-lives."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_62768f2cecef81', 'les_6970e3e2c814da', 'learn', 10, 'callout', '{"tone":"warning","title":"Rate vs factor","body":"Growth of 3% means multiply by 1.03, not by 0.03 and not by 3. Decay of 20% means multiply by 0.80. Writing $y = a(0.20)^x$ would mean losing 80% each step."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f4a0f21ff6e1de', 'les_6970e3e2c814da', 'learn', 11, 'callout', '{"tone":"application","title":"Where this shows up","body":"Savings and loans, populations, viral video views, carbon-14 dating, cooling and the spread of disease early in an outbreak are modeled with exponential functions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e4e6251114b539', 'les_6970e3e2c814da', 1, 'practice', 'multiple_choice', 1, 'Which function models exponential decay?', '{"choices":["$y = 3(1.5)^x$","$y = 0.5(2)^x$","$y = 8(0.75)^x$","$y = 2x + 5$"],"answer":2}', '["Look for a factor between 0 and 1."]', '$b = 0.75$ is between 0 and 1, so $y = 8(0.75)^x$ decays.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_760eb8705c560d', 'les_6970e3e2c814da', 2, 'practice', 'numeric', 1, 'What is the growth factor for a 7% annual increase?', '{"answer":1.07}', '["b = 1 + r."]', '$1 + 0.07 = 1.07$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_36ca1d4bb61704', 'les_6970e3e2c814da', 3, 'practice', 'numeric', 2, 'What percent does $y = 200(0.92)^t$ decrease by each step? Enter just the number.', '{"answer":8,"unit":"%"}', '["1 − 0.92."]', '$1 - 0.92 = 0.08$, an 8% decrease.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bcd2ceee8ecaa5', 'les_6970e3e2c814da', 4, 'practice', 'numeric', 2, 'A bacteria culture starts with 300 cells and doubles every hour. How many cells after 5 hours?', '{"answer":9600}', '["$300 \\cdot 2^5$."]', '$300 \cdot 32 = 9600$ cells.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4623bf295cd603', 'les_6970e3e2c814da', 5, 'practice', 'numeric', 2, 'A laptop costs 1,200 dollars and loses 20% of its value each year. What is it worth after 3 years, in dollars?', '{"answer":614.4,"unit":"dollars"}', '["$1200(0.8)^3$."]', '$1200 \cdot 0.512 = 614.40$ dollars.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1b45b2e4a35029', 'les_6970e3e2c814da', 6, 'practice', 'numeric', 3, '2,500 dollars is invested at 4% interest compounded annually. To the nearest cent, what is the balance after 8 years?', '{"answer":3421.42,"unit":"dollars","tolerance":0.01}', '["$2500(1.04)^8$.","$1.04^8 \\approx 1.368569$."]', '$2500 \cdot 1.3685690504 \approx 3421.42$ dollars.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3ee482730e9166', 'les_6970e3e2c814da', 7, 'review', 'numeric', 3, 'A radioactive sample of 80 g has a half-life of 5 days. How many grams remain after 15 days?', '{"answer":10,"unit":"g"}', '["15 days is 3 half-lives."]', '$80 \cdot \left(\frac{1}{2}\right)^3 = 10$ g.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_995fc7b1dd6d9d', 'subj_math', 'exponential-functions', 'Exponential functions', 'Functions of the form y = a·bˣ that change by a constant factor.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6970e3e2c814da', (SELECT id FROM concepts WHERE slug = 'exponential-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_6970e3e2c814da', (SELECT id FROM formulas WHERE slug = 'exponential-function'), 1);

-- Lesson: exponents-square-roots
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3118326eb4bbec', 'exponents-square-roots', 'Exponents and square roots', 'Read and evaluate powers, including negative bases and zero exponents, and find and estimate square roots.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d89c5802a01fb2', 'les_3118326eb4bbec', 1, 'Write repeated multiplication with exponents and evaluate powers.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7ddb118cb96c6b', 'les_3118326eb4bbec', 2, 'Distinguish between (−a)ⁿ and −aⁿ.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dbcdfdaf188e85', 'les_3118326eb4bbec', 3, 'Find square roots of perfect squares and estimate other square roots between consecutive integers.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d89c5802a01fb2', 'les_3118326eb4bbec', 'learn', 1, 'definition', '{"term":"Power","body":"$a^n$ means $n$ factors of $a$: $a^n = a \\cdot a \\cdots a$. In $2^5$, 2 is the base and 5 is the exponent: $2^5 = 2 \\cdot 2 \\cdot 2 \\cdot 2 \\cdot 2 = 32$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7ddb118cb96c6b', 'les_3118326eb4bbec', 'learn', 2, 'text', '{"body":"Squares and cubes get their names from geometry: a square with side 4 has area $4^2 = 16$, and a cube with edge 4 has volume $4^3 = 64$. Any number to the first power is itself ($9^1 = 9$), and any nonzero number to the zero power is 1 ($9^0 = 1$). The zero-power rule comes from patterns: $3^3 = 27$, $3^2 = 9$, $3^1 = 3$, so each step divides by 3 and the next step gives $3^0 = 1$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dbcdfdaf188e85', 'les_3118326eb4bbec', 'learn', 3, 'callout', '{"tone":"warning","title":"Parentheses matter","body":"$(-5)^2 = (-5)(-5) = 25$, but $-5^2 = -(5 \\cdot 5) = -25$. The exponent applies only to what is directly in front of it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ea63984e90e2c3', 'les_3118326eb4bbec', 'learn', 4, 'definition', '{"term":"Square root","body":"$\\sqrt{n}$ (the principal square root) is the nonnegative number whose square is $n$. $\\sqrt{49} = 7$ because $7^2 = 49$. Both 7 and $-7$ square to 49, but the symbol $\\sqrt{\\phantom{x}}$ means the nonnegative one."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_995db21d2d9a3b', 'les_3118326eb4bbec', 'learn', 5, 'text', '{"body":"Numbers like 1, 4, 9, 16, 25, 36, 49, 64, 81, 100, 121 and 144 are perfect squares: their square roots are whole numbers. Other square roots are irrational decimals, but you can estimate them. Since $36 < 40 < 49$, $\\sqrt{40}$ is between 6 and 7, and closer to 6."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_974827b49e2e1d', 'les_3118326eb4bbec', 'learn', 6, 'worked_example', '{"title":"Evaluate $(-2)^3 + 4^2 - 10^0$","steps":[{"latex":"(-2)^3 = -8","explanation":"Three negative factors: negative."},{"latex":"4^2 = 16, \\quad 10^0 = 1","explanation":""},{"latex":"-8 + 16 - 1 = 7","explanation":"Combine left to right."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f3fb37aadabea7', 'les_3118326eb4bbec', 'learn', 7, 'worked_example', '{"title":"Estimate $\\sqrt{70}$ to one decimal place","steps":[{"latex":"64 < 70 < 81 \\Rightarrow 8 < \\sqrt{70} < 9","explanation":"Find the perfect squares on each side."},{"latex":"8.3^2 = 68.89, \\quad 8.4^2 = 70.56","explanation":"Test tenths near the lower end."},{"latex":"\\sqrt{70} \\approx 8.4","explanation":"70 is closer to 70.56 than to 68.89."}],"check":"A calculator gives $\\sqrt{70} = 8.3666\\ldots$, which rounds to 8.4."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f7f0456aa4f265', 'les_3118326eb4bbec', 'learn', 8, 'worked_example', '{"title":"Evaluate $\\sqrt{\\tfrac{9}{25}}$ and $\\sqrt{0.16}$","steps":[{"latex":"\\sqrt{\\tfrac{9}{25}} = \\tfrac{3}{5}","explanation":"Because $\\left(\\frac{3}{5}\\right)^2 = \\frac{9}{25}$."},{"latex":"\\sqrt{0.16} = 0.4","explanation":"Because $0.4^2 = 0.16$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3c82a389bf521b', 'les_3118326eb4bbec', 'learn', 9, 'callout', '{"tone":"note","title":"Negative numbers under the root","body":"$\\sqrt{-9}$ is not a real number: no real number squared gives a negative. (In Algebra 2 you''ll meet the imaginary number $i$, which handles this.)"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5eb6460ea1210c', 'les_3118326eb4bbec', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"A square garden with area 50 square meters has sides $\\sqrt{50} \\approx 7.07$ m. Bacteria that double every hour multiply by $2^{10} = 1024$ in ten hours."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d89c5802a01fb2', 'les_3118326eb4bbec', 1, 'practice', 'numeric', 1, 'Evaluate $3^4$.', '{"answer":81}', '["Four factors of 3."]', '$3 \cdot 3 \cdot 3 \cdot 3 = 81$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7ddb118cb96c6b', 'les_3118326eb4bbec', 2, 'practice', 'numeric', 1, 'Evaluate $\sqrt{121}$.', '{"answer":11}', '["What number times itself is 121?"]', '$11^2 = 121$, so $\sqrt{121} = 11$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dbcdfdaf188e85', 'les_3118326eb4bbec', 3, 'practice', 'numeric', 2, 'Evaluate $-4^2$.', '{"answer":-16}', '["The exponent applies only to 4."]', '$-4^2 = -(4^2) = -16$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ea63984e90e2c3', 'les_3118326eb4bbec', 4, 'practice', 'numeric', 2, 'Evaluate $(-1)^{7} + (-1)^{8}$.', '{"answer":0}', '["Odd number of negative factors gives −1; even gives 1."]', '$-1 + 1 = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_995db21d2d9a3b', 'les_3118326eb4bbec', 5, 'practice', 'multiple_choice', 2, 'Between which two consecutive integers is $\sqrt{55}$?', '{"choices":["5 and 6","6 and 7","7 and 8","27 and 28"],"answer":2}', '["Which perfect squares are just below and above 55?"]', '$49 < 55 < 64$, so $7 < \sqrt{55} < 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_974827b49e2e1d', 'les_3118326eb4bbec', 6, 'practice', 'numeric', 2, 'Evaluate $\left(\tfrac{2}{3}\right)^3$. Enter a fraction.', '{"answer":0.2962962962962963,"tolerance":0.000001}', '["Cube the numerator and the denominator."]', '$\frac{2^3}{3^3} = \frac{8}{27}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f3fb37aadabea7', 'les_3118326eb4bbec', 7, 'practice', 'numeric', 2, 'A square tile has an area of 144 square inches. What is the length of one side, in inches?', '{"answer":12,"unit":"in"}', '["Side × side = area."]', '$\sqrt{144} = 12$ inches.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f7f0456aa4f265', 'les_3118326eb4bbec', 8, 'review', 'numeric', 3, 'Evaluate $2^5 - 5^2 + 7^0 - \sqrt{36}$.', '{"answer":2}', '["$2^5 = 32$, $5^2 = 25$, $7^0 = 1$, $\\sqrt{36} = 6$."]', '$32 - 25 + 1 - 6 = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3c82a389bf521b', 'les_3118326eb4bbec', 9, 'review', 'short_text', 3, 'Estimate $\sqrt{30}$ to the nearest tenth.', '{"accept":["5.5"]}', '["30 is between 25 and 36.","$5.4^2 = 29.16$ and $5.5^2 = 30.25$."]', '$30$ is closer to $30.25$ than to $29.16$, so $\sqrt{30} \approx 5.5$. (Exact: 5.477…)');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_5268d3a788488b', 'subj_math', 'exponents', 'Exponents', 'Notation for repeated multiplication of a base.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3118326eb4bbec', (SELECT id FROM concepts WHERE slug = 'exponents'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_283755837f95ab', 'subj_math', 'square-roots', 'Square roots', 'A number that, multiplied by itself, gives a given number.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3118326eb4bbec', (SELECT id FROM concepts WHERE slug = 'square-roots'));

-- Lesson: factoring-trinomials
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_347676a1b6c033', 'factoring-trinomials', 'Factoring trinomials', 'Factor x² + bx + c by finding two numbers with the right product and sum, and factor ax² + bx + c with the ac (grouping) method.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e10a9d31937d33', 'les_347676a1b6c033', 1, 'Factor x² + bx + c by finding integers whose product is c and sum is b.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0c6ce6b321fc21', 'les_347676a1b6c033', 2, 'Use signs of b and c to narrow the search.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_30a972b2612f0f', 'les_347676a1b6c033', 3, 'Factor ax² + bx + c with a ≠ 1 using the ac method, after removing any GCF.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e10a9d31937d33', 'les_347676a1b6c033', 'learn', 1, 'text', '{"body":"Multiplying $(x + p)(x + q)$ gives $x^2 + (p + q)x + pq$. So to factor $x^2 + bx + c$, look for two numbers $p$ and $q$ with product $c$ and sum $b$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0c6ce6b321fc21', 'les_347676a1b6c033', 'learn', 2, 'worked_example', '{"title":"Factor $x^2 + 7x + 12$","steps":[{"latex":"pq = 12,\\ p + q = 7","explanation":"List factor pairs of 12: 1·12, 2·6, 3·4."},{"latex":"3 \\cdot 4 = 12,\\ 3 + 4 = 7","explanation":""},{"latex":"(x + 3)(x + 4)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_30a972b2612f0f', 'les_347676a1b6c033', 'learn', 3, 'callout', '{"tone":"tip","title":"Let the signs guide you","body":"If $c > 0$, both numbers have the same sign as $b$. If $c < 0$, the numbers have opposite signs, and the larger absolute value takes the sign of $b$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d400b66a7705f5', 'les_347676a1b6c033', 'learn', 4, 'worked_example', '{"title":"Factor $x^2 - 2x - 15$","steps":[{"latex":"pq = -15,\\ p + q = -2","explanation":"c is negative: opposite signs."},{"latex":"-5 \\cdot 3 = -15,\\ -5 + 3 = -2","explanation":""},{"latex":"(x - 5)(x + 3)","explanation":""}],"check":"Check: $x^2 + 3x - 5x - 15 = x^2 - 2x - 15$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2d279d290d5bc9', 'les_347676a1b6c033', 'experiment', 5, 'activity', '{"activity":"area-model","title":"Factoring as finding the edges","params":{"a":1,"b":-5,"c":1,"d":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_22822d4192d6c7', 'les_347676a1b6c033', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Set the sliders so the product reads $x^2 + x - 12$. Which edges do you need? Then try $x^2 - 7x + 12$. The constant cell is $bd$ and the middle cells add to the $x$-coefficient."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_22cf5db2fca9d9', 'les_347676a1b6c033', 'learn', 7, 'worked_example', '{"title":"Factor $6x^2 + 11x - 10$ (the ac method)","steps":[{"latex":"ac = 6(-10) = -60,\\ b = 11","explanation":"Find two numbers with product −60 and sum 11."},{"latex":"15 \\cdot (-4) = -60,\\ 15 - 4 = 11","explanation":""},{"latex":"6x^2 + 15x - 4x - 10","explanation":"Split the middle term."},{"latex":"3x(2x + 5) - 2(2x + 5) = (2x + 5)(3x - 2)","explanation":"Factor by grouping."}],"check":"Check: $6x^2 - 4x + 15x - 10$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a42fa7e5866269', 'les_347676a1b6c033', 'learn', 8, 'worked_example', '{"title":"Factor $2x^3 - 8x^2 - 24x$ completely","steps":[{"latex":"2x(x^2 - 4x - 12)","explanation":"Always take out the GCF first."},{"latex":"2x(x - 6)(x + 2)","explanation":"−6 · 2 = −12 and −6 + 2 = −4."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9ffc6fa4760a93', 'les_347676a1b6c033', 'learn', 9, 'callout', '{"tone":"warning","title":"Some trinomials don''t factor","body":"$x^2 + 3x + 5$ has no integer pair with product 5 and sum 3. It is prime over the integers. Later, the quadratic formula will handle these."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e48de71a2630e3', 'les_347676a1b6c033', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Factoring turns a quadratic equation into a product equal to zero, which can then be solved. A ball''s height $-16t^2 + 32t + 48 = -16(t - 3)(t + 1)$ shows it hits the ground at $t = 3$ s."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e10a9d31937d33', 'les_347676a1b6c033', 1, 'practice', 'short_text', 1, 'Factor $x^2 + 9x + 20$.', '{"accept":["(x+4)(x+5)","(x+5)(x+4)"]}', '["Product 20, sum 9."]', '$(x + 4)(x + 5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0c6ce6b321fc21', 'les_347676a1b6c033', 2, 'practice', 'short_text', 2, 'Factor $x^2 - 10x + 21$.', '{"accept":["(x-3)(x-7)","(x-7)(x-3)"]}', '["Product 21, sum −10: both negative."]', '$(x - 3)(x - 7)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_30a972b2612f0f', 'les_347676a1b6c033', 3, 'practice', 'short_text', 2, 'Factor $x^2 + 4x - 32$.', '{"accept":["(x+8)(x-4)","(x-4)(x+8)"]}', '["Product −32, sum 4."]', '$8 \cdot (-4) = -32$ and $8 - 4 = 4$: $(x + 8)(x - 4)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d400b66a7705f5', 'les_347676a1b6c033', 4, 'practice', 'short_text', 2, 'Factor $2x^2 + 7x + 3$.', '{"accept":["(2x+1)(x+3)","(x+3)(2x+1)"]}', '["ac = 6, b = 7: use 6 and 1.","$2x^2 + 6x + x + 3$."]', '$2x(x + 3) + 1(x + 3) = (2x + 1)(x + 3)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2d279d290d5bc9', 'les_347676a1b6c033', 5, 'practice', 'short_text', 3, 'Factor $3x^2 - 10x - 8$.', '{"accept":["(3x+2)(x-4)","(x-4)(3x+2)"]}', '["ac = −24, b = −10: use −12 and 2."]', '$3x^2 - 12x + 2x - 8 = 3x(x - 4) + 2(x - 4) = (3x + 2)(x - 4)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_22822d4192d6c7', 'les_347676a1b6c033', 6, 'review', 'short_text', 3, 'Factor completely: $5x^2 - 5x - 30$.', '{"accept":["5(x-3)(x+2)","5(x+2)(x-3)"]}', '["GCF first: 5."]', '$5(x^2 - x - 6) = 5(x - 3)(x + 2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_22cf5db2fca9d9', 'les_347676a1b6c033', 7, 'review', 'multiple_choice', 3, 'Which trinomial cannot be factored over the integers?', '{"choices":["$x^2 + 5x + 6$","$x^2 - x - 6$","$x^2 + 2x + 6$","$x^2 - 5x + 6$"],"answer":2}', '["Look for a pair with product 6 and the given sum."]', 'The integer pairs with product 6 are $1 \cdot 6$, $2 \cdot 3$, $(-1)(-6)$ and $(-2)(-3)$, with sums 7, 5, −7 and −5. None sums to 2, so $x^2 + 2x + 6$ is prime.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_5694f8f8fb67bd', 'subj_math', 'factoring', 'Factoring', 'Writing a polynomial as a product of simpler polynomials.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_347676a1b6c033', (SELECT id FROM concepts WHERE slug = 'factoring'));

-- Lesson: fractions-decimals-percents
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7b07134679a8af', 'fractions-decimals-percents', 'Converting between fractions, decimals and percents', 'Move fluently between the three ways of writing a part of a whole, including percents above 100% and below 1%.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9cef3c85fe57b8', 'les_7b07134679a8af', 1, 'Explain a percent as a ratio out of 100.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_827eb3562bb82e', 'les_7b07134679a8af', 2, 'Convert among fractions, decimals and percents, including mixed numbers and repeating decimals.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_001b9fc4e8cb11', 'les_7b07134679a8af', 3, 'Compare quantities given in different forms.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9cef3c85fe57b8', 'les_7b07134679a8af', 'learn', 1, 'definition', '{"term":"Percent","body":"\"Per cent\" means \"per hundred.\" $p\\%$ means $\\frac{p}{100}$. So $37\\% = \\frac{37}{100} = 0.37$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_827eb3562bb82e', 'les_7b07134679a8af', 'learn', 2, 'text', '{"body":"Fractions, decimals and percents are three names for the same number. Which one is most useful depends on the job: fractions are exact, decimals are easy to compute with, and percents make comparisons out of 100 easy."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_001b9fc4e8cb11', 'les_7b07134679a8af', 'learn', 3, 'worked_example', '{"title":"Percent to decimal and fraction: $45\\%$","steps":[{"latex":"45\\% = 0.45","explanation":"Divide by 100: move the decimal point two places left."},{"latex":"= \\tfrac{45}{100} = \\tfrac{9}{20}","explanation":"Write over 100 and simplify by 5."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e9b96a8dc7d115', 'les_7b07134679a8af', 'learn', 4, 'worked_example', '{"title":"Fraction to percent: $\\frac{3}{8}$","steps":[{"latex":"3 \\div 8 = 0.375","explanation":"Divide to get a decimal."},{"latex":"0.375 \\times 100 = 37.5\\%","explanation":"Multiply by 100: move the decimal point two places right."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d4e0a71bde24b7', 'les_7b07134679a8af', 'learn', 5, 'worked_example', '{"title":"Repeating decimal: $\\frac{2}{3}$ as a percent","steps":[{"latex":"\\tfrac{2}{3} = 0.\\overline{6}","explanation":""},{"latex":"0.\\overline{6} \\times 100 = 66.\\overline{6}\\% = 66\\tfrac{2}{3}\\%","explanation":"Keep it exact, or round to 66.7% if a rounded value is fine."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b40d047ecb7d20', 'les_7b07134679a8af', 'learn', 6, 'text', '{"body":"Percents can be greater than 100 or less than 1. $250\\% = 2.5$ means two and a half times the whole. $0.4\\% = 0.004$ is less than one hundredth."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_09f3bc7665d5da', 'les_7b07134679a8af', 'learn', 7, 'callout', '{"tone":"tip","title":"Benchmarks worth memorizing","body":"$\\frac{1}{2} = 50\\%$, $\\frac{1}{4} = 25\\%$, $\\frac{3}{4} = 75\\%$, $\\frac{1}{5} = 20\\%$, $\\frac{1}{10} = 10\\%$, $\\frac{1}{3} = 33\\frac{1}{3}\\%$, $\\frac{1}{8} = 12.5\\%$. Many other conversions build from these."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f5f5a6800bdb59', 'les_7b07134679a8af', 'learn', 8, 'callout', '{"tone":"warning","title":"Watch the direction","body":"Percent to decimal: divide by 100 ($8\\% = 0.08$, not 0.8). Decimal to percent: multiply by 100 ($0.8 = 80\\%$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_32a56480376f80', 'les_7b07134679a8af', 'experiment', 9, 'activity', '{"activity":"fraction-bars","title":"Compare two fractions","params":{"n1":3,"d1":5,"n2":5,"d2":8,"op":"compare"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3b10a54545dd9f', 'les_7b07134679a8af', 'experiment', 10, 'callout', '{"tone":"tip","title":"Try this","body":"Compare $\\frac{3}{5}$ and $\\frac{5}{8}$. Convert both to percents before reading the result. The decimal readouts show 0.6 and 0.625, so $60\\% < 62.5\\%$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1f5d1576cada73', 'les_7b07134679a8af', 'learn', 11, 'callout', '{"tone":"application","title":"Where this shows up","body":"A test score of 42 out of 48 is $\\frac{42}{48} = 0.875 = 87.5\\%$. Nutrition labels, sports statistics, interest rates and election results all report parts of a whole as percents."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9cef3c85fe57b8', 'les_7b07134679a8af', 1, 'practice', 'numeric', 1, 'Write $64\%$ as a decimal.', '{"answer":0.64}', '["Divide by 100."]', '$64\% = 0.64$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_827eb3562bb82e', 'les_7b07134679a8af', 2, 'practice', 'numeric', 1, 'Write $0.07$ as a percent. Enter just the number of percent.', '{"answer":7,"unit":"%"}', '["Multiply by 100."]', '$0.07 \times 100 = 7\%$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_001b9fc4e8cb11', 'les_7b07134679a8af', 3, 'practice', 'short_text', 1, 'Write $35\%$ as a fraction in simplest form.', '{"accept":["7/20"]}', '["$\\frac{35}{100}$, then divide by 5."]', '$\frac{35}{100} = \frac{7}{20}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e9b96a8dc7d115', 'les_7b07134679a8af', 4, 'practice', 'numeric', 2, 'Write $\frac{7}{8}$ as a percent. Enter just the number.', '{"answer":87.5,"unit":"%"}', '["7 ÷ 8 = 0.875."]', '$0.875 = 87.5\%$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d4e0a71bde24b7', 'les_7b07134679a8af', 5, 'practice', 'numeric', 2, 'Write $1\frac{3}{5}$ as a percent. Enter just the number.', '{"answer":160,"unit":"%"}', '["$1\\frac{3}{5} = 1.6$."]', '$1.6 \times 100 = 160\%$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b40d047ecb7d20', 'les_7b07134679a8af', 6, 'practice', 'numeric', 2, 'Write $0.3\%$ as a decimal.', '{"answer":0.003}', '["Divide by 100."]', '$0.3 \div 100 = 0.003$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_09f3bc7665d5da', 'les_7b07134679a8af', 7, 'practice', 'multiple_choice', 2, 'Which is greatest?', '{"choices":["$\\frac{5}{8}$","$0.6$","$63\\%$","$\\frac{3}{5}$"],"answer":2}', '["Convert all to percents."]', '$\frac{5}{8} = 62.5\%$, $0.6 = 60\%$, $63\%$, $\frac{3}{5} = 60\%$. The greatest is $63\%$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f5f5a6800bdb59', 'les_7b07134679a8af', 8, 'review', 'numeric', 3, 'A team won 18 of its 24 games. What percent did it win? Enter just the number.', '{"answer":75,"unit":"%"}', '["$\\frac{18}{24} = \\frac{3}{4}$."]', '$\frac{18}{24} = 0.75 = 75\%$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_32a56480376f80', 'les_7b07134679a8af', 9, 'review', 'short_text', 3, 'Write $12.5\%$ as a fraction in simplest form.', '{"accept":["1/8"]}', '["$12.5\\% = \\frac{12.5}{100} = \\frac{125}{1000}$."]', '$\frac{125}{1000} = \frac{1}{8}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_56b24954548baa', 'subj_math', 'percent', 'Percent', 'A ratio that compares a number to 100.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7b07134679a8af', (SELECT id FROM concepts WHERE slug = 'percent'));

-- Lesson: function-notation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c81494bd3da8bc', 'function-notation', 'Function notation', 'Read and use f(x) notation: evaluate functions, solve f(x) = k, read values from graphs and interpret function statements in context.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4378d08be2a028', 'les_c81494bd3da8bc', 1, 'Read f(x) as ''the output of f when the input is x'' and avoid reading it as multiplication.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_006389def233c7', 'les_c81494bd3da8bc', 2, 'Evaluate functions for numbers and expressions, and solve f(x) = k for x.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_64c573b6faaed9', 'les_c81494bd3da8bc', 3, 'Interpret statements such as f(3) = 12 in context and from a graph.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4378d08be2a028', 'les_c81494bd3da8bc', 'learn', 1, 'definition', '{"term":"Function notation","body":"If $f$ is a function, $f(x)$ (read \"f of x\") is the output of $f$ for the input $x$. Writing $f(x) = 2x + 3$ names the function $f$ and gives its rule."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_006389def233c7', 'les_c81494bd3da8bc', 'learn', 2, 'callout', '{"tone":"warning","title":"Not multiplication","body":"$f(x)$ does not mean $f$ times $x$. The parentheses hold the input. $f(4)$ means \"put 4 into $f$.\""}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_64c573b6faaed9', 'les_c81494bd3da8bc', 'learn', 3, 'text', '{"body":"Function notation lets you name several functions and say exactly which input you mean. Instead of \"find $y$ when $x = 4$\", you can write $f(4)$. The letter can be anything: $g(t)$, $h(n)$ or $C(m)$ for a cost after $m$ minutes."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d25729171d9d63', 'les_c81494bd3da8bc', 'learn', 4, 'worked_example', '{"title":"Let $f(x) = x^2 - 3x$. Find $f(-2)$ and $f(a + 1)$.","steps":[{"latex":"f(-2) = (-2)^2 - 3(-2) = 4 + 6 = 10","explanation":"Replace every x with (−2)."},{"latex":"f(a + 1) = (a + 1)^2 - 3(a + 1)","explanation":"Replace every x with (a + 1)."},{"latex":"= a^2 + 2a + 1 - 3a - 3 = a^2 - a - 2","explanation":"Expand and combine."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_728a93bb1ee5e9', 'les_c81494bd3da8bc', 'learn', 5, 'worked_example', '{"title":"Let $g(x) = 5 - 2x$. Solve $g(x) = -7$.","steps":[{"latex":"5 - 2x = -7","explanation":"This time the output is given; find the input."},{"latex":"-2x = -12 \\Rightarrow x = 6","explanation":""}],"check":"Check: $g(6) = 5 - 12 = -7$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_646a6d16d20266', 'les_c81494bd3da8bc', 'learn', 6, 'worked_example', '{"title":"$C(m) = 0.15m + 20$ is a monthly phone bill in dollars for $m$ minutes. Interpret $C(300) = 65$.","steps":[{"latex":"C(300) = 0.15(300) + 20 = 65","explanation":""},{"latex":"\\text{300 minutes cost 65 dollars}","explanation":"The input is minutes, the output is dollars."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ed2d964ef158b5', 'les_c81494bd3da8bc', 'learn', 7, 'text', '{"body":"On a graph, $f(a)$ is the $y$-coordinate of the point above (or below) $x = a$. Solving $f(x) = k$ means finding the $x$-values where the graph has height $k$, that is, where it meets the horizontal line $y = k$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8a37ca557f653e', 'les_c81494bd3da8bc', 'learn', 8, 'callout', '{"tone":"tip","title":"Two kinds of question","body":"\"Find $f(5)$\": you know the input, so compute the output. \"Find $x$ such that $f(x) = 5$\": you know the output, so solve an equation. Mixing these up is the most common error."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d84a69d7a8d308', 'les_c81494bd3da8bc', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Spreadsheets and programming languages use exactly this notation: =AVERAGE(B2:B9) or area(5). A function of time, such as $h(t)$ for height, makes physics formulas easy to read."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4378d08be2a028', 'les_c81494bd3da8bc', 1, 'practice', 'numeric', 1, 'If $f(x) = 4x - 9$, find $f(3)$.', '{"answer":3}', '["Replace x with 3."]', '$4(3) - 9 = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_006389def233c7', 'les_c81494bd3da8bc', 2, 'practice', 'numeric', 1, 'If $g(x) = x^2 + 1$, find $g(-4)$.', '{"answer":17}', '["$(-4)^2 = 16$."]', '$16 + 1 = 17$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_64c573b6faaed9', 'les_c81494bd3da8bc', 3, 'practice', 'numeric', 2, 'If $h(t) = -16t^2 + 64t$, find $h(1.5)$.', '{"answer":60}', '["$-16(2.25) + 96$."]', '$-36 + 96 = 60$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d25729171d9d63', 'les_c81494bd3da8bc', 4, 'practice', 'numeric', 2, 'If $f(x) = 3x + 7$, find $x$ so that $f(x) = 25$.', '{"answer":6}', '["Solve $3x + 7 = 25$."]', '$3x = 18$, $x = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_728a93bb1ee5e9', 'les_c81494bd3da8bc', 5, 'practice', 'short_text', 2, 'If $f(x) = 2x - 5$, find $f(x + 3)$ in simplest form.', '{"accept":["2x+1","1+2x"]}', '["Replace x with (x + 3)."]', '$2(x + 3) - 5 = 2x + 6 - 5 = 2x + 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_646a6d16d20266', 'les_c81494bd3da8bc', 6, 'practice', 'multiple_choice', 2, '$T(d)$ is the temperature in °F on day $d$ of March. What does $T(10) = 48$ mean?', '{"choices":["On March 48 it was 10 °F","On March 10 it was 48 °F","The temperature rose 48 degrees in 10 days","T times 10 equals 48"],"answer":1}', '["The input is the day, the output is the temperature."]', 'The input 10 is the day and the output 48 is the temperature.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ed2d964ef158b5', 'les_c81494bd3da8bc', 7, 'review', 'numeric', 3, 'If $f(x) = x^2 - 2x$ and $g(x) = 3x + 1$, find $f(g(1))$.', '{"answer":8}', '["Work from the inside out: g(1) = 4.","Then find f(4)."]', '$g(1) = 4$ and $f(4) = 16 - 8 = 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8a37ca557f653e', 'les_c81494bd3da8bc', 8, 'review', 'short_text', 3, 'If $f(x) = x^2$, solve $f(x) = 49$. Enter both solutions, smaller first.', '{"accept":["-7,7"]}', '["Which numbers squared give 49?"]', '$x = -7$ or $x = 7$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_c81494bd3da8bc', 'subj_math', 'function-notation', 'Function notation', 'Writing f(x) for the output of function f at input x.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c81494bd3da8bc', (SELECT id FROM concepts WHERE slug = 'function-notation'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2f887def33825e', 'subj_math', 'functions', 'Functions', 'Relations that assign exactly one output to each input.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c81494bd3da8bc', (SELECT id FROM concepts WHERE slug = 'functions'));

-- Lesson: graphs-tables-equations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_02b18d150a28b1', 'graphs-tables-equations', 'Graphs, tables and equations', 'Move between verbal descriptions, tables, graphs and equations of a function, and read key features such as intercepts, increasing or decreasing intervals and maximums from a graph.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3d6f2e3728afdd', 'les_02b18d150a28b1', 1, 'Represent the same function as a description, a table, a graph and an equation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_24856cfec5dbc4', 'les_02b18d150a28b1', 2, 'Read intercepts, intervals of increase and decrease, and maximum or minimum values from a graph.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0b4c481134a255', 'les_02b18d150a28b1', 3, 'Decide which representation is most useful for a given question.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3d6f2e3728afdd', 'les_02b18d150a28b1', 'learn', 1, 'text', '{"body":"A function can be described four ways: in words, by a table, by a graph or by an equation. Each answers some questions quickly. An equation gives exact values, a table organizes specific inputs, and a graph shows the overall behavior at a glance."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_24856cfec5dbc4', 'les_02b18d150a28b1', 'learn', 2, 'definition', '{"term":"Key features of a graph","body":"The $x$-intercepts (zeros) are where the graph crosses the $x$-axis ($f(x) = 0$). The $y$-intercept is $f(0)$. A function is increasing on an interval if the graph rises from left to right there, and decreasing if it falls. A maximum or minimum is a highest or lowest point."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0b4c481134a255', 'les_02b18d150a28b1', 'learn', 3, 'worked_example', '{"title":"A drone rises 3 m per second from a 2-m platform for 5 seconds. Represent its height.","steps":[{"latex":"\\text{Equation: } h(t) = 2 + 3t,\\ 0 \\le t \\le 5","explanation":"Start plus rate times time, with a domain from the situation."},{"latex":"\\text{Table: } t = 0, 1, 2, 3, 4, 5 \\to h = 2, 5, 8, 11, 14, 17","explanation":""},{"latex":"\\text{Graph: segment from } (0, 2) \\text{ to } (5, 17)","explanation":"A line segment, because the rate is constant and time is limited."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2e1f51583e6967', 'les_02b18d150a28b1', 'experiment', 4, 'activity', '{"activity":"vertex-explorer","title":"Read the key features","params":{"a":-1,"h":2,"k":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_91146820fc69da', 'les_02b18d150a28b1', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"For this parabola, find the zeros, the vertex and where it increases. It rises until $x = 2$ and falls after. Drag the vertex below the x-axis: what happens to the zeros?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_de935185e0e226', 'les_02b18d150a28b1', 'learn', 6, 'worked_example', '{"title":"Use $f(x) = -(x - 2)^2 + 4$","steps":[{"latex":"f(0) = -4 + 4 = 0","explanation":"y-intercept at (0, 0)."},{"latex":"-(x - 2)^2 + 4 = 0 \\Rightarrow x = 0 \\text{ or } x = 4","explanation":"Zeros: (x − 2)² = 4, so x − 2 = ±2."},{"latex":"\\text{max } 4 \\text{ at } x = 2","explanation":"Increasing for x < 2, decreasing for x > 2."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_10c8804caf6910', 'les_02b18d150a28b1', 'learn', 7, 'callout', '{"tone":"warning","title":"Connect points only when it makes sense","body":"If the input can only be whole numbers (people, tickets, days), the graph is a set of separate dots. Connecting them suggests values like 2.5 tickets that don''t exist."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_59d74ac3b33a07', 'les_02b18d150a28b1', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Weather apps show a temperature graph for the day, a table for each hour, and the forecast in words. Reading the high, the low and when it warms up is reading key features of a function."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3d6f2e3728afdd', 'les_02b18d150a28b1', 1, 'practice', 'numeric', 1, 'For $f(x) = 6 - 2x$, what is the y-intercept (the value of $f(0)$)?', '{"answer":6}', '["Substitute x = 0."]', '$f(0) = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_24856cfec5dbc4', 'les_02b18d150a28b1', 2, 'practice', 'numeric', 1, 'For $f(x) = 6 - 2x$, what is the x-intercept?', '{"answer":3}', '["Solve $6 - 2x = 0$."]', '$x = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0b4c481134a255', 'les_02b18d150a28b1', 3, 'practice', 'multiple_choice', 2, 'A table shows $x$: 0, 1, 2, 3 and $y$: 10, 7, 4, 1. Which equation matches?', '{"choices":["$y = 3x + 10$","$y = -3x + 10$","$y = 10 - x$","$y = -3x + 1$"],"answer":1}', '["What is y at x = 0, and how does y change each step?"]', 'Start at 10 and decrease by 3: $y = -3x + 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2e1f51583e6967', 'les_02b18d150a28b1', 4, 'practice', 'multiple_choice', 2, 'On which interval is $f(x) = (x + 1)^2 - 4$ decreasing?', '{"choices":["$x > -1$","$x < -1$","$x < -4$","$x > 4$"],"answer":1}', '["The parabola opens up with vertex (−1, −4)."]', 'It falls until it reaches the vertex at $x = -1$, so it decreases for $x < -1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_91146820fc69da', 'les_02b18d150a28b1', 5, 'practice', 'short_text', 2, 'Find the zeros of $g(x) = (x - 3)^2 - 9$. Enter both, smaller first.', '{"accept":["0,6"]}', '["$(x - 3)^2 = 9$, so $x - 3 = \\pm 3$."]', '$x = 0$ or $x = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_de935185e0e226', 'les_02b18d150a28b1', 6, 'practice', 'multiple_choice', 2, 'A store sells notebooks for 3 dollars each. Should the graph of cost versus number of notebooks be a solid line?', '{"choices":["Yes, because the rate is constant","No, it should be separate points, because you can only buy whole notebooks","No, it should be a curve","Yes, starting at (0, 3)"],"answer":1}', '["Can you buy 2.5 notebooks?"]', 'The domain is whole numbers, so the graph is a set of discrete points on the line $y = 3x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_10c8804caf6910', 'les_02b18d150a28b1', 7, 'review', 'numeric', 3, 'The height of a ball is $h(t) = -5t^2 + 20t + 1$ meters. What is its maximum height? (The vertex is at $t = 2$.)', '{"answer":21,"unit":"m"}', '["Evaluate h(2)."]', '$h(2) = -20 + 40 + 1 = 21$ m.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_67d79e4caef3ff', 'subj_math', 'multiple-representations', 'Tables, graphs and equations', 'Three linked ways to show the same relationship between two variables.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_02b18d150a28b1', (SELECT id FROM concepts WHERE slug = 'multiple-representations'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2f887def33825e', 'subj_math', 'functions', 'Functions', 'Relations that assign exactly one output to each input.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_02b18d150a28b1', (SELECT id FROM concepts WHERE slug = 'functions'));

-- Lesson: greatest-common-factor
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6727bdd3384dda', 'greatest-common-factor', 'Factoring out the greatest common factor', 'Find the GCF of monomials, factor it out of a polynomial, and factor four-term polynomials by grouping.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e3367819e4dad4', 'les_6727bdd3384dda', 1, 'Find the greatest common factor of two or more monomials.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_af202406155d3f', 'les_6727bdd3384dda', 2, 'Factor the GCF out of a polynomial and check by multiplying.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a2f74f497aa8f8', 'les_6727bdd3384dda', 3, 'Factor four-term polynomials by grouping, including a common binomial factor.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e3367819e4dad4', 'les_6727bdd3384dda', 'learn', 1, 'text', '{"body":"Factoring reverses multiplication. Multiplying turns $3x(x + 4)$ into $3x^2 + 12x$; factoring turns $3x^2 + 12x$ back into $3x(x + 4)$. The first step in every factoring problem is to look for a greatest common factor."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_af202406155d3f', 'les_6727bdd3384dda', 'learn', 2, 'definition', '{"term":"Greatest common factor (GCF) of monomials","body":"The GCF of the coefficients times each variable that appears in every term, raised to its smallest exponent. GCF of $12x^3y^2$ and $18x^2y^5$: $\\gcd(12, 18) = 6$, $x^2$, $y^2$, so $6x^2y^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a2f74f497aa8f8', 'les_6727bdd3384dda', 'learn', 3, 'worked_example', '{"title":"Factor $8x^4 - 20x^3 + 4x^2$","steps":[{"latex":"\\text{GCF} = 4x^2","explanation":"gcd(8, 20, 4) = 4; smallest power of x is 2."},{"latex":"4x^2(2x^2 - 5x + 1)","explanation":"Divide each term by 4x²."}],"check":"Check: $4x^2 \\cdot 2x^2 - 4x^2 \\cdot 5x + 4x^2 \\cdot 1 = 8x^4 - 20x^3 + 4x^2$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e2e8495e02df0a', 'les_6727bdd3384dda', 'learn', 4, 'worked_example', '{"title":"Factor $-6y^3 + 9y$ with a positive leading term inside","steps":[{"latex":"-3y(2y^2 - 3)","explanation":"Factoring out −3y makes the first term inside positive."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3ed136233356a7', 'les_6727bdd3384dda', 'learn', 5, 'worked_example', '{"title":"Factor $5x(x - 2) + 3(x - 2)$","steps":[{"latex":"(x - 2)(5x + 3)","explanation":"The binomial (x − 2) is itself a common factor."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5438870ae0900f', 'les_6727bdd3384dda', 'learn', 6, 'definition', '{"term":"Factoring by grouping","body":"For four terms: group them in pairs, factor the GCF from each pair, then factor out the common binomial."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cf06f801645541', 'les_6727bdd3384dda', 'learn', 7, 'worked_example', '{"title":"Factor $x^3 + 4x^2 + 3x + 12$","steps":[{"latex":"(x^3 + 4x^2) + (3x + 12)","explanation":"Group in pairs."},{"latex":"x^2(x + 4) + 3(x + 4)","explanation":"Factor each pair."},{"latex":"(x + 4)(x^2 + 3)","explanation":"Factor out (x + 4)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4dd31d48dc52a6', 'les_6727bdd3384dda', 'learn', 8, 'callout', '{"tone":"warning","title":"Don''t drop the 1","body":"Factoring $3x$ out of $3x^2 + 3x$ gives $3x(x + 1)$, not $3x(x)$. Each term must leave something behind, and dividing a term by itself leaves 1."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f5fd6890e79279', 'les_6727bdd3384dda', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Factoring out a GCF simplifies formulas, such as $A = 2\\pi r^2 + 2\\pi rh = 2\\pi r(r + h)$ for a cylinder''s surface area, and it is the first step in solving many polynomial equations."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e3367819e4dad4', 'les_6727bdd3384dda', 1, 'practice', 'multiple_choice', 1, 'What is the GCF of $14a^3$ and $21a^2$?', '{"choices":["$7a^3$","$7a^2$","$42a^3$","$7a$"],"answer":1}', '["gcd(14, 21) and the smaller power of a."]', '$7a^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_af202406155d3f', 'les_6727bdd3384dda', 2, 'practice', 'short_text', 1, 'Factor $6x + 15$.', '{"accept":["3(2x+5)"]}', '["GCF of 6 and 15."]', '$3(2x + 5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a2f74f497aa8f8', 'les_6727bdd3384dda', 3, 'practice', 'short_text', 2, 'Factor $10m^3 - 25m^2$.', '{"accept":["5m^2(2m-5)"]}', '["GCF is 5m²."]', '$5m^2(2m - 5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e2e8495e02df0a', 'les_6727bdd3384dda', 4, 'practice', 'short_text', 2, 'Factor $9x^2y + 12xy^2 - 3xy$.', '{"accept":["3xy(3x+4y-1)"]}', '["GCF is 3xy.","Don''t forget the −1."]', '$3xy(3x + 4y - 1)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3ed136233356a7', 'les_6727bdd3384dda', 5, 'practice', 'short_text', 2, 'Factor $2x(x + 7) - 5(x + 7)$.', '{"accept":["(x+7)(2x-5)","(2x-5)(x+7)"]}', '["(x + 7) is common to both terms."]', '$(x + 7)(2x - 5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5438870ae0900f', 'les_6727bdd3384dda', 6, 'review', 'short_text', 3, 'Factor by grouping: $x^3 - 2x^2 + 5x - 10$.', '{"accept":["(x-2)(x^2+5)","(x^2+5)(x-2)"]}', '["$x^2(x - 2) + 5(x - 2)$."]', '$(x - 2)(x^2 + 5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cf06f801645541', 'les_6727bdd3384dda', 7, 'review', 'short_text', 3, 'Factor by grouping: $6x^2 + 9x - 4x - 6$.', '{"accept":["(2x+3)(3x-2)","(3x-2)(2x+3)"]}', '["$3x(2x + 3) - 2(2x + 3)$."]', '$(2x + 3)(3x - 2)$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_5694f8f8fb67bd', 'subj_math', 'factoring', 'Factoring', 'Writing a polynomial as a product of simpler polynomials.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6727bdd3384dda', (SELECT id FROM concepts WHERE slug = 'factoring'));

-- Lesson: integers-number-line
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a02ada0fc2f6ce', 'integers-number-line', 'Integers and the number line', 'Place positive and negative whole numbers on a number line, compare them, and find opposites and absolute values.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_063e60aa329023', 'les_a02ada0fc2f6ce', 1, 'Locate integers on a horizontal or vertical number line.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_101191fd4cf60f', 'les_a02ada0fc2f6ce', 2, 'Compare and order integers using < and >.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5fe9014ac22ba8', 'les_a02ada0fc2f6ce', 3, 'Find the opposite and the absolute value of an integer and explain each as a distance or reflection.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_063e60aa329023', 'les_a02ada0fc2f6ce', 'learn', 1, 'text', '{"body":"Many quantities have a direction as well as a size. A temperature can be 5 degrees above zero or 5 degrees below. A bank balance can be 40 dollars or 40 dollars overdrawn. An elevator can stop 3 floors above the lobby or 2 floors below it. Negative numbers let one number line describe both directions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_101191fd4cf60f', 'les_a02ada0fc2f6ce', 'learn', 2, 'definition', '{"term":"Integers","body":"The set $\\{\\dots, -3, -2, -1, 0, 1, 2, 3, \\dots\\}$: the counting numbers, their opposites, and zero. Integers have no fractional or decimal part."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5fe9014ac22ba8', 'les_a02ada0fc2f6ce', 'learn', 3, 'text', '{"body":"On a horizontal number line, positive numbers are to the right of 0 and negative numbers are to the left. The further right a number is, the greater it is. That means $-2 > -7$: $-2$ is to the right of $-7$, even though 7 looks \"bigger.\" Think of temperature: $-2^\\circ$ is warmer than $-7^\\circ$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0560d63f73e8a3', 'les_a02ada0fc2f6ce', 'learn', 4, 'definition', '{"term":"Opposites","body":"Two numbers the same distance from 0 on opposite sides, such as 6 and $-6$. The opposite of $a$ is written $-a$, so $-(-6) = 6$. The opposite of 0 is 0."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_28e248279fc480', 'les_a02ada0fc2f6ce', 'learn', 5, 'definition', '{"term":"Absolute value","body":"The distance from a number to 0, written $|a|$. Distance is never negative, so $|6| = 6$, $|-6| = 6$ and $|0| = 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_32787f37ae905e', 'les_a02ada0fc2f6ce', 'learn', 6, 'worked_example', '{"title":"Order $3, -5, 0, -1, 4$ from least to greatest","steps":[{"latex":"-5,\\ -1","explanation":"Negatives first. The one furthest left (−5) is least."},{"latex":"-5 < -1 < 0","explanation":"Zero is greater than every negative number."},{"latex":"-5 < -1 < 0 < 3 < 4","explanation":"Then the positives, smallest first."}],"check":"Read the list on a number line from left to right. Each number should sit to the right of the one before it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2691c771fb7c33', 'les_a02ada0fc2f6ce', 'learn', 7, 'worked_example', '{"title":"Evaluate $-|-8| + |3|$","steps":[{"latex":"|-8| = 8,\\ |3| = 3","explanation":"Find each absolute value first: they are distances from 0."},{"latex":"-8 + 3","explanation":"The negative sign outside the bars stays: it takes the opposite of 8."},{"latex":"-5","explanation":"Start at −8 and move 3 to the right."}],"check":"A common slip is to think $-|-8|$ is 8. The bars give 8, and the sign in front makes it $-8$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_50a98573e4ef9c', 'les_a02ada0fc2f6ce', 'learn', 8, 'callout', '{"tone":"warning","title":"Absolute value is not ''make it positive''","body":"$|a|$ is a distance, so it is never negative, but $-|a|$ is never positive. Keep track of what is inside the bars and what is outside."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_179a8b621594d9', 'les_a02ada0fc2f6ce', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Sea level is 0 on an elevation scale. Death Valley''s lowest point is about $-86$ meters and Denver is about $+1609$ meters. Elevation, temperature, money and golf scores all use the same number line."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9941e2ef6978cf', 'les_a02ada0fc2f6ce', 'experiment', 10, 'activity', '{"activity":"number-line","title":"Move along the number line","params":{"a":-4,"b":6,"op":"add"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_54d537000bfb6c', 'les_a02ada0fc2f6ce', 'experiment', 11, 'callout', '{"tone":"tip","title":"Try this","body":"Set the start to $-4$ and add 0. Now compare the readouts for $|\\text{start}|$ and the start itself. Then try start $= 7$ and add $-14$. Where do you land, and how are 7 and the result related?"}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_063e60aa329023', 'les_a02ada0fc2f6ce', 1, 'practice', 'multiple_choice', 1, 'Which statement is true?', '{"choices":["$-9 > -3$","$-3 > -9$","$0 < -1$","$-4 > 2$"],"answer":1}', '["Picture each pair on a number line. The number further right is greater."]', '$-3$ is to the right of $-9$, so $-3 > -9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_101191fd4cf60f', 'les_a02ada0fc2f6ce', 2, 'practice', 'numeric', 1, 'What is $|-14|$?', '{"answer":14}', '["Absolute value is distance from 0."]', '$-14$ is 14 units from 0, so $|-14| = 14$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5fe9014ac22ba8', 'les_a02ada0fc2f6ce', 3, 'practice', 'numeric', 1, 'What is the opposite of $-25$?', '{"answer":25}', '["The opposite is the same distance from 0 on the other side."]', '$-(-25) = 25$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0560d63f73e8a3', 'les_a02ada0fc2f6ce', 4, 'practice', 'multiple_choice', 2, 'Order from least to greatest: $-2,\ 5,\ -8,\ 0,\ -3$.', '{"choices":["$-2, -3, -8, 0, 5$","$-8, -3, -2, 0, 5$","$0, -2, -3, 5, -8$","$-8, -2, -3, 0, 5$"],"answer":1}', '["The most negative number is furthest left, so it is the least."]', 'On the number line from left to right: $-8, -3, -2, 0, 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_28e248279fc480', 'les_a02ada0fc2f6ce', 5, 'practice', 'numeric', 2, 'Evaluate $|-6| - |4|$.', '{"answer":2}', '["Find each absolute value, then subtract."]', '$6 - 4 = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_32787f37ae905e', 'les_a02ada0fc2f6ce', 6, 'practice', 'numeric', 2, 'At 6 a.m. the temperature was $-11^\circ$F. At noon it was $4^\circ$F. How many degrees did it rise?', '{"answer":15,"unit":"°F"}', '["Count the steps from −11 up to 0, then from 0 up to 4."]', 'From $-11$ to 0 is 11 degrees and from 0 to 4 is 4 more: $11 + 4 = 15$ degrees.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2691c771fb7c33', 'les_a02ada0fc2f6ce', 7, 'practice', 'short_text', 2, 'Name both integers that are 7 units from 0. Enter them separated by a comma, smaller first.', '{"accept":["-7,7"]}', '["There is one on each side of 0."]', '$-7$ and $7$ both have absolute value 7.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_50a98573e4ef9c', 'les_a02ada0fc2f6ce', 8, 'review', 'numeric', 3, 'Evaluate $-|{-5}| - (-|{-2}|)$.', '{"answer":-3}', '["$|-5| = 5$ and $|-2| = 2$, so this is $-5 - (-2)$.","Subtracting a negative is adding its opposite."]', '$-5 - (-2) = -5 + 2 = -3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_179a8b621594d9', 'les_a02ada0fc2f6ce', 9, 'review', 'multiple_choice', 2, 'If $|x| = 9$, which is true?', '{"choices":["$x = 9$ only","$x = -9$ only","$x = 9$ or $x = -9$","There is no such $x$"],"answer":2}', '["Which numbers are 9 units from 0?"]', 'Both 9 and $-9$ are 9 units from 0, so $x = 9$ or $x = -9$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9e35a694eb0354', 'subj_math', 'integers', 'Integers', 'The whole numbers, their opposites and zero: …, −2, −1, 0, 1, 2, …');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a02ada0fc2f6ce', (SELECT id FROM concepts WHERE slug = 'integers'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a359f5dece460d', 'subj_math', 'absolute-value', 'Absolute value', 'The distance of a number from zero on the number line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a02ada0fc2f6ce', (SELECT id FROM concepts WHERE slug = 'absolute-value'));

-- Lesson: interpreting-linear-models
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e22ba86ab5fd75', 'interpreting-linear-models', 'Interpreting linear models', 'Interpret the slope and intercept of a linear model in context with units, build models from descriptions, and judge when a linear model is reasonable.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_918818974fd0b8', 'les_e22ba86ab5fd75', 1, 'Interpret slope as a rate of change and the intercept as a starting value, with units.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3320c25c2359ae', 'les_e22ba86ab5fd75', 2, 'Write a linear model from a verbal description or two data points.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e036370f9fd7ff', 'les_e22ba86ab5fd75', 3, 'Decide whether the intercept and predictions make sense in context and identify limits of the model.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_918818974fd0b8', 'les_e22ba86ab5fd75', 'learn', 1, 'text', '{"body":"A linear model $y = mx + b$ says two things about a situation. The slope $m$ is the rate: how much $y$ changes for each 1-unit increase in $x$, in units of \"$y$-units per $x$-unit.\" The intercept $b$ is the value of $y$ when $x = 0$, often a starting amount."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3320c25c2359ae', 'les_e22ba86ab5fd75', 'learn', 2, 'worked_example', '{"title":"A candle''s height is $h = 24 - 1.5t$ cm after $t$ hours. Interpret the numbers.","steps":[{"latex":"m = -1.5 \\text{ cm per hour}","explanation":"The candle gets 1.5 cm shorter each hour."},{"latex":"b = 24 \\text{ cm}","explanation":"Its height when lit (t = 0)."},{"latex":"0 = 24 - 1.5t \\Rightarrow t = 16","explanation":"The x-intercept: it burns out after 16 hours."}],"check":"A sensible domain is 0 ≤ t ≤ 16. The model says nothing about times after the candle is gone."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e036370f9fd7ff', 'les_e22ba86ab5fd75', 'experiment', 3, 'activity', '{"activity":"linear-graph","title":"Read slope and intercept as a story","params":{"m":-1.5,"b":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7855b11431006b', 'les_e22ba86ab5fd75', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Imagine $y$ is dollars left on a transit card and $x$ is rides. Describe the line in words. Which slider changes the price per ride, and which changes the starting balance? Where does the card run out?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5f9078508a1234', 'les_e22ba86ab5fd75', 'learn', 5, 'worked_example', '{"title":"A plumber charged 170 dollars for a 2-hour job and 290 dollars for a 5-hour job. Build and interpret a linear model.","steps":[{"latex":"m = \\frac{290 - 170}{5 - 2} = 40","explanation":"40 dollars per hour of labor."},{"latex":"C - 170 = 40(h - 2) \\Rightarrow C = 40h + 90","explanation":""},{"latex":"b = 90","explanation":"A 90-dollar call-out fee before any work."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_78174c4e8f2acb', 'les_e22ba86ab5fd75', 'learn', 6, 'callout', '{"tone":"warning","title":"Intercepts that don''t make sense","body":"A model of adult height versus shoe size might give a \"height\" of 120 cm for shoe size 0. That intercept is just where the line crosses the axis; no one has shoe size 0. Say when an intercept has no real meaning."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1c5976bbbf4e9d', 'les_e22ba86ab5fd75', 'learn', 7, 'callout', '{"tone":"warning","title":"Is linear the right model?","body":"Linear models assume a constant rate. Population growth, cooling coffee and compound interest change at changing rates. If the differences in your data aren''t roughly constant, try another model."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6a88e8a16a4c23', 'les_e22ba86ab5fd75', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"\"The average US gas price rose 0.04 dollars per month this year\" is a slope. Fitness apps estimate calories as a rate times minutes, and phone plans list a monthly fee (intercept) plus a per-gigabyte charge (slope)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_918818974fd0b8', 'les_e22ba86ab5fd75', 1, 'practice', 'multiple_choice', 1, 'In $C = 12n + 30$, $C$ is the cost in dollars of a party for $n$ guests. What does 12 mean?', '{"choices":["A 12-dollar fixed fee","12 dollars per guest","12 guests","The total cost"],"answer":1}', '["The slope multiplies the number of guests."]', 'Each additional guest adds 12 dollars.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3320c25c2359ae', 'les_e22ba86ab5fd75', 2, 'practice', 'multiple_choice', 1, 'In the same model, what does 30 mean?', '{"choices":["30 guests","30 dollars per guest","A 30-dollar cost even with no guests","The maximum cost"],"answer":2}', '["What is C when n = 0?"]', 'A fixed 30-dollar cost, such as a room fee.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e036370f9fd7ff', 'les_e22ba86ab5fd75', 3, 'practice', 'numeric', 2, 'A tank holds $W = 800 - 25t$ liters after $t$ minutes of draining. How many minutes until it is empty?', '{"answer":32,"unit":"min"}', '["Solve $800 - 25t = 0$."]', '$t = 32$ minutes.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7855b11431006b', 'les_e22ba86ab5fd75', 4, 'practice', 'numeric', 2, 'A tree was 1.2 m tall when planted and grows 0.45 m per year. Using a linear model, how tall is it after 6 years?', '{"answer":3.9,"unit":"m"}', '["$h = 1.2 + 0.45t$."]', '$1.2 + 0.45(6) = 3.9$ m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5f9078508a1234', 'les_e22ba86ab5fd75', 5, 'practice', 'numeric', 2, 'A rideshare costs 11.50 dollars for 3 miles and 21.50 dollars for 7 miles. What is the cost per mile?', '{"answer":2.5,"unit":"dollars per mile"}', '["Slope between the two points."]', '$\frac{21.50 - 11.50}{7 - 3} = 2.50$ dollars per mile.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_78174c4e8f2acb', 'les_e22ba86ab5fd75', 6, 'review', 'numeric', 3, 'For that rideshare, what is the base fare (the cost at 0 miles)?', '{"answer":4,"unit":"dollars"}', '["$11.50 = 2.5(3) + b$."]', '$b = 11.50 - 7.50 = 4$ dollars.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1c5976bbbf4e9d', 'les_e22ba86ab5fd75', 7, 'review', 'multiple_choice', 3, 'A model for a child''s height is $h = 6.5a + 77$ cm for ages 2 to 10. What''s wrong with using it to predict height at age 40?', '{"choices":["Nothing","Children stop growing, so the constant rate doesn''t continue","The intercept is negative","The slope should be negative"],"answer":1}', '["Does height increase at a steady rate forever?"]', 'It predicts 337 cm at age 40. Growth stops in the late teens, so the linear trend can''t be extended that far.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_6a3ec2dbe14a2b', 'subj_math', 'linear-models', 'Linear models', 'Using y = mx + b to describe a quantity that changes at a constant rate.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e22ba86ab5fd75', (SELECT id FROM concepts WHERE slug = 'linear-models'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_e22ba86ab5fd75', (SELECT id FROM formulas WHERE slug = 'slope-intercept-form'), 1);

-- Lesson: key-features-quadratics
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8b5aabf98f399f', 'key-features-quadratics', 'Key features: vertex, axis of symmetry and intercepts', 'Find the axis of symmetry, vertex, y-intercept and x-intercepts of y = ax² + bx + c, and use them to sketch the parabola and answer max/min questions.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3dba1adffbf7d8', 'les_8b5aabf98f399f', 1, 'Find the axis of symmetry x = −b/(2a) and the vertex of a quadratic in standard form.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4179ef867933ed', 'les_8b5aabf98f399f', 2, 'Find the y-intercept and use symmetry to locate other points.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_90caf5f2a7cc0e', 'les_8b5aabf98f399f', 3, 'Interpret the vertex as a maximum or minimum in context.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3dba1adffbf7d8', 'les_8b5aabf98f399f', 'learn', 1, 'text', '{"body":"The graph of $y = ax^2 + bx + c$ is a parabola. It opens up when $a > 0$ (with a lowest point) and down when $a < 0$ (with a highest point). That turning point is the vertex, and the parabola is a mirror image of itself across the vertical line through it, the axis of symmetry."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4179ef867933ed', 'les_8b5aabf98f399f', 'learn', 2, 'definition', '{"term":"Axis of symmetry and vertex","body":"For $y = ax^2 + bx + c$, the axis of symmetry is $x = -\\dfrac{b}{2a}$. The vertex is the point on the parabola with that $x$-value: $\\left(-\\frac{b}{2a},\\ f\\!\\left(-\\frac{b}{2a}\\right)\\right)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_90caf5f2a7cc0e', 'les_8b5aabf98f399f', 'learn', 3, 'text', '{"body":"Why $-\\frac{b}{2a}$? The parabola crosses the line $y = c$ where $ax^2 + bx = 0$, that is, at $x = 0$ and $x = -\\frac{b}{a}$. By symmetry, the axis lies halfway between those two points: at $x = -\\frac{b}{2a}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0ee5fec69e35af', 'les_8b5aabf98f399f', 'learn', 4, 'worked_example', '{"title":"Find the key features of $y = 2x^2 - 8x + 5$","steps":[{"latex":"x = -\\frac{-8}{2(2)} = 2","explanation":"Axis of symmetry."},{"latex":"y = 2(4) - 16 + 5 = -3","explanation":"Vertex (2, −3). It''s a minimum because a = 2 > 0."},{"latex":"(0, 5)","explanation":"y-intercept: c."},{"latex":"(4, 5)","explanation":"Mirror image of (0, 5) across x = 2."},{"latex":"2x^2 - 8x + 5 = 0 \\Rightarrow x = 2 \\pm \\tfrac{\\sqrt{6}}{2} \\approx 0.78,\\ 3.22","explanation":"x-intercepts, from the quadratic formula."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0301199fd4e910', 'les_8b5aabf98f399f', 'experiment', 5, 'activity', '{"activity":"vertex-explorer","title":"Vertex, axis and zeros","params":{"a":2,"h":2,"k":-3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d814deca476d31', 'les_8b5aabf98f399f', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"This is $y = 2(x - 2)^2 - 3$, the same parabola in vertex form. Read off the vertex and confirm the expanded form shows $2x^2 - 8x + 5$. Raise the vertex above the x-axis: how many zeros now?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5251c871fa450e', 'les_8b5aabf98f399f', 'learn', 7, 'worked_example', '{"title":"A ball''s height is $h(t) = -16t^2 + 48t + 6$ feet. Find its maximum height and when it occurs.","steps":[{"latex":"t = -\\frac{48}{2(-16)} = 1.5 \\text{ s}","explanation":"a < 0, so the vertex is a maximum."},{"latex":"h(1.5) = -36 + 72 + 6 = 42 \\text{ ft}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9fc46006a8d719', 'les_8b5aabf98f399f', 'learn', 8, 'callout', '{"tone":"warning","title":"Sign of b","body":"In $y = x^2 + 6x$, $-\\frac{b}{2a} = -\\frac{6}{2} = -3$. The vertex is to the left of the y-axis when $a$ and $b$ have the same sign."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_da23504868d6a5', 'les_8b5aabf98f399f', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Maximizing area with fixed fencing, finding the best ticket price for revenue, and the peak height of a jump or a fountain all come from the vertex of a parabola."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3dba1adffbf7d8', 'les_8b5aabf98f399f', 1, 'practice', 'numeric', 1, 'What is the axis of symmetry of $y = x^2 - 6x + 2$? Enter the x-value.', '{"answer":3}', '["$-\\frac{b}{2a} = -\\frac{-6}{2}$."]', '$x = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4179ef867933ed', 'les_8b5aabf98f399f', 2, 'practice', 'short_text', 2, 'Find the vertex of $y = x^2 + 4x - 1$. Enter as (x,y).', '{"accept":["(-2,-5)"]}', '["Axis: $x = -2$.","Evaluate y at x = −2."]', '$x = -2$ and $y = 4 - 8 - 1 = -5$: $(-2, -5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_90caf5f2a7cc0e', 'les_8b5aabf98f399f', 3, 'practice', 'multiple_choice', 2, 'Does $y = -3x^2 + 12x + 1$ have a maximum or a minimum, and what is it?', '{"choices":["Minimum 13","Maximum 13","Maximum 2","Minimum 1"],"answer":1}', '["$a < 0$: opens down.","Axis $x = 2$."]', '$x = 2$ and $y = -12 + 24 + 1 = 13$: a maximum of 13.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0ee5fec69e35af', 'les_8b5aabf98f399f', 4, 'practice', 'numeric', 2, 'The parabola $y = x^2 - 8x + 7$ passes through $(1, 0)$. Use symmetry to find the other x-intercept.', '{"answer":7}', '["The axis is $x = 4$.","1 is 3 units left of 4."]', 'The mirror point is 3 units to the right: $x = 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0301199fd4e910', 'les_8b5aabf98f399f', 5, 'practice', 'numeric', 2, 'A rocket''s height is $h(t) = -5t^2 + 40t$ meters. What is its maximum height?', '{"answer":80,"unit":"m"}', '["$t = -\\frac{40}{2(-5)} = 4$."]', '$h(4) = -80 + 160 = 80$ m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d814deca476d31', 'les_8b5aabf98f399f', 6, 'review', 'numeric', 3, 'A farmer has 100 m of fencing for a rectangular pen. The area is $A = x(50 - x)$. What width $x$ gives the largest area?', '{"answer":25,"unit":"m"}', '["$A = -x^2 + 50x$."]', '$x = -\frac{50}{2(-1)} = 25$ m, a 25 m by 25 m square with area 625 m².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5251c871fa450e', 'les_8b5aabf98f399f', 7, 'review', 'short_text', 3, 'Find the y-intercept of $y = 3(x - 1)^2 - 7$. Enter as (x,y).', '{"accept":["(0,-4)"]}', '["Substitute x = 0."]', '$3(1) - 7 = -4$: $(0, -4)$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_21fa51d21dc50e', 'subj_math', 'quadratic-functions', 'Quadratic functions', 'Functions of the form f(x) = ax² + bx + c with a ≠ 0, whose graphs are parabolas.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8b5aabf98f399f', (SELECT id FROM concepts WHERE slug = 'quadratic-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_8b5aabf98f399f', (SELECT id FROM formulas WHERE slug = 'vertex-form'), 1);

-- Lesson: literal-equations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_14ebad20325fbe', 'literal-equations', 'Literal equations and formulas', 'Solve a formula for any one of its variables, state restrictions such as nonzero denominators, and use the rearranged formula efficiently.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e253dbfa4fc3c8', 'les_14ebad20325fbe', 1, 'Solve a literal equation for a specified variable using inverse operations.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2c9c215907e5f1', 'les_14ebad20325fbe', 2, 'Factor out a variable that appears in more than one term.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9187ad03283f8d', 'les_14ebad20325fbe', 3, 'State the conditions under which the rearranged formula is valid, and use it to compute values.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e253dbfa4fc3c8', 'les_14ebad20325fbe', 'learn', 1, 'definition', '{"term":"Literal equation","body":"An equation with two or more variables, such as $d = rt$ or $A = \\frac{1}{2}bh$. Solving it for one variable expresses that variable in terms of the others."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2c9c215907e5f1', 'les_14ebad20325fbe', 'learn', 2, 'text', '{"body":"Solve a literal equation exactly the way you solve a numeric one: undo operations in reverse order, doing the same thing to both sides. The only difference is that the \"answer\" is an expression rather than a number. Treat every letter except the one you are solving for as if it were a known number."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9187ad03283f8d', 'les_14ebad20325fbe', 'learn', 3, 'worked_example', '{"title":"Solve $d = rt$ for $t$","steps":[{"latex":"\\frac{d}{r} = \\frac{rt}{r}","explanation":"t is multiplied by r, so divide both sides by r."},{"latex":"t = \\frac{d}{r}, \\quad r \\ne 0","explanation":"Division by r requires r ≠ 0."}],"check":"Test with numbers: 150 miles at 50 mph takes $\\frac{150}{50} = 3$ hours. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_424c9bd5789a4e', 'les_14ebad20325fbe', 'learn', 4, 'worked_example', '{"title":"Solve $A = \\tfrac{1}{2}(b_1 + b_2)h$ for $b_2$","steps":[{"latex":"2A = (b_1 + b_2)h","explanation":"Multiply both sides by 2."},{"latex":"\\frac{2A}{h} = b_1 + b_2","explanation":"Divide by h (h ≠ 0)."},{"latex":"b_2 = \\frac{2A}{h} - b_1","explanation":"Subtract b₁."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4cfdc18e43e524', 'les_14ebad20325fbe', 'learn', 5, 'worked_example', '{"title":"Solve $F = \\tfrac{9}{5}C + 32$ for $C$","steps":[{"latex":"F - 32 = \\tfrac{9}{5}C","explanation":"Subtract 32."},{"latex":"C = \\tfrac{5}{9}(F - 32)","explanation":"Multiply by 5/9."}],"check":"Check: $F = 212$ gives $C = \\frac{5}{9}(180) = 100$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5328290836fc73', 'les_14ebad20325fbe', 'learn', 6, 'worked_example', '{"title":"Solve $ax + b = cx$ for $x$","steps":[{"latex":"ax - cx = -b","explanation":"Gather the x-terms on one side."},{"latex":"x(a - c) = -b","explanation":"Factor out x: the distributive property in reverse."},{"latex":"x = \\frac{-b}{a - c} = \\frac{b}{c - a}, \\quad a \\ne c","explanation":"Divide by (a − c), which must not be zero."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d3708c943874dd', 'les_14ebad20325fbe', 'learn', 7, 'callout', '{"tone":"warning","title":"Never divide by an expression that could be zero","body":"When you divide by a variable or an expression like $a - c$, note that it must be nonzero. If $a = c$, the equation $ax + b = cx$ becomes $b = 0$, which has no solution or every solution depending on $b$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fc7d43e25f21d9', 'les_14ebad20325fbe', 'learn', 8, 'callout', '{"tone":"tip","title":"When to rearrange first","body":"If you need to compute the same variable many times, rearrange the formula once and then substitute. If you need it only once, substituting numbers first and then solving is often quicker and less error-prone."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_13ff54407663cd', 'les_14ebad20325fbe', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Science formulas are constantly rearranged: $V = IR$ for $I$, $\\rho = \\frac{m}{V}$ for $V$, $PV = nRT$ for $T$. Spreadsheets for loan payments and recipe scaling rely on the same skill."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e253dbfa4fc3c8', 'les_14ebad20325fbe', 1, 'practice', 'short_text', 1, 'Solve $P = 4s$ for $s$.', '{"accept":["s=P/4","s=p/4"]}', '["Divide both sides by 4."]', '$s = \frac{P}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2c9c215907e5f1', 'les_14ebad20325fbe', 2, 'practice', 'short_text', 1, 'Solve $y = x + k$ for $x$.', '{"accept":["x=y-k"]}', '["Subtract k from both sides."]', '$x = y - k$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9187ad03283f8d', 'les_14ebad20325fbe', 3, 'practice', 'short_text', 2, 'Solve $V = lwh$ for $w$.', '{"accept":["w=V/(lh)","w=v/(lh)","w=V/(hl)"]}', '["Divide both sides by lh."]', '$w = \frac{V}{lh}$, with $l, h \ne 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_424c9bd5789a4e', 'les_14ebad20325fbe', 4, 'practice', 'short_text', 2, 'Solve $3x + 2y = 12$ for $y$.', '{"accept":["y=6-3x/2","y=-3x/2+6","y=(12-3x)/2","y=-1.5x+6","y=6-1.5x"]}', '["Subtract 3x, then divide by 2."]', '$2y = 12 - 3x$, so $y = 6 - \frac{3}{2}x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4cfdc18e43e524', 'les_14ebad20325fbe', 5, 'practice', 'short_text', 2, 'Solve $P = 2l + 2w$ for $l$.', '{"accept":["l=(P-2w)/2","l=P/2-w","l=(p-2w)/2","l=p/2-w"]}', '["Subtract 2w, then divide by 2."]', '$l = \frac{P - 2w}{2} = \frac{P}{2} - w$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5328290836fc73', 'les_14ebad20325fbe', 6, 'practice', 'numeric', 2, 'Use $C = \tfrac{5}{9}(F - 32)$ to convert $68^\circ$F to Celsius.', '{"answer":20,"unit":"°C"}', '["$68 - 32 = 36$."]', '$\frac{5}{9} \cdot 36 = 20^\circ$C.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d3708c943874dd', 'les_14ebad20325fbe', 7, 'practice', 'multiple_choice', 3, 'Solve $m = \dfrac{y - b}{x}$ for $b$.', '{"choices":["$b = y - mx$","$b = mx - y$","$b = \\frac{y}{mx}$","$b = y + mx$"],"answer":0}', '["Multiply both sides by x first."]', '$mx = y - b$, so $b = y - mx$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fc7d43e25f21d9', 'les_14ebad20325fbe', 8, 'review', 'short_text', 3, 'Solve $ax - 5 = bx$ for $x$ (assume $a \ne b$).', '{"accept":["x=5/(a-b)","x=-5/(b-a)"]}', '["Get both x-terms on one side.","Factor out x."]', '$ax - bx = 5$, so $x(a - b) = 5$ and $x = \frac{5}{a - b}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_14ebad20325fbe', 'subj_math', 'literal-equations', 'Literal equations', 'Equations with several variables that are solved for one variable in terms of the others.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_14ebad20325fbe', (SELECT id FROM concepts WHERE slug = 'literal-equations'));

-- Lesson: mean-median-mode-range
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1e6d87d037c656', 'mean-median-mode-range', 'Mean, median, mode and range', 'Summarize a data set with measures of center and the range, see how outliers affect each one, and choose the measure that best describes the data.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_40305d5ee494f1', 'les_1e6d87d037c656', 1, 'Compute the mean, median, mode and range of a data set.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2a826f0b9be487', 'les_1e6d87d037c656', 2, 'Describe how an outlier affects the mean and the median.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_69196ce64c3ce7', 'les_1e6d87d037c656', 3, 'Choose an appropriate measure of center for a situation and justify the choice.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_40305d5ee494f1', 'les_1e6d87d037c656', 'learn', 1, 'definition', '{"term":"Mean","body":"The sum of the values divided by how many there are. It is the \"fair share\" value: if everyone pooled their values and split them equally, each would get the mean."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2a826f0b9be487', 'les_1e6d87d037c656', 'learn', 2, 'definition', '{"term":"Median","body":"The middle value when the data are in order. With an even number of values, it is the mean of the two middle values."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_69196ce64c3ce7', 'les_1e6d87d037c656', 'learn', 3, 'definition', '{"term":"Mode","body":"The value that occurs most often. A data set can have one mode, several modes, or no mode (if every value occurs equally often)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1084dee622c97e', 'les_1e6d87d037c656', 'learn', 4, 'definition', '{"term":"Range","body":"The maximum minus the minimum. It is a simple measure of spread: how far apart the values are."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9359b605cec1b7', 'les_1e6d87d037c656', 'learn', 5, 'worked_example', '{"title":"Quiz scores: 8, 6, 9, 10, 7, 8, 8, 4","steps":[{"latex":"4, 6, 7, 8, 8, 8, 9, 10","explanation":"Order the data first."},{"latex":"\\text{mean} = \\tfrac{60}{8} = 7.5","explanation":"The sum is 60 and there are 8 scores."},{"latex":"\\text{median} = \\tfrac{8 + 8}{2} = 8","explanation":"The 4th and 5th values are both 8."},{"latex":"\\text{mode} = 8,\\quad \\text{range} = 10 - 4 = 6","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3224a4aaf22bfe', 'les_1e6d87d037c656', 'experiment', 6, 'activity', '{"activity":"data-explorer","title":"Drag the data","params":{"dataset":"outlier","view":"none"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_81540bb95a93c9', 'les_1e6d87d037c656', 'experiment', 7, 'callout', '{"tone":"tip","title":"Try this","body":"This data set has an outlier at 19. Drag it down to 6 and watch the mean and the median. Which one moves more? Then drag it back up to 20."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9718da982ef554', 'les_1e6d87d037c656', 'learn', 8, 'text', '{"body":"The mean uses every value, so a single extreme value (an outlier) pulls it toward the tail. The median depends only on the order, so it barely moves. For skewed data or data with outliers, such as incomes or house prices, the median is usually the better description of a typical value."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c0035aa26db5a4', 'les_1e6d87d037c656', 'learn', 9, 'worked_example', '{"title":"Five friends earn 12, 13, 13, 15 and 97 dollars per hour.","steps":[{"latex":"\\text{mean} = \\tfrac{150}{5} = 30","explanation":"Pulled up by 97."},{"latex":"\\text{median} = 13","explanation":"The middle of the ordered list."}],"check":"Four of the five earn less than the mean. The median, 13, describes a typical friend much better."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_482e0bb985f5a8', 'les_1e6d87d037c656', 'learn', 10, 'worked_example', '{"title":"A student''s first four test scores average 84. What score on the fifth test makes the mean 86?","steps":[{"latex":"4 \\cdot 84 = 336","explanation":"The total of the first four."},{"latex":"5 \\cdot 86 = 430","explanation":"The total needed for a mean of 86."},{"latex":"430 - 336 = 94","explanation":"The fifth score must be 94."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_314063b4fb2146', 'les_1e6d87d037c656', 'learn', 11, 'callout', '{"tone":"warning","title":"Order before finding the median","body":"The median of 9, 2, 7 is 7, not 2. Always sort the data first."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c9289c1ec2031c', 'les_1e6d87d037c656', 'learn', 12, 'callout', '{"tone":"application","title":"Where this shows up","body":"News reports quote median home prices and median household income because a few very large values would distort the mean. Grade books use the mean. Shoe stores stock most of the mode size."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_40305d5ee494f1', 'les_1e6d87d037c656', 1, 'practice', 'numeric', 1, 'Find the mean of 12, 15, 9, 20, 14.', '{"answer":14}', '["Add, then divide by 5."]', '$\frac{70}{5} = 14$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2a826f0b9be487', 'les_1e6d87d037c656', 2, 'practice', 'numeric', 1, 'Find the median of 7, 3, 9, 1, 5.', '{"answer":5}', '["Order the values first."]', '1, 3, 5, 7, 9: the median is 5.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_69196ce64c3ce7', 'les_1e6d87d037c656', 3, 'practice', 'numeric', 2, 'Find the median of 4, 10, 6, 8, 12, 2.', '{"answer":7}', '["Ordered: 2, 4, 6, 8, 10, 12.","Average the two middle values."]', '$\frac{6 + 8}{2} = 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1084dee622c97e', 'les_1e6d87d037c656', 4, 'practice', 'numeric', 2, 'Find the range of $-3, 8, 0, -7, 5$.', '{"answer":15}', '["Maximum minus minimum."]', '$8 - (-7) = 15$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9359b605cec1b7', 'les_1e6d87d037c656', 5, 'practice', 'multiple_choice', 2, 'Data: 2, 3, 3, 5, 5, 7. What is the mode?', '{"choices":["3","5","3 and 5","No mode"],"answer":2}', '["Which values occur most often?"]', '3 and 5 each occur twice, so the data set has two modes.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3224a4aaf22bfe', 'les_1e6d87d037c656', 6, 'practice', 'multiple_choice', 2, 'House prices on a street: 210k, 225k, 230k, 240k, 1.2 million. Which measure best describes a typical price?', '{"choices":["Mean","Median","Range","Mode"],"answer":1}', '["One house is an outlier."]', 'The median (230k) is not affected by the 1.2 million outlier; the mean (421k) is higher than four of the five prices.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_81540bb95a93c9', 'les_1e6d87d037c656', 7, 'review', 'numeric', 3, 'The mean of 6 numbers is 15. Five of them are 12, 18, 10, 20 and 16. What is the sixth?', '{"answer":14}', '["The total must be 6 × 15 = 90."]', '$90 - (12 + 18 + 10 + 20 + 16) = 90 - 76 = 14$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9718da982ef554', 'les_1e6d87d037c656', 8, 'review', 'multiple_choice', 3, 'A value much larger than the rest is added to a data set. Which statement is most likely true?', '{"choices":["The median increases a lot and the mean barely changes.","The mean increases more than the median.","Neither changes.","Both decrease."],"answer":1}', '["Which measure uses the size of every value?"]', 'The mean includes the size of the new value, so it is pulled up strongly; the median moves at most to a neighboring value.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_29e8de240bd5a6', 'subj_math', 'measures-of-center', 'Measures of center', 'Single values (mean, median, mode) that describe a typical value of a data set.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1e6d87d037c656', (SELECT id FROM concepts WHERE slug = 'measures-of-center'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_1e6d87d037c656', (SELECT id FROM formulas WHERE slug = 'mean'), 1);

-- Lesson: measures-center-spread
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1b1c7e5223ab3c', 'measures-center-spread', 'Measures of center and spread', 'Compute and compare mean, median, IQR and standard deviation, see which are resistant to outliers, and pick appropriate measures for a data set''s shape.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fa387393d8adaa', 'les_1b1c7e5223ab3c', 1, 'Compute the mean, median, range, interquartile range and standard deviation of a data set.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9d749ef4d4de87', 'les_1b1c7e5223ab3c', 2, 'Explain which measures are resistant to outliers and why.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_43a202a7a59d3a', 'les_1b1c7e5223ab3c', 3, 'Choose and justify measures of center and spread based on a distribution''s shape, and compare two data sets.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa387393d8adaa', 'les_1b1c7e5223ab3c', 'learn', 1, 'text', '{"body":"A data summary needs two things: a typical value (center) and how much values vary (spread). Two classes can both average 75 on a test, but if one class''s scores range from 70 to 80 and the other''s from 40 to 100, they are very different classes."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9d749ef4d4de87', 'les_1b1c7e5223ab3c', 'learn', 2, 'definition', '{"term":"Interquartile range (IQR)","body":"$Q_3 - Q_1$: the spread of the middle half of the data. Because it ignores the lowest and highest quarters, it is resistant to outliers, just like the median."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_43a202a7a59d3a', 'les_1b1c7e5223ab3c', 'learn', 3, 'formula', '{"latex":"\\sigma = \\sqrt{\\frac{\\sum (x_i - \\bar{x})^2}{n}}","title":"Standard deviation (population)","note":"The typical distance of the values from the mean. For a sample, statisticians usually divide by $n - 1$ instead of $n$ (written $s$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0a72987ac54718', 'les_1b1c7e5223ab3c', 'learn', 4, 'worked_example', '{"title":"Find the standard deviation of 2, 4, 4, 4, 5, 5, 7, 9","steps":[{"latex":"\\bar{x} = \\tfrac{40}{8} = 5","explanation":"Mean."},{"latex":"\\text{deviations: } -3, -1, -1, -1, 0, 0, 2, 4","explanation":"Subtract the mean from each value."},{"latex":"\\text{squares: } 9, 1, 1, 1, 0, 0, 4, 16 \\to \\text{sum } 32","explanation":""},{"latex":"\\sigma = \\sqrt{32/8} = \\sqrt{4} = 2","explanation":""}],"check":"On average, values are about 2 away from the mean of 5."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_33714f40cdccb9', 'les_1b1c7e5223ab3c', 'experiment', 5, 'activity', '{"activity":"data-explorer","title":"Which measures resist an outlier?","params":{"dataset":"quiz","view":"box"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_677c0b596a55e1', 'les_1b1c7e5223ab3c', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Note the mean, median, IQR and σ. Drag the highest score to 20. Which two measures barely change, and which two jump? That''s what \"resistant\" means."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_47a5ed7605ab78', 'les_1b1c7e5223ab3c', 'learn', 7, 'text', '{"body":"For a roughly symmetric distribution with no outliers, report the mean and standard deviation. For a skewed distribution or one with outliers, report the median and IQR, which aren''t pulled by the tail."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_50726b12e7cb41', 'les_1b1c7e5223ab3c', 'learn', 8, 'worked_example', '{"title":"Compare: Team A scores 20, 22, 23, 25, 30; Team B scores 10, 18, 24, 31, 37","steps":[{"latex":"\\text{A: mean } 24,\\ \\text{median } 23,\\ \\text{range } 10","explanation":""},{"latex":"\\text{B: mean } 24,\\ \\text{median } 24,\\ \\text{range } 27","explanation":""},{"latex":"\\sigma_A \\approx 3.4,\\ \\sigma_B \\approx 9.4","explanation":"Same center; B is much more spread out, so it is less consistent."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4f2082d750bc44', 'les_1b1c7e5223ab3c', 'learn', 9, 'callout', '{"tone":"warning","title":"Standard deviation is never negative","body":"$\\sigma = 0$ only when all values are equal. Adding the same number to every value doesn''t change σ or the IQR; multiplying every value by 2 doubles them."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1e4c26679f525d', 'les_1b1c7e5223ab3c', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Manufacturers track standard deviation to keep products consistent, investors use it to measure risk, and weather reports use averages and ranges. Income statistics use medians because incomes are strongly skewed."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fa387393d8adaa', 'les_1b1c7e5223ab3c', 1, 'practice', 'numeric', 1, 'Find the IQR of a data set with $Q_1 = 31$ and $Q_3 = 47$.', '{"answer":16}', '["$Q_3 - Q_1$."]', '$47 - 31 = 16$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9d749ef4d4de87', 'les_1b1c7e5223ab3c', 2, 'practice', 'numeric', 2, 'Find the mean of 3, 7, 7, 8, 10.', '{"answer":7}', '["Sum is 35."]', '$35 \div 5 = 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_43a202a7a59d3a', 'les_1b1c7e5223ab3c', 3, 'practice', 'numeric', 2, 'Find the population standard deviation of 3, 7, 7, 8, 10. Round to two decimals.', '{"answer":2.28,"tolerance":0.006}', '["Mean is 7.","Squared deviations: 16, 0, 0, 1, 9."]', 'Sum 26, $26 / 5 = 5.2$, $\sigma = \sqrt{5.2} \approx 2.28$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0a72987ac54718', 'les_1b1c7e5223ab3c', 4, 'practice', 'multiple_choice', 2, 'Which measures are resistant to outliers?', '{"choices":["Mean and standard deviation","Median and IQR","Mean and IQR","Range and standard deviation"],"answer":1}', '["Which measures depend only on the middle of the ordered data?"]', 'The median and IQR depend on the positions of the middle values, so a single extreme value barely affects them.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_33714f40cdccb9', 'les_1b1c7e5223ab3c', 5, 'practice', 'multiple_choice', 2, 'A data set of home prices is strongly skewed right. Which summary is most appropriate?', '{"choices":["Mean and standard deviation","Median and IQR","Mode and range","Mean and range"],"answer":1}', '["Skew pulls the mean toward the tail."]', 'For skewed data, the median and IQR describe a typical value and spread better.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_677c0b596a55e1', 'les_1b1c7e5223ab3c', 6, 'review', 'multiple_choice', 3, 'Every value in a data set is increased by 5. What happens to the standard deviation?', '{"choices":["It increases by 5","It stays the same","It is multiplied by 5","It decreases"],"answer":1}', '["Does shifting all values change how far they are from the mean?"]', 'The mean also rises by 5, so every deviation is unchanged and σ stays the same.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_47a5ed7605ab78', 'les_1b1c7e5223ab3c', 7, 'review', 'numeric', 3, 'Data: 12, 15, 18, 20, 22, 25, 60. Using the 1.5 × IQR rule with $Q_1 = 15$ and $Q_3 = 25$, what is the upper fence?', '{"answer":40}', '["IQR = 10; $1.5 \\times 10 = 15$."]', '$25 + 15 = 40$. Since $60 > 40$, the value 60 is an outlier.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_29e8de240bd5a6', 'subj_math', 'measures-of-center', 'Measures of center', 'Single values (mean, median, mode) that describe a typical value of a data set.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1b1c7e5223ab3c', (SELECT id FROM concepts WHERE slug = 'measures-of-center'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_0454385f2e08f7', 'subj_math', 'standard-deviation', 'Standard deviation', 'A measure of the typical distance of data values from the mean.');
