-- Lesson: modeling-with-systems
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e58c256d2b5417', 'modeling-with-systems', 'Modeling with systems of equations', 'Translate word problems about totals, mixtures, rates and comparisons into systems, solve them, and interpret the answers in context.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5cea44d8f783fc', 'les_e58c256d2b5417', 1, 'Define variables and write a system of two equations from a situation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e1bc13a4c73be7', 'les_e58c256d2b5417', 2, 'Solve mixture, total-value, rate and break-even problems.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_72aa5dca12464e', 'les_e58c256d2b5417', 3, 'Interpret the solution in context and check that it is reasonable.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5cea44d8f783fc', 'les_e58c256d2b5417', 'learn', 1, 'text', '{"body":"Most system word problems give two separate facts about the same two unknowns. Each fact becomes one equation. A reliable process: name the variables with units, write one equation per fact, solve by the most convenient method, then answer the question that was actually asked and check it against the story."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e1bc13a4c73be7', 'les_e58c256d2b5417', 'learn', 2, 'worked_example', '{"title":"Total and value: 32 coins, all dimes and quarters, are worth 5.75 dollars. How many of each?","steps":[{"latex":"d + q = 32","explanation":"Count equation."},{"latex":"0.10d + 0.25q = 5.75","explanation":"Value equation, in dollars."},{"latex":"10d + 25q = 575;\\ \\ 10d + 10q = 320","explanation":"Multiply the value equation by 100 and the count equation by 10."},{"latex":"15q = 255 \\Rightarrow q = 17,\\ d = 15","explanation":"Subtract, then back-substitute."}],"check":"Check: 15 dimes = 1.50 and 17 quarters = 4.25, total 5.75 dollars. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_72aa5dca12464e', 'les_e58c256d2b5417', 'learn', 3, 'worked_example', '{"title":"Rate with a current: a boat goes 36 km downstream in 2 h and returns upstream in 3 h. Find the boat''s speed in still water and the current''s speed.","steps":[{"latex":"2(b + c) = 36 \\Rightarrow b + c = 18","explanation":"Downstream the current helps."},{"latex":"3(b - c) = 36 \\Rightarrow b - c = 12","explanation":"Upstream it slows the boat."},{"latex":"2b = 30 \\Rightarrow b = 15,\\ c = 3","explanation":"Add the equations."}],"check":"Boat 15 km/h, current 3 km/h. Downstream 18 km/h for 2 h = 36 km ✓."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2fff99023a07a9', 'les_e58c256d2b5417', 'learn', 4, 'worked_example', '{"title":"Break-even: a bakery''s costs are $C = 400 + 1.5x$ and revenue is $R = 3.5x$ for $x$ loaves. When does it break even?","steps":[{"latex":"3.5x = 400 + 1.5x","explanation":"Break even when revenue equals cost."},{"latex":"2x = 400 \\Rightarrow x = 200","explanation":"200 loaves (700 dollars of revenue)."}],"check":"Selling more than 200 loaves makes a profit; fewer causes a loss."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8c4be37c9ff57e', 'les_e58c256d2b5417', 'experiment', 5, 'activity', '{"activity":"systems-graph","title":"Break-even on a graph (scaled)","params":{"m1":1.5,"b1":4,"m2":3.5,"b2":0}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5002b1450bdc8f', 'les_e58c256d2b5417', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Scaled down by 100 loaves and 100 dollars, cost is $y = 1.5x + 4$ and revenue is $y = 3.5x$. Where do the lines cross? Which line is higher to the right of that point, and what does that mean for the bakery?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7b52c788c23628', 'les_e58c256d2b5417', 'learn', 7, 'callout', '{"tone":"warning","title":"Answer the real question","body":"If the problem asks for \"the price of an adult ticket,\" don''t stop at listing both variables without saying which is which. And reject answers that make no sense, such as negative coins or 12.6 people; they signal an error in the setup."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_93f1ba5b28bb65', 'les_e58c256d2b5417', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Nutrition planning (two foods supplying exactly so much protein and so many calories), comparing job offers, mixing alloys or solutions, and setting prices all lead to systems of equations."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5cea44d8f783fc', 'les_e58c256d2b5417', 1, 'practice', 'numeric', 2, 'A theater sold 220 tickets. Adult tickets cost 12 dollars and child tickets 7 dollars, and sales were 2,140 dollars. How many adult tickets were sold?', '{"answer":120}', '["$a + c = 220$, $12a + 7c = 2140$.","Substitute $c = 220 - a$."]', '$12a + 1540 - 7a = 2140$, so $5a = 600$ and $a = 120$ (and $c = 100$).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e1bc13a4c73be7', 'les_e58c256d2b5417', 2, 'practice', 'numeric', 2, 'How many liters of a 30% salt solution must be mixed with a 70% salt solution to make 20 L of a 45% solution?', '{"answer":12.5,"unit":"L"}', '["$x + y = 20$, $0.30x + 0.70y = 9$."]', 'From $y = 20 - x$: $0.30x + 14 - 0.70x = 9$, so $-0.40x = -5$ and $x = 12.5$ L of the 30% solution (and 7.5 L of the 70%).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_72aa5dca12464e', 'les_e58c256d2b5417', 3, 'practice', 'numeric', 2, 'A plane flies 1,200 miles with the wind in 3 hours and returns against the wind in 4 hours. What is the wind speed, in mph?', '{"answer":50,"unit":"mph"}', '["$p + w = 400$ and $p - w = 300$."]', 'Subtracting gives $2w = 100$, so $w = 50$ mph (and the plane''s airspeed is 350 mph).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2fff99023a07a9', 'les_e58c256d2b5417', 4, 'practice', 'numeric', 3, 'A company sells shirts for 18 dollars each. It has fixed costs of 2,400 dollars and each shirt costs 6 dollars to make. How many shirts must it sell to break even?', '{"answer":200}', '["$18x = 2400 + 6x$."]', '$12x = 2400$, so $x = 200$ shirts.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8c4be37c9ff57e', 'les_e58c256d2b5417', 5, 'review', 'short_text', 3, 'The perimeter of a rectangle is 54 cm and its length is 3 cm less than twice its width. Find the length in cm.', '{"accept":["17"]}', '["$2l + 2w = 54$ and $l = 2w - 3$."]', '$2(2w - 3) + 2w = 54$, so $6w = 60$, $w = 10$ and $l = 17$ cm.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5002b1450bdc8f', 'les_e58c256d2b5417', 6, 'review', 'numeric', 3, 'A jar has 40 nickels and quarters worth 6.00 dollars. How many quarters are there?', '{"answer":20}', '["$n + q = 40$, $0.05n + 0.25q = 6$."]', 'Multiply value by 20: $n + 5q = 120$. Subtract the count: $4q = 80$, $q = 20$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_892a66cf1a2bc1', 'subj_math', 'systems-of-equations', 'Systems of linear equations', 'Two or more equations solved together; solutions satisfy all of them.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e58c256d2b5417', (SELECT id FROM concepts WHERE slug = 'systems-of-equations'));

-- Lesson: multiplying-dividing-integers
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c3cafc8e04d825', 'multiplying-dividing-integers', 'Multiplying and dividing integers', 'Find the sign of a product or quotient, see why a negative times a negative is positive, and work with zero.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7d06fee12e1285', 'les_c3cafc8e04d825', 1, 'Multiply and divide integers and determine the sign of the result.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b5913bb1da85c3', 'les_c3cafc8e04d825', 2, 'Explain why the product of two negative numbers is positive using patterns.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9fdc6331b8219d', 'les_c3cafc8e04d825', 3, 'Recognize that division by zero is undefined.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7d06fee12e1285', 'les_c3cafc8e04d825', 'learn', 1, 'text', '{"body":"Multiplication is repeated addition: $3 \\times (-4)$ means three groups of $-4$, which is $-4 + (-4) + (-4) = -12$. A positive times a negative is negative. Because order doesn''t matter in multiplication, $(-4) \\times 3$ is also $-12$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b5913bb1da85c3', 'les_c3cafc8e04d825', 'learn', 2, 'text', '{"body":"What about a negative times a negative? Look at the pattern below. Each time the first factor drops by 1, the product goes up by 4. Continuing the pattern forces $(-1)(-4) = 4$ and $(-2)(-4) = 8$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9fdc6331b8219d', 'les_c3cafc8e04d825', 'learn', 3, 'worked_example', '{"title":"A pattern for $(-4)$ times decreasing numbers","steps":[{"latex":"2 \\times (-4) = -8","explanation":""},{"latex":"1 \\times (-4) = -4","explanation":"Up by 4."},{"latex":"0 \\times (-4) = 0","explanation":"Up by 4 again."},{"latex":"(-1) \\times (-4) = 4","explanation":"The pattern continues: up by 4 makes a positive."},{"latex":"(-2) \\times (-4) = 8","explanation":"So a negative times a negative is positive."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5ae89d615d5e1d', 'les_c3cafc8e04d825', 'learn', 4, 'definition', '{"term":"Sign rules","body":"Same signs give a positive result; different signs give a negative result. These rules apply to both multiplication and division: $(-24) \\div (-6) = 4$ and $24 \\div (-6) = -4$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eacb8e90878ebf', 'les_c3cafc8e04d825', 'learn', 5, 'text', '{"body":"With several factors, count the negatives. An even number of negative factors gives a positive product; an odd number gives a negative product. For example $(-1)(-2)(-3) = -6$ has three negative factors, so it is negative."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_47555b57128da6', 'les_c3cafc8e04d825', 'learn', 6, 'callout', '{"tone":"warning","title":"Zero","body":"$0 \\div 5 = 0$, because $0 \\times 5 = 0$. But $5 \\div 0$ is undefined: no number times 0 gives 5. Expressions like $\\frac{7}{0}$ have no value."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e9ff30c0f37c0b', 'les_c3cafc8e04d825', 'learn', 7, 'worked_example', '{"title":"Evaluate $\\dfrac{(-6)(5)}{-3} \\cdot (-2)$","steps":[{"latex":"(-6)(5) = -30","explanation":"Different signs: negative."},{"latex":"-30 \\div (-3) = 10","explanation":"Same signs: positive."},{"latex":"10 \\cdot (-2) = -20","explanation":"Different signs: negative."}],"check":"Count negatives in the whole expression: −6, −3 and −2 make three, an odd number, so the result must be negative. It is."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0dbb2f943cd487', 'les_c3cafc8e04d825', 'learn', 8, 'worked_example', '{"title":"Evaluate $(-2)^4$ and $-2^4$","steps":[{"latex":"(-2)^4 = (-2)(-2)(-2)(-2) = 16","explanation":"Four negative factors: an even count, so the result is positive."},{"latex":"-2^4 = -(2 \\cdot 2 \\cdot 2 \\cdot 2) = -16","explanation":"Without parentheses the exponent applies only to 2. The minus sign is applied afterwards."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cd072c1f93c6a3', 'les_c3cafc8e04d825', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"A stock that loses 3 dollars a day for 5 days changes by $5 \\times (-3) = -15$ dollars. Looking back, 4 days ago it was $(-4) \\times (-3) = 12$ dollars higher than today. Negative time multiplied by a negative rate gives a positive change."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7d06fee12e1285', 'les_c3cafc8e04d825', 1, 'practice', 'numeric', 1, 'Evaluate $(-7)(8)$.', '{"answer":-56}', '["Different signs give a negative product."]', '$7 \times 8 = 56$, negative: $-56$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b5913bb1da85c3', 'les_c3cafc8e04d825', 2, 'practice', 'numeric', 1, 'Evaluate $(-9)(-6)$.', '{"answer":54}', '["Same signs give a positive product."]', '$(-9)(-6) = 54$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9fdc6331b8219d', 'les_c3cafc8e04d825', 3, 'practice', 'numeric', 1, 'Evaluate $-63 \div 7$.', '{"answer":-9}', '["Different signs give a negative quotient."]', '$63 \div 7 = 9$, so $-9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5ae89d615d5e1d', 'les_c3cafc8e04d825', 4, 'practice', 'numeric', 2, 'Evaluate $\dfrac{-84}{-12}$.', '{"answer":7}', '["Same signs give a positive quotient."]', '$84 \div 12 = 7$, positive.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eacb8e90878ebf', 'les_c3cafc8e04d825', 5, 'practice', 'multiple_choice', 2, 'What is the sign of $(-3)(-1)(4)(-2)(-5)$?', '{"choices":["Positive","Negative","Zero","Not possible to tell"],"answer":0}', '["Count the negative factors."]', 'There are four negative factors, an even number, so the product is positive. (It equals 120.)');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_47555b57128da6', 'les_c3cafc8e04d825', 6, 'practice', 'numeric', 2, 'Evaluate $(-3)^3$.', '{"answer":-27}', '["Three negative factors."]', '$(-3)(-3)(-3) = 9 \cdot (-3) = -27$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e9ff30c0f37c0b', 'les_c3cafc8e04d825', 7, 'practice', 'numeric', 2, 'A diver descends at 4 meters per second for 9 seconds. What is the change in depth, in meters (use a negative number for downward)?', '{"answer":-36,"unit":"m"}', '["Rate × time, with descending as negative."]', '$(-4)(9) = -36$ meters.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0dbb2f943cd487', 'les_c3cafc8e04d825', 8, 'practice', 'multiple_choice', 2, 'Which expression is undefined?', '{"choices":["$0 \\div (-8)$","$-8 \\div 0$","$0 \\times (-8)$","$-8 \\div (-8)$"],"answer":1}', '["Division by zero has no answer."]', '$-8 \div 0$ is undefined; no number times 0 equals $-8$. The others equal 0, 0 and 1.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cd072c1f93c6a3', 'les_c3cafc8e04d825', 9, 'review', 'short_text', 3, 'Find $n$ if $-6n = 72$.', '{"accept":["-12","n=-12"]}', '["Divide both sides by −6."]', '$n = 72 \div (-6) = -12$. Check: $-6 \cdot (-12) = 72$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e8c137e7e28d15', 'les_c3cafc8e04d825', 10, 'review', 'numeric', 3, 'Evaluate $\dfrac{(-2)^3 \cdot (-3)}{-4}$.', '{"answer":-6}', '["$(-2)^3 = -8$.","$-8 \\cdot (-3) = 24$."]', '$\frac{(-8)(-3)}{-4} = \frac{24}{-4} = -6$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_63b5062a11fac9', 'subj_math', 'integer-multiplication', 'Integer multiplication and division', 'Products and quotients of signed numbers and their signs.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c3cafc8e04d825', (SELECT id FROM concepts WHERE slug = 'integer-multiplication'));

-- Lesson: multiplying-polynomials
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_96d56f592219a3', 'multiplying-polynomials', 'Multiplying polynomials', 'Multiply monomials, binomials and larger polynomials with the distributive property and the area model, and check products by substitution.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cfa056bfd1da08', 'les_96d56f592219a3', 1, 'Multiply a polynomial by a monomial.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bb471be7aa256f', 'les_96d56f592219a3', 2, 'Multiply two binomials using the area model or the distributive property (FOIL as a special case).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d8b431080f287f', 'les_96d56f592219a3', 3, 'Multiply a binomial by a trinomial and simplify the product.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cfa056bfd1da08', 'les_96d56f592219a3', 'learn', 1, 'text', '{"body":"Every polynomial product is the distributive property applied repeatedly: each term of the first factor multiplies each term of the second. The area model keeps track of all those products in a grid, and then like terms are combined."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bb471be7aa256f', 'les_96d56f592219a3', 'learn', 2, 'worked_example', '{"title":"Multiply $-3x^2(4x^2 - 2x + 5)$","steps":[{"latex":"(-3x^2)(4x^2) + (-3x^2)(-2x) + (-3x^2)(5)","explanation":"Distribute to each term."},{"latex":"-12x^4 + 6x^3 - 15x^2","explanation":"Multiply coefficients and add exponents."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d8b431080f287f', 'les_96d56f592219a3', 'experiment', 3, 'activity', '{"activity":"area-model","title":"Binomial times binomial","params":{"a":2,"b":3,"c":1,"d":-4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5b48de62db7791', 'les_96d56f592219a3', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"The model shows $(2x + 3)(x - 4)$. Read the four cells: $2x^2$, $3x$, $-8x$ and $-12$. Combine them, then change $d$ to $+4$ and predict the new middle term before looking."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d91ce4f982357b', 'les_96d56f592219a3', 'learn', 5, 'worked_example', '{"title":"Multiply $(2x + 3)(x - 4)$","steps":[{"latex":"2x \\cdot x + 2x(-4) + 3 \\cdot x + 3(-4)","explanation":"Each term times each term (First, Outer, Inner, Last)."},{"latex":"2x^2 - 8x + 3x - 12","explanation":""},{"latex":"2x^2 - 5x - 12","explanation":"Combine the like middle terms."}],"check":"Check with $x = 1$: $(5)(-3) = -15$ and $2 - 5 - 12 = -15$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ed2cd575a5668e', 'les_96d56f592219a3', 'learn', 6, 'worked_example', '{"title":"Multiply $(x - 2)(x^2 + 3x - 1)$","steps":[{"latex":"x(x^2 + 3x - 1) - 2(x^2 + 3x - 1)","explanation":"Distribute each term of the binomial."},{"latex":"x^3 + 3x^2 - x - 2x^2 - 6x + 2","explanation":""},{"latex":"x^3 + x^2 - 7x + 2","explanation":"Combine like terms."}],"check":"A 2-term factor times a 3-term factor gives 6 products before combining."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_980c901010a7d4', 'les_96d56f592219a3', 'learn', 7, 'callout', '{"tone":"warning","title":"FOIL is only for two binomials","body":"FOIL is a mnemonic for the four products of two binomials. For longer polynomials, use the distributive property or a larger area grid; every term must meet every term."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fe11236d6f76e9', 'les_96d56f592219a3', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"A garden $x$ m by $x + 5$ m with a 2-m path all around covers $(x + 4)(x + 9) = x^2 + 13x + 36$ m². Subtract the garden''s $x^2 + 5x$ to get the path area, $8x + 36$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cfa056bfd1da08', 'les_96d56f592219a3', 1, 'practice', 'short_text', 1, 'Multiply $4x(3x - 7)$.', '{"accept":["12x^2-28x"]}', '["Distribute 4x."]', '$12x^2 - 28x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bb471be7aa256f', 'les_96d56f592219a3', 2, 'practice', 'short_text', 2, 'Multiply $(x + 5)(x + 2)$.', '{"accept":["x^2+7x+10"]}', '["Four products, then combine the middle terms."]', '$x^2 + 2x + 5x + 10 = x^2 + 7x + 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d8b431080f287f', 'les_96d56f592219a3', 3, 'practice', 'short_text', 2, 'Multiply $(3x - 1)(2x + 5)$.', '{"accept":["6x^2+13x-5"]}', '["$6x^2 + 15x - 2x - 5$."]', '$6x^2 + 13x - 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5b48de62db7791', 'les_96d56f592219a3', 4, 'practice', 'short_text', 2, 'Multiply $(x - 6)(x + 6)$.', '{"accept":["x^2-36"]}', '["The middle terms cancel."]', '$x^2 + 6x - 6x - 36 = x^2 - 36$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d91ce4f982357b', 'les_96d56f592219a3', 5, 'practice', 'multiple_choice', 2, 'What is the coefficient of $x$ in $(2x - 3)(4x + 1)$?', '{"choices":["−12","−10","2","14"],"answer":1}', '["Outer + inner: $2x \\cdot 1 + (-3)(4x)$."]', '$2x - 12x = -10x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ed2cd575a5668e', 'les_96d56f592219a3', 6, 'review', 'short_text', 3, 'Multiply $(x + 3)(x^2 - 2x + 4)$.', '{"accept":["x^3+x^2-2x+12"]}', '["$x^3 - 2x^2 + 4x + 3x^2 - 6x + 12$."]', '$x^3 + x^2 - 2x + 12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_980c901010a7d4', 'les_96d56f592219a3', 7, 'review', 'short_text', 3, 'A rectangle has length $3x + 2$ and width $x - 1$. Write its area in standard form.', '{"accept":["3x^2-x-2"]}', '["Area = length × width."]', '$3x^2 - 3x + 2x - 2 = 3x^2 - x - 2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_4bafbcd5e3010f', 'subj_math', 'polynomials', 'Polynomials', 'Sums of terms of the form axⁿ with whole-number exponents.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_96d56f592219a3', (SELECT id FROM concepts WHERE slug = 'polynomials'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_862d74cf83941b', 'subj_math', 'distributive-property', 'Distributive property', 'a(b + c) = ab + ac: multiplication distributes over addition and subtraction.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_96d56f592219a3', (SELECT id FROM concepts WHERE slug = 'distributive-property'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_96d56f592219a3', (SELECT id FROM formulas WHERE slug = 'exponent-rules'), 1);

-- Lesson: one-step-equations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7c201e76f18f21', 'one-step-equations', 'One-step equations', 'Solve equations that need a single inverse operation, using the properties of equality, and check every solution.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_730af412302d2e', 'les_7c201e76f18f21', 1, 'Explain what a solution of an equation is.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7140c573c5afbc', 'les_7c201e76f18f21', 2, 'Solve one-step equations using inverse operations and the properties of equality.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eef097989dc29c', 'les_7c201e76f18f21', 3, 'Write and solve a one-step equation from a word problem and check the answer in context.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_730af412302d2e', 'les_7c201e76f18f21', 'learn', 1, 'definition', '{"term":"Equation and solution","body":"An equation states that two expressions are equal, like $x + 9 = 4$. A solution is a value of the variable that makes the statement true. Here $x = -5$ is the solution because $-5 + 9 = 4$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7140c573c5afbc', 'les_7c201e76f18f21', 'learn', 2, 'text', '{"body":"An equation is like a balanced scale. To keep it balanced, whatever you do to one side you must do to the other. To solve, use the inverse operation that undoes what has been done to the variable. Addition and subtraction undo each other, and so do multiplication and division."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eef097989dc29c', 'les_7c201e76f18f21', 'learn', 3, 'definition', '{"term":"Properties of equality","body":"If $a = b$, then $a + c = b + c$, $a - c = b - c$, $ac = bc$, and $\\frac{a}{c} = \\frac{b}{c}$ for $c \\ne 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8b6c86d2dd5bd9', 'les_7c201e76f18f21', 'experiment', 4, 'activity', '{"activity":"balance-equation","title":"Keep the scale balanced","params":{"a":1,"b":9,"c":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_59b6316d0527b2', 'les_7c201e76f18f21', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Solve $x + 9 = 4$ in the balance. Then set $a = 4$, $b = 0$, $c = -28$ to solve $4x = -28$. Which operation removes the 4?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3a009b3a1e63bd', 'les_7c201e76f18f21', 'learn', 6, 'worked_example', '{"title":"Solve $y - 12 = -7$","steps":[{"latex":"y - 12 + 12 = -7 + 12","explanation":"12 is subtracted from y; add 12 to both sides."},{"latex":"y = 5","explanation":""}],"check":"Check: $5 - 12 = -7$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3f76646ecf7317', 'les_7c201e76f18f21', 'learn', 7, 'worked_example', '{"title":"Solve $-6n = 42$","steps":[{"latex":"\\frac{-6n}{-6} = \\frac{42}{-6}","explanation":"n is multiplied by −6; divide both sides by −6."},{"latex":"n = -7","explanation":""}],"check":"Check: $-6(-7) = 42$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9f6ffc5a62e2ce', 'les_7c201e76f18f21', 'learn', 8, 'worked_example', '{"title":"Solve $\\tfrac{3}{4}k = 18$","steps":[{"latex":"\\tfrac{4}{3} \\cdot \\tfrac{3}{4}k = \\tfrac{4}{3} \\cdot 18","explanation":"Multiply by the reciprocal, 4/3, to undo multiplying by 3/4."},{"latex":"k = 24","explanation":"$\\frac{4 \\cdot 18}{3} = 24$."}],"check":"Check: $\\frac{3}{4} \\cdot 24 = 18$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d8861a38661913', 'les_7c201e76f18f21', 'learn', 9, 'worked_example', '{"title":"After spending 23.75 dollars, Jay has 41.50 dollars left. How much did he start with?","steps":[{"latex":"s - 23.75 = 41.50","explanation":"Let s be the starting amount."},{"latex":"s = 41.50 + 23.75 = 65.25","explanation":"Add 23.75 to both sides."}],"check":"Jay started with 65.25 dollars. Check: 65.25 − 23.75 = 41.50."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ac84cd0724df22', 'les_7c201e76f18f21', 'learn', 10, 'callout', '{"tone":"warning","title":"Divide by the whole coefficient","body":"In $-x = 9$, the coefficient is $-1$. Divide (or multiply) by $-1$: $x = -9$. Writing $x = 9$ ignores the negative sign."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c474b64ad7f8ae', 'les_7c201e76f18f21', 'learn', 11, 'callout', '{"tone":"application","title":"Where this shows up","body":"\"A box of 8 identical bottles weighs 6 kg; how much does one weigh?\" is $8w = 6$, so $w = 0.75$ kg. Many everyday questions are one-step equations in disguise."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_730af412302d2e', 'les_7c201e76f18f21', 1, 'practice', 'numeric', 1, 'Solve $x + 15 = 6$.', '{"answer":-9}', '["Subtract 15 from both sides."]', '$x = 6 - 15 = -9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7140c573c5afbc', 'les_7c201e76f18f21', 2, 'practice', 'numeric', 1, 'Solve $\frac{m}{4} = -3$.', '{"answer":-12}', '["Multiply both sides by 4."]', '$m = -12$. Check: $-12 \div 4 = -3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eef097989dc29c', 'les_7c201e76f18f21', 3, 'practice', 'numeric', 1, 'Solve $-9p = -54$.', '{"answer":6}', '["Divide both sides by −9."]', '$p = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8b6c86d2dd5bd9', 'les_7c201e76f18f21', 4, 'practice', 'numeric', 2, 'Solve $w - 3.6 = -1.2$.', '{"answer":2.4}', '["Add 3.6 to both sides."]', '$w = -1.2 + 3.6 = 2.4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_59b6316d0527b2', 'les_7c201e76f18f21', 5, 'practice', 'numeric', 2, 'Solve $-\tfrac{2}{5}x = 8$.', '{"answer":-20}', '["Multiply by $-\\frac{5}{2}$."]', '$x = 8 \cdot \left(-\frac{5}{2}\right) = -20$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3a009b3a1e63bd', 'les_7c201e76f18f21', 6, 'practice', 'multiple_choice', 2, 'Which equation has the solution $x = -4$?', '{"choices":["$x + 7 = -11$","$-3x = 12$","$\\frac{x}{2} = 2$","$x - 5 = 1$"],"answer":1}', '["Substitute −4 into each equation."]', '$-3(-4) = 12$ is true. The others give $3 \ne -11$, $-2 \ne 2$ and $-9 \ne 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3f76646ecf7317', 'les_7c201e76f18f21', 7, 'practice', 'numeric', 2, 'A shirt costs 3 times as much as a pair of socks. The shirt costs 22.50 dollars. How much do the socks cost?', '{"answer":7.5,"unit":"dollars"}', '["$3s = 22.50$."]', '$s = 22.50 \div 3 = 7.50$ dollars.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9f6ffc5a62e2ce', 'les_7c201e76f18f21', 8, 'review', 'numeric', 3, 'The temperature dropped 14 degrees overnight to $-5^\circ$F. What was the temperature the evening before?', '{"answer":9,"unit":"°F"}', '["$t - 14 = -5$."]', '$t = -5 + 14 = 9^\circ$F.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d8861a38661913', 'les_7c201e76f18f21', 9, 'review', 'short_text', 3, 'Solve $-x = -\tfrac{3}{8}$. Enter x as a fraction.', '{"accept":["3/8","x=3/8"]}', '["Multiply both sides by −1."]', '$x = \frac{3}{8}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_af8e49eafb99e2', 'subj_math', 'properties-of-equality', 'Properties of equality', 'Doing the same operation to both sides of an equation keeps it true.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7c201e76f18f21', (SELECT id FROM concepts WHERE slug = 'properties-of-equality'));

-- Lesson: operations-with-decimals
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_fa74b5eae9f445', 'operations-with-decimals', 'Operations with decimals', 'Add, subtract, multiply and divide decimals, including negative decimals, and check answers by estimating.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c4798a81400a48', 'les_fa74b5eae9f445', 1, 'Add and subtract decimals by aligning place values.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a1d83c161dd87b', 'les_fa74b5eae9f445', 2, 'Multiply decimals and place the decimal point by counting decimal places.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_95f792e6ff6713', 'les_fa74b5eae9f445', 3, 'Divide by a decimal by first making the divisor a whole number, and check with estimation.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c4798a81400a48', 'les_fa74b5eae9f445', 'learn', 1, 'text', '{"body":"A decimal is a fraction whose denominator is a power of ten: $0.7 = \\frac{7}{10}$ and $2.35 = \\frac{235}{100}$. Every rule for decimals comes from that fact plus place value."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a1d83c161dd87b', 'les_fa74b5eae9f445', 'learn', 2, 'definition', '{"term":"Adding and subtracting","body":"Line up the decimal points so that tenths sit above tenths and hundredths above hundredths. Fill empty places with zeros if that helps: $5.4 - 2.37$ becomes $5.40 - 2.37 = 3.03$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_95f792e6ff6713', 'les_fa74b5eae9f445', 'learn', 3, 'definition', '{"term":"Multiplying","body":"Multiply as if the numbers were whole, then give the product as many decimal places as the factors have in total. $0.3 \\times 0.04$: $3 \\times 4 = 12$, and $1 + 2 = 3$ places gives $0.012$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9856b78b727d72', 'les_fa74b5eae9f445', 'learn', 4, 'text', '{"body":"Why count places? $0.3 = \\frac{3}{10}$ and $0.04 = \\frac{4}{100}$, so the product is $\\frac{12}{1000} = 0.012$. The denominators multiply to 1000, which is three decimal places."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_760bd4d3caf585', 'les_fa74b5eae9f445', 'learn', 5, 'definition', '{"term":"Dividing","body":"Multiply the divisor and the dividend by the same power of ten so the divisor is a whole number, then divide. $4.5 \\div 0.15 = 450 \\div 15 = 30$. This doesn''t change the answer, because $\\frac{4.5}{0.15} = \\frac{450}{15}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3b53c0fae338a4', 'les_fa74b5eae9f445', 'learn', 6, 'worked_example', '{"title":"Evaluate $-3.6 + 1.25 - 0.8$","steps":[{"latex":"-3.60 + 1.25 = -2.35","explanation":"Different signs: 3.60 − 1.25 = 2.35, keep the negative."},{"latex":"-2.35 - 0.80 = -3.15","explanation":"Same direction (both negative): add and keep the sign."}],"check":"Estimate: −4 + 1 − 1 = −4. The answer −3.15 is reasonably close."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e3b030e2c1aaa1', 'les_fa74b5eae9f445', 'learn', 7, 'worked_example', '{"title":"Evaluate $2.6 \\times (-0.35)$","steps":[{"latex":"26 \\times 35 = 910","explanation":"Multiply as whole numbers."},{"latex":"0.910","explanation":"One place + two places = three decimal places."},{"latex":"-0.91","explanation":"Different signs: negative. Trailing zeros can be dropped."}],"check":"Estimate: $3 \\times 0.35 \\approx 1$, so a size near 0.9 is believable."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6b956116147fbe', 'les_fa74b5eae9f445', 'learn', 8, 'worked_example', '{"title":"Evaluate $7.68 \\div 0.24$","steps":[{"latex":"768 \\div 24","explanation":"Move both decimal points two places right."},{"latex":"= 32","explanation":"24 × 32 = 768."}],"check":"Check: $0.24 \\times 32 = 7.68$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_94db3cd39539f2', 'les_fa74b5eae9f445', 'learn', 9, 'callout', '{"tone":"warning","title":"Dividing by a decimal less than 1","body":"Dividing by a number between 0 and 1 makes the result larger, and multiplying by one makes it smaller. $6 \\div 0.5 = 12$ but $6 \\times 0.5 = 3$. If your answer goes the wrong way, recheck the decimal point."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f20781edb24c04', 'les_fa74b5eae9f445', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Gas costs 3.49 dollars per gallon and you buy 11.2 gallons: $3.49 \\times 11.2 = 39.088$, about 39.09 dollars. A 2.5-liter bottle poured into 0.25-liter cups fills $2.5 \\div 0.25 = 10$ cups."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c4798a81400a48', 'les_fa74b5eae9f445', 1, 'practice', 'numeric', 1, 'Evaluate $8.4 - 3.75$.', '{"answer":4.65}', '["Write 8.4 as 8.40."]', '$8.40 - 3.75 = 4.65$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a1d83c161dd87b', 'les_fa74b5eae9f445', 2, 'practice', 'numeric', 1, 'Evaluate $0.6 \times 0.7$.', '{"answer":0.42}', '["6 × 7 = 42; count the decimal places."]', 'Two decimal places in total: $0.42$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_95f792e6ff6713', 'les_fa74b5eae9f445', 3, 'practice', 'numeric', 2, 'Evaluate $1.5 \times (-0.08)$.', '{"answer":-0.12}', '["15 × 8 = 120.","Three decimal places, negative sign."]', '$-0.120 = -0.12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9856b78b727d72', 'les_fa74b5eae9f445', 4, 'practice', 'numeric', 2, 'Evaluate $9.1 \div 0.13$.', '{"answer":70}', '["Move both decimal points two places: 910 ÷ 13."]', '$910 \div 13 = 70$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_760bd4d3caf585', 'les_fa74b5eae9f445', 5, 'practice', 'numeric', 2, 'Evaluate $-4.2 - (-6.05)$.', '{"answer":1.85}', '["Subtracting a negative is adding."]', '$-4.20 + 6.05 = 1.85$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3b53c0fae338a4', 'les_fa74b5eae9f445', 6, 'practice', 'multiple_choice', 2, 'Without calculating exactly, which is closest to $48.2 \div 0.49$?', '{"choices":["About 2.4","About 24","About 100","About 1000"],"answer":2}', '["0.49 is about one half.","Dividing by one half doubles."]', '$48 \div 0.5 = 96$, so about 100. (The exact value is about 98.4.)');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e3b030e2c1aaa1', 'les_fa74b5eae9f445', 7, 'practice', 'numeric', 2, 'Notebooks cost 2.35 dollars each. How much do 6 notebooks cost, in dollars?', '{"answer":14.1,"unit":"dollars"}', '["Multiply 2.35 by 6."]', '$2.35 \times 6 = 14.10$ dollars.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6b956116147fbe', 'les_fa74b5eae9f445', 8, 'review', 'numeric', 3, 'A 3.6-meter board is cut into pieces 0.45 m long. How many pieces are there?', '{"answer":8}', '["Divide 3.6 by 0.45.","Multiply both by 100: 360 ÷ 45."]', '$360 \div 45 = 8$ pieces. Check: $0.45 \times 8 = 3.6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_94db3cd39539f2', 'les_fa74b5eae9f445', 9, 'review', 'numeric', 3, 'Evaluate $(2.5 - 4.1) \times 0.5 + 0.3$.', '{"answer":-0.5}', '["Parentheses first: 2.5 − 4.1 = −1.6."]', '$-1.6 \times 0.5 = -0.8$, then $-0.8 + 0.3 = -0.5$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_5d674cfe1c0346', 'subj_math', 'decimal-operations', 'Decimal operations', 'Arithmetic with numbers written in base-ten decimal form.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_fa74b5eae9f445', (SELECT id FROM concepts WHERE slug = 'decimal-operations'));

-- Lesson: operations-with-fractions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5118fdbf4738c4', 'operations-with-fractions', 'Operations with fractions', 'Add and subtract fractions with a common denominator, multiply straight across, and divide by multiplying by the reciprocal, including mixed numbers and negatives.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c8329082223915', 'les_5118fdbf4738c4', 1, 'Add and subtract fractions and mixed numbers using a least common denominator.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cf327bb7beaae6', 'les_5118fdbf4738c4', 2, 'Multiply fractions and simplify before or after multiplying.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e3b1e8286137ed', 'les_5118fdbf4738c4', 3, 'Divide fractions by multiplying by the reciprocal, and explain why it works.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c8329082223915', 'les_5118fdbf4738c4', 'learn', 1, 'text', '{"body":"A fraction $\\frac{a}{b}$ means $a$ pieces, each of size $\\frac{1}{b}$. You can only add or subtract pieces that are the same size, so fractions need a common denominator first. Multiplying and dividing do not need one."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cf327bb7beaae6', 'les_5118fdbf4738c4', 'learn', 2, 'definition', '{"term":"Least common denominator (LCD)","body":"The least common multiple of the denominators. For $\\frac{1}{6}$ and $\\frac{3}{8}$ the LCD is 24, because 24 is the smallest number both 6 and 8 divide into."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e3b1e8286137ed', 'les_5118fdbf4738c4', 'experiment', 3, 'activity', '{"activity":"fraction-bars","title":"Why a common denominator?","params":{"n1":1,"d1":2,"n2":1,"d2":3,"op":"add"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c6a170ef73854', 'les_5118fdbf4738c4', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Add $\\frac{1}{2} + \\frac{1}{3}$ in the simulation, then change the second fraction to $\\frac{2}{6}$. The thin cells change size but the shaded length stays the same. That''s why rewriting with a common denominator doesn''t change the value."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1a0bd096e81562', 'les_5118fdbf4738c4', 'learn', 5, 'worked_example', '{"title":"Evaluate $\\frac{5}{6} - \\frac{3}{8}$","steps":[{"latex":"\\tfrac{5}{6} = \\tfrac{20}{24},\\quad \\tfrac{3}{8} = \\tfrac{9}{24}","explanation":"LCD of 6 and 8 is 24. Multiply top and bottom by the same factor."},{"latex":"\\tfrac{20}{24} - \\tfrac{9}{24} = \\tfrac{11}{24}","explanation":"Same-size pieces: subtract the numerators, keep the denominator."}],"check":"$\\frac{11}{24} \\approx 0.458$, and $0.833 - 0.375 = 0.458$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_605f48b884a605', 'les_5118fdbf4738c4', 'learn', 6, 'definition', '{"term":"Multiplying fractions","body":"$\\dfrac{a}{b} \\cdot \\dfrac{c}{d} = \\dfrac{ac}{bd}$. Multiply numerators and multiply denominators. \"Of\" usually means multiply: $\\frac{2}{3}$ of $\\frac{3}{4}$ is $\\frac{2}{3} \\cdot \\frac{3}{4} = \\frac{6}{12} = \\frac{1}{2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4b6da97429e7a1', 'les_5118fdbf4738c4', 'learn', 7, 'definition', '{"term":"Dividing fractions","body":"$\\dfrac{a}{b} \\div \\dfrac{c}{d} = \\dfrac{a}{b} \\cdot \\dfrac{d}{c}$, where $c \\ne 0$. Dividing by a number is the same as multiplying by its reciprocal."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c262c6e5184588', 'les_5118fdbf4738c4', 'learn', 8, 'text', '{"body":"Why does flipping work? $3 \\div \\frac{1}{4}$ asks how many quarters fit in 3. Four quarters fit in each whole, so 12 fit in 3, and $3 \\cdot 4 = 12$. In general, multiplying $\\frac{c}{d}$ by $\\frac{d}{c}$ gives 1, so multiplying by the reciprocal undoes the division."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ada693b5d9208a', 'les_5118fdbf4738c4', 'learn', 9, 'worked_example', '{"title":"Evaluate $2\\frac{1}{4} \\div \\left(-\\frac{3}{5}\\right)$","steps":[{"latex":"2\\tfrac{1}{4} = \\tfrac{9}{4}","explanation":"Convert the mixed number: 2 · 4 + 1 = 9 quarters."},{"latex":"\\tfrac{9}{4} \\cdot \\left(-\\tfrac{5}{3}\\right)","explanation":"Multiply by the reciprocal of −3/5."},{"latex":"\\tfrac{\\cancel{9}^{\\,3}}{4} \\cdot \\left(-\\tfrac{5}{\\cancel{3}_{\\,1}}\\right) = -\\tfrac{15}{4}","explanation":"Simplify 9 and 3 first, then multiply. Different signs: negative."},{"latex":"-\\tfrac{15}{4} = -3\\tfrac{3}{4}","explanation":"Write as a mixed number if asked."}],"check":"Estimate: $2.25 \\div 0.6 \\approx 3.75$, and the sign is negative."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_56bf7f42d4933a', 'les_5118fdbf4738c4', 'learn', 10, 'worked_example', '{"title":"Evaluate $3\\frac{2}{3} + 1\\frac{5}{6}$","steps":[{"latex":"3\\tfrac{4}{6} + 1\\tfrac{5}{6}","explanation":"LCD is 6."},{"latex":"4\\tfrac{9}{6}","explanation":"Add whole parts and fraction parts."},{"latex":"4 + 1\\tfrac{3}{6} = 5\\tfrac{1}{2}","explanation":"9/6 is more than a whole: 1 and 3/6."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7b9f329a6d159e', 'les_5118fdbf4738c4', 'learn', 11, 'callout', '{"tone":"warning","title":"Common mistakes","body":"Never add denominators: $\\frac{1}{2} + \\frac{1}{3} \\ne \\frac{2}{5}$. Do not find a common denominator to multiply. And when dividing, flip only the second fraction (the divisor)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c75f897fcdc851', 'les_5118fdbf4738c4', 'learn', 12, 'callout', '{"tone":"application","title":"Where this shows up","body":"A recipe calls for $\\frac{3}{4}$ cup of flour and you want to make $2\\frac{1}{2}$ batches: $\\frac{3}{4} \\cdot \\frac{5}{2} = \\frac{15}{8} = 1\\frac{7}{8}$ cups. A board $7\\frac{1}{2}$ feet long cut into $\\frac{3}{4}$-foot pieces gives $\\frac{15}{2} \\div \\frac{3}{4} = 10$ pieces."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c8329082223915', 'les_5118fdbf4738c4', 1, 'practice', 'short_text', 1, 'Evaluate $\frac{2}{5} + \frac{1}{4}$. Give a fraction in simplest form, a/b.', '{"accept":["13/20"]}', '["The LCD of 5 and 4 is 20."]', '$\frac{8}{20} + \frac{5}{20} = \frac{13}{20}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cf327bb7beaae6', 'les_5118fdbf4738c4', 2, 'practice', 'short_text', 1, 'Evaluate $\frac{4}{9} \cdot \frac{3}{8}$ in simplest form.', '{"accept":["1/6"]}', '["Simplify 4 with 8 and 3 with 9 before multiplying."]', '$\frac{4 \cdot 3}{9 \cdot 8} = \frac{12}{72} = \frac{1}{6}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e3b1e8286137ed', 'les_5118fdbf4738c4', 3, 'practice', 'short_text', 2, 'Evaluate $\frac{5}{6} \div \frac{10}{9}$ in simplest form.', '{"accept":["3/4"]}', '["Multiply by the reciprocal of 10/9."]', '$\frac{5}{6} \cdot \frac{9}{10} = \frac{45}{60} = \frac{3}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7c6a170ef73854', 'les_5118fdbf4738c4', 4, 'practice', 'short_text', 2, 'Evaluate $-\frac{3}{4} + \frac{1}{6}$ in simplest form.', '{"accept":["-7/12"]}', '["LCD is 12.","$-\\frac{9}{12} + \\frac{2}{12}$."]', '$-\frac{9}{12} + \frac{2}{12} = -\frac{7}{12}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1a0bd096e81562', 'les_5118fdbf4738c4', 5, 'practice', 'numeric', 2, 'Evaluate $4\frac{1}{2} - 2\frac{2}{3}$. Enter a fraction or mixed-number value as a fraction, such as 11/6.', '{"answer":1.8333333333333333,"tolerance":0.000001}', '["Convert to improper fractions: $\\frac{9}{2} - \\frac{8}{3}$.","LCD is 6."]', '$\frac{27}{6} - \frac{16}{6} = \frac{11}{6} = 1\frac{5}{6}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_605f48b884a605', 'les_5118fdbf4738c4', 6, 'practice', 'multiple_choice', 2, 'Which is equal to $\frac{2}{3} \div 4$?', '{"choices":["$\\frac{8}{3}$","$\\frac{1}{6}$","$\\frac{2}{12} \\cdot 4$","$\\frac{3}{8}$"],"answer":1}', '["$4 = \\frac{4}{1}$; its reciprocal is $\\frac{1}{4}$."]', '$\frac{2}{3} \cdot \frac{1}{4} = \frac{2}{12} = \frac{1}{6}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4b6da97429e7a1', 'les_5118fdbf4738c4', 7, 'practice', 'numeric', 2, 'A ribbon is $6\frac{3}{4}$ feet long. How many pieces $\frac{3}{8}$ foot long can be cut from it?', '{"answer":18}', '["Divide: $\\frac{27}{4} \\div \\frac{3}{8}$."]', '$\frac{27}{4} \cdot \frac{8}{3} = \frac{216}{12} = 18$ pieces.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c262c6e5184588', 'les_5118fdbf4738c4', 8, 'review', 'numeric', 3, 'Evaluate $\left(\frac{1}{2} - \frac{5}{6}\right) \div \left(-\frac{2}{9}\right)$.', '{"answer":1.5}', '["Inside the parentheses: $\\frac{3}{6} - \\frac{5}{6} = -\\frac{1}{3}$.","Then $-\\frac{1}{3} \\cdot \\left(-\\frac{9}{2}\\right)$."]', '$-\frac{1}{3} \cdot -\frac{9}{2} = \frac{9}{6} = \frac{3}{2} = 1.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ada693b5d9208a', 'les_5118fdbf4738c4', 9, 'review', 'multiple_choice', 2, 'A student wrote $\frac{3}{5} + \frac{1}{5} = \frac{4}{10}$. What is the correct sum and the error?', '{"choices":["$\\frac{4}{10}$; no error","$\\frac{4}{5}$; denominators should not be added","$\\frac{3}{25}$; denominators should be multiplied","$\\frac{2}{5}$; numerators should be subtracted"],"answer":1}', '["Three fifths plus one fifth is how many fifths?"]', 'The pieces are fifths, so 3 fifths + 1 fifth = 4 fifths, $\frac{4}{5}$. The denominator names the size of the pieces and stays the same.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1499d6a8f68b81', 'subj_math', 'fraction-operations', 'Fraction operations', 'Adding, subtracting, multiplying and dividing fractions and mixed numbers.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5118fdbf4738c4', (SELECT id FROM concepts WHERE slug = 'fraction-operations'));

-- Lesson: order-of-operations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_910b651b848bff', 'order-of-operations', 'The order of operations', 'Evaluate expressions with several operations in the agreed order, including grouping symbols, fraction bars and negative numbers.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_066b0b4b1177e1', 'les_910b651b848bff', 1, 'State the order of operations and explain why a shared convention is needed.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1883439fe4762b', 'les_910b651b848bff', 2, 'Evaluate expressions with grouping symbols, exponents, multiplication, division, addition and subtraction.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_48015e388d501b', 'les_910b651b848bff', 3, 'Treat a fraction bar and absolute value bars as grouping symbols.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_066b0b4b1177e1', 'les_910b651b848bff', 'learn', 1, 'text', '{"body":"What is $3 + 4 \\times 5$? If you add first you get 35; if you multiply first you get 23. Both can''t be right, so mathematicians agree on one order. The agreed answer is 23."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1883439fe4762b', 'les_910b651b848bff', 'learn', 2, 'definition', '{"term":"Order of operations","body":"1. Grouping symbols: parentheses ( ), brackets [ ], braces { }, absolute value bars, fraction bars and radicals, innermost first.\n2. Exponents (powers and roots).\n3. Multiplication and division, from left to right.\n4. Addition and subtraction, from left to right."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_48015e388d501b', 'les_910b651b848bff', 'learn', 3, 'callout', '{"tone":"warning","title":"PEMDAS can mislead","body":"The memory aid PEMDAS lists M before D and A before S, but multiplication and division have equal rank (as do addition and subtraction). Work left to right within each rank. $12 \\div 3 \\times 2 = 4 \\times 2 = 8$, not $12 \\div 6 = 2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a245b2cce41ca4', 'les_910b651b848bff', 'learn', 4, 'worked_example', '{"title":"Evaluate $20 - 3(4 - 6)^2 \\div 6$","steps":[{"latex":"20 - 3(-2)^2 \\div 6","explanation":"Parentheses first: 4 − 6 = −2."},{"latex":"20 - 3(4) \\div 6","explanation":"Exponent: (−2)² = 4."},{"latex":"20 - 12 \\div 6 = 20 - 2","explanation":"Multiply and divide left to right: 3 · 4 = 12, then 12 ÷ 6 = 2."},{"latex":"18","explanation":"Subtract last."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_08568181d10e81', 'les_910b651b848bff', 'learn', 5, 'worked_example', '{"title":"Evaluate $\\dfrac{5^2 - 9}{2 + 6} + |{-3}|$","steps":[{"latex":"\\dfrac{25 - 9}{8} + 3","explanation":"The fraction bar groups the top and the bottom separately. Absolute value bars group too."},{"latex":"\\dfrac{16}{8} + 3 = 2 + 3","explanation":"Finish the top, then divide."},{"latex":"5","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_46080f66b512e3', 'les_910b651b848bff', 'learn', 6, 'worked_example', '{"title":"Evaluate $2[\\,9 - (1 + 3)^2\\,] - 4$","steps":[{"latex":"2[\\,9 - 4^2\\,] - 4","explanation":"Innermost grouping first."},{"latex":"2[\\,9 - 16\\,] - 4 = 2(-7) - 4","explanation":""},{"latex":"-14 - 4 = -18","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_519ecfa3ee6c5d', 'les_910b651b848bff', 'learn', 7, 'callout', '{"tone":"tip","title":"Underline as you go","body":"Rewrite the whole expression after each step, changing only one part. It is slower on paper but almost eliminates mistakes with signs and skipped terms."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_32c04804cb1469', 'les_910b651b848bff', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Spreadsheets and calculators follow the same order. Typing =100-20/4 gives 95, not 20. To average three test scores you need =(85+90+77)/3; without the parentheses only 77 is divided."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_066b0b4b1177e1', 'les_910b651b848bff', 1, 'practice', 'numeric', 1, 'Evaluate $6 + 8 \div 2$.', '{"answer":10}', '["Divide before adding."]', '$8 \div 2 = 4$, then $6 + 4 = 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1883439fe4762b', 'les_910b651b848bff', 2, 'practice', 'numeric', 1, 'Evaluate $(6 + 8) \div 2$.', '{"answer":7}', '["Parentheses first."]', '$14 \div 2 = 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_48015e388d501b', 'les_910b651b848bff', 3, 'practice', 'numeric', 2, 'Evaluate $18 \div 3 \times 2 - 4$.', '{"answer":8}', '["Divide and multiply from left to right."]', '$18 \div 3 = 6$, $6 \times 2 = 12$, $12 - 4 = 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a245b2cce41ca4', 'les_910b651b848bff', 4, 'practice', 'numeric', 2, 'Evaluate $5 - 2^3 + 4 \cdot 3$.', '{"answer":9}', '["Exponent first: 2³ = 8."]', '$5 - 8 + 12 = 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_08568181d10e81', 'les_910b651b848bff', 5, 'practice', 'numeric', 2, 'Evaluate $\dfrac{3 + 4 \cdot 6}{7 - 4}$.', '{"answer":9}', '["Simplify the numerator and denominator separately.","Numerator: 3 + 24."]', '$\frac{27}{3} = 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_46080f66b512e3', 'les_910b651b848bff', 6, 'practice', 'numeric', 2, 'Evaluate $-3^2 + (-3)^2$.', '{"answer":0}', '["$-3^2 = -9$ and $(-3)^2 = 9$."]', '$-9 + 9 = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_519ecfa3ee6c5d', 'les_910b651b848bff', 7, 'practice', 'multiple_choice', 2, 'Where should parentheses go so that $2 + 6 \times 3 - 1 = 16$?', '{"choices":["$(2 + 6) \\times 3 - 1$","$2 + 6 \\times (3 - 1)$","$(2 + 6) \\times (3 - 1)$","$2 + (6 \\times 3 - 1)$"],"answer":2}', '["Evaluate each option.","16 = 8 × 2. Which grouping makes an 8 and a 2?"]', '$(2 + 6) \times (3 - 1) = 8 \times 2 = 16$. The others give $23$, $14$ and $19$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_32c04804cb1469', 'les_910b651b848bff', 8, 'review', 'numeric', 3, 'Evaluate $4\left[\,10 - 2(7 - 9)\,\right] \div 8$.', '{"answer":7}', '["Innermost: 7 − 9 = −2.","Then 10 − 2(−2) = 14."]', '$4 \cdot 14 \div 8 = 56 \div 8 = 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0c785532c09edc', 'les_910b651b848bff', 9, 'review', 'short_text', 3, 'A student evaluated $24 \div 4 \cdot 2$ as 3. What is the correct value?', '{"accept":["12"]}', '["Division and multiplication have equal rank; go left to right."]', '$24 \div 4 = 6$, then $6 \cdot 2 = 12$. The student multiplied first.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_910b651b848bff', 'subj_math', 'order-of-operations', 'Order of operations', 'The convention for which operations to carry out first in an expression.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_910b651b848bff', (SELECT id FROM concepts WHERE slug = 'order-of-operations'));

-- Lesson: parallel-perpendicular-lines
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0f2ca5aa438e5f', 'parallel-perpendicular-lines', 'Parallel and perpendicular lines', 'Use slopes to decide whether lines are parallel or perpendicular and write equations of lines parallel or perpendicular to a given line.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8fbcce04a2508b', 'les_0f2ca5aa438e5f', 1, 'State the slope conditions for parallel and perpendicular lines.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fcbbb01032cc57', 'les_0f2ca5aa438e5f', 2, 'Classify pairs of lines as parallel, perpendicular or neither.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_69eca7228bb7dd', 'les_0f2ca5aa438e5f', 3, 'Write the equation of a line through a point that is parallel or perpendicular to a given line.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8fbcce04a2508b', 'les_0f2ca5aa438e5f', 'learn', 1, 'definition', '{"term":"Parallel lines","body":"Two distinct non-vertical lines are parallel exactly when they have the same slope. All vertical lines are parallel to one another."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fcbbb01032cc57', 'les_0f2ca5aa438e5f', 'learn', 2, 'definition', '{"term":"Perpendicular lines","body":"Two non-vertical lines are perpendicular exactly when their slopes multiply to $-1$: $m_2 = -\\frac{1}{m_1}$ (negative reciprocals). A horizontal line and a vertical line are perpendicular."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_69eca7228bb7dd', 'les_0f2ca5aa438e5f', 'learn', 3, 'text', '{"body":"Why negative reciprocals? Rotate a slope triangle with run 3 and rise 2 by $90°$. The run becomes the rise and the rise becomes the run, with one direction flipped. The slope $\\frac{2}{3}$ turns into $-\\frac{3}{2}$, and $\\frac{2}{3} \\cdot \\left(-\\frac{3}{2}\\right) = -1$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9df8dc375c4edf', 'les_0f2ca5aa438e5f', 'experiment', 4, 'activity', '{"activity":"systems-graph","title":"Make the lines parallel, then perpendicular","params":{"m1":2,"b1":1,"m2":2,"b2":-3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5fa32ca6397e5e', 'les_0f2ca5aa438e5f', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"The lines start parallel, and the readout says they never meet. Set slope 2 to $-0.5$: now $2 \\cdot (-0.5) = -1$, so they are perpendicular. Check the right angle where they cross."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_79083c71081781', 'les_0f2ca5aa438e5f', 'learn', 6, 'worked_example', '{"title":"Classify $y = 4x - 1$ and $x + 4y = 8$","steps":[{"latex":"m_1 = 4","explanation":""},{"latex":"4y = -x + 8 \\Rightarrow m_2 = -\\tfrac{1}{4}","explanation":"Rewrite the second line in slope-intercept form."},{"latex":"4 \\cdot \\left(-\\tfrac{1}{4}\\right) = -1","explanation":"Perpendicular."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b1bd87544fcc8b', 'les_0f2ca5aa438e5f', 'learn', 7, 'worked_example', '{"title":"Write the line through $(6, -2)$ parallel to $y = \\tfrac{2}{3}x + 5$","steps":[{"latex":"m = \\tfrac{2}{3}","explanation":"Parallel: same slope."},{"latex":"y + 2 = \\tfrac{2}{3}(x - 6)","explanation":"Point-slope form."},{"latex":"y = \\tfrac{2}{3}x - 6","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_57e0ad34af5e81', 'les_0f2ca5aa438e5f', 'learn', 8, 'worked_example', '{"title":"Write the line through $(6, -2)$ perpendicular to $y = \\tfrac{2}{3}x + 5$","steps":[{"latex":"m = -\\tfrac{3}{2}","explanation":"Negative reciprocal of 2/3."},{"latex":"y + 2 = -\\tfrac{3}{2}(x - 6)","explanation":""},{"latex":"y = -\\tfrac{3}{2}x + 7","explanation":"$-\\frac{3}{2}(x - 6) = -\\frac{3}{2}x + 9$, then subtract 2."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f33aa7caf48035', 'les_0f2ca5aa438e5f', 'learn', 9, 'callout', '{"tone":"warning","title":"Reciprocal and negate","body":"The perpendicular slope to $-5$ is $\\frac{1}{5}$, not $5$ or $-\\frac{1}{5}$. Do both steps: flip it and change the sign."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_76f87dfcafe0a9', 'les_0f2ca5aa438e5f', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"City planners lay out streets on parallel and perpendicular grids, carpenters check square corners, and in coordinate geometry you can prove a shape is a rectangle by showing adjacent sides have slopes that multiply to $-1$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8fbcce04a2508b', 'les_0f2ca5aa438e5f', 1, 'practice', 'numeric', 1, 'What is the slope of a line parallel to $y = -3x + 7$?', '{"answer":-3}', '["Parallel lines have equal slopes."]', '$-3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fcbbb01032cc57', 'les_0f2ca5aa438e5f', 2, 'practice', 'short_text', 1, 'What is the slope of a line perpendicular to $y = 4x - 2$? Give a fraction.', '{"accept":["-1/4","-0.25"]}', '["Negative reciprocal."]', '$-\frac{1}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_69eca7228bb7dd', 'les_0f2ca5aa438e5f', 3, 'practice', 'multiple_choice', 2, 'Classify the lines $2x - y = 3$ and $y = 2x + 9$.', '{"choices":["Parallel","Perpendicular","Neither","The same line"],"answer":0}', '["The first is $y = 2x - 3$."]', 'Both have slope 2 and different intercepts, so they are parallel.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9df8dc375c4edf', 'les_0f2ca5aa438e5f', 4, 'practice', 'multiple_choice', 2, 'Classify the lines $y = \tfrac{3}{5}x$ and $y = \tfrac{5}{3}x - 1$.', '{"choices":["Parallel","Perpendicular","Neither","The same line"],"answer":2}', '["Multiply the slopes."]', '$\frac{3}{5} \cdot \frac{5}{3} = 1$, not $-1$, and the slopes are different: neither.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5fa32ca6397e5e', 'les_0f2ca5aa438e5f', 5, 'practice', 'short_text', 2, 'Write the line through $(2, 3)$ parallel to $y = -x + 4$, in slope-intercept form.', '{"accept":["y=-x+5","y=5-x"]}', '["$y - 3 = -1(x - 2)$."]', '$y = -x + 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_79083c71081781', 'les_0f2ca5aa438e5f', 6, 'practice', 'short_text', 3, 'Write the line through $(4, 1)$ perpendicular to $y = 2x - 5$, in slope-intercept form.', '{"accept":["y=-x/2+3","y=-(1/2)x+3","y=-0.5x+3","y=3-x/2"]}', '["Slope $-\\frac{1}{2}$.","$y - 1 = -\\frac{1}{2}(x - 4)$."]', '$y = -\frac{1}{2}x + 2 + 1 = -\frac{1}{2}x + 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b1bd87544fcc8b', 'les_0f2ca5aa438e5f', 7, 'review', 'multiple_choice', 3, 'Which line is perpendicular to $x = 7$?', '{"choices":["$x = -7$","$y = 7x$","$y = -2$","$y = x$"],"answer":2}', '["$x = 7$ is vertical."]', 'A vertical line is perpendicular to every horizontal line, such as $y = -2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9cbba3ce35bb4c', 'subj_math', 'parallel-perpendicular', 'Parallel and perpendicular lines', 'Parallel lines have equal slopes; perpendicular slopes are negative reciprocals.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0f2ca5aa438e5f', (SELECT id FROM concepts WHERE slug = 'parallel-perpendicular'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0f2ca5aa438e5f', (SELECT id FROM formulas WHERE slug = 'point-slope-form'), 1);

-- Lesson: percent-problems
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_234d81b42d8c27', 'percent-problems', 'Percent problems: tax, discount and percent change', 'Find a percent of a number, the whole from a part, and percent increase or decrease, then apply them to tax, tips, discounts and markups.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_24604c9794a133', 'les_234d81b42d8c27', 1, 'Solve the three basic percent problems with the equation part = percent × whole.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_473be9cddf8a95', 'les_234d81b42d8c27', 2, 'Compute sales tax, tips, discounts and markups, including with multipliers like 1.08 and 0.75.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4bcf7918c7d47a', 'les_234d81b42d8c27', 3, 'Find percent increase and decrease and explain why successive percent changes do not simply add.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_24604c9794a133', 'les_234d81b42d8c27', 'learn', 1, 'text', '{"body":"Almost every percent problem is one equation: $\\text{part} = \\text{percent} \\times \\text{whole}$, with the percent written as a decimal. Two of the three quantities are given, and you solve for the third."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_473be9cddf8a95', 'les_234d81b42d8c27', 'learn', 2, 'worked_example', '{"title":"Three kinds of question","steps":[{"latex":"\\text{What is } 15\\% \\text{ of } 80?\\quad 0.15 \\times 80 = 12","explanation":"Unknown part."},{"latex":"18 \\text{ is what percent of } 72?\\quad 18 = p \\times 72 \\Rightarrow p = 0.25 = 25\\%","explanation":"Unknown percent."},{"latex":"42 \\text{ is } 60\\% \\text{ of what?}\\quad 42 = 0.6w \\Rightarrow w = 70","explanation":"Unknown whole."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4bcf7918c7d47a', 'les_234d81b42d8c27', 'learn', 3, 'definition', '{"term":"Multiplier","body":"Increasing by $p\\%$ multiplies by $1 + \\frac{p}{100}$, and decreasing by $p\\%$ multiplies by $1 - \\frac{p}{100}$. An 8% sales tax multiplies the price by 1.08; a 25% discount multiplies it by 0.75."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_95adf0cec27d29', 'les_234d81b42d8c27', 'learn', 4, 'worked_example', '{"title":"A 64-dollar jacket is 30% off, and then 7.5% sales tax is added. What is the final price?","steps":[{"latex":"64 \\times 0.70 = 44.80","explanation":"30% off leaves 70% of the price."},{"latex":"44.80 \\times 1.075 = 48.16","explanation":"Tax adds 7.5%."}],"check":"Estimate: about 45 after the discount, plus a bit under 4 in tax, so about 48."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_050194cb0e1d32', 'les_234d81b42d8c27', 'learn', 5, 'formula', '{"latex":"\\text{percent change} = \\frac{\\text{new} - \\text{original}}{\\text{original}} \\times 100\\%","title":"Percent change","note":"A positive result is an increase; a negative result is a decrease. Always divide by the original amount."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d337baa61c1de8', 'les_234d81b42d8c27', 'learn', 6, 'worked_example', '{"title":"A town''s population went from 12,500 to 11,750. Find the percent change.","steps":[{"latex":"\\frac{11{,}750 - 12{,}500}{12{,}500} = \\frac{-750}{12{,}500}","explanation":"New minus original, over original."},{"latex":"= -0.06 = -6\\%","explanation":"A 6% decrease."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2077640abbbf95', 'les_234d81b42d8c27', 'learn', 7, 'callout', '{"tone":"warning","title":"Percent changes don''t add","body":"A price that rises 20% and then falls 20% does not return to where it started. $100 \\times 1.2 = 120$, then $120 \\times 0.8 = 96$: a 4% net loss. The second percent is taken of a different amount."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5980b02fd22444', 'les_234d81b42d8c27', 'learn', 8, 'worked_example', '{"title":"After a 15% raise, Lena earns 20.70 dollars an hour. What did she earn before?","steps":[{"latex":"1.15w = 20.70","explanation":"The new wage is 115% of the old one."},{"latex":"w = 20.70 \\div 1.15 = 18","explanation":""}],"check":"Check: $18 \\times 1.15 = 20.70$. ✓ Subtracting 15% of 20.70 instead would give 17.60, which is wrong because the 15% was of the old wage."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1003214e313d81', 'les_234d81b42d8c27', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Receipts (tax and tips), store sales, interest on savings, grade changes and news reports (\"prices rose 3.2% this year\") all use percent change. Simple interest is $I = Prt$: 500 dollars at 4% per year for 3 years earns $500 \\times 0.04 \\times 3 = 60$ dollars."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_24604c9794a133', 'les_234d81b42d8c27', 1, 'practice', 'numeric', 1, 'What is 35% of 240?', '{"answer":84}', '["Multiply 0.35 by 240."]', '$0.35 \times 240 = 84$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_473be9cddf8a95', 'les_234d81b42d8c27', 2, 'practice', 'numeric', 1, '27 is what percent of 90? Enter just the number.', '{"answer":30,"unit":"%"}', '["Divide 27 by 90."]', '$27 \div 90 = 0.3 = 30\%$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4bcf7918c7d47a', 'les_234d81b42d8c27', 3, 'practice', 'numeric', 2, '45 is 75% of what number?', '{"answer":60}', '["$45 = 0.75w$."]', '$w = 45 \div 0.75 = 60$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_95adf0cec27d29', 'les_234d81b42d8c27', 4, 'practice', 'numeric', 2, 'A meal costs 46 dollars. What is the total with an 18% tip?', '{"answer":54.28,"unit":"dollars","tolerance":0.005}', '["Multiply by 1.18."]', '$46 \times 1.18 = 54.28$ dollars.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_050194cb0e1d32', 'les_234d81b42d8c27', 5, 'practice', 'numeric', 2, 'A game''s price falls from 60 dollars to 45 dollars. What is the percent decrease? Enter a positive number.', '{"answer":25,"unit":"%"}', '["Change is 15 dollars; divide by the original."]', '$\frac{15}{60} = 0.25$, a 25% decrease.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d337baa61c1de8', 'les_234d81b42d8c27', 6, 'practice', 'numeric', 2, 'A store marks up a 32-dollar item by 40%. What is the selling price?', '{"answer":44.8,"unit":"dollars"}', '["Multiply by 1.40."]', '$32 \times 1.4 = 44.80$ dollars.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2077640abbbf95', 'les_234d81b42d8c27', 7, 'practice', 'multiple_choice', 3, 'A price is increased by 10% and then the new price is increased by 10% again. What is the total percent increase?', '{"choices":["20%","21%","19%","11%"],"answer":1}', '["Multiply by 1.1 twice: $1.1^2$."]', '$1.1 \times 1.1 = 1.21$, a 21% increase. The second 10% is taken of a larger amount.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5980b02fd22444', 'les_234d81b42d8c27', 8, 'review', 'numeric', 3, 'After a 20% discount, a bike costs 228 dollars. What was the original price?', '{"answer":285,"unit":"dollars"}', '["The sale price is 80% of the original."]', '$0.8p = 228$, so $p = 285$ dollars. Check: $285 \times 0.8 = 228$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1003214e313d81', 'les_234d81b42d8c27', 9, 'review', 'numeric', 3, 'Find the simple interest earned on 1,200 dollars at 3.5% per year for 4 years.', '{"answer":168,"unit":"dollars"}', '["$I = Prt$ with $r = 0.035$."]', '$1200 \times 0.035 \times 4 = 168$ dollars.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_4211ece0122b59', 'subj_math', 'percent-change', 'Percent change', 'Change relative to the original amount, expressed as a percent.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_234d81b42d8c27', (SELECT id FROM concepts WHERE slug = 'percent-change'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_234d81b42d8c27', (SELECT id FROM formulas WHERE slug = 'percent-change'), 1);

-- Lesson: plotting-points-four-quadrants
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d25429779e35a2', 'plotting-points-four-quadrants', 'Plotting points in all four quadrants', 'Read and plot ordered pairs anywhere on the coordinate plane, name quadrants, reflect points across the axes and find distances along gridlines.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a44b29e20ad6ed', 'les_d25429779e35a2', 1, 'Plot and read ordered pairs with positive and negative coordinates.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d7f9d92f7aa4fb', 'les_d25429779e35a2', 2, 'Identify the quadrant or axis that contains a point from the signs of its coordinates.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a1e5012aee5edd', 'les_d25429779e35a2', 3, 'Reflect points across the axes and find horizontal or vertical distances between points.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a44b29e20ad6ed', 'les_d25429779e35a2', 'learn', 1, 'definition', '{"term":"Coordinate plane","body":"Two number lines that cross at right angles at their zeros. The horizontal one is the $x$-axis, the vertical one is the $y$-axis, and they meet at the origin $(0, 0)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d7f9d92f7aa4fb', 'les_d25429779e35a2', 'learn', 2, 'definition', '{"term":"Ordered pair","body":"A pair $(x, y)$ that locates a point. Start at the origin, move $x$ units horizontally (right if positive, left if negative), then $y$ units vertically (up if positive, down if negative)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a1e5012aee5edd', 'les_d25429779e35a2', 'learn', 3, 'text', '{"body":"The axes split the plane into four quadrants, numbered I, II, III and IV counterclockwise from the upper right. Signs tell you the quadrant: $(+, +)$ is in I, $(-, +)$ in II, $(-, -)$ in III and $(+, -)$ in IV. A point with a 0 coordinate lies on an axis and is in no quadrant."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_95eb773db1bfa9', 'les_d25429779e35a2', 'experiment', 4, 'activity', '{"activity":"coordinate-plane","title":"Move a point around the plane","params":{"x":-4,"y":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6266b71011e4cd', 'les_d25429779e35a2', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Move P into each quadrant and note the signs. Then turn on \"Reflect over x-axis.\" Which coordinate changes sign? Predict before you try the y-axis and the origin."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6ead1526eba473', 'les_d25429779e35a2', 'learn', 6, 'worked_example', '{"title":"Plot $A(-3, 5)$ and $B(4, -2)$ and name their quadrants","steps":[{"latex":"A: 3 \\text{ left},\\ 5 \\text{ up}","explanation":"Negative x, positive y: Quadrant II."},{"latex":"B: 4 \\text{ right},\\ 2 \\text{ down}","explanation":"Positive x, negative y: Quadrant IV."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_238283eb9f8d0b', 'les_d25429779e35a2', 'learn', 7, 'worked_example', '{"title":"Find the distance between $(-2, 6)$ and $(-2, -3)$","steps":[{"latex":"x \\text{ is the same, so the points are on a vertical line}","explanation":""},{"latex":"|6 - (-3)| = 9","explanation":"Subtract the y-coordinates and take the absolute value."}],"check":"Counting grid squares: 6 units from y = 6 down to 0, then 3 more to −3, for 9 in all."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d9efb2118a41be', 'les_d25429779e35a2', 'learn', 8, 'callout', '{"tone":"warning","title":"Order matters","body":"$(2, 5)$ and $(5, 2)$ are different points. The x-coordinate always comes first: \"run before you jump.\""}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b0966fb99cd27c', 'les_d25429779e35a2', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Maps use coordinate grids, video games place every object by coordinates, and a city grid can be described with streets as axes. The reflection rules are used in graphics software to flip images."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a44b29e20ad6ed', 'les_d25429779e35a2', 1, 'practice', 'multiple_choice', 1, 'In which quadrant is $(-6, -1)$?', '{"choices":["I","II","III","IV"],"answer":2}', '["Both coordinates are negative."]', '$(-, -)$ is Quadrant III.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d7f9d92f7aa4fb', 'les_d25429779e35a2', 2, 'practice', 'multiple_choice', 1, 'Where is the point $(0, -4)$?', '{"choices":["Quadrant III","Quadrant IV","On the x-axis","On the y-axis"],"answer":3}', '["The x-coordinate is 0."]', 'With $x = 0$, the point is on the $y$-axis, 4 units below the origin.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a1e5012aee5edd', 'les_d25429779e35a2', 3, 'practice', 'short_text', 2, 'Reflect $(5, -3)$ across the $x$-axis. Enter the image as (x,y).', '{"accept":["(5,3)"]}', '["Reflecting across the x-axis changes the sign of y."]', '$(5, 3)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_95eb773db1bfa9', 'les_d25429779e35a2', 4, 'practice', 'short_text', 2, 'Reflect $(-2, 7)$ across the $y$-axis. Enter the image as (x,y).', '{"accept":["(2,7)"]}', '["Reflecting across the y-axis changes the sign of x."]', '$(2, 7)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6266b71011e4cd', 'les_d25429779e35a2', 5, 'practice', 'numeric', 2, 'What is the distance between $(-5, 1)$ and $(3, 1)$?', '{"answer":8}', '["Same y-coordinate: subtract the x-coordinates."]', '$|3 - (-5)| = 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6ead1526eba473', 'les_d25429779e35a2', 6, 'practice', 'multiple_choice', 2, 'A point has a positive x-coordinate and its y-coordinate is the opposite of its x-coordinate. Where is it?', '{"choices":["Quadrant I","Quadrant II","Quadrant III","Quadrant IV"],"answer":3}', '["Try x = 2."]', 'For example $(2, -2)$: positive $x$, negative $y$, so Quadrant IV.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_238283eb9f8d0b', 'les_d25429779e35a2', 7, 'review', 'numeric', 3, 'Three corners of a rectangle are $(-3, 4)$, $(5, 4)$ and $(5, -2)$. What is its area?', '{"answer":48,"unit":"square units"}', '["The fourth corner is (−3, −2).","Width = 5 − (−3); height = 4 − (−2)."]', 'Width 8, height 6, area $8 \times 6 = 48$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d9efb2118a41be', 'les_d25429779e35a2', 8, 'review', 'short_text', 3, 'The fourth corner of the rectangle in the previous problem is…? Enter as (x,y).', '{"accept":["(-3,-2)"]}', '["It shares an x-coordinate with (−3, 4) and a y-coordinate with (5, −2)."]', '$(-3, -2)$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_77ce7c91076f7b', 'subj_math', 'coordinate-plane', 'Coordinate plane', 'A plane with perpendicular number lines (axes) used to locate points by ordered pairs.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d25429779e35a2', (SELECT id FROM concepts WHERE slug = 'coordinate-plane'));

-- Lesson: point-slope-form
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_619ad09fad8869', 'point-slope-form', 'Point-slope form', 'Write the equation of a line from a point and a slope or from two points, and convert point-slope form to slope-intercept form.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8533bc19d80283', 'les_619ad09fad8869', 1, 'Explain where point-slope form comes from using the slope formula.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_785a0863905498', 'les_619ad09fad8869', 2, 'Write the equation of a line given a point and slope, or two points.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_37ec575ca33bc1', 'les_619ad09fad8869', 3, 'Convert between point-slope and slope-intercept forms and check that a point lies on a line.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8533bc19d80283', 'les_619ad09fad8869', 'learn', 1, 'text', '{"body":"Slope-intercept form needs the $y$-intercept. Often you know a different point on the line instead. Point-slope form uses whatever point you have."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_785a0863905498', 'les_619ad09fad8869', 'learn', 2, 'formula', '{"latex":"y - y_1 = m(x - x_1)","title":"Point-slope form","note":"The line with slope $m$ through the point $(x_1, y_1)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_37ec575ca33bc1', 'les_619ad09fad8869', 'learn', 3, 'text', '{"body":"It comes straight from the slope formula. If $(x, y)$ is any other point on the line through $(x_1, y_1)$ with slope $m$, then $\\frac{y - y_1}{x - x_1} = m$. Multiplying both sides by $x - x_1$ gives $y - y_1 = m(x - x_1)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_24fc58426b0d10', 'les_619ad09fad8869', 'learn', 4, 'worked_example', '{"title":"Write the line with slope $-2$ through $(3, -1)$","steps":[{"latex":"y - (-1) = -2(x - 3)","explanation":"Substitute m = −2, x₁ = 3, y₁ = −1."},{"latex":"y + 1 = -2(x - 3)","explanation":"Point-slope form."},{"latex":"y = -2x + 6 - 1 = -2x + 5","explanation":"Slope-intercept form, if needed."}],"check":"Check: $-2(3) + 5 = -1$. ✓ The point is on the line."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96d912e94da83f', 'les_619ad09fad8869', 'learn', 5, 'worked_example', '{"title":"Write the line through $(-4, 7)$ and $(2, -2)$","steps":[{"latex":"m = \\frac{-2 - 7}{2 - (-4)} = \\frac{-9}{6} = -\\tfrac{3}{2}","explanation":"Find the slope first."},{"latex":"y - 7 = -\\tfrac{3}{2}(x + 4)","explanation":"Use either point; here (−4, 7)."},{"latex":"y = -\\tfrac{3}{2}x - 6 + 7 = -\\tfrac{3}{2}x + 1","explanation":""}],"check":"Check with the other point: $-\\frac{3}{2}(2) + 1 = -2$. ✓ Using $(2, -2)$ instead gives the same line."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7d5c370c7cdead', 'les_619ad09fad8869', 'experiment', 6, 'activity', '{"activity":"linear-graph","title":"Check your line","params":{"m":-1.5,"b":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_df2c6e3b7a93d0', 'les_619ad09fad8869', 'experiment', 7, 'callout', '{"tone":"tip","title":"Try this","body":"The line $y = -\\frac{3}{2}x + 1$ is set up. Confirm visually that it passes through $(-4, 7)$ and $(2, -2)$. Then change the slope and notice it stops passing through both."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f28d4d496aa9c0', 'les_619ad09fad8869', 'learn', 8, 'callout', '{"tone":"warning","title":"Signs inside the parentheses","body":"The form has subtraction: $x - x_1$. For the point $(-4, 7)$, $x - (-4)$ becomes $x + 4$. A point $(5, -3)$ gives $y + 3 = m(x - 5)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bf8a9f68571621', 'les_619ad09fad8869', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"A plumber charges 85 dollars for a 1-hour job and 55 dollars per extra hour. You know one point, (1, 85), and the slope, 55: $C - 85 = 55(h - 1)$, or $C = 55h + 30$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8533bc19d80283', 'les_619ad09fad8869', 1, 'practice', 'short_text', 1, 'Write the point-slope form of the line with slope 4 through $(1, 6)$. Use the format y-6=4(x-1).', '{"accept":["y-6=4(x-1)"]}', '["Substitute into y − y₁ = m(x − x₁)."]', '$y - 6 = 4(x - 1)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_785a0863905498', 'les_619ad09fad8869', 2, 'practice', 'short_text', 2, 'Write the line with slope $-3$ through $(-2, 5)$ in slope-intercept form.', '{"accept":["y=-3x-1","y=-1-3x"]}', '["$y - 5 = -3(x + 2)$."]', '$y = -3x - 6 + 5 = -3x - 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_37ec575ca33bc1', 'les_619ad09fad8869', 3, 'practice', 'short_text', 2, 'Write the line through $(1, 2)$ and $(4, 11)$ in slope-intercept form.', '{"accept":["y=3x-1","y=-1+3x"]}', '["Slope = (11 − 2)/(4 − 1).","Then $y - 2 = 3(x - 1)$."]', '$m = 3$ and $y = 3x - 3 + 2 = 3x - 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_24fc58426b0d10', 'les_619ad09fad8869', 4, 'practice', 'multiple_choice', 2, 'Which point lies on the line $y + 2 = \tfrac{1}{2}(x - 6)$?', '{"choices":["$(6, 2)$","$(-6, 2)$","$(6, -2)$","$(2, 6)$"],"answer":2}', '["Read the point from the form: be careful with signs."]', '$y + 2 = y - (-2)$, so the point is $(6, -2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_96d912e94da83f', 'les_619ad09fad8869', 5, 'practice', 'short_text', 3, 'Write the line through $(-3, 4)$ and $(3, 0)$ in slope-intercept form.', '{"accept":["y=-2x/3+2","y=-(2/3)x+2","y=2-2x/3","y=(-2/3)x+2"]}', '["$m = \\frac{0 - 4}{3 - (-3)} = -\\frac{2}{3}$."]', '$y - 0 = -\frac{2}{3}(x - 3)$, so $y = -\frac{2}{3}x + 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7d5c370c7cdead', 'les_619ad09fad8869', 6, 'review', 'short_text', 3, 'A gym''s cost is 165 dollars for 3 months and 285 dollars for 7 months, and it is linear. Write the cost C for m months as C=…', '{"accept":["C=30m+75","C=75+30m","c=30m+75"]}', '["Slope = (285 − 165)/(7 − 3).","Then use point-slope form."]', '$m = \frac{120}{4} = 30$. $C - 165 = 30(m - 3)$ gives $C = 30m + 75$: a 75-dollar sign-up fee plus 30 dollars a month.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_619ad09fad8869', 'subj_math', 'point-slope-form', 'Point-slope form', 'y − y₁ = m(x − x₁): the line with slope m through (x₁, y₁).');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_619ad09fad8869', (SELECT id FROM concepts WHERE slug = 'point-slope-form'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_619ad09fad8869', (SELECT id FROM formulas WHERE slug = 'point-slope-form'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_619ad09fad8869', (SELECT id FROM formulas WHERE slug = 'slope'), 2);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_619ad09fad8869', (SELECT id FROM formulas WHERE slug = 'slope-intercept-form'), 3);

-- Lesson: properties-of-exponents
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9b92d8621d6779', 'properties-of-exponents', 'Properties of exponents', 'Derive and apply the product, quotient and power rules for exponents to simplify numerical and algebraic expressions, including scientific notation.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e6d5f927a686aa', 'les_9b92d8621d6779', 1, 'Explain the product, quotient, power-of-a-power, power-of-a-product and power-of-a-quotient rules from the meaning of exponents.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1b02c6c4d42ddb', 'les_9b92d8621d6779', 2, 'Simplify expressions with variables and integer coefficients using these rules.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7c75d1969ba884', 'les_9b92d8621d6779', 3, 'Multiply and divide numbers in scientific notation.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e6d5f927a686aa', 'les_9b92d8621d6779', 'learn', 1, 'text', '{"body":"Every exponent rule follows from what an exponent means: $a^n$ is $n$ factors of $a$. You never have to memorize them blindly. Write out the factors once and the rule is visible."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1b02c6c4d42ddb', 'les_9b92d8621d6779', 'learn', 2, 'definition', '{"term":"Product rule","body":"$a^m \\cdot a^n = a^{m+n}$. Example: $x^3 \\cdot x^4 = (xxx)(xxxx) = x^7$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c75d1969ba884', 'les_9b92d8621d6779', 'learn', 3, 'definition', '{"term":"Quotient rule","body":"$\\dfrac{a^m}{a^n} = a^{m-n}$ for $a \\ne 0$. Example: $\\dfrac{x^6}{x^2} = \\dfrac{xxxxxx}{xx} = x^4$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4f10d803df33bb', 'les_9b92d8621d6779', 'learn', 4, 'definition', '{"term":"Power rules","body":"Power of a power: $(a^m)^n = a^{mn}$. Power of a product: $(ab)^n = a^n b^n$. Power of a quotient: $\\left(\\frac{a}{b}\\right)^n = \\frac{a^n}{b^n}$, $b \\ne 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_86d171010def68', 'les_9b92d8621d6779', 'learn', 5, 'worked_example', '{"title":"Simplify $(2x^3y)^4$","steps":[{"latex":"2^4 (x^3)^4 y^4","explanation":"Raise each factor to the 4th power."},{"latex":"16x^{12}y^4","explanation":"Multiply exponents: 3 · 4 = 12."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_be66ff9ea23d4f', 'les_9b92d8621d6779', 'learn', 6, 'worked_example', '{"title":"Simplify $\\dfrac{12a^5b^3}{4a^2b}$","steps":[{"latex":"\\tfrac{12}{4} \\cdot a^{5-2} \\cdot b^{3-1}","explanation":"Divide coefficients; subtract exponents for each base."},{"latex":"3a^3b^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_418274229dd0b5', 'les_9b92d8621d6779', 'learn', 7, 'worked_example', '{"title":"Simplify $(-3m^2)^3 \\cdot m^4$","steps":[{"latex":"(-3)^3 (m^2)^3 \\cdot m^4 = -27m^6 \\cdot m^4","explanation":"Cube −3 and m² separately."},{"latex":"-27m^{10}","explanation":"Product rule: 6 + 4."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_26b0842e4297f1', 'les_9b92d8621d6779', 'learn', 8, 'callout', '{"tone":"warning","title":"Common mix-ups","body":"$x^3 \\cdot x^4 = x^7$, not $x^{12}$ (multiply exponents only for a power of a power). $(x + y)^2 \\ne x^2 + y^2$: the power rule works for products, not sums. And $3x^2$ means $3 \\cdot x^2$, so $(3x)^2 = 9x^2$ but $3x^2$ is not."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cb208ab0fcd780', 'les_9b92d8621d6779', 'learn', 9, 'worked_example', '{"title":"Compute $(4 \\times 10^5)(6 \\times 10^{-2})$ in scientific notation","steps":[{"latex":"(4 \\cdot 6) \\times 10^{5 + (-2)} = 24 \\times 10^3","explanation":"Multiply the numbers and add the exponents."},{"latex":"2.4 \\times 10^4","explanation":"Adjust so the leading number is from 1 to 10."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_803175b903ab18', 'les_9b92d8621d6779', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Scientists use these rules constantly: light travels about $3 \\times 10^8$ m/s, so in $5 \\times 10^2$ seconds it goes $15 \\times 10^{10} = 1.5 \\times 10^{11}$ m, about the distance from the Sun to Earth."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e6d5f927a686aa', 'les_9b92d8621d6779', 1, 'practice', 'short_text', 1, 'Simplify $x^5 \cdot x^3$.', '{"accept":["x^8"]}', '["Add the exponents."]', '$x^8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1b02c6c4d42ddb', 'les_9b92d8621d6779', 2, 'practice', 'short_text', 1, 'Simplify $\dfrac{y^9}{y^4}$.', '{"accept":["y^5"]}', '["Subtract the exponents."]', '$y^5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7c75d1969ba884', 'les_9b92d8621d6779', 3, 'practice', 'short_text', 2, 'Simplify $(a^4)^3$.', '{"accept":["a^12"]}', '["Multiply the exponents."]', '$a^{12}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4f10d803df33bb', 'les_9b92d8621d6779', 4, 'practice', 'short_text', 2, 'Simplify $(3x^2y^5)^2$.', '{"accept":["9x^4y^10"]}', '["Square each factor."]', '$9x^4y^{10}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_86d171010def68', 'les_9b92d8621d6779', 5, 'practice', 'short_text', 2, 'Simplify $\dfrac{18m^7n^4}{6m^3n}$.', '{"accept":["3m^4n^3"]}', '["Divide 18 by 6; subtract the exponents."]', '$3m^4n^3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_be66ff9ea23d4f', 'les_9b92d8621d6779', 6, 'practice', 'multiple_choice', 2, 'Which is equal to $(2x)^3$?', '{"choices":["$2x^3$","$6x^3$","$8x^3$","$8x$"],"answer":2}', '["The cube applies to both 2 and x."]', '$2^3 x^3 = 8x^3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_418274229dd0b5', 'les_9b92d8621d6779', 7, 'practice', 'numeric', 3, 'Compute $(3 \times 10^4)(5 \times 10^3)$. Enter the answer as a plain number or in e-notation.', '{"answer":150000000,"relative":true,"tolerance":1e-9}', '["3 · 5 = 15, and 10⁴ · 10³ = 10⁷."]', '$15 \times 10^7 = 1.5 \times 10^8 = 150{,}000{,}000$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_26b0842e4297f1', 'les_9b92d8621d6779', 8, 'review', 'short_text', 3, 'Simplify $\left(\dfrac{2a^3}{b}\right)^4 \cdot b^6$.', '{"accept":["16a^12b^2"]}', '["$\\frac{16a^{12}}{b^4} \\cdot b^6$."]', '$16a^{12}b^{6-4} = 16a^{12}b^2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_5268d3a788488b', 'subj_math', 'exponents', 'Exponents', 'Notation for repeated multiplication of a base.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9b92d8621d6779', (SELECT id FROM concepts WHERE slug = 'exponents'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1f00e6e426f079', 'subj_math', 'exponent-rules', 'Exponent rules', 'Product, quotient and power rules for simplifying powers.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9b92d8621d6779', (SELECT id FROM concepts WHERE slug = 'exponent-rules'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9b92d8621d6779', (SELECT id FROM formulas WHERE slug = 'exponent-rules'), 1);

-- Lesson: properties-real-numbers
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9c9b6676ee4ac0', 'properties-real-numbers', 'Properties of real numbers', 'Name and use the commutative, associative, distributive, identity and inverse properties to justify each step of a simplification.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9dbe71e3ef93f9', 'les_9c9b6676ee4ac0', 1, 'State the commutative, associative, distributive, identity and inverse properties.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fd357fa13da9ce', 'les_9c9b6676ee4ac0', 2, 'Identify which property justifies a given step.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2bd70da4374a9a', 'les_9c9b6676ee4ac0', 3, 'Use properties to simplify expressions and compute mentally, and recognize which operations they do not apply to.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9dbe71e3ef93f9', 'les_9c9b6676ee4ac0', 'learn', 1, 'text', '{"body":"Algebra moves are not tricks. Each step in simplifying an expression is allowed by one of a few basic properties that hold for every real number. Naming them lets you explain why your work is correct, which is the start of proof."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fd357fa13da9ce', 'les_9c9b6676ee4ac0', 'learn', 2, 'definition', '{"term":"Commutative properties","body":"Order doesn''t matter: $a + b = b + a$ and $ab = ba$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2bd70da4374a9a', 'les_9c9b6676ee4ac0', 'learn', 3, 'definition', '{"term":"Associative properties","body":"Grouping doesn''t matter: $(a + b) + c = a + (b + c)$ and $(ab)c = a(bc)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f696df0b11d213', 'les_9c9b6676ee4ac0', 'learn', 4, 'definition', '{"term":"Distributive property","body":"$a(b + c) = ab + ac$. It connects multiplication with addition."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_87cbd02cd27af5', 'les_9c9b6676ee4ac0', 'learn', 5, 'definition', '{"term":"Identity and inverse properties","body":"Additive identity: $a + 0 = a$. Multiplicative identity: $a \\cdot 1 = a$. Additive inverse: $a + (-a) = 0$. Multiplicative inverse: $a \\cdot \\frac{1}{a} = 1$ for $a \\ne 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eaed86bd4a3caa', 'les_9c9b6676ee4ac0', 'learn', 6, 'callout', '{"tone":"warning","title":"Subtraction and division","body":"Subtraction and division are not commutative or associative: $8 - 3 \\ne 3 - 8$ and $(16 \\div 4) \\div 2 = 2$ while $16 \\div (4 \\div 2) = 8$. Rewrite subtraction as adding the opposite before rearranging terms."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_111dba3c4e0a6b', 'les_9c9b6676ee4ac0', 'learn', 7, 'worked_example', '{"title":"Justify each step: $4 + 3x + 6 = 3x + 10$","steps":[{"latex":"3x + 4 + 6","explanation":"Commutative property of addition."},{"latex":"3x + (4 + 6)","explanation":"Associative property of addition."},{"latex":"3x + 10","explanation":"Simplify (arithmetic)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_699f8c4a0870be', 'les_9c9b6676ee4ac0', 'learn', 8, 'worked_example', '{"title":"Compute $25 \\cdot 37 \\cdot 4$ mentally","steps":[{"latex":"25 \\cdot 4 \\cdot 37","explanation":"Commutative property of multiplication."},{"latex":"(25 \\cdot 4) \\cdot 37 = 100 \\cdot 37","explanation":"Associative property."},{"latex":"3700","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_30a390d9069efd', 'les_9c9b6676ee4ac0', 'learn', 9, 'worked_example', '{"title":"Justify: $5(x + 2) - 5x = 10$","steps":[{"latex":"5x + 10 - 5x","explanation":"Distributive property."},{"latex":"5x + (-5x) + 10","explanation":"Commutative property (after writing − as + opposite)."},{"latex":"0 + 10 = 10","explanation":"Additive inverse, then additive identity."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ab27255dfa58a4', 'les_9c9b6676ee4ac0', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Cashiers group coins to make round numbers, and spreadsheets and computer algebra systems rearrange expressions using exactly these rules. Computer floating-point arithmetic is famous for not being perfectly associative, which is why programmers sometimes get 0.30000000000000004."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9dbe71e3ef93f9', 'les_9c9b6676ee4ac0', 1, 'practice', 'multiple_choice', 1, 'Which property is shown by $7 \cdot (2 \cdot x) = (7 \cdot 2) \cdot x$?', '{"choices":["Commutative","Associative","Distributive","Identity"],"answer":1}', '["What changed: the order or the grouping?"]', 'The grouping changed, so it is the associative property of multiplication.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fd357fa13da9ce', 'les_9c9b6676ee4ac0', 2, 'practice', 'multiple_choice', 1, 'Which property is shown by $-9 + 9 = 0$?', '{"choices":["Additive identity","Additive inverse","Multiplicative inverse","Commutative"],"answer":1}', '["A number plus its opposite."]', 'Adding a number and its opposite gives 0: the additive inverse property.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2bd70da4374a9a', 'les_9c9b6676ee4ac0', 3, 'practice', 'multiple_choice', 2, 'Which property is shown by $\frac{3}{5} \cdot \frac{5}{3} = 1$?', '{"choices":["Multiplicative identity","Multiplicative inverse","Commutative","Associative"],"answer":1}', '["What do you get when you multiply a number by its reciprocal?"]', 'A number times its reciprocal is 1: the multiplicative inverse property.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f696df0b11d213', 'les_9c9b6676ee4ac0', 4, 'practice', 'multiple_choice', 2, 'Which equation is false for some real numbers?', '{"choices":["$a + b = b + a$","$a - b = b - a$","$a(b + c) = ab + ac$","$a \\cdot 1 = a$"],"answer":1}', '["Try a = 5, b = 2."]', '$5 - 2 = 3$ but $2 - 5 = -3$. Subtraction is not commutative.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_87cbd02cd27af5', 'les_9c9b6676ee4ac0', 5, 'practice', 'multiple_choice', 2, 'In simplifying $2(3x) = 6x$, which property is used?', '{"choices":["Distributive","Associative property of multiplication","Commutative property of addition","Multiplicative identity"],"answer":1}', '["$2(3x) = 2 \\cdot (3 \\cdot x)$."]', '$2 \cdot (3 \cdot x) = (2 \cdot 3) \cdot x = 6x$: regrouping factors is the associative property. No addition is involved, so it isn''t distributive.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eaed86bd4a3caa', 'les_9c9b6676ee4ac0', 6, 'review', 'short_text', 3, 'Use properties to simplify $8 + 6y - 8 + y$.', '{"accept":["7y"]}', '["Rearrange so the 8 and −8 are together."]', '$(8 - 8) + (6y + y) = 0 + 7y = 7y$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_111dba3c4e0a6b', 'les_9c9b6676ee4ac0', 7, 'review', 'multiple_choice', 3, 'A student says $(24 \div 6) \div 2 = 24 \div (6 \div 2)$ by the associative property. Is she right?', '{"choices":["Yes","No; the left side is 2 and the right side is 8","No; the left side is 8 and the right side is 2","Yes, because both equal 4"],"answer":1}', '["Evaluate both sides."]', '$(24 \div 6) \div 2 = 4 \div 2 = 2$ and $24 \div (6 \div 2) = 24 \div 3 = 8$. Division is not associative.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_70b33ef1280762', 'subj_math', 'field-properties', 'Properties of real numbers', 'Commutative, associative, distributive, identity and inverse properties.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9c9b6676ee4ac0', (SELECT id FROM concepts WHERE slug = 'field-properties'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_862d74cf83941b', 'subj_math', 'distributive-property', 'Distributive property', 'a(b + c) = ab + ac: multiplication distributes over addition and subtraction.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9c9b6676ee4ac0', (SELECT id FROM concepts WHERE slug = 'distributive-property'));

-- Lesson: rational-exponents-radicals
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3030b9b8801462', 'rational-exponents-radicals', 'Rational exponents and radicals', 'Interpret fractional exponents as roots, convert between radical and exponent form, and evaluate and simplify expressions with rational exponents.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3a6122cfea8d05', 'les_3030b9b8801462', 1, 'Explain why a^(1/n) is the nth root of a using the power-of-a-power rule.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5baf328531d1e3', 'les_3030b9b8801462', 2, 'Convert between radical form and rational exponent form.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_da232844d39ffc', 'les_3030b9b8801462', 3, 'Evaluate and simplify expressions with rational exponents, including negative ones.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3a6122cfea8d05', 'les_3030b9b8801462', 'learn', 1, 'text', '{"body":"If the exponent rules are to keep working for fractions, what must $9^{1/2}$ be? Squaring it should give $\\left(9^{1/2}\\right)^2 = 9^{1/2 \\cdot 2} = 9^1 = 9$. The positive number whose square is 9 is 3, so $9^{1/2} = \\sqrt{9} = 3$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5baf328531d1e3', 'les_3030b9b8801462', 'learn', 2, 'definition', '{"term":"Rational exponents","body":"For $a > 0$ and positive integers $m, n$: $a^{1/n} = \\sqrt[n]{a}$ and $a^{m/n} = \\left(\\sqrt[n]{a}\\right)^m = \\sqrt[n]{a^m}$. The denominator is the root; the numerator is the power."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_da232844d39ffc', 'les_3030b9b8801462', 'learn', 3, 'definition', '{"term":"nth root","body":"$\\sqrt[n]{a}$ is the number whose $n$th power is $a$: $\\sqrt[3]{64} = 4$ because $4^3 = 64$. Odd roots of negative numbers are real ($\\sqrt[3]{-8} = -2$); even roots of negative numbers are not."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d4d6a5f364451f', 'les_3030b9b8801462', 'learn', 4, 'worked_example', '{"title":"Evaluate $27^{2/3}$","steps":[{"latex":"\\left(\\sqrt[3]{27}\\right)^2","explanation":"Root first: the numbers stay small."},{"latex":"3^2 = 9","explanation":""}],"check":"Power first gives the same answer: $\\sqrt[3]{27^2} = \\sqrt[3]{729} = 9$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9c1e7e9528cbb0', 'les_3030b9b8801462', 'learn', 5, 'worked_example', '{"title":"Evaluate $16^{-3/4}$","steps":[{"latex":"\\frac{1}{16^{3/4}}","explanation":"Negative exponent: reciprocal."},{"latex":"\\frac{1}{\\left(\\sqrt[4]{16}\\right)^3} = \\frac{1}{2^3} = \\frac{1}{8}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_49b680d3dbaa99', 'les_3030b9b8801462', 'learn', 6, 'worked_example', '{"title":"Simplify $x^{1/2} \\cdot x^{1/3}$ and $\\left(y^{6}\\right)^{2/3}$ for positive $x, y$","steps":[{"latex":"x^{1/2 + 1/3} = x^{5/6}","explanation":"Product rule: add the fractions."},{"latex":"y^{6 \\cdot 2/3} = y^4","explanation":"Power of a power: multiply."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_50f69d13a5f020', 'les_3030b9b8801462', 'learn', 7, 'callout', '{"tone":"warning","title":"The exponent fraction is not a multiplier","body":"$8^{1/3}$ is $2$, not $\\frac{8}{3}$. And $25^{-1/2} = \\frac{1}{5}$, not $-5$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_26a157e1d72766', 'les_3030b9b8801462', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Kepler''s third law relates a planet''s orbital period to its distance by $T \\propto a^{3/2}$, and animal metabolic rate scales roughly as mass to the $\\frac{3}{4}$ power. Musical pitches step by a factor of $2^{1/12}$ per semitone."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3a6122cfea8d05', 'les_3030b9b8801462', 1, 'practice', 'numeric', 1, 'Evaluate $49^{1/2}$.', '{"answer":7}', '["Square root of 49."]', '$\sqrt{49} = 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5baf328531d1e3', 'les_3030b9b8801462', 2, 'practice', 'numeric', 1, 'Evaluate $125^{1/3}$.', '{"answer":5}', '["Cube root."]', '$5^3 = 125$, so 5.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_da232844d39ffc', 'les_3030b9b8801462', 3, 'practice', 'numeric', 2, 'Evaluate $8^{2/3}$.', '{"answer":4}', '["Cube root first, then square."]', '$(\sqrt[3]{8})^2 = 2^2 = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d4d6a5f364451f', 'les_3030b9b8801462', 4, 'practice', 'numeric', 2, 'Evaluate $81^{3/4}$.', '{"answer":27}', '["Fourth root of 81 is 3."]', '$3^3 = 27$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9c1e7e9528cbb0', 'les_3030b9b8801462', 5, 'practice', 'numeric', 2, 'Evaluate $32^{-2/5}$. Enter a fraction or decimal.', '{"answer":0.25}', '["Fifth root of 32 is 2.","Then square and take the reciprocal."]', '$\frac{1}{(\sqrt[5]{32})^2} = \frac{1}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_49b680d3dbaa99', 'les_3030b9b8801462', 6, 'practice', 'multiple_choice', 2, 'Which is $\sqrt[4]{x^3}$ in exponent form?', '{"choices":["$x^{4/3}$","$x^{3/4}$","$x^{12}$","$x^{-3/4}$"],"answer":1}', '["Root index goes in the denominator."]', '$x^{3/4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_50f69d13a5f020', 'les_3030b9b8801462', 7, 'review', 'short_text', 3, 'Simplify $a^{2/3} \cdot a^{1/6}$. Use the format a^(m/n).', '{"accept":["a^(5/6)","a^5/6"]}', '["$\\frac{2}{3} = \\frac{4}{6}$."]', '$a^{4/6 + 1/6} = a^{5/6}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_26a157e1d72766', 'les_3030b9b8801462', 8, 'review', 'numeric', 3, 'Evaluate $(-27)^{1/3} + 16^{1/4}$.', '{"answer":-1}', '["Odd roots of negatives are real.","$\\sqrt[3]{-27} = -3$."]', '$-3 + 2 = -1$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_665ff91e2ff4eb', 'subj_math', 'rational-exponents', 'Rational exponents', 'Exponents that are fractions; a^(m/n) is the nth root of a, raised to the m.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3030b9b8801462', (SELECT id FROM concepts WHERE slug = 'rational-exponents'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_283755837f95ab', 'subj_math', 'square-roots', 'Square roots', 'A number that, multiplied by itself, gives a given number.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3030b9b8801462', (SELECT id FROM concepts WHERE slug = 'square-roots'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_3030b9b8801462', (SELECT id FROM formulas WHERE slug = 'exponent-rules'), 1);

-- Lesson: rational-numbers-decimals
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7bc50c743d2362', 'rational-numbers-decimals', 'Rational numbers and their decimal forms', 'Recognize rational numbers, convert fractions to terminating or repeating decimals, and convert decimals back to fractions.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0d2d87aeda87f2', 'les_7bc50c743d2362', 1, 'Define a rational number and give examples, including negatives and integers.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_57c66178163dda', 'les_7bc50c743d2362', 2, 'Convert a fraction to a decimal by division and identify terminating and repeating decimals.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3284845df6faa1', 'les_7bc50c743d2362', 3, 'Convert terminating and simple repeating decimals to fractions in simplest form.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d2d87aeda87f2', 'les_7bc50c743d2362', 'learn', 1, 'definition', '{"term":"Rational number","body":"Any number that can be written as $\\frac{a}{b}$ where $a$ and $b$ are integers and $b \\ne 0$. Examples: $\\frac{3}{4}$, $-\\frac{5}{2}$, $7 = \\frac{7}{1}$, $0.25 = \\frac{1}{4}$ and $0.\\overline{3} = \\frac{1}{3}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_57c66178163dda', 'les_7bc50c743d2362', 'learn', 2, 'text', '{"body":"Every integer is rational, because it can be written over 1. Negative fractions can put the sign in three places: $-\\frac{2}{3} = \\frac{-2}{3} = \\frac{2}{-3}$. All three name the same point on the number line, two-thirds of the way from 0 to $-1$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3284845df6faa1', 'les_7bc50c743d2362', 'learn', 3, 'text', '{"body":"To turn a fraction into a decimal, divide the numerator by the denominator. Either the division ends (a terminating decimal) or a block of digits repeats forever (a repeating decimal). A bar marks the repeating block: $\\frac{2}{11} = 0.181818\\ldots = 0.\\overline{18}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_29c59911d04445', 'les_7bc50c743d2362', 'learn', 4, 'callout', '{"tone":"tip","title":"Which fractions terminate?","body":"In simplest form, a fraction terminates exactly when its denominator has no prime factors other than 2 and 5. $\\frac{7}{40}$ terminates because $40 = 2^3 \\cdot 5$. $\\frac{5}{12}$ repeats because 12 has a factor of 3."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_226239f6914d54', 'les_7bc50c743d2362', 'learn', 5, 'worked_example', '{"title":"Write $\\frac{5}{8}$ and $\\frac{5}{6}$ as decimals","steps":[{"latex":"5 \\div 8 = 0.625","explanation":"The division ends after three places: terminating."},{"latex":"5 \\div 6 = 0.8333\\ldots","explanation":"After the 8, the remainder 2 repeats, so 3 repeats."},{"latex":"\\tfrac{5}{6} = 0.8\\overline{3}","explanation":"Only the 3 repeats, so the bar goes over the 3 alone."}],"check":"Check: $8 = 2^3$ (terminates) and $6 = 2 \\cdot 3$ (repeats), matching the tip above."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4deb1961ae4b5b', 'les_7bc50c743d2362', 'learn', 6, 'worked_example', '{"title":"Write $0.45$ and $-2.6$ as fractions in simplest form","steps":[{"latex":"0.45 = \\tfrac{45}{100}","explanation":"Two decimal places means hundredths."},{"latex":"\\tfrac{45}{100} = \\tfrac{9}{20}","explanation":"Divide the top and bottom by their GCF, 5."},{"latex":"-2.6 = -2\\tfrac{6}{10} = -\\tfrac{26}{10} = -\\tfrac{13}{5}","explanation":"One decimal place means tenths. Then simplify by 2."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2b41401ee71ec0', 'les_7bc50c743d2362', 'learn', 7, 'worked_example', '{"title":"Write $0.\\overline{7}$ as a fraction","steps":[{"latex":"x = 0.777\\ldots","explanation":"Call the number x."},{"latex":"10x = 7.777\\ldots","explanation":"One digit repeats, so multiply by 10 to shift one place."},{"latex":"10x - x = 7","explanation":"Subtracting removes the endless tail."},{"latex":"9x = 7 \\Rightarrow x = \\tfrac{7}{9}","explanation":"Divide by 9."}],"check":"Check: $7 \\div 9 = 0.777\\ldots$"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4d80df0051f570', 'les_7bc50c743d2362', 'learn', 8, 'callout', '{"tone":"note","title":"Not every decimal is rational","body":"Decimals that never end and never repeat, such as $\\pi = 3.14159\\ldots$ and $\\sqrt{2} = 1.41421\\ldots$, are irrational. You will meet them when you study square roots and the real number system."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96ccdd25f63758', 'les_7bc50c743d2362', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Batting averages, sale prices and recipe scaling all switch between fractions and decimals. A player with 7 hits in 20 at-bats has an average of $7 \\div 20 = 0.350$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d2d87aeda87f2', 'les_7bc50c743d2362', 1, 'practice', 'numeric', 1, 'Write $\frac{3}{8}$ as a decimal.', '{"answer":0.375}', '["Divide 3 by 8."]', '$3 \div 8 = 0.375$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_57c66178163dda', 'les_7bc50c743d2362', 2, 'practice', 'multiple_choice', 1, 'Which number is not rational?', '{"choices":["$-\\frac{4}{9}$","$0.\\overline{12}$","$\\sqrt{2}$","$-6$"],"answer":2}', '["Rational numbers can be written as a fraction of integers."]', '$\sqrt{2}$ is a non-repeating, non-terminating decimal, so it is irrational. $-6 = \frac{-6}{1}$, and $0.\overline{12} = \frac{12}{99} = \frac{4}{33}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3284845df6faa1', 'les_7bc50c743d2362', 3, 'practice', 'multiple_choice', 2, 'Which fraction has a repeating decimal form?', '{"choices":["$\\frac{7}{20}$","$\\frac{3}{16}$","$\\frac{4}{15}$","$\\frac{9}{25}$"],"answer":2}', '["Factor each denominator. Does it have a prime factor other than 2 or 5?"]', '$15 = 3 \cdot 5$ has a factor of 3, so $\frac{4}{15} = 0.2\overline{6}$ repeats. The others have denominators $2^2 \cdot 5$, $2^4$ and $5^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_29c59911d04445', 'les_7bc50c743d2362', 4, 'practice', 'short_text', 2, 'Write $0.64$ as a fraction in simplest form. Use the format a/b.', '{"accept":["16/25"]}', '["0.64 is 64 hundredths.","The GCF of 64 and 100 is 4."]', '$\frac{64}{100} = \frac{16}{25}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_226239f6914d54', 'les_7bc50c743d2362', 5, 'practice', 'numeric', 2, 'Write $-\frac{7}{4}$ as a decimal.', '{"answer":-1.75}', '["$7 \\div 4 = 1.75$."]', '$-\frac{7}{4} = -1.75$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4deb1961ae4b5b', 'les_7bc50c743d2362', 6, 'practice', 'short_text', 3, 'Write $0.\overline{36}$ as a fraction in simplest form. Use the format a/b.', '{"accept":["4/11"]}', '["Two digits repeat, so multiply by 100.","$100x - x = 36$."]', '$99x = 36$, so $x = \frac{36}{99} = \frac{4}{11}$. Check: $4 \div 11 = 0.3636\ldots$');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2b41401ee71ec0', 'les_7bc50c743d2362', 7, 'review', 'multiple_choice', 2, 'Order from least to greatest: $-0.6,\ -\frac{2}{3},\ -\frac{1}{2}$.', '{"choices":["$-\\frac{1}{2}, -0.6, -\\frac{2}{3}$","$-\\frac{2}{3}, -0.6, -\\frac{1}{2}$","$-0.6, -\\frac{2}{3}, -\\frac{1}{2}$","$-\\frac{2}{3}, -\\frac{1}{2}, -0.6$"],"answer":1}', '["Convert: $-\\frac{2}{3} \\approx -0.667$, $-\\frac{1}{2} = -0.5$."]', '$-0.667 < -0.6 < -0.5$, so $-\frac{2}{3} < -0.6 < -\frac{1}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4d80df0051f570', 'les_7bc50c743d2362', 8, 'review', 'numeric', 2, 'A runner finishes 9 laps out of 12 planned. Write the fraction completed as a decimal.', '{"answer":0.75}', '["$\\frac{9}{12}$ simplifies to $\\frac{3}{4}$."]', '$\frac{9}{12} = \frac{3}{4} = 0.75$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36a6777463a5e2', 'subj_math', 'rational-numbers', 'Rational numbers', 'Numbers that can be written as a ratio of two integers with a nonzero denominator.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7bc50c743d2362', (SELECT id FROM concepts WHERE slug = 'rational-numbers'));

-- Lesson: ratios-equivalent-ratios
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7dde13e6ad979d', 'ratios-equivalent-ratios', 'Ratios and equivalent ratios', 'Write ratios three ways, simplify them, and build equivalent ratios with tables and double number lines.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6e0cd34afde3c8', 'les_7dde13e6ad979d', 1, 'Write a ratio as a : b, a to b and a/b, and say what it compares.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5ae10d6b77b6c9', 'les_7dde13e6ad979d', 2, 'Simplify a ratio and generate equivalent ratios by multiplying or dividing both parts by the same number.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_95ea2d5577a864', 'les_7dde13e6ad979d', 3, 'Use ratio tables and double number lines to solve problems.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e0cd34afde3c8', 'les_7dde13e6ad979d', 'learn', 1, 'definition', '{"term":"Ratio","body":"A comparison of two quantities, written $a : b$, \"$a$ to $b$\" or $\\frac{a}{b}$. If a class has 12 girls and 15 boys, the ratio of girls to boys is $12 : 15$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5ae10d6b77b6c9', 'les_7dde13e6ad979d', 'learn', 2, 'text', '{"body":"Order matters: girls to boys is $12 : 15$, but boys to girls is $15 : 12$. A ratio can also compare a part to the whole. Here there are 27 students, so girls to all students is $12 : 27$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_95ea2d5577a864', 'les_7dde13e6ad979d', 'learn', 3, 'definition', '{"term":"Equivalent ratios","body":"Ratios that describe the same relationship. Multiplying or dividing both parts by the same nonzero number gives an equivalent ratio: $12 : 15 = 4 : 5 = 8 : 10$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_97fd5afe5e1a97', 'les_7dde13e6ad979d', 'learn', 4, 'text', '{"body":"A ratio is in simplest form when its parts are whole numbers with no common factor other than 1. To simplify, divide both parts by their greatest common factor. $12 : 15$ has GCF 3, so it simplifies to $4 : 5$: for every 4 girls there are 5 boys."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a738cd9ff25c22', 'les_7dde13e6ad979d', 'experiment', 5, 'activity', '{"activity":"ratio-line","title":"Scale a ratio","params":{"a":2,"b":5,"k":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1548c214548814', 'les_7dde13e6ad979d', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Set the ratio to $2 : 5$ and move the scale factor. Every vertical pair is equivalent. Which scale factor gives 15 for B? What does the pair at scale factor 0.5 mean?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4b7c2edf05329f', 'les_7dde13e6ad979d', 'learn', 7, 'worked_example', '{"title":"Lemonade uses 3 cups of lemon juice for every 8 cups of water. How much juice goes with 20 cups of water?","steps":[{"latex":"\\begin{array}{c|c|c|c} \\text{juice} & 3 & 1.5 & 7.5 \\\\ \\hline \\text{water} & 8 & 4 & 20 \\end{array}","explanation":"Make a ratio table. Halve both to get 4 cups of water, then multiply by 5."},{"latex":"7.5 \\text{ cups of juice}","explanation":"Each column keeps the same ratio."}],"check":"Check: $\\frac{7.5}{20} = 0.375 = \\frac{3}{8}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d454d83d54d126', 'les_7dde13e6ad979d', 'learn', 8, 'worked_example', '{"title":"Simplify $1.5 : 4.5$ and $\\frac{2}{3} : \\frac{5}{6}$","steps":[{"latex":"1.5 : 4.5 = 15 : 45 = 1 : 3","explanation":"Multiply by 10 to clear decimals, then divide by 15."},{"latex":"\\tfrac{2}{3} : \\tfrac{5}{6} = 4 : 5","explanation":"Multiply both parts by 6, the LCD."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_017422dfa2e348', 'les_7dde13e6ad979d', 'learn', 9, 'callout', '{"tone":"warning","title":"Adding is not scaling","body":"Adding the same amount to both parts does not keep a ratio equivalent. $2 : 3$ and $4 : 5$ are not equivalent, because $\\frac{2}{3} \\ne \\frac{4}{5}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cfe595d958ebf9', 'les_7dde13e6ad979d', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Paint mixes, concrete, recipes, screen shapes (a 16 : 9 display) and gear trains all use ratios. Scaling a recipe means using an equivalent ratio for every ingredient."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6e0cd34afde3c8', 'les_7dde13e6ad979d', 1, 'practice', 'short_text', 1, 'A bag has 6 red and 10 blue marbles. Write the ratio of red to blue in simplest form, as a:b.', '{"accept":["3:5"]}', '["Divide both parts by 2."]', '$6 : 10 = 3 : 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5ae10d6b77b6c9', 'les_7dde13e6ad979d', 2, 'practice', 'short_text', 1, 'Using the same bag, write the ratio of blue marbles to all marbles in simplest form.', '{"accept":["5:8"]}', '["There are 16 marbles in all."]', '$10 : 16 = 5 : 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_95ea2d5577a864', 'les_7dde13e6ad979d', 3, 'practice', 'multiple_choice', 2, 'Which ratio is equivalent to $4 : 7$?', '{"choices":["$8 : 11$","$12 : 21$","$7 : 4$","$16 : 21$"],"answer":1}', '["Multiply both parts by the same number."]', '$4 \cdot 3 : 7 \cdot 3 = 12 : 21$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_97fd5afe5e1a97', 'les_7dde13e6ad979d', 4, 'practice', 'numeric', 2, 'A recipe uses 2 cups of rice for 3 cups of water. How many cups of water are needed for 5 cups of rice?', '{"answer":7.5,"unit":"cups"}', '["Find the water for 1 cup of rice first."]', '$\frac{3}{2} = 1.5$ cups of water per cup of rice, so $5 \cdot 1.5 = 7.5$ cups.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a738cd9ff25c22', 'les_7dde13e6ad979d', 5, 'practice', 'short_text', 2, 'Simplify $2.4 : 3.6$ to whole numbers in simplest form.', '{"accept":["2:3"]}', '["Multiply by 10: 24 : 36."]', '$24 : 36 = 2 : 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1548c214548814', 'les_7dde13e6ad979d', 6, 'practice', 'numeric', 2, 'The ratio of cats to dogs at a shelter is $5 : 3$. There are 40 cats. How many dogs are there?', '{"answer":24}', '["40 is 5 times what number?"]', 'The scale factor is $40 \div 5 = 8$, so there are $3 \cdot 8 = 24$ dogs.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4b7c2edf05329f', 'les_7dde13e6ad979d', 7, 'practice', 'numeric', 3, 'A school''s ratio of students to teachers is $18 : 1$. The school has 990 students. How many teachers does it have?', '{"answer":55}', '["990 ÷ 18."]', '$990 \div 18 = 55$ teachers.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d454d83d54d126', 'les_7dde13e6ad979d', 8, 'review', 'numeric', 3, 'Green paint is mixed from blue and yellow in the ratio $2 : 3$. How many liters of blue are in 15 liters of green paint?', '{"answer":6,"unit":"L"}', '["2 + 3 = 5 parts make the whole.","Each part is 15 ÷ 5 liters."]', 'Each part is 3 L, so blue is $2 \cdot 3 = 6$ L (and yellow is 9 L).');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_c361e7db0f7e94', 'subj_math', 'ratios', 'Ratios', 'A comparison of two quantities by division.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7dde13e6ad979d', (SELECT id FROM concepts WHERE slug = 'ratios'));

-- Lesson: relations-and-functions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_96dd4515619a0b', 'relations-and-functions', 'Relations and functions', 'Decide whether a relation is a function from ordered pairs, tables, mappings and graphs, using the vertical line test.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9e43164380376d', 'les_96dd4515619a0b', 1, 'Define relation, function, input and output.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_97ffc939bee802', 'les_96dd4515619a0b', 2, 'Determine whether a relation given as ordered pairs, a table, a mapping diagram or a graph is a function.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0791c408e65aae', 'les_96dd4515619a0b', 3, 'Apply the vertical line test and explain why it works.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9e43164380376d', 'les_96dd4515619a0b', 'learn', 1, 'definition', '{"term":"Relation","body":"Any set of ordered pairs $(x, y)$. The $x$-values are the inputs and the $y$-values are the outputs."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_97ffc939bee802', 'les_96dd4515619a0b', 'learn', 2, 'definition', '{"term":"Function","body":"A relation in which each input has exactly one output. Different inputs may share an output, but one input may never have two different outputs."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0791c408e65aae', 'les_96dd4515619a0b', 'learn', 3, 'text', '{"body":"Think of a function as a reliable machine: put in the same input and you always get the same output. A vending machine where button B4 sometimes gives chips and sometimes gives a cookie is not a function. A machine where B4 and B5 both give chips is fine."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_86880fa35e52f3', 'les_96dd4515619a0b', 'learn', 4, 'worked_example', '{"title":"Is $\\{(1, 4), (2, 5), (3, 4), (1, 7)\\}$ a function?","steps":[{"latex":"(1, 4) \\text{ and } (1, 7)","explanation":"The input 1 appears with two different outputs."},{"latex":"\\text{Not a function}","explanation":"One repeated input with different outputs is enough."}],"check":"$(1, 4)$ and $(3, 4)$ share an output, which is allowed."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_af7f2e95a4d90c', 'les_96dd4515619a0b', 'learn', 5, 'worked_example', '{"title":"Is the table $x$: −2, −1, 0, 1, 2 and $y$: 4, 1, 0, 1, 4 a function?","steps":[{"latex":"\\text{each } x \\text{ appears once}","explanation":"No input is repeated."},{"latex":"\\text{Function}","explanation":"Repeated outputs (4 and 1) don''t matter. This is y = x²."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ebdec2e7572e33', 'les_96dd4515619a0b', 'learn', 6, 'definition', '{"term":"Vertical line test","body":"A graph represents $y$ as a function of $x$ exactly when no vertical line crosses it more than once."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_263eb93799d16a', 'les_96dd4515619a0b', 'learn', 7, 'text', '{"body":"Why does it work? Every point on a vertical line $x = a$ has the same input $a$. If the line hits the graph twice, the input $a$ has two outputs. Parabolas that open up or down pass the test; a circle or a sideways parabola fails it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_025dacecd298c2', 'les_96dd4515619a0b', 'learn', 8, 'worked_example', '{"title":"Is $x = y^2$ a function of $x$?","steps":[{"latex":"x = 4 \\Rightarrow y = 2 \\text{ or } y = -2","explanation":"Find the outputs for one input."},{"latex":"\\text{Not a function}","explanation":"The input 4 has two outputs; the vertical line x = 4 meets the graph twice."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2391b1d5426d1d', 'les_96dd4515619a0b', 'learn', 9, 'callout', '{"tone":"warning","title":"Which variable is the input?","body":"Unless told otherwise, $x$ is the input. $x = y^2$ is not a function of $x$, but it is a function of $y$ (each $y$ gives one $x$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c390ffa77c03e9', 'les_96dd4515619a0b', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Each person has exactly one birthday (person → birthday is a function), but many people share a birthday (birthday → person is not). Databases depend on this idea: an ID number must determine exactly one record."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9e43164380376d', 'les_96dd4515619a0b', 1, 'practice', 'multiple_choice', 1, 'Which relation is a function?', '{"choices":["$\\{(2, 3), (2, 5), (4, 7)\\}$","$\\{(1, 0), (2, 0), (3, 0)\\}$","$\\{(5, 1), (6, 2), (5, 3)\\}$","$\\{(0, 0), (0, 1)\\}$"],"answer":1}', '["Look for a repeated input with different outputs."]', 'In $\{(1,0), (2,0), (3,0)\}$ each input appears once. The others repeat an input with different outputs.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_97ffc939bee802', 'les_96dd4515619a0b', 2, 'practice', 'multiple_choice', 2, 'Which graph passes the vertical line test?', '{"choices":["A circle","A horizontal line","A vertical line","The sideways parabola x = y²"],"answer":1}', '["Imagine sliding a vertical line across each graph."]', 'A horizontal line $y = c$ meets each vertical line exactly once. A vertical line fails completely: every point on it has the same input.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0791c408e65aae', 'les_96dd4515619a0b', 3, 'practice', 'multiple_choice', 2, 'A mapping diagram sends 1 → a, 2 → a, 3 → b. Is it a function?', '{"choices":["Yes","No, because a is used twice","No, because 3 maps to b","Cannot tell"],"answer":0}', '["Does any input have two outputs?"]', 'Each input has exactly one arrow, so it is a function. Two inputs sharing the output $a$ is allowed.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_86880fa35e52f3', 'les_96dd4515619a0b', 4, 'practice', 'multiple_choice', 2, 'Is "student → locker number" a function if each student has exactly one locker?', '{"choices":["Yes","No","Only if lockers are numbered in order","Only if no two students share a locker"],"answer":0}', '["Does each input (student) have exactly one output?"]', 'Yes. Each student (input) is paired with one locker (output). Even if two students shared a locker, it would still be a function.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_af7f2e95a4d90c', 'les_96dd4515619a0b', 5, 'review', 'short_text', 3, 'What value of $k$ makes $\{(3, 1), (k, 5), (4, 1)\}$ NOT a function? Give one value.', '{"accept":["3","4","k=3","k=4"]}', '["Repeat an input that already has a different output."]', 'If $k = 3$ or $k = 4$, that input would have two outputs (1 and 5).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ebdec2e7572e33', 'les_96dd4515619a0b', 6, 'review', 'multiple_choice', 3, 'Which equation does NOT define y as a function of x?', '{"choices":["$y = 3x - 1$","$y = x^2 + 2$","$y = |x|$","$x^2 + y^2 = 9$"],"answer":3}', '["Try x = 0 in each."]', 'For $x^2 + y^2 = 9$, $x = 0$ gives $y = 3$ or $y = -3$. It''s a circle and fails the vertical line test.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2f887def33825e', 'subj_math', 'functions', 'Functions', 'Relations that assign exactly one output to each input.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_96dd4515619a0b', (SELECT id FROM concepts WHERE slug = 'functions'));

-- Lesson: scale-drawings
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_4f933ee4c4c7a3', 'scale-drawings', 'Scale drawings and maps', 'Use a scale to convert between drawing lengths and actual lengths, and see how areas scale by the square of the scale factor.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_64996039c2f88b', 'les_4f933ee4c4c7a3', 1, 'Interpret a scale such as 1 cm : 5 m and write it as a scale factor.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_aed9c9bafb7264', 'les_4f933ee4c4c7a3', 2, 'Find actual lengths from a scale drawing or map, and drawing lengths from actual lengths.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_14069432643252', 'les_4f933ee4c4c7a3', 3, 'Explain why areas scale by the square of the scale factor.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_64996039c2f88b', 'les_4f933ee4c4c7a3', 'learn', 1, 'definition', '{"term":"Scale","body":"A ratio that compares lengths in a drawing to actual lengths, such as \"1 in : 20 ft\" or \"1 : 50,000.\" Every length in the drawing is the same fraction of the real length."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aed9c9bafb7264', 'les_4f933ee4c4c7a3', 'learn', 2, 'text', '{"body":"A scale is a proportion waiting to be used. If 1 cm on a map stands for 5 km, then 7.2 cm stands for $7.2 \\times 5 = 36$ km. Going the other way, a real distance of 12 km is drawn as $12 \\div 5 = 2.4$ cm."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_14069432643252', 'les_4f933ee4c4c7a3', 'learn', 3, 'definition', '{"term":"Scale factor","body":"A scale with the same unit on both sides, written as one number. \"1 cm : 5 m\" becomes 1 cm : 500 cm, a scale factor of $\\frac{1}{500}$ from the real object to the drawing."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dcb6dbe684806a', 'les_4f933ee4c4c7a3', 'learn', 4, 'worked_example', '{"title":"On a floor plan, 1 in = 4 ft. A room measures $3\\frac{1}{2}$ in by $2\\frac{3}{4}$ in on the plan. Find its actual dimensions and area.","steps":[{"latex":"3.5 \\times 4 = 14 \\text{ ft}","explanation":"Length."},{"latex":"2.75 \\times 4 = 11 \\text{ ft}","explanation":"Width."},{"latex":"14 \\times 11 = 154 \\text{ ft}^2","explanation":"Actual area."}],"check":"The drawing''s area is $3.5 \\times 2.75 = 9.625$ in². Multiply by $4^2 = 16$: $9.625 \\times 16 = 154$. Areas scale by the square of the scale factor."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3b25d1d42737e1', 'les_4f933ee4c4c7a3', 'learn', 5, 'worked_example', '{"title":"A map has scale 1 : 25,000. Two towns are 8.4 cm apart on the map. How far apart are they in kilometers?","steps":[{"latex":"8.4 \\times 25{,}000 = 210{,}000 \\text{ cm}","explanation":"Real distance in the map''s unit."},{"latex":"210{,}000 \\text{ cm} = 2100 \\text{ m} = 2.1 \\text{ km}","explanation":"100 cm per meter, 1000 m per kilometer."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_521f9d6875427d', 'les_4f933ee4c4c7a3', 'learn', 6, 'callout', '{"tone":"tip","title":"Keep units visible","body":"Write the units at every step. Most scale errors are unit errors, such as mixing inches with feet or centimeters with kilometers."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aa11db5a59b725', 'les_4f933ee4c4c7a3', 'learn', 7, 'callout', '{"tone":"warning","title":"Area is not multiplied by the scale","body":"If every length is doubled, the area is multiplied by $2^2 = 4$, not 2. A model built at 1 : 10 has $\\frac{1}{100}$ of the area and $\\frac{1}{1000}$ of the volume of the real object."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5d383a049fc580', 'les_4f933ee4c4c7a3', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Architects, engineers, model builders and anyone reading a hiking map use scales. A 1 : 24 model car that is 18.5 cm long represents a car $18.5 \\times 24 = 444$ cm, about 4.4 m, long."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_64996039c2f88b', 'les_4f933ee4c4c7a3', 1, 'practice', 'numeric', 1, 'A map scale is 1 cm : 15 km. Two cities are 6 cm apart on the map. What is the actual distance in km?', '{"answer":90,"unit":"km"}', '["Multiply by 15."]', '$6 \times 15 = 90$ km.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aed9c9bafb7264', 'les_4f933ee4c4c7a3', 2, 'practice', 'numeric', 1, 'On a drawing with scale 1 in : 8 ft, a wall is 40 ft long. How long is it on the drawing, in inches?', '{"answer":5,"unit":"in"}', '["Divide 40 by 8."]', '$40 \div 8 = 5$ in.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_14069432643252', 'les_4f933ee4c4c7a3', 3, 'practice', 'numeric', 2, 'A model airplane is built at a scale of 1 : 72. The model''s wingspan is 50 cm. What is the real wingspan in meters?', '{"answer":36,"unit":"m"}', '["50 × 72 cm, then convert to meters."]', '$50 \times 72 = 3600$ cm $= 36$ m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dcb6dbe684806a', 'les_4f933ee4c4c7a3', 4, 'practice', 'multiple_choice', 2, 'The scale "1 cm : 2 m" written as a scale factor from drawing to real object is…', '{"choices":["1 : 2","1 : 20","1 : 200","1 : 2000"],"answer":2}', '["Convert 2 m to centimeters."]', '2 m = 200 cm, so the scale is 1 : 200.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3b25d1d42737e1', 'les_4f933ee4c4c7a3', 5, 'practice', 'numeric', 2, 'A garden is drawn at a scale of 1 cm : 3 m. On the drawing it is a rectangle 4 cm by 2.5 cm. What is the actual area of the garden, in square meters?', '{"answer":90,"unit":"m²"}', '["Find the actual length and width first.","12 m by 7.5 m."]', '$12 \times 7.5 = 90$ m².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_521f9d6875427d', 'les_4f933ee4c4c7a3', 6, 'review', 'numeric', 3, 'A photo 4 in by 6 in is enlarged with a scale factor of 2.5. By what number is its area multiplied?', '{"answer":6.25}', '["Areas scale by the square of the scale factor."]', '$2.5^2 = 6.25$. (The area goes from 24 in² to 150 in², and $150 \div 24 = 6.25$.)');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aa11db5a59b725', 'les_4f933ee4c4c7a3', 7, 'review', 'numeric', 3, 'On a map, 2.5 in represents 75 miles. What does 4 in represent, in miles?', '{"answer":120,"unit":"mi"}', '["Find miles per inch: 75 ÷ 2.5."]', '30 miles per inch, so $4 \times 30 = 120$ miles.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a07b8f6016132a', 'subj_math', 'scale-factor', 'Scale factor', 'The ratio of a length in a copy to the corresponding length in the original.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_4f933ee4c4c7a3', (SELECT id FROM concepts WHERE slug = 'scale-factor'));

-- Lesson: scatter-plots-lines-of-fit
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_68fdc6b1d7d304', 'scatter-plots-lines-of-fit', 'Scatter plots and lines of fit', 'Describe the direction, form and strength of a relationship in a scatter plot, fit and write a line, interpret the correlation coefficient, and separate correlation from causation.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_268b7b295b10b5', 'les_68fdc6b1d7d304', 1, 'Describe a scatter plot by direction, form and strength, and identify outliers.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fa0a5e9bf0cdbd', 'les_68fdc6b1d7d304', 2, 'Draw a line of fit, write its equation from two points, and use it to make predictions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0bab3700459049', 'les_68fdc6b1d7d304', 3, 'Interpret the correlation coefficient r and explain why correlation does not imply causation.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_268b7b295b10b5', 'les_68fdc6b1d7d304', 'learn', 1, 'definition', '{"term":"Scatter plot","body":"A graph of paired data $(x, y)$, one point per individual. It shows whether two quantities are related."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa0a5e9bf0cdbd', 'les_68fdc6b1d7d304', 'learn', 2, 'text', '{"body":"Describe a scatter plot by its direction (positive: $y$ tends to rise as $x$ rises; negative: $y$ tends to fall), its form (linear, curved or no pattern), and its strength (how tightly the points cluster around a line or curve). Note any outliers, points far from the overall pattern."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0bab3700459049', 'les_68fdc6b1d7d304', 'learn', 3, 'definition', '{"term":"Line of fit","body":"A line that follows the trend of the points, with about as many points above it as below it. A least-squares regression line, computed by calculators and software, is the line that makes the sum of the squared vertical distances to the points as small as possible."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_87e831569b92e8', 'les_68fdc6b1d7d304', 'learn', 4, 'worked_example', '{"title":"Hours studied vs test score: a line of fit passes through (1, 62) and (6, 92). Write it and predict the score for 4 hours.","steps":[{"latex":"m = \\frac{92 - 62}{6 - 1} = 6","explanation":"About 6 more points per extra hour."},{"latex":"y - 62 = 6(x - 1) \\Rightarrow y = 6x + 56","explanation":""},{"latex":"y(4) = 6(4) + 56 = 80","explanation":"Predicted score: about 80."}],"check":"The intercept 56 predicts the score with no studying. That is reasonable only if 0 hours is within or near the data."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f1956c9492eda5', 'les_68fdc6b1d7d304', 'learn', 5, 'definition', '{"term":"Correlation coefficient r","body":"A number from $-1$ to $1$ that measures the direction and strength of a linear relationship. $r$ near $1$: strong positive. $r$ near $-1$: strong negative. $r$ near 0: weak or no linear relationship."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_08a3c753840fa5', 'les_68fdc6b1d7d304', 'learn', 6, 'callout', '{"tone":"warning","title":"Correlation is not causation","body":"Ice-cream sales and drownings are positively correlated, but ice cream doesn''t cause drowning. Both rise in hot weather, a lurking variable. Only a controlled experiment can show that one variable causes changes in another."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c45eab1a9d1988', 'les_68fdc6b1d7d304', 'learn', 7, 'callout', '{"tone":"warning","title":"Extrapolation is risky","body":"Predicting far outside the range of the data, such as a score for 20 hours of studying ($6 \\cdot 20 + 56 = 176$ out of 100), can give nonsense. The trend may not continue."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7a0abe57e57647', 'les_68fdc6b1d7d304', 'learn', 8, 'callout', '{"tone":"note","title":"Residuals","body":"A residual is actual minus predicted: $y - \\hat{y}$. A student who studied 4 hours and scored 85 has residual $85 - 80 = 5$, doing better than the line predicts. Residuals that show a pattern suggest a line isn''t the right model."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d9b3b25c9fc34c', 'les_68fdc6b1d7d304', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Doctors relate height to weight, economists relate income to spending, and scientists relate temperature to chirp rates of crickets. A line of fit turns a cloud of data into a usable prediction rule."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_268b7b295b10b5', 'les_68fdc6b1d7d304', 1, 'practice', 'multiple_choice', 1, 'As the outside temperature rises, heating costs fall. What kind of correlation is this?', '{"choices":["Positive","Negative","None","Causation"],"answer":1}', '["One variable goes up as the other goes down."]', 'Negative correlation.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fa0a5e9bf0cdbd', 'les_68fdc6b1d7d304', 2, 'practice', 'multiple_choice', 2, 'Which value of r shows the strongest linear relationship?', '{"choices":["0.65","−0.92","0.08","−0.40"],"answer":1}', '["Strength depends on how close |r| is to 1."]', '$|-0.92| = 0.92$ is closest to 1.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0bab3700459049', 'les_68fdc6b1d7d304', 3, 'practice', 'numeric', 2, 'A line of fit is $y = 2.5x + 10$, where x is months and y is plant height in cm. Predict the height at 8 months.', '{"answer":30,"unit":"cm"}', '["Substitute x = 8."]', '$2.5(8) + 10 = 30$ cm.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_87e831569b92e8', 'les_68fdc6b1d7d304', 4, 'practice', 'numeric', 2, 'A line of fit passes through (2, 15) and (10, 55). What is its slope?', '{"answer":5}', '["Rise over run."]', '$\frac{55 - 15}{10 - 2} = \frac{40}{8} = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f1956c9492eda5', 'les_68fdc6b1d7d304', 5, 'practice', 'numeric', 2, 'Using $y = 2.5x + 10$, a plant at 6 months measured 28 cm. What is the residual?', '{"answer":3,"unit":"cm"}', '["Predicted value: 2.5 · 6 + 10.","Residual = actual − predicted."]', 'Predicted 25 cm, so the residual is $28 - 25 = 3$ cm.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_08a3c753840fa5', 'les_68fdc6b1d7d304', 6, 'review', 'multiple_choice', 3, 'Cities with more firefighters tend to have more fires. What''s the best explanation?', '{"choices":["Firefighters cause fires","Fires cause firefighters to be hired, so the relationship is causal","A lurking variable such as city size affects both","The correlation must be a mistake"],"answer":2}', '["What makes a city have more of both?"]', 'Bigger cities have both more fires and more firefighters. City size is a lurking variable.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c45eab1a9d1988', 'les_68fdc6b1d7d304', 7, 'review', 'multiple_choice', 3, 'Data were collected for cars aged 1 to 8 years. Which use of the line of fit is least reliable?', '{"choices":["Predicting value at 3 years","Predicting value at 7.5 years","Predicting value at 25 years","Predicting value at 5 years"],"answer":2}', '["Which input is far outside the data?"]', '25 years is far beyond the data (extrapolation), so the prediction is unreliable and could even be negative.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d3b0d7239ea2f7', 'subj_math', 'scatter-plots', 'Scatter plots', 'Graphs of paired numerical data used to look for relationships.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_68fdc6b1d7d304', (SELECT id FROM concepts WHERE slug = 'scatter-plots'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1469596fc89ae5', 'subj_math', 'correlation', 'Correlation', 'The direction and strength of a linear relationship, measured by r between −1 and 1.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_68fdc6b1d7d304', (SELECT id FROM concepts WHERE slug = 'correlation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_68fdc6b1d7d304', (SELECT id FROM formulas WHERE slug = 'slope'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_68fdc6b1d7d304', (SELECT id FROM formulas WHERE slug = 'point-slope-form'), 2);

-- Lesson: simplifying-expressions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9163fa7f57cb28', 'simplifying-expressions', 'Simplifying expressions', 'Simplify algebraic expressions with distribution, like terms, fractions and nested grouping, and test equivalence by substitution.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_258cef28ba8793', 'les_9163fa7f57cb28', 1, 'Simplify expressions by distributing and combining like terms, including nested grouping symbols.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d2973030e4b4d7', 'les_9163fa7f57cb28', 2, 'Simplify expressions with fractional coefficients.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8adc102ad66063', 'les_9163fa7f57cb28', 3, 'Decide whether two expressions are equivalent, and use a counterexample to show they are not.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_258cef28ba8793', 'les_9163fa7f57cb28', 'learn', 1, 'definition', '{"term":"Equivalent expressions","body":"Two expressions are equivalent if they have the same value for every value of their variables. $3(x + 2)$ and $3x + 6$ are equivalent; $3x + 2$ is not equivalent to either."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d2973030e4b4d7', 'les_9163fa7f57cb28', 'learn', 2, 'text', '{"body":"Simplifying means rewriting an expression as an equivalent one that is shorter and easier to use: no parentheses left to distribute and no like terms left to combine. The standard order is distribute, then combine like terms, writing terms from the highest power down."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8adc102ad66063', 'les_9163fa7f57cb28', 'learn', 3, 'worked_example', '{"title":"Simplify $3(2x - 5) - 4(x - 3) + 2x$","steps":[{"latex":"6x - 15 - 4x + 12 + 2x","explanation":"Distribute 3 and −4. Note (−4)(−3) = +12."},{"latex":"(6x - 4x + 2x) + (-15 + 12)","explanation":"Group like terms."},{"latex":"4x - 3","explanation":""}],"check":"Check with $x = 1$: $3(-3) - 4(-2) + 2 = -9 + 8 + 2 = 1$, and $4(1) - 3 = 1$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_256bce30d122e0', 'les_9163fa7f57cb28', 'learn', 4, 'worked_example', '{"title":"Simplify $5 - 2[\\,x - 3(x + 1)\\,]$","steps":[{"latex":"5 - 2[\\,x - 3x - 3\\,]","explanation":"Work from the innermost grouping out."},{"latex":"5 - 2[\\,-2x - 3\\,]","explanation":"Combine inside the brackets."},{"latex":"5 + 4x + 6 = 4x + 11","explanation":"Distribute −2."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_052405f12e0e8b', 'les_9163fa7f57cb28', 'learn', 5, 'worked_example', '{"title":"Simplify $\\tfrac{1}{2}(4a - 6) + \\tfrac{2}{3}(3a + 9)$","steps":[{"latex":"2a - 3 + 2a + 6","explanation":"Distribute each fraction."},{"latex":"4a + 3","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_21dce32624b45d', 'les_9163fa7f57cb28', 'learn', 6, 'worked_example', '{"title":"Simplify $\\dfrac{x}{3} + \\dfrac{x}{4}$","steps":[{"latex":"\\tfrac{4x}{12} + \\tfrac{3x}{12}","explanation":"Common denominator 12."},{"latex":"\\tfrac{7x}{12}","explanation":"Or think of it as $\\frac{1}{3}x + \\frac{1}{4}x = \\frac{7}{12}x$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_03817a79ef4a0e', 'les_9163fa7f57cb28', 'experiment', 7, 'activity', '{"activity":"area-model","title":"Distributing and combining in one picture","params":{"a":2,"b":-3,"c":1,"d":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_871a317b2c368c', 'les_9163fa7f57cb28', 'experiment', 8, 'callout', '{"tone":"tip","title":"Try this","body":"The model multiplies $(2x - 3)(x + 4)$. The two middle cells, $-3x$ and $8x$, are like terms. Change $b$ until they cancel exactly. What is the product then?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0f8ce0d76449ce', 'les_9163fa7f57cb28', 'learn', 9, 'callout', '{"tone":"warning","title":"A counterexample settles it","body":"To show two expressions are not equivalent, one value is enough. $(x + 3)^2$ and $x^2 + 9$ differ at $x = 1$: $16 \\ne 10$. To show they are equivalent, you need algebra, because checking a few values doesn''t cover every number."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c3d3de45e4a1fa', 'les_9163fa7f57cb28', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Simplified formulas are faster to compute and easier to compare. A store''s total for $n$ items at 4 dollars with a 10% discount and a 5-dollar fee, $0.9(4n) + 5$, simplifies to $3.6n + 5$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_258cef28ba8793', 'les_9163fa7f57cb28', 1, 'practice', 'short_text', 1, 'Simplify $7x - 2(3x + 4)$.', '{"accept":["x-8","-8+x"]}', '["Distribute −2 to both terms."]', '$7x - 6x - 8 = x - 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d2973030e4b4d7', 'les_9163fa7f57cb28', 2, 'practice', 'short_text', 2, 'Simplify $-(2y - 5) + 3(y - 1)$.', '{"accept":["y+2","2+y"]}', '["$-2y + 5 + 3y - 3$."]', '$y + 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8adc102ad66063', 'les_9163fa7f57cb28', 3, 'practice', 'short_text', 2, 'Simplify $4 - 3[\,2 - (x - 5)\,]$.', '{"accept":["3x-17","-17+3x"]}', '["Innermost first: 2 − (x − 5) = 7 − x.","Then 4 − 3(7 − x)."]', '$4 - 21 + 3x = 3x - 17$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_256bce30d122e0', 'les_9163fa7f57cb28', 4, 'practice', 'short_text', 2, 'Simplify $\tfrac{3}{4}(8m + 12) - 5m$.', '{"accept":["m+9","9+m"]}', '["$\\frac{3}{4} \\cdot 8 = 6$ and $\\frac{3}{4} \\cdot 12 = 9$."]', '$6m + 9 - 5m = m + 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_052405f12e0e8b', 'les_9163fa7f57cb28', 5, 'practice', 'short_text', 2, 'Simplify $\frac{x}{2} - \frac{x}{5}$. Write the answer like 3x/10.', '{"accept":["3x/10","(3/10)x","3/10x"]}', '["Common denominator 10."]', '$\frac{5x}{10} - \frac{2x}{10} = \frac{3x}{10}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_21dce32624b45d', 'les_9163fa7f57cb28', 6, 'practice', 'multiple_choice', 2, 'Which expression is equivalent to $2(x - 4) + 3(x + 1)$?', '{"choices":["$5x - 5$","$5x - 3$","$5x + 11$","$6x - 5$"],"answer":0}', '["Distribute and combine."]', '$2x - 8 + 3x + 3 = 5x - 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_03817a79ef4a0e', 'les_9163fa7f57cb28', 7, 'review', 'multiple_choice', 3, 'Which value of $x$ shows that $2(x + 3)$ and $2x + 3$ are not equivalent?', '{"choices":["Any value of x","Only x = 0","No value","Only x = 3"],"answer":0}', '["Simplify 2(x + 3) and compare."]', '$2(x + 3) = 2x + 6$, which is always 3 more than $2x + 3$. They differ for every value of $x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_871a317b2c368c', 'les_9163fa7f57cb28', 8, 'review', 'short_text', 3, 'Simplify $0.4(5n - 10) - 0.2(5n + 15)$.', '{"accept":["n-7","-7+n"]}', '["$2n - 4 - n - 3$."]', '$n - 7$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36a538d0deeeca', 'subj_math', 'equivalent-expressions', 'Equivalent expressions', 'Expressions that have the same value for every value of the variables.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9163fa7f57cb28', (SELECT id FROM concepts WHERE slug = 'equivalent-expressions'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7927ef860f1bc4', 'subj_math', 'like-terms', 'Like terms', 'Terms with exactly the same variables raised to the same powers.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9163fa7f57cb28', (SELECT id FROM concepts WHERE slug = 'like-terms'));

-- Lesson: solving-linear-inequalities
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9aeb8c0b72bc5c', 'solving-linear-inequalities', 'Solving linear inequalities', 'Solve multi-step linear inequalities, including variables on both sides, write solutions in set and interval notation, and recognize when every or no real number works.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_984ca0df18409a', 'les_9aeb8c0b72bc5c', 1, 'Solve multi-step inequalities, reversing the symbol when multiplying or dividing by a negative.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2fa6af6bb74408', 'les_9aeb8c0b72bc5c', 2, 'Write solution sets with inequality, set-builder and interval notation, and graph them.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7dc669482dd602', 'les_9aeb8c0b72bc5c', 3, 'Identify inequalities whose solution set is all real numbers or the empty set.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_984ca0df18409a', 'les_9aeb8c0b72bc5c', 'learn', 1, 'text', '{"body":"Multi-step inequalities are solved with the same moves as multi-step equations: distribute, combine like terms, collect variables on one side and isolate. The one extra rule is that multiplying or dividing both sides by a negative number reverses the inequality."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2fa6af6bb74408', 'les_9aeb8c0b72bc5c', 'learn', 2, 'definition', '{"term":"Interval notation","body":"A bracket $[\\ ]$ includes an endpoint and a parenthesis $(\\ )$ excludes it. Infinity always gets a parenthesis. $x \\ge 3$ is $[3, \\infty)$, $x < -1$ is $(-\\infty, -1)$, and $-2 < x \\le 5$ is $(-2, 5]$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7dc669482dd602', 'les_9aeb8c0b72bc5c', 'learn', 3, 'worked_example', '{"title":"Solve $5 - 3(x + 4) \\ge 2x + 8$","steps":[{"latex":"5 - 3x - 12 \\ge 2x + 8","explanation":"Distribute −3."},{"latex":"-3x - 7 \\ge 2x + 8","explanation":"Combine like terms."},{"latex":"-5x \\ge 15","explanation":"Subtract 2x and add 7 on both sides."},{"latex":"x \\le -3","explanation":"Divide by −5 and reverse the symbol."}],"check":"Interval: $(-\\infty, -3]$. Test $x = -4$: $5 - 3(0) = 5$ and $2(-4) + 8 = 0$, and $5 \\ge 0$ ✓. Test $x = 0$: $-7 \\ge 8$ is false ✓."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a550f27dafa646', 'les_9aeb8c0b72bc5c', 'learn', 4, 'callout', '{"tone":"tip","title":"Avoid reversing","body":"You can often avoid dividing by a negative by collecting the variable on the side where its coefficient stays positive. In the example, adding $3x$ to both sides gives $-7 \\ge 5x + 8$, then $-15 \\ge 5x$, so $-3 \\ge x$, which is the same answer."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a2b8a18e9ea00c', 'les_9aeb8c0b72bc5c', 'experiment', 5, 'activity', '{"activity":"inequality-line","title":"Graph x ≤ −3","params":{"rel":"≤","c":-3,"mode":"single"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a2122ae547de0c', 'les_9aeb8c0b72bc5c', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Set the test value to $-3$, $-2.5$ and $-6$, and check each in the original inequality $5 - 3(x + 4) \\ge 2x + 8$ by hand."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e3d4d09c4a2459', 'les_9aeb8c0b72bc5c', 'learn', 7, 'worked_example', '{"title":"Solve $2(x - 3) < 2x + 1$","steps":[{"latex":"2x - 6 < 2x + 1","explanation":""},{"latex":"-6 < 1","explanation":"Subtracting 2x removes the variable entirely."},{"latex":"\\text{always true}","explanation":"Every real number is a solution: (−∞, ∞)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4c768fe330166c', 'les_9aeb8c0b72bc5c', 'learn', 8, 'worked_example', '{"title":"Solve $4x + 3 > 4(x + 1)$","steps":[{"latex":"4x + 3 > 4x + 4","explanation":""},{"latex":"3 > 4","explanation":"False, no matter what x is."},{"latex":"\\varnothing","explanation":"No solution: the empty set."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d12e3478686141', 'les_9aeb8c0b72bc5c', 'learn', 9, 'callout', '{"tone":"warning","title":"Interval notation reads left to right","body":"Write the smaller number first: $x > 4$ is $(4, \\infty)$, not $(\\infty, 4)$. And never put a bracket next to $\\infty$, because infinity is not a number you can include."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8420b6a8895704', 'les_9aeb8c0b72bc5c', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"\"A rental van costs 40 dollars plus 0.25 dollars per mile; a truck costs 55 dollars plus 0.15 per mile. When is the truck cheaper?\" $55 + 0.15m < 40 + 0.25m$ gives $m > 150$: for trips over 150 miles."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_984ca0df18409a', 'les_9aeb8c0b72bc5c', 1, 'practice', 'short_text', 1, 'Solve $3x - 4 > 11$.', '{"accept":["x>5"]}', '["Add 4, then divide by 3."]', '$3x > 15$, $x > 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2fa6af6bb74408', 'les_9aeb8c0b72bc5c', 2, 'practice', 'short_text', 2, 'Solve $-2(x + 1) \le 8$.', '{"accept":["x>=-5","x≥-5"]}', '["Distribute or divide by −2 first.","Remember to reverse the symbol."]', '$-2x - 2 \le 8$, $-2x \le 10$, $x \ge -5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7dc669482dd602', 'les_9aeb8c0b72bc5c', 3, 'practice', 'short_text', 2, 'Solve $7 - x > 3x + 15$.', '{"accept":["x<-2"]}', '["Collect x on one side: 7 − 15 > 4x."]', '$-8 > 4x$, so $x < -2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a550f27dafa646', 'les_9aeb8c0b72bc5c', 4, 'practice', 'multiple_choice', 2, 'Which interval notation represents $x \ge -4$?', '{"choices":["$(-4, \\infty)$","$[-4, \\infty)$","$(-\\infty, -4]$","$[-4, \\infty]$"],"answer":1}', '["Is −4 included?","Infinity always gets a parenthesis."]', '$[-4, \infty)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a2b8a18e9ea00c', 'les_9aeb8c0b72bc5c', 5, 'practice', 'multiple_choice', 2, 'Solve $3(x - 2) \ge 3x - 6$.', '{"choices":["x ≥ 0","No solution","All real numbers","x ≥ 2"],"answer":2}', '["Distribute and simplify."]', '$3x - 6 \ge 3x - 6$ gives $0 \ge 0$, which is always true, so every real number is a solution.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a2122ae547de0c', 'les_9aeb8c0b72bc5c', 6, 'practice', 'short_text', 3, 'Solve $\frac{x}{4} - 1 < \frac{x}{2} + 2$.', '{"accept":["x>-12"]}', '["Multiply every term by 4 to clear fractions.","x − 4 < 2x + 8."]', '$x - 4 < 2x + 8$ gives $-12 < x$, so $x > -12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e3d4d09c4a2459', 'les_9aeb8c0b72bc5c', 7, 'review', 'multiple_choice', 3, 'Plan A costs 20 dollars per month plus 0.10 dollars per text. Plan B costs 35 dollars per month with unlimited texts. For how many texts is Plan B cheaper?', '{"choices":["More than 150","Fewer than 150","More than 350","Exactly 150"],"answer":0}', '["$35 < 20 + 0.10t$."]', '$15 < 0.10t$, so $t > 150$ texts.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_b43909c23e4964', 'subj_math', 'solving-inequalities', 'Solving inequalities', 'Finding all values that make an inequality true.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9aeb8c0b72bc5c', (SELECT id FROM concepts WHERE slug = 'solving-inequalities'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_26afa03b5cfa25', 'subj_math', 'interval-notation', 'Interval notation', 'Writing sets of real numbers as intervals using brackets and parentheses.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9aeb8c0b72bc5c', (SELECT id FROM concepts WHERE slug = 'interval-notation'));

-- Lesson: solving-proportions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0157d0a7a861de', 'solving-proportions', 'Solving proportions', 'Decide whether two ratios form a proportion, solve proportions with cross products, and recognize proportional relationships in tables and graphs.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ffcb4fb590b1fe', 'les_0157d0a7a861de', 1, 'Test whether two ratios are proportional.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_45a3f458f01cb3', 'les_0157d0a7a861de', 2, 'Solve a proportion for an unknown using equivalent ratios or cross products.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_689ea5375e2abc', 'les_0157d0a7a861de', 3, 'Recognize a proportional relationship as y = kx and find the constant of proportionality.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ffcb4fb590b1fe', 'les_0157d0a7a861de', 'learn', 1, 'definition', '{"term":"Proportion","body":"An equation stating that two ratios are equal, such as $\\dfrac{3}{4} = \\dfrac{9}{12}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_45a3f458f01cb3', 'les_0157d0a7a861de', 'learn', 2, 'definition', '{"term":"Cross products","body":"For $b \\ne 0$ and $d \\ne 0$, $\\dfrac{a}{b} = \\dfrac{c}{d}$ exactly when $ad = bc$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_689ea5375e2abc', 'les_0157d0a7a861de', 'learn', 3, 'text', '{"body":"Why do cross products work? Multiply both sides of $\\frac{a}{b} = \\frac{c}{d}$ by $bd$. The left side becomes $ad$ and the right side becomes $bc$. This is just the multiplication property of equality, so it is safe whenever neither denominator is zero."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3013a4962af656', 'les_0157d0a7a861de', 'learn', 4, 'worked_example', '{"title":"Solve $\\dfrac{x}{15} = \\dfrac{4}{6}$","steps":[{"latex":"6x = 4 \\cdot 15","explanation":"Cross products."},{"latex":"6x = 60","explanation":""},{"latex":"x = 10","explanation":"Divide by 6."}],"check":"Check: $\\frac{10}{15} = \\frac{2}{3}$ and $\\frac{4}{6} = \\frac{2}{3}$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5ed94681e243bc', 'les_0157d0a7a861de', 'learn', 5, 'worked_example', '{"title":"Solve $\\dfrac{3}{x + 2} = \\dfrac{5}{x + 6}$","steps":[{"latex":"3(x + 6) = 5(x + 2)","explanation":"Cross products. Keep the binomials in parentheses."},{"latex":"3x + 18 = 5x + 10","explanation":"Distribute."},{"latex":"8 = 2x \\Rightarrow x = 4","explanation":"Subtract 3x and 10 from both sides."}],"check":"Check: $\\frac{3}{6} = \\frac{1}{2}$ and $\\frac{5}{10} = \\frac{1}{2}$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e333a8fca18065', 'les_0157d0a7a861de', 'learn', 6, 'definition', '{"term":"Proportional relationship","body":"Two quantities are proportional if their ratio is always the same constant $k$: $\\frac{y}{x} = k$, or $y = kx$. Its graph is a straight line through the origin."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_beb0c7228091d6', 'les_0157d0a7a861de', 'learn', 7, 'worked_example', '{"title":"Is this table proportional? $x$: 2, 5, 8; $y$: 7, 17.5, 28","steps":[{"latex":"\\tfrac{7}{2} = 3.5,\\ \\tfrac{17.5}{5} = 3.5,\\ \\tfrac{28}{8} = 3.5","explanation":"Compute y ÷ x for each pair."},{"latex":"y = 3.5x","explanation":"The ratio is constant, so it is proportional with k = 3.5."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_567e68dece1dd9', 'les_0157d0a7a861de', 'learn', 8, 'callout', '{"tone":"warning","title":"Not every linear pattern is proportional","body":"A taxi that charges 3 dollars plus 2 dollars per mile has costs 5, 7, 9 for 1, 2, 3 miles. The ratios $\\frac{5}{1}, \\frac{7}{2}, \\frac{9}{3}$ are not equal, so cost is not proportional to distance. Its graph is a line that does not go through the origin."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6c85baa91c8159', 'les_0157d0a7a861de', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Map scales, currency exchange, dosage by body weight and converting units are all proportions. If 1 inch represents 25 miles, then 3.4 inches represents $3.4 \\times 25 = 85$ miles."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ffcb4fb590b1fe', 'les_0157d0a7a861de', 1, 'practice', 'multiple_choice', 1, 'Which pair of ratios forms a proportion?', '{"choices":["$\\frac{2}{3}, \\frac{6}{8}$","$\\frac{4}{10}, \\frac{6}{15}$","$\\frac{5}{7}, \\frac{7}{9}$","$\\frac{3}{5}, \\frac{5}{3}$"],"answer":1}', '["Compare the cross products."]', '$4 \cdot 15 = 60$ and $10 \cdot 6 = 60$, so $\frac{4}{10} = \frac{6}{15}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_45a3f458f01cb3', 'les_0157d0a7a861de', 2, 'practice', 'numeric', 1, 'Solve $\dfrac{7}{x} = \dfrac{21}{30}$.', '{"answer":10}', '["Cross multiply: 21x = 210."]', '$21x = 210$, so $x = 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_689ea5375e2abc', 'les_0157d0a7a861de', 3, 'practice', 'numeric', 2, 'Solve $\dfrac{n}{8} = \dfrac{15}{12}$.', '{"answer":10}', '["$12n = 120$."]', '$n = 10$. Check: $\frac{10}{8} = 1.25 = \frac{15}{12}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3013a4962af656', 'les_0157d0a7a861de', 4, 'practice', 'numeric', 2, 'Solve $\dfrac{2.5}{4} = \dfrac{x}{10}$.', '{"answer":6.25}', '["$4x = 25$."]', '$x = \frac{25}{4} = 6.25$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5ed94681e243bc', 'les_0157d0a7a861de', 5, 'practice', 'numeric', 2, 'Five notebooks cost 8.75 dollars. At the same price, how much do 8 notebooks cost?', '{"answer":14,"unit":"dollars"}', '["Set up $\\frac{5}{8.75} = \\frac{8}{c}$."]', '$5c = 70$, so $c = 14$ dollars.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e333a8fca18065', 'les_0157d0a7a861de', 6, 'practice', 'numeric', 3, 'Solve $\dfrac{x - 1}{4} = \dfrac{x + 5}{10}$.', '{"answer":5}', '["Cross multiply: 10(x − 1) = 4(x + 5).","10x − 10 = 4x + 20."]', '$6x = 30$, $x = 5$. Check: $\frac{4}{4} = 1$ and $\frac{10}{10} = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_beb0c7228091d6', 'les_0157d0a7a861de', 7, 'review', 'numeric', 2, 'A relationship is proportional with $y = 18$ when $x = 4$. What is $y$ when $x = 10$?', '{"answer":45}', '["Find k = y/x."]', '$k = 18 \div 4 = 4.5$, so $y = 4.5 \cdot 10 = 45$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_567e68dece1dd9', 'les_0157d0a7a861de', 8, 'review', 'short_text', 3, 'A gym charges a 20-dollar fee plus 10 dollars per class. Is the total cost proportional to the number of classes? Answer yes or no.', '{"accept":["no"]}', '["Compare cost ÷ classes for 1 and 2 classes."]', '1 class costs 30 (ratio 30) and 2 classes cost 40 (ratio 20). The ratio changes, so it is not proportional; the fixed fee means the graph does not pass through the origin.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_04d008a6f2f3e9', 'subj_math', 'proportions', 'Proportions', 'Equations stating that two ratios are equal.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0157d0a7a861de', (SELECT id FROM concepts WHERE slug = 'proportions'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_aca385a0d0254f', 'subj_math', 'constant-of-proportionality', 'Constant of proportionality', 'The constant ratio k = y/x in a proportional relationship y = kx.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0157d0a7a861de', (SELECT id FROM concepts WHERE slug = 'constant-of-proportionality'));

-- Lesson: solving-quadratics-factoring
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0f1e3ab9b95540', 'solving-quadratics-factoring', 'Solving quadratic equations by factoring', 'Use the zero-product property to solve quadratic equations: set the equation equal to zero, factor, and solve each factor.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_287181b48983a0', 'les_0f1e3ab9b95540', 1, 'State and explain the zero-product property.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e4e8588fe3b9df', 'les_0f1e3ab9b95540', 2, 'Solve quadratic equations by writing them in standard form and factoring.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_997ea0ab9cc397', 'les_0f1e3ab9b95540', 3, 'Connect solutions of ax² + bx + c = 0 to the x-intercepts of the graph and solve applied problems.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_287181b48983a0', 'les_0f1e3ab9b95540', 'learn', 1, 'definition', '{"term":"Zero-product property","body":"If $ab = 0$, then $a = 0$ or $b = 0$ (or both). A product can only be zero if one of its factors is zero."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e4e8588fe3b9df', 'les_0f1e3ab9b95540', 'learn', 2, 'text', '{"body":"That makes factoring powerful. $(x - 3)(x + 5) = 0$ is true exactly when $x - 3 = 0$ or $x + 5 = 0$, so $x = 3$ or $x = -5$. But it only works when one side is zero. $(x - 3)(x + 5) = 9$ tells you nothing about either factor on its own."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_997ea0ab9cc397', 'les_0f1e3ab9b95540', 'learn', 3, 'worked_example', '{"title":"Solve $x^2 + 2x = 15$","steps":[{"latex":"x^2 + 2x - 15 = 0","explanation":"Get zero on one side."},{"latex":"(x + 5)(x - 3) = 0","explanation":"Factor."},{"latex":"x = -5 \\text{ or } x = 3","explanation":"Set each factor equal to zero."}],"check":"Check: $25 - 10 = 15$ ✓ and $9 + 6 = 15$ ✓."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fb7a70832ca3cd', 'les_0f1e3ab9b95540', 'learn', 4, 'worked_example', '{"title":"Solve $3x^2 = 12x$","steps":[{"latex":"3x^2 - 12x = 0","explanation":"Don''t divide by x: you would lose the solution x = 0."},{"latex":"3x(x - 4) = 0","explanation":""},{"latex":"x = 0 \\text{ or } x = 4","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_02600154b5b7fc', 'les_0f1e3ab9b95540', 'learn', 5, 'worked_example', '{"title":"Solve $2x^2 - 5x - 3 = 0","steps":[{"latex":"(2x + 1)(x - 3) = 0","explanation":"ac method: −6 = −6 · 1, and −6 + 1 = −5."},{"latex":"x = -\\tfrac{1}{2} \\text{ or } x = 3","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_219487ba30598c', 'les_0f1e3ab9b95540', 'experiment', 6, 'activity', '{"activity":"vertex-explorer","title":"Solutions are x-intercepts","params":{"a":1,"h":-1,"k":-4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8b6a8db9fbaa1d', 'les_0f1e3ab9b95540', 'experiment', 7, 'callout', '{"tone":"tip","title":"Try this","body":"This parabola is $y = (x + 1)^2 - 4 = x^2 + 2x - 3 = (x + 3)(x - 1)$. Its zeros are where $x^2 + 2x - 3 = 0$. Do the readouts agree? Move the vertex until there''s only one zero: what does the factored form look like then?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_44d202518f5010', 'les_0f1e3ab9b95540', 'learn', 8, 'callout', '{"tone":"warning","title":"Zero on one side first","body":"From $x(x - 2) = 8$, concluding $x = 8$ or $x - 2 = 8$ is wrong. Expand and rearrange: $x^2 - 2x - 8 = 0$, so $(x - 4)(x + 2) = 0$ and $x = 4$ or $x = -2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ce3192ec86b632', 'les_0f1e3ab9b95540', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"A rectangle''s length is 3 cm more than its width and its area is 40 cm²: $w(w + 3) = 40$ gives $(w + 8)(w - 5) = 0$. Only $w = 5$ makes sense, because a width can''t be negative."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_287181b48983a0', 'les_0f1e3ab9b95540', 1, 'practice', 'short_text', 1, 'Solve $(x - 7)(x + 2) = 0$. Enter both solutions, smaller first.', '{"accept":["-2,7"]}', '["Set each factor to zero."]', '$x = 7$ or $x = -2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e4e8588fe3b9df', 'les_0f1e3ab9b95540', 2, 'practice', 'short_text', 2, 'Solve $x^2 - 9x + 20 = 0$. Enter both solutions, smaller first.', '{"accept":["4,5"]}', '["Factor: product 20, sum −9."]', '$(x - 4)(x - 5) = 0$, so $x = 4$ or $x = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_997ea0ab9cc397', 'les_0f1e3ab9b95540', 3, 'practice', 'short_text', 2, 'Solve $x^2 = 7x$. Enter both solutions, smaller first.', '{"accept":["0,7"]}', '["Move 7x to the left and factor out x."]', '$x(x - 7) = 0$: $x = 0$ or $x = 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fb7a70832ca3cd', 'les_0f1e3ab9b95540', 4, 'practice', 'short_text', 2, 'Solve $x^2 - 49 = 0$. Enter both solutions, smaller first.', '{"accept":["-7,7"]}', '["Difference of squares."]', '$(x + 7)(x - 7) = 0$: $x = \pm 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_02600154b5b7fc', 'les_0f1e3ab9b95540', 5, 'practice', 'short_text', 3, 'Solve $3x^2 + 10x - 8 = 0$. Enter both solutions, smaller first, as integers or fractions.', '{"accept":["-4,2/3"]}', '["ac = −24, b = 10: use 12 and −2.","$(3x - 2)(x + 4) = 0$."]', '$x = \frac{2}{3}$ or $x = -4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_219487ba30598c', 'les_0f1e3ab9b95540', 6, 'practice', 'multiple_choice', 2, 'A student solved $x(x + 1) = 6$ by writing $x = 6$ or $x + 1 = 6$. What''s wrong?', '{"choices":["Nothing","The zero-product property needs 0 on one side","They should divide by x","They should take square roots"],"answer":1}', '["What does the zero-product property require?"]', 'Rewrite as $x^2 + x - 6 = 0$, so $(x + 3)(x - 2) = 0$ and $x = -3$ or $x = 2$. Neither $x = 6$ nor $x = 5$ works.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8b6a8db9fbaa1d', 'les_0f1e3ab9b95540', 7, 'review', 'short_text', 3, 'The product of two consecutive positive integers is 132. What is the smaller integer?', '{"accept":["11"]}', '["$n(n + 1) = 132$.","$n^2 + n - 132 = 0$."]', '$(n + 12)(n - 11) = 0$; the positive solution is $n = 11$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7b162503938c0f', 'subj_math', 'zero-product-property', 'Zero-product property', 'If ab = 0, then a = 0 or b = 0.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0f1e3ab9b95540', (SELECT id FROM concepts WHERE slug = 'zero-product-property'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_5694f8f8fb67bd', 'subj_math', 'factoring', 'Factoring', 'Writing a polynomial as a product of simpler polynomials.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0f1e3ab9b95540', (SELECT id FROM concepts WHERE slug = 'factoring'));

-- Lesson: solving-quadratics-square-roots
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7433872e8fc6a4', 'solving-quadratics-square-roots', 'Solving quadratic equations with square roots', 'Solve equations of the form a(x − h)² = k by isolating the square and taking both square roots, and decide how many real solutions exist.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2bcacd95f5fc25', 'les_7433872e8fc6a4', 1, 'Solve x² = k and (x − h)² = k, including both the positive and negative roots.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_93a9dd73728839', 'les_7433872e8fc6a4', 2, 'Simplify square-root answers and give decimal approximations.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_58f9454cbdf2d4', 'les_7433872e8fc6a4', 3, 'Determine the number of real solutions from the sign of k.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2bcacd95f5fc25', 'les_7433872e8fc6a4', 'learn', 1, 'text', '{"body":"When a quadratic has no $x$-term, or the variable appears only inside one squared expression, you don''t need to factor. Isolate the square, then undo it with a square root. Since both $5^2$ and $(-5)^2$ equal 25, $x^2 = 25$ has two solutions: $x = \\pm 5$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_93a9dd73728839', 'les_7433872e8fc6a4', 'learn', 2, 'worked_example', '{"title":"Solve $3x^2 - 7 = 41$","steps":[{"latex":"3x^2 = 48 \\Rightarrow x^2 = 16","explanation":"Isolate x²."},{"latex":"x = \\pm 4","explanation":"Take both square roots."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_58f9454cbdf2d4', 'les_7433872e8fc6a4', 'learn', 3, 'worked_example', '{"title":"Solve $(x - 2)^2 = 18$","steps":[{"latex":"x - 2 = \\pm\\sqrt{18} = \\pm 3\\sqrt{2}","explanation":"$\\sqrt{18} = \\sqrt{9 \\cdot 2} = 3\\sqrt{2}$."},{"latex":"x = 2 \\pm 3\\sqrt{2}","explanation":"Add 2."},{"latex":"x \\approx 6.24 \\text{ or } x \\approx -2.24","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_632fc9654fc09a', 'les_7433872e8fc6a4', 'learn', 4, 'worked_example', '{"title":"Solve $2(x + 1)^2 + 10 = 4$","steps":[{"latex":"2(x + 1)^2 = -6 \\Rightarrow (x + 1)^2 = -3","explanation":""},{"latex":"\\text{No real solution}","explanation":"A square of a real number can''t be negative."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ba857c2235a566', 'les_7433872e8fc6a4', 'learn', 5, 'callout', '{"tone":"tip","title":"How many solutions?","body":"After isolating, $(\\ldots)^2 = k$ has two real solutions if $k > 0$, one if $k = 0$, and none if $k < 0$. Graphically: the parabola $y = (x - h)^2$ meets the line $y = k$ twice, once or not at all."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0fd97917f175ef', 'les_7433872e8fc6a4', 'learn', 6, 'callout', '{"tone":"warning","title":"Don''t forget ±","body":"Writing only $x = 4$ for $x^2 = 16$ loses the solution $x = -4$. The symbol $\\sqrt{16}$ means only 4, so you add the $\\pm$ yourself when solving."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f53251310a3826', 'les_7433872e8fc6a4', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"A rock dropped from 64 ft has height $h = 64 - 16t^2$. It lands when $16t^2 = 64$, so $t^2 = 4$ and $t = 2$ s (the negative root makes no sense for time). The area of a square, $A = s^2$, also gives $s = \\sqrt{A}$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2bcacd95f5fc25', 'les_7433872e8fc6a4', 1, 'practice', 'short_text', 1, 'Solve $x^2 = 81$. Enter both solutions, smaller first.', '{"accept":["-9,9"]}', '["Two numbers square to 81."]', '$x = \pm 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_93a9dd73728839', 'les_7433872e8fc6a4', 2, 'practice', 'short_text', 2, 'Solve $4x^2 - 100 = 0$. Enter both solutions, smaller first.', '{"accept":["-5,5"]}', '["$x^2 = 25$."]', '$x = \pm 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_58f9454cbdf2d4', 'les_7433872e8fc6a4', 3, 'practice', 'short_text', 2, 'Solve $(x + 3)^2 = 49$. Enter both solutions, smaller first.', '{"accept":["-10,4"]}', '["$x + 3 = \\pm 7$."]', '$x = 4$ or $x = -10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_632fc9654fc09a', 'les_7433872e8fc6a4', 4, 'practice', 'numeric', 2, 'Solve $(x - 5)^2 = 12$ and give the larger solution to two decimal places.', '{"answer":8.46,"tolerance":0.006}', '["$x = 5 \\pm 2\\sqrt{3}$."]', '$5 + 2\sqrt{3} \approx 5 + 3.464 = 8.46$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ba857c2235a566', 'les_7433872e8fc6a4', 5, 'practice', 'multiple_choice', 2, 'How many real solutions does $5(x - 1)^2 + 20 = 0$ have?', '{"choices":["0","1","2","Infinitely many"],"answer":0}', '["Isolate: $(x - 1)^2 = -4$."]', 'A square can''t equal $-4$, so there are no real solutions.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0fd97917f175ef', 'les_7433872e8fc6a4', 6, 'practice', 'multiple_choice', 2, 'How many real solutions does $(2x - 6)^2 = 0$ have?', '{"choices":["0","1","2","4"],"answer":1}', '["Only 0 squares to 0."]', '$2x - 6 = 0$ gives the single solution $x = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f53251310a3826', 'les_7433872e8fc6a4', 7, 'review', 'numeric', 3, 'A square garden has area 200 m². To the nearest tenth of a meter, how long is each side?', '{"answer":14.1,"unit":"m","tolerance":0.05}', '["$s^2 = 200$, and $s$ must be positive."]', '$s = \sqrt{200} = 10\sqrt{2} \approx 14.1$ m.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_283755837f95ab', 'subj_math', 'square-roots', 'Square roots', 'A number that, multiplied by itself, gives a given number.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7433872e8fc6a4', (SELECT id FROM concepts WHERE slug = 'square-roots'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_21fa51d21dc50e', 'subj_math', 'quadratic-functions', 'Quadratic functions', 'Functions of the form f(x) = ax² + bx + c with a ≠ 0, whose graphs are parabolas.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7433872e8fc6a4', (SELECT id FROM concepts WHERE slug = 'quadratic-functions'));

-- Lesson: solving-simple-inequalities
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_2f59d0e0c8ccce', 'solving-simple-inequalities', 'Solving one-step and two-step inequalities', 'Solve inequalities with inverse operations, reverse the symbol when multiplying or dividing by a negative, and graph the solution set.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_985049f1acab49', 'les_2f59d0e0c8ccce', 1, 'Solve one- and two-step inequalities using inverse operations.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c7e46810042c3f', 'les_2f59d0e0c8ccce', 2, 'Explain why multiplying or dividing both sides by a negative number reverses the inequality.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_14e0271ca4d07a', 'les_2f59d0e0c8ccce', 3, 'Graph solution sets and interpret them in context, including whole-number answers.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_985049f1acab49', 'les_2f59d0e0c8ccce', 'learn', 1, 'text', '{"body":"Solving an inequality works almost exactly like solving an equation. You can add or subtract the same number on both sides, and you can multiply or divide both sides by the same positive number, and the inequality stays true."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c7e46810042c3f', 'les_2f59d0e0c8ccce', 'learn', 2, 'definition', '{"term":"The one difference","body":"When you multiply or divide both sides by a negative number, reverse the inequality symbol: $<$ becomes $>$, and $\\le$ becomes $\\ge$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_14e0271ca4d07a', 'les_2f59d0e0c8ccce', 'learn', 3, 'text', '{"body":"Why? Start with a true statement, $2 < 5$. Multiply both sides by $-1$: you get $-2$ and $-5$. On the number line, $-2$ is to the right of $-5$, so $-2 > -5$. Multiplying by a negative reflects numbers across 0, which reverses their order."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e401c136898f9', 'les_2f59d0e0c8ccce', 'learn', 4, 'worked_example', '{"title":"Solve $x - 8 \\ge -3$","steps":[{"latex":"x \\ge -3 + 8","explanation":"Add 8 to both sides."},{"latex":"x \\ge 5","explanation":"Closed circle at 5, shade right."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cc86dd74f90b5e', 'les_2f59d0e0c8ccce', 'learn', 5, 'worked_example', '{"title":"Solve $-4x < 20$","steps":[{"latex":"\\frac{-4x}{-4} > \\frac{20}{-4}","explanation":"Divide by −4 and reverse the symbol."},{"latex":"x > -5","explanation":""}],"check":"Check with a value that should work, $x = 0$: $-4(0) = 0 < 20$. ✓ Check one that shouldn''t, $x = -6$: $24 < 20$ is false. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4bf7648cce0f95', 'les_2f59d0e0c8ccce', 'learn', 6, 'worked_example', '{"title":"Solve $7 - \\tfrac{x}{3} \\le 9$","steps":[{"latex":"-\\tfrac{x}{3} \\le 2","explanation":"Subtract 7 from both sides."},{"latex":"x \\ge -6","explanation":"Multiply by −3 and reverse the symbol."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7d4b2b352d609f', 'les_2f59d0e0c8ccce', 'experiment', 7, 'activity', '{"activity":"inequality-line","title":"Graph the solution x ≥ −6","params":{"rel":"≥","c":-6,"mode":"single"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4795faae90d926', 'les_2f59d0e0c8ccce', 'experiment', 8, 'callout', '{"tone":"tip","title":"Try this","body":"Move the test value to $-6$, then to $-7$, and substitute each into $7 - \\frac{x}{3} \\le 9$ yourself. Do your answers match the ✓ and ✗ marks?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4fd78a4a5806de', 'les_2f59d0e0c8ccce', 'learn', 9, 'worked_example', '{"title":"A phone plan costs 25 dollars plus 3 dollars per gigabyte. How many whole gigabytes can you use and keep the bill at most 50 dollars?","steps":[{"latex":"25 + 3g \\le 50","explanation":"Write the inequality."},{"latex":"3g \\le 25 \\Rightarrow g \\le 8.\\overline{3}","explanation":""},{"latex":"g \\le 8","explanation":"Only whole gigabytes are billed, so the most is 8."}],"check":"Check: $25 + 3(8) = 49 \\le 50$ but $25 + 3(9) = 52 > 50$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9e072477fe04da', 'les_2f59d0e0c8ccce', 'learn', 10, 'callout', '{"tone":"warning","title":"Reverse only for negative multipliers","body":"In $-3 + x > 4$ the $-3$ is added, not multiplied, so no reversal: $x > 7$. And in $2x > -10$ you divide by positive 2, so $x > -5$, even though $-10$ is negative."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_820616be2f9718', 'les_2f59d0e0c8ccce', 'learn', 11, 'callout', '{"tone":"application","title":"Where this shows up","body":"Budgets (\"spend no more than\"), grades (\"what score do I need on the final?\") and safety limits are naturally inequalities."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_985049f1acab49', 'les_2f59d0e0c8ccce', 1, 'practice', 'short_text', 1, 'Solve $x + 6 < 2$. Write the answer like x<…', '{"accept":["x<-4"]}', '["Subtract 6 from both sides."]', '$x < -4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c7e46810042c3f', 'les_2f59d0e0c8ccce', 2, 'practice', 'short_text', 1, 'Solve $5x \ge 35$.', '{"accept":["x>=7","x≥7"]}', '["Divide by a positive 5; no reversal."]', '$x \ge 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_14e0271ca4d07a', 'les_2f59d0e0c8ccce', 3, 'practice', 'short_text', 2, 'Solve $-3x > 12$.', '{"accept":["x<-4"]}', '["Divide by −3 and reverse the symbol."]', '$x < -4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6e401c136898f9', 'les_2f59d0e0c8ccce', 4, 'practice', 'short_text', 2, 'Solve $\frac{x}{-2} \le 5$.', '{"accept":["x>=-10","x≥-10"]}', '["Multiply by −2 and reverse."]', '$x \ge -10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cc86dd74f90b5e', 'les_2f59d0e0c8ccce', 5, 'practice', 'short_text', 2, 'Solve $4x - 9 > 11$.', '{"accept":["x>5"]}', '["Add 9, then divide by 4."]', '$4x > 20$, so $x > 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4bf7648cce0f95', 'les_2f59d0e0c8ccce', 6, 'practice', 'short_text', 2, 'Solve $10 - 2x \ge 16$.', '{"accept":["x<=-3","x≤-3"]}', '["Subtract 10: −2x ≥ 6.","Divide by −2 and reverse."]', '$-2x \ge 6$, so $x \le -3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7d4b2b352d609f', 'les_2f59d0e0c8ccce', 7, 'practice', 'multiple_choice', 3, 'Sam has 40 dollars and wants to buy a 12-dollar shirt and some 7-dollar books. What is the greatest number of books he can buy?', '{"choices":["3","4","5","6"],"answer":1}', '["$12 + 7b \\le 40$."]', '$7b \le 28$, so $b \le 4$. He can buy at most 4 books.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4795faae90d926', 'les_2f59d0e0c8ccce', 8, 'review', 'multiple_choice', 3, 'Which graph matches the solution of $-5x + 1 < 16$?', '{"choices":["Open circle at −3, shading right","Open circle at −3, shading left","Closed circle at −3, shading right","Open circle at 3, shading left"],"answer":0}', '["Subtract 1, then divide by −5 and reverse."]', '$-5x < 15$ gives $x > -3$: an open circle at $-3$ with shading to the right.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_b43909c23e4964', 'subj_math', 'solving-inequalities', 'Solving inequalities', 'Finding all values that make an inequality true.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_2f59d0e0c8ccce', (SELECT id FROM concepts WHERE slug = 'solving-inequalities'));

-- Lesson: special-products-factoring
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_640dd98a938edc', 'special-products-factoring', 'Special products and factoring patterns', 'Recognize and use perfect-square trinomials and the difference of two squares, both for multiplying quickly and for factoring.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f4a20c8b890c90', 'les_640dd98a938edc', 1, 'Expand (a + b)², (a − b)² and (a + b)(a − b) using the patterns.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3206b24f59c350', 'les_640dd98a938edc', 2, 'Recognize perfect-square trinomials and differences of squares.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_be6d5b6dad671b', 'les_640dd98a938edc', 3, 'Factor completely using these patterns together with the GCF.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f4a20c8b890c90', 'les_640dd98a938edc', 'learn', 1, 'definition', '{"term":"Square of a binomial","body":"$(a + b)^2 = a^2 + 2ab + b^2$ and $(a - b)^2 = a^2 - 2ab + b^2$. The middle term is twice the product of the two terms."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3206b24f59c350', 'les_640dd98a938edc', 'learn', 2, 'definition', '{"term":"Difference of two squares","body":"$(a + b)(a - b) = a^2 - b^2$. The middle terms $+ab$ and $-ab$ cancel."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_be6d5b6dad671b', 'les_640dd98a938edc', 'experiment', 3, 'activity', '{"activity":"area-model","title":"See the perfect square","params":{"a":1,"b":3,"c":1,"d":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c0a5e8ebae80e7', 'les_640dd98a938edc', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"With $(x + 3)(x + 3)$, the model is a square with two identical $3x$ rectangles: that''s where $2ab$ comes from. Change $d$ to $-3$. The middle cells become $3x$ and $-3x$ and cancel, leaving $x^2 - 9$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_72bc8da34ee7a8', 'les_640dd98a938edc', 'learn', 5, 'callout', '{"tone":"warning","title":"The classic mistake","body":"$(x + 5)^2 \\ne x^2 + 25$. It is $x^2 + 10x + 25$. Check with $x = 1$: $36$, not $26$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e5da664232fc2b', 'les_640dd98a938edc', 'learn', 6, 'worked_example', '{"title":"Expand $(3x - 4)^2$ and $(2y + 7)(2y - 7)$","steps":[{"latex":"(3x)^2 - 2(3x)(4) + 4^2 = 9x^2 - 24x + 16","explanation":"a = 3x, b = 4."},{"latex":"(2y)^2 - 7^2 = 4y^2 - 49","explanation":"Difference of squares."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_342b185c945a3d', 'les_640dd98a938edc', 'learn', 7, 'text', '{"body":"To factor with these patterns, check whether the first and last terms are perfect squares. A trinomial $a^2 \\pm 2ab + b^2$ is a perfect square if its middle term is exactly twice the product of the square roots. A binomial $a^2 - b^2$ is a difference of squares. A sum of squares like $x^2 + 9$ does not factor over the real numbers."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bdf2351dff2634', 'les_640dd98a938edc', 'learn', 8, 'worked_example', '{"title":"Factor $x^2 - 14x + 49$","steps":[{"latex":"x^2 = (x)^2,\\ 49 = 7^2","explanation":"First and last are squares."},{"latex":"2 \\cdot x \\cdot 7 = 14x","explanation":"The middle term matches."},{"latex":"(x - 7)^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_02f2904e54ac6b', 'les_640dd98a938edc', 'learn', 9, 'worked_example', '{"title":"Factor $3x^3 - 75x$ completely","steps":[{"latex":"3x(x^2 - 25)","explanation":"GCF first."},{"latex":"3x(x + 5)(x - 5)","explanation":"Difference of squares."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2743df44a956be', 'les_640dd98a938edc', 'learn', 10, 'worked_example', '{"title":"Factor $16a^4 - 81$","steps":[{"latex":"(4a^2 + 9)(4a^2 - 9)","explanation":"16a⁴ = (4a²)² and 81 = 9²."},{"latex":"(4a^2 + 9)(2a + 3)(2a - 3)","explanation":"4a² − 9 is again a difference of squares; 4a² + 9 is not factorable."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a26d08c8ccafb9', 'les_640dd98a938edc', 'learn', 11, 'callout', '{"tone":"application","title":"Mental math","body":"$47 \\times 53 = (50 - 3)(50 + 3) = 2500 - 9 = 2491$, and $99^2 = (100 - 1)^2 = 10{,}000 - 200 + 1 = 9801$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f4a20c8b890c90', 'les_640dd98a938edc', 1, 'practice', 'short_text', 1, 'Expand $(x + 6)^2$.', '{"accept":["x^2+12x+36"]}', '["Middle term: 2 · x · 6."]', '$x^2 + 12x + 36$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3206b24f59c350', 'les_640dd98a938edc', 2, 'practice', 'short_text', 1, 'Expand $(a - 9)(a + 9)$.', '{"accept":["a^2-81"]}', '["Difference of squares."]', '$a^2 - 81$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_be6d5b6dad671b', 'les_640dd98a938edc', 3, 'practice', 'short_text', 2, 'Expand $(5y - 2)^2$.', '{"accept":["25y^2-20y+4"]}', '["$(5y)^2 - 2(5y)(2) + 2^2$."]', '$25y^2 - 20y + 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c0a5e8ebae80e7', 'les_640dd98a938edc', 4, 'practice', 'short_text', 2, 'Factor $x^2 - 64$.', '{"accept":["(x+8)(x-8)","(x-8)(x+8)"]}', '["64 = 8²."]', '$(x + 8)(x - 8)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_72bc8da34ee7a8', 'les_640dd98a938edc', 5, 'practice', 'short_text', 2, 'Factor $x^2 + 10x + 25$.', '{"accept":["(x+5)^2","(x+5)(x+5)"]}', '["25 = 5², and 2 · 5 = 10."]', '$(x + 5)^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e5da664232fc2b', 'les_640dd98a938edc', 6, 'practice', 'multiple_choice', 2, 'Which polynomial is a perfect-square trinomial?', '{"choices":["$x^2 + 6x + 36$","$4x^2 - 12x + 9$","$x^2 - 8x - 16$","$9x^2 + 6x + 4$"],"answer":1}', '["Check whether the middle term is 2ab."]', '$4x^2 - 12x + 9 = (2x - 3)^2$ since $2(2x)(3) = 12x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_342b185c945a3d', 'les_640dd98a938edc', 7, 'review', 'short_text', 3, 'Factor completely: $2x^3 - 32x$.', '{"accept":["2x(x+4)(x-4)","2x(x-4)(x+4)"]}', '["GCF 2x first.","Then x² − 16."]', '$2x(x^2 - 16) = 2x(x + 4)(x - 4)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bdf2351dff2634', 'les_640dd98a938edc', 8, 'review', 'short_text', 3, 'Compute $102 \times 98$ using a special product. Enter the product.', '{"accept":["9996"]}', '["$(100 + 2)(100 - 2)$."]', '$10{,}000 - 4 = 9996$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_eb1b014f707879', 'subj_math', 'special-products', 'Special products', 'Perfect-square trinomials and the difference of two squares.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_640dd98a938edc', (SELECT id FROM concepts WHERE slug = 'special-products'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_5694f8f8fb67bd', 'subj_math', 'factoring', 'Factoring', 'Writing a polynomial as a product of simpler polynomials.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_640dd98a938edc', (SELECT id FROM concepts WHERE slug = 'factoring'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_640dd98a938edc', (SELECT id FROM formulas WHERE slug = 'special-products'), 1);

-- Lesson: standard-form-line
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a12c6f30803d0d', 'standard-form-line', 'Standard form of a linear equation', 'Write lines in standard form Ax + By = C, graph them quickly with intercepts, convert between forms, and recognize horizontal and vertical lines.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_065d58131090f8', 'les_a12c6f30803d0d', 1, 'Write a linear equation in standard form with integer coefficients.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_adaa85848e19be', 'les_a12c6f30803d0d', 2, 'Find the x- and y-intercepts from standard form and use them to graph.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_08d6bf44cf0d95', 'les_a12c6f30803d0d', 3, 'Convert between standard and slope-intercept forms and handle horizontal and vertical lines.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_065d58131090f8', 'les_a12c6f30803d0d', 'learn', 1, 'formula', '{"latex":"Ax + By = C","title":"Standard form","note":"A, B and C are usually integers with A ≥ 0, and A and B are not both 0."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_adaa85848e19be', 'les_a12c6f30803d0d', 'learn', 2, 'text', '{"body":"Standard form is natural when two quantities share a total. If adult tickets cost 8 dollars, child tickets cost 5 dollars and a family spends 40 dollars, then $8a + 5c = 40$. It is also the only form that can describe a vertical line, such as $x = 3$ (here $A = 1$, $B = 0$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_08d6bf44cf0d95', 'les_a12c6f30803d0d', 'learn', 3, 'definition', '{"term":"Intercept method","body":"To graph $Ax + By = C$, set $y = 0$ to find the $x$-intercept and set $x = 0$ to find the $y$-intercept. Plot both and draw the line through them."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c059c0ebf8445d', 'les_a12c6f30803d0d', 'learn', 4, 'worked_example', '{"title":"Graph $3x - 4y = 12$ using intercepts","steps":[{"latex":"y = 0: 3x = 12 \\Rightarrow x = 4","explanation":"x-intercept (4, 0)."},{"latex":"x = 0: -4y = 12 \\Rightarrow y = -3","explanation":"y-intercept (0, −3)."},{"latex":"m = \\frac{-3 - 0}{0 - 4} = \\tfrac{3}{4}","explanation":"The slope is −A/B = −3/(−4) = 3/4."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a19df2ce4bb397', 'les_a12c6f30803d0d', 'learn', 5, 'worked_example', '{"title":"Write $y = -\\tfrac{2}{3}x + 5$ in standard form","steps":[{"latex":"3y = -2x + 15","explanation":"Multiply every term by 3 to clear the fraction."},{"latex":"2x + 3y = 15","explanation":"Add 2x to both sides. A = 2 is positive."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f1ffc9d5978e18', 'les_a12c6f30803d0d', 'learn', 6, 'worked_example', '{"title":"Write $4x + 2y = 10$ in slope-intercept form","steps":[{"latex":"2y = -4x + 10","explanation":"Subtract 4x."},{"latex":"y = -2x + 5","explanation":"Divide every term by 2."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_92ab3c2c2160e1', 'les_a12c6f30803d0d', 'learn', 7, 'definition', '{"term":"Horizontal and vertical lines","body":"$y = k$ is horizontal with slope 0. $x = h$ is vertical and its slope is undefined. A vertical line is not a function of $x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_17d443d5b73422', 'les_a12c6f30803d0d', 'learn', 8, 'callout', '{"tone":"warning","title":"Slope from standard form","body":"The slope of $Ax + By = C$ is $-\\frac{A}{B}$, not $\\frac{A}{B}$ and not $A$. Rewriting in slope-intercept form is the safest way to check."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_97ffca113d75e1', 'les_a12c6f30803d0d', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Budget lines: with 60 dollars to spend on 4-dollar notebooks ($n$) and 6-dollar binders ($b$), every affordable full-budget combination satisfies $4n + 6b = 60$. Its intercepts show the most of each item you could buy alone: 15 notebooks or 10 binders."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_065d58131090f8', 'les_a12c6f30803d0d', 1, 'practice', 'numeric', 1, 'What is the x-intercept of $5x + 2y = 20$?', '{"answer":4}', '["Set y = 0."]', '$5x = 20$, $x = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_adaa85848e19be', 'les_a12c6f30803d0d', 2, 'practice', 'numeric', 1, 'What is the y-intercept of $5x + 2y = 20$?', '{"answer":10}', '["Set x = 0."]', '$2y = 20$, $y = 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_08d6bf44cf0d95', 'les_a12c6f30803d0d', 3, 'practice', 'numeric', 2, 'What is the slope of $6x - 3y = 9$?', '{"answer":2}', '["Solve for y: $-3y = -6x + 9$."]', '$y = 2x - 3$, so the slope is 2. (Also $-\frac{A}{B} = -\frac{6}{-3} = 2$.)');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c059c0ebf8445d', 'les_a12c6f30803d0d', 4, 'practice', 'short_text', 2, 'Write $y = \tfrac{3}{4}x - 2$ in standard form with integer coefficients and A > 0.', '{"accept":["3x-4y=8"]}', '["Multiply every term by 4.","Move the x-term to the left side."]', '$4y = 3x - 8$, so $3x - 4y = 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a19df2ce4bb397', 'les_a12c6f30803d0d', 5, 'practice', 'multiple_choice', 2, 'Which equation describes a vertical line through $(-2, 5)$?', '{"choices":["$y = 5$","$x = -2$","$y = -2$","$x = 5$"],"answer":1}', '["On a vertical line every point has the same x-coordinate."]', '$x = -2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f1ffc9d5978e18', 'les_a12c6f30803d0d', 6, 'practice', 'multiple_choice', 2, 'What is the slope of $y = -7$?', '{"choices":["−7","0","Undefined","1"],"answer":1}', '["It''s a horizontal line."]', 'A horizontal line has slope 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_92ab3c2c2160e1', 'les_a12c6f30803d0d', 7, 'review', 'numeric', 3, 'Adult tickets cost 9 dollars and student tickets cost 6 dollars. A group spent 120 dollars and bought 8 adult tickets. How many student tickets did it buy?', '{"answer":8}', '["$9a + 6s = 120$ with $a = 8$."]', '$72 + 6s = 120$, so $6s = 48$ and $s = 8$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_dba3aab7e8b9cb', 'subj_math', 'standard-form', 'Standard form of a line', 'Ax + By = C with A and B not both zero.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a12c6f30803d0d', (SELECT id FROM concepts WHERE slug = 'standard-form'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a12c6f30803d0d', (SELECT id FROM formulas WHERE slug = 'standard-form-line'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a12c6f30803d0d', (SELECT id FROM formulas WHERE slug = 'slope-intercept-form'), 2);

-- Lesson: systems-by-elimination
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5b582c60e29fbe', 'systems-by-elimination', 'Solving systems by elimination', 'Add or subtract equations, after scaling if needed, to eliminate a variable, and choose between substitution and elimination.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7e94c5763ae58d', 'les_5b582c60e29fbe', 1, 'Explain why adding equations produces an equation that the solution still satisfies.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b8ec7aa358353c', 'les_5b582c60e29fbe', 2, 'Solve systems by elimination, multiplying one or both equations to create opposite coefficients.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3ed2c4ba6ca687', 'les_5b582c60e29fbe', 3, 'Choose an efficient method for a given system.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7e94c5763ae58d', 'les_5b582c60e29fbe', 'learn', 1, 'text', '{"body":"If $A = B$ and $C = D$, then $A + C = B + D$: adding equal amounts to equal amounts keeps things equal. So you can add two equations of a system, and the solution still satisfies the result. If a variable has opposite coefficients, it cancels."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b8ec7aa358353c', 'les_5b582c60e29fbe', 'learn', 2, 'worked_example', '{"title":"Solve $3x + 2y = 11$ and $5x - 2y = 13$","steps":[{"latex":"8x = 24","explanation":"Add the equations: +2y and −2y cancel."},{"latex":"x = 3","explanation":""},{"latex":"3(3) + 2y = 11 \\Rightarrow y = 1","explanation":"Substitute back."}],"check":"Check: $5(3) - 2(1) = 13$ ✓."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3ed2c4ba6ca687', 'les_5b582c60e29fbe', 'learn', 3, 'worked_example', '{"title":"Solve $2x + 5y = 1$ and $3x - 2y = 11$","steps":[{"latex":"4x + 10y = 2","explanation":"Multiply the first equation by 2."},{"latex":"15x - 10y = 55","explanation":"Multiply the second by 5. Now the y-terms are opposites."},{"latex":"19x = 57 \\Rightarrow x = 3","explanation":"Add."},{"latex":"2(3) + 5y = 1 \\Rightarrow y = -1","explanation":"Solution: (3, −1)."}],"check":"Check: $3(3) - 2(-1) = 11$ ✓."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1e7b6e2a0baaaa', 'les_5b582c60e29fbe', 'learn', 4, 'callout', '{"tone":"tip","title":"Which method?","body":"Use substitution when a variable is already isolated or has coefficient 1. Use elimination when both equations are in standard form, especially when coefficients already match or are easy to make opposite."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b46512a506dff4', 'les_5b582c60e29fbe', 'learn', 5, 'worked_example', '{"title":"Solve $4x - 6y = 10$ and $-2x + 3y = 7$","steps":[{"latex":"4x - 6y = 10,\\quad -4x + 6y = 14","explanation":"Multiply the second by 2."},{"latex":"0 = 24","explanation":"Both variables cancel and the statement is false."},{"latex":"\\text{No solution}","explanation":"The lines are parallel."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_80e025999a0eb1', 'les_5b582c60e29fbe', 'learn', 6, 'callout', '{"tone":"warning","title":"Multiply every term","body":"When scaling an equation, multiply both sides completely, including the constant: $2(3x - 2y = 11)$ is $6x - 4y = 22$. Forgetting the 11 is a common slip."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_09c0afbae20264', 'les_5b582c60e29fbe', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"A chemistry lab mixes a 10% acid solution with a 40% solution to make 30 L of a 20% solution: $x + y = 30$ and $0.10x + 0.40y = 6$. Multiplying the first by $-0.10$ and adding gives $0.30y = 3$, so $y = 10$ L and $x = 20$ L."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7e94c5763ae58d', 'les_5b582c60e29fbe', 1, 'practice', 'short_text', 1, 'Solve $x + y = 9$ and $x - y = 1$. Enter as (x,y).', '{"accept":["(5,4)"]}', '["Add the equations."]', '$2x = 10$, $x = 5$, $y = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b8ec7aa358353c', 'les_5b582c60e29fbe', 2, 'practice', 'short_text', 2, 'Solve $2x + 3y = 12$ and $2x - y = 4$. Enter as (x,y).', '{"accept":["(3,2)"]}', '["Subtract the second equation from the first."]', '$4y = 8$, $y = 2$, then $2x = 6$, $x = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3ed2c4ba6ca687', 'les_5b582c60e29fbe', 3, 'practice', 'short_text', 2, 'Solve $3x - 2y = 4$ and $x + 4y = 20$. Enter as (x,y).', '{"accept":["(4,4)"]}', '["Multiply the first equation by 2.","$6x - 4y = 8$, then add."]', '$7x = 28$, $x = 4$, and $4 + 4y = 20$ gives $y = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1e7b6e2a0baaaa', 'les_5b582c60e29fbe', 4, 'practice', 'short_text', 3, 'Solve $5x + 2y = 3$ and $3x + 5y = -21$. Enter as (x,y).', '{"accept":["(3,-6)"]}', '["Multiply the first by 5 and the second by −2.","$25x + 10y = 15$ and $-6x - 10y = 42$."]', '$19x = 57$, $x = 3$; $15 + 2y = 3$, $y = -6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b46512a506dff4', 'les_5b582c60e29fbe', 5, 'practice', 'multiple_choice', 2, 'Adding two equations gives $0 = 0$. What does that tell you?', '{"choices":["The solution is (0, 0)","No solution","Infinitely many solutions","x = 0"],"answer":2}', '["Is 0 = 0 ever false?"]', 'A true statement with no variables means the equations describe the same line: infinitely many solutions.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_80e025999a0eb1', 'les_5b582c60e29fbe', 6, 'review', 'short_text', 3, 'Four pens and three notebooks cost 18 dollars. Two pens and five notebooks cost 23 dollars. How much is one notebook, in dollars?', '{"accept":["4"]}', '["$4p + 3n = 18$ and $2p + 5n = 23$.","Multiply the second by −2 and add."]', '$-7n = -28$, so $n = 4$ dollars (and $p = 1.50$ dollars).');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_892a66cf1a2bc1', 'subj_math', 'systems-of-equations', 'Systems of linear equations', 'Two or more equations solved together; solutions satisfy all of them.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5b582c60e29fbe', (SELECT id FROM concepts WHERE slug = 'systems-of-equations'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_fb3a4b96066b1d', 'subj_math', 'elimination', 'Elimination method', 'Combining equations so that one variable cancels.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5b582c60e29fbe', (SELECT id FROM concepts WHERE slug = 'elimination'));

-- Lesson: systems-by-graphing
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_648017dc8b0437', 'systems-by-graphing', 'Solving systems by graphing', 'Solve a system of two linear equations by graphing, check solutions algebraically, and recognize systems with no solution or infinitely many.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_34ecbfbc691373', 'les_648017dc8b0437', 1, 'Define a system of linear equations and its solution.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ab2efc3b24f84f', 'les_648017dc8b0437', 2, 'Solve a system by graphing and verify the intersection point in both equations.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8c9eb7b6322728', 'les_648017dc8b0437', 3, 'Classify systems as having one solution, no solution or infinitely many by comparing slopes and intercepts.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_34ecbfbc691373', 'les_648017dc8b0437', 'learn', 1, 'definition', '{"term":"System of linear equations","body":"Two or more linear equations in the same variables. A solution is an ordered pair that makes every equation true at the same time."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ab2efc3b24f84f', 'les_648017dc8b0437', 'learn', 2, 'text', '{"body":"Each equation''s graph is the set of all points that satisfy it. A point that satisfies both must lie on both lines, so the solution of the system is where the lines intersect."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8c9eb7b6322728', 'les_648017dc8b0437', 'experiment', 3, 'activity', '{"activity":"systems-graph","title":"Find the intersection","params":{"m1":1,"b1":1,"m2":-0.5,"b2":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_608934157ad2a7', 'les_648017dc8b0437', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"The system $y = x + 1$, $y = -\\frac{1}{2}x + 4$ meets at $(2, 3)$. Check that point in both equations by hand. Then make the slopes equal. What happens to the solution, and what if the intercepts are also equal?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f0f44e454917a4', 'les_648017dc8b0437', 'learn', 5, 'worked_example', '{"title":"Solve by graphing: $y = 2x - 3$ and $x + y = 3$","steps":[{"latex":"y = -x + 3","explanation":"Rewrite the second equation in slope-intercept form."},{"latex":"\\text{Graph both: they cross at } (2, 1)","explanation":"Line 1 from (0, −3) up 2, right 1; line 2 from (0, 3) down 1, right 1."},{"latex":"1 = 2(2) - 3 ✓ \\quad 2 + 1 = 3 ✓","explanation":"Always check the point in both original equations."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6f6f6a9bffb4ba', 'les_648017dc8b0437', 'learn', 6, 'definition', '{"term":"Number of solutions","body":"Different slopes: the lines cross once, so exactly one solution. Same slope, different intercepts: parallel lines, no solution (inconsistent). Same slope and same intercept: the same line, infinitely many solutions (dependent)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d55ba05504cc1d', 'les_648017dc8b0437', 'learn', 7, 'worked_example', '{"title":"Classify $2x - y = 4$ and $-6x + 3y = -12$","steps":[{"latex":"y = 2x - 4","explanation":"First equation."},{"latex":"3y = 6x - 12 \\Rightarrow y = 2x - 4","explanation":"Second equation: the same line."},{"latex":"\\text{Infinitely many solutions}","explanation":"Every point on y = 2x − 4 works."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fc3fd56ff05d25', 'les_648017dc8b0437', 'learn', 8, 'callout', '{"tone":"warning","title":"Graphs can mislead","body":"If the intersection is at a point like $(\\frac{7}{3}, -\\frac{1}{4})$, reading it from a graph only gives an estimate. Graphing is great for seeing the situation; substitution and elimination give exact answers."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_429831fa502cc5', 'les_648017dc8b0437', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Break-even analysis: a business''s cost line and revenue line cross where profit is zero. Comparing two phone plans graphically shows the usage at which they cost the same."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_34ecbfbc691373', 'les_648017dc8b0437', 1, 'practice', 'multiple_choice', 1, 'Which point is a solution of the system $y = x + 2$ and $y = 3x - 2$?', '{"choices":["$(1, 3)$","$(2, 4)$","$(0, 2)$","$(4, 6)$"],"answer":1}', '["Check each point in both equations."]', '$(2, 4)$: $2 + 2 = 4$ ✓ and $3(2) - 2 = 4$ ✓.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ab2efc3b24f84f', 'les_648017dc8b0437', 2, 'practice', 'short_text', 2, 'Solve by graphing (or check): $y = -x + 5$ and $y = x - 1$. Enter as (x,y).', '{"accept":["(3,2)"]}', '["Where are the y-values equal?"]', '$-x + 5 = x - 1$ gives $x = 3$ and $y = 2$: $(3, 2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8c9eb7b6322728', 'les_648017dc8b0437', 3, 'practice', 'multiple_choice', 2, 'How many solutions does $y = 3x + 1$, $y = 3x - 4$ have?', '{"choices":["One","None","Infinitely many","Two"],"answer":1}', '["Compare slopes and intercepts."]', 'Same slope, different intercepts: parallel lines, no solution.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_608934157ad2a7', 'les_648017dc8b0437', 4, 'practice', 'multiple_choice', 2, 'How many solutions does $x + 2y = 6$, $2x + 4y = 12$ have?', '{"choices":["One","None","Infinitely many","Two"],"answer":2}', '["Divide the second equation by 2."]', 'The second equation is the first multiplied by 2, so they describe the same line: infinitely many solutions.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f0f44e454917a4', 'les_648017dc8b0437', 5, 'practice', 'multiple_choice', 2, 'The lines in a system have slopes $\frac{1}{2}$ and $-2$. How many solutions does it have?', '{"choices":["One","None","Infinitely many","Cannot tell"],"answer":0}', '["Lines with different slopes always cross."]', 'Different slopes, so the lines intersect exactly once. (They are also perpendicular.)');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6f6f6a9bffb4ba', 'les_648017dc8b0437', 6, 'review', 'short_text', 3, 'Plan A: 40 dollars plus 5 dollars per class. Plan B: 10 dollars per class. After how many classes do they cost the same? Enter the number.', '{"accept":["8"]}', '["Solve $40 + 5c = 10c$."]', '$40 = 5c$, so $c = 8$ classes (both cost 80 dollars).');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_892a66cf1a2bc1', 'subj_math', 'systems-of-equations', 'Systems of linear equations', 'Two or more equations solved together; solutions satisfy all of them.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_648017dc8b0437', (SELECT id FROM concepts WHERE slug = 'systems-of-equations'));

-- Lesson: systems-by-substitution
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_87ce3ea0932664', 'systems-by-substitution', 'Solving systems by substitution', 'Solve systems exactly by solving one equation for a variable and substituting into the other, including systems with no solution or infinitely many.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_61f3aa08ac4ce7', 'les_87ce3ea0932664', 1, 'Solve a system by substitution and check the solution in both equations.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7f16226decaf7c', 'les_87ce3ea0932664', 2, 'Choose the variable that is easiest to isolate.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_706cefae2a65e4', 'les_87ce3ea0932664', 3, 'Recognize no-solution and infinitely-many-solution systems from the algebra.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_61f3aa08ac4ce7', 'les_87ce3ea0932664', 'learn', 1, 'text', '{"body":"Substitution turns two equations in two unknowns into one equation in one unknown. If one equation says $y = 2x + 1$, then wherever $y$ appears in the other equation you can write $2x + 1$ instead, because at the solution they are the same number."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7f16226decaf7c', 'les_87ce3ea0932664', 'learn', 2, 'worked_example', '{"title":"Solve $y = 2x + 1$ and $3x + 2y = 16$","steps":[{"latex":"3x + 2(2x + 1) = 16","explanation":"Substitute 2x + 1 for y. Keep the parentheses."},{"latex":"7x + 2 = 16 \\Rightarrow x = 2","explanation":"Solve for x."},{"latex":"y = 2(2) + 1 = 5","explanation":"Substitute back to find y."},{"latex":"(2, 5)","explanation":""}],"check":"Check: $3(2) + 2(5) = 16$ ✓ and $5 = 2(2) + 1$ ✓."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_706cefae2a65e4', 'les_87ce3ea0932664', 'learn', 3, 'callout', '{"tone":"tip","title":"Isolate a variable with coefficient 1 or −1","body":"In $x - 4y = 3$, solving for $x$ gives $x = 4y + 3$ with no fractions. Solving for $y$ would introduce fractions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2b049a4f61bbc2', 'les_87ce3ea0932664', 'learn', 4, 'worked_example', '{"title":"Solve $x - 4y = 3$ and $2x + 5y = -20$","steps":[{"latex":"x = 4y + 3","explanation":"Isolate x in the first equation."},{"latex":"2(4y + 3) + 5y = -20","explanation":"Substitute into the second."},{"latex":"13y + 6 = -20 \\Rightarrow y = -2","explanation":""},{"latex":"x = 4(-2) + 3 = -5","explanation":"Solution: (−5, −2)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_59ab77c2acba2e', 'les_87ce3ea0932664', 'learn', 5, 'worked_example', '{"title":"Solve $y = 3x - 2$ and $6x - 2y = 4$","steps":[{"latex":"6x - 2(3x - 2) = 4","explanation":""},{"latex":"6x - 6x + 4 = 4 \\Rightarrow 4 = 4","explanation":"The variable disappears and a true statement is left."},{"latex":"\\text{Infinitely many solutions}","explanation":"The equations describe the same line."}],"check":"If instead you got a false statement like $4 = 9$, there would be no solution (parallel lines)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fbb69c13a4c921', 'les_87ce3ea0932664', 'learn', 6, 'callout', '{"tone":"warning","title":"Finish the job","body":"After finding $x$, you still need $y$. A solution of a system is an ordered pair. Substitute into the simpler equation, then check both."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bd752ccd66dd26', 'les_87ce3ea0932664', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"A concert sold 500 tickets: adult tickets at 15 dollars and student tickets at 9 dollars, for 6,300 dollars in all. With $a + s = 500$ and $15a + 9s = 6300$, substituting $s = 500 - a$ gives $6a + 4500 = 6300$, so $a = 300$ and $s = 200$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_61f3aa08ac4ce7', 'les_87ce3ea0932664', 1, 'practice', 'short_text', 1, 'Solve $y = x + 3$ and $2x + y = 12$. Enter as (x,y).', '{"accept":["(3,6)"]}', '["Substitute x + 3 for y."]', '$2x + x + 3 = 12$, $x = 3$, $y = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7f16226decaf7c', 'les_87ce3ea0932664', 2, 'practice', 'short_text', 2, 'Solve $x = 2y - 1$ and $3x - 4y = 5$. Enter as (x,y).', '{"accept":["(7,4)"]}', '["$3(2y - 1) - 4y = 5$."]', '$2y - 3 = 5$, $y = 4$, $x = 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_706cefae2a65e4', 'les_87ce3ea0932664', 3, 'practice', 'short_text', 2, 'Solve $x + y = 10$ and $x - y = 4$. Enter as (x,y).', '{"accept":["(7,3)"]}', '["$x = 10 - y$."]', '$10 - 2y = 4$, $y = 3$, $x = 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2b049a4f61bbc2', 'les_87ce3ea0932664', 4, 'practice', 'multiple_choice', 2, 'Solving a system by substitution gives $-3 = 5$. What does this mean?', '{"choices":["x = −3","There is no solution","There are infinitely many solutions","You made an error"],"answer":1}', '["Can −3 ever equal 5?"]', 'A false statement means no ordered pair satisfies both equations: the lines are parallel.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_59ab77c2acba2e', 'les_87ce3ea0932664', 5, 'practice', 'short_text', 3, 'Solve $2x + 3y = 7$ and $x - 2y = 7$. Enter as (x,y).', '{"accept":["(5,-1)"]}', '["$x = 2y + 7$.","$2(2y + 7) + 3y = 7$."]', '$7y + 14 = 7$, $y = -1$, $x = 5$. Check: $10 - 3 = 7$ ✓ and $5 + 2 = 7$ ✓.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fbb69c13a4c921', 'les_87ce3ea0932664', 6, 'review', 'short_text', 3, 'The sum of two numbers is 42 and one is 6 more than twice the other. Find the larger number.', '{"accept":["30"]}', '["$x + y = 42$ and $y = 2x + 6$."]', '$x + 2x + 6 = 42$, $x = 12$, $y = 30$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_892a66cf1a2bc1', 'subj_math', 'systems-of-equations', 'Systems of linear equations', 'Two or more equations solved together; solutions satisfy all of them.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_87ce3ea0932664', (SELECT id FROM concepts WHERE slug = 'systems-of-equations'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a6288710b74b75', 'subj_math', 'substitution', 'Substitution', 'Replacing a variable with a value to evaluate an expression.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_87ce3ea0932664', (SELECT id FROM concepts WHERE slug = 'substitution'));

-- Lesson: systems-of-inequalities
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f8e941fe2abb69', 'systems-of-inequalities', 'Systems of linear inequalities', 'Graph linear inequalities in two variables as half-planes, find the solution region of a system, and use it to model constraints.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_da85de6bfe489e', 'les_f8e941fe2abb69', 1, 'Graph a linear inequality in two variables with a solid or dashed boundary and the correct shading.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_acf9c81a7bfe3f', 'les_f8e941fe2abb69', 2, 'Graph a system of inequalities and identify points in its solution region.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_075525a317db1a', 'les_f8e941fe2abb69', 3, 'Write a system of inequalities from a real situation with constraints.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_da85de6bfe489e', 'les_f8e941fe2abb69', 'learn', 1, 'definition', '{"term":"Linear inequality in two variables","body":"An inequality such as $y > 2x - 1$ or $3x + 4y \\le 12$. Its solutions are all the points on one side of the boundary line, a half-plane."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_acf9c81a7bfe3f', 'les_f8e941fe2abb69', 'learn', 2, 'text', '{"body":"To graph: draw the boundary line, solid if the symbol is $\\le$ or $\\ge$ (points on the line count) or dashed if it is $<$ or $>$. Then shade the side that contains solutions. In slope-intercept form, $y >$ or $y \\ge$ means shade above and $y <$ or $y \\le$ means shade below. You can always check with a test point such as $(0, 0)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_075525a317db1a', 'les_f8e941fe2abb69', 'learn', 3, 'worked_example', '{"title":"Graph $3x + 4y \\le 12$","steps":[{"latex":"y \\le -\\tfrac{3}{4}x + 3","explanation":"Solve for y."},{"latex":"\\text{solid line, slope } -\\tfrac{3}{4},\\ y\\text{-intercept } 3","explanation":"≤ means the line is included."},{"latex":"(0, 0): 0 \\le 12 \\text{ true}","explanation":"Test point: shade the side containing the origin, below the line."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ace8734f465fe1', 'les_f8e941fe2abb69', 'learn', 4, 'callout', '{"tone":"warning","title":"Dividing by a negative","body":"$-2y > 6x - 8$ becomes $y < -3x + 4$. Dividing by $-2$ reverses the symbol, which flips the shading from above to below."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_26977a4ee9de20', 'les_f8e941fe2abb69', 'learn', 5, 'definition', '{"term":"System of inequalities","body":"Its solutions are the points that satisfy every inequality: the region where all the shadings overlap."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3001e298df2862', 'les_f8e941fe2abb69', 'experiment', 6, 'activity', '{"activity":"systems-graph","title":"Overlap of two half-planes","params":{"m1":1,"b1":-2,"m2":-0.5,"b2":4,"s1":"above","s2":"below"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ac66f8fd7943a5', 'les_f8e941fe2abb69', 'experiment', 7, 'callout', '{"tone":"tip","title":"Try this","body":"The graph shows $y \\ge x - 2$ and $y \\le -\\frac{1}{2}x + 4$. The doubly shaded wedge is the solution region. Is $(0, 0)$ in it? Check both inequalities by hand. Then flip one shading and see how the region changes."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_05ad59342b2ab8', 'les_f8e941fe2abb69', 'learn', 8, 'worked_example', '{"title":"A club sells shirts (12 dollars profit) and hats (8 dollars profit). It can make at most 50 items and wants at least 480 dollars profit. Write the system.","steps":[{"latex":"s + h \\le 50","explanation":"Production limit."},{"latex":"12s + 8h \\ge 480","explanation":"Profit goal."},{"latex":"s \\ge 0,\\ h \\ge 0","explanation":"You can''t make negative items."}],"check":"$(30, 15)$ works: $45 \\le 50$ and $360 + 120 = 480 \\ge 480$. $(20, 20)$ does not: profit is only 400 dollars."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_94683bea2f7dca', 'les_f8e941fe2abb69', 'learn', 9, 'callout', '{"tone":"note","title":"Boundaries and corners","body":"A point on a dashed boundary is not a solution. The corners of a solution region, where boundary lines meet, become important in linear programming, where you find the best combination under constraints."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c1c24d8e756652', 'les_f8e941fe2abb69', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Diet plans (at least so much protein, at most so many calories), budgets, factory schedules and shipping limits are systems of inequalities. Any point in the region is a workable plan."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_da85de6bfe489e', 'les_f8e941fe2abb69', 1, 'practice', 'multiple_choice', 1, 'Which point is a solution of $y > 2x + 1$?', '{"choices":["$(0, 0)$","$(1, 3)$","$(-1, 2)$","$(2, 4)$"],"answer":2}', '["Substitute and check whether y is greater than 2x + 1."]', '$(-1, 2)$: $2 > 2(-1) + 1 = -1$ ✓. $(1, 3)$ gives $3 > 3$, which is false.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_acf9c81a7bfe3f', 'les_f8e941fe2abb69', 2, 'practice', 'multiple_choice', 2, 'How should $y \le -x + 3$ be graphed?', '{"choices":["Dashed line, shade above","Solid line, shade above","Solid line, shade below","Dashed line, shade below"],"answer":2}', '["≤ means the boundary is included.","y less than means below."]', 'Solid line (≤) with shading below.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_075525a317db1a', 'les_f8e941fe2abb69', 3, 'practice', 'multiple_choice', 2, 'Which inequality has a dashed boundary and shading above the line?', '{"choices":["$y \\ge 3x$","$y > 3x$","$y < 3x$","$y \\le 3x$"],"answer":1}', '["Strict inequality means dashed."]', '$y > 3x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ace8734f465fe1', 'les_f8e941fe2abb69', 4, 'practice', 'multiple_choice', 2, 'Which point is in the solution region of $y \ge x - 2$ and $y \le -\frac{1}{2}x + 4$?', '{"choices":["$(0, 5)$","$(6, 0)$","$(2, 1)$","$(-4, -7)$"],"answer":2}', '["Check each point in both inequalities."]', '$(2, 1)$: $1 \ge 0$ ✓ and $1 \le 3$ ✓. $(0, 5)$ fails the second, $(6, 0)$ fails the first, and $(-4, -7)$ fails the first.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_26977a4ee9de20', 'les_f8e941fe2abb69', 5, 'practice', 'multiple_choice', 2, 'Rewrite $-3y < 6x + 9$ in slope-intercept form.', '{"choices":["$y < -2x - 3$","$y > -2x - 3$","$y > 2x + 3$","$y < 2x + 3$"],"answer":1}', '["Divide every term by −3 and reverse the symbol."]', '$y > -2x - 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3001e298df2862', 'les_f8e941fe2abb69', 6, 'review', 'multiple_choice', 3, 'You have at most 40 dollars to spend on 5-dollar movie tickets (m) and 2-dollar snacks (s), and you want at least 3 tickets. Which system models this?', '{"choices":["$5m + 2s \\le 40,\\ m \\ge 3,\\ s \\ge 0$","$5m + 2s \\ge 40,\\ m \\le 3$","$m + s \\le 40,\\ m \\ge 3$","$2m + 5s \\le 40,\\ m \\ge 3,\\ s \\ge 0$"],"answer":0}', '["Total cost is 5m + 2s.","At most means ≤."]', '$5m + 2s \le 40$, $m \ge 3$ and $s \ge 0$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_f6b9a7607c0e90', 'subj_math', 'linear-inequalities-2var', 'Linear inequalities in two variables', 'Inequalities whose solutions form a half-plane bounded by a line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f8e941fe2abb69', (SELECT id FROM concepts WHERE slug = 'linear-inequalities-2var'));

-- Lesson: tables-graphs-patterns
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_fd7e36d577a716', 'tables-graphs-patterns', 'Tables, graphs and patterns', 'Describe a pattern with a rule, show the same relationship as a table, a graph and an equation, and use one representation to make predictions.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e5bf491c54f05d', 'les_fd7e36d577a716', 1, 'Identify independent and dependent variables in a situation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1a584f666c0642', 'les_fd7e36d577a716', 2, 'Write an equation from a table that grows by a constant amount.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4d1eab1ac70d07', 'les_fd7e36d577a716', 3, 'Graph a relationship from a table and use the graph or equation to predict values.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e5bf491c54f05d', 'les_fd7e36d577a716', 'learn', 1, 'text', '{"body":"Suppose a pool has 40 liters of water and a hose adds 15 liters each minute. You can describe this in words, in a table, as points on a graph, or with an equation. Each view makes a different question easy."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1a584f666c0642', 'les_fd7e36d577a716', 'learn', 2, 'definition', '{"term":"Independent and dependent variables","body":"The independent variable is the input you choose or control (minutes, here). The dependent variable is the output that depends on it (liters). By convention the independent variable goes on the horizontal axis."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4d1eab1ac70d07', 'les_fd7e36d577a716', 'learn', 3, 'worked_example', '{"title":"Build a table and an equation for the pool","steps":[{"latex":"\\begin{array}{c|c|c|c|c} t \\text{ (min)} & 0 & 1 & 2 & 3 \\\\ \\hline V \\text{ (L)} & 40 & 55 & 70 & 85 \\end{array}","explanation":"Start at 40 and add 15 each minute."},{"latex":"V = 40 + 15t","explanation":"The starting amount plus 15 for each minute."},{"latex":"V(20) = 40 + 15(20) = 340 \\text{ L}","explanation":"The equation predicts far-away values without extending the table."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7df1849b6e8625', 'les_fd7e36d577a716', 'learn', 4, 'text', '{"body":"When the outputs change by the same amount for each step of 1 in the input, the points lie on a straight line. That constant change is the rate of change, and it becomes the slope when you study linear functions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_57474986c86faa', 'les_fd7e36d577a716', 'experiment', 5, 'activity', '{"activity":"linear-graph","title":"See the pattern as a line","params":{"m":1.5,"b":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7af40f355ba58d', 'les_fd7e36d577a716', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Scaled down by 10, the pool is $y = 1.5x + 4$. Read off the y-values at $x = 0, 1, 2, 3$ and compare them with the table above, divided by 10. Which number in the equation sets where the line starts?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_870d34ac47e07a', 'les_fd7e36d577a716', 'learn', 7, 'worked_example', '{"title":"Find a rule for the table $x$: 1, 2, 3, 4 and $y$: 2, 5, 8, 11","steps":[{"latex":"\\Delta y = 3 \\text{ for each } \\Delta x = 1","explanation":"y goes up by 3 each time."},{"latex":"y = 3x + b","explanation":"The rule has the form 3x plus a starting value."},{"latex":"2 = 3(1) + b \\Rightarrow b = -1","explanation":"Use any row to find b."},{"latex":"y = 3x - 1","explanation":"Check: 3(4) − 1 = 11. ✓"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_022e1a5560e587', 'les_fd7e36d577a716', 'learn', 8, 'callout', '{"tone":"warning","title":"Not every pattern is linear","body":"The table $x$: 1, 2, 3, 4 with $y$: 2, 4, 8, 16 doubles each step instead of adding a fixed amount. Its points curve upward. Always check the differences before writing $y = mx + b$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_514c10c595086f', 'les_fd7e36d577a716', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Taxi fares, phone plans, savings with regular deposits and the height of a stack of cups all follow \"start + rate × steps.\" Spreadsheets build such tables automatically by filling a formula down a column."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e5bf491c54f05d', 'les_fd7e36d577a716', 1, 'practice', 'multiple_choice', 1, 'A plant grows taller each week. Which is the independent variable?', '{"choices":["Height","Number of weeks","The plant","The ruler"],"answer":1}', '["Which quantity do you choose, and which depends on it?"]', 'Height depends on how many weeks have passed, so weeks is the independent variable.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1a584f666c0642', 'les_fd7e36d577a716', 2, 'practice', 'numeric', 1, 'A pattern starts at 7 and adds 4 each step. What is the value at step 5, if step 0 is 7?', '{"answer":27}', '["7 + 4 · 5."]', '$7 + 4(5) = 27$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4d1eab1ac70d07', 'les_fd7e36d577a716', 3, 'practice', 'short_text', 2, 'Write an equation for the table $x$: 0, 1, 2, 3 and $y$: 5, 9, 13, 17. Use the form y=…', '{"accept":["y=4x+5","y=5+4x"]}', '["What is y when x = 0?","By how much does y change each step?"]', 'Start at 5 and add 4: $y = 4x + 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7df1849b6e8625', 'les_fd7e36d577a716', 4, 'practice', 'short_text', 2, 'Write an equation for the table $x$: 1, 2, 3, 4 and $y$: 1, −1, −3, −5.', '{"accept":["y=-2x+3","y=3-2x"]}', '["y decreases by 2 each step.","Use (1, 1) to find b."]', '$y = -2x + b$ and $1 = -2 + b$, so $b = 3$: $y = -2x + 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_57474986c86faa', 'les_fd7e36d577a716', 5, 'practice', 'numeric', 2, 'A tank holds 500 gallons and drains 12 gallons per minute. How many gallons remain after 25 minutes?', '{"answer":200,"unit":"gal"}', '["$V = 500 - 12t$."]', '$500 - 12(25) = 500 - 300 = 200$ gallons.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7af40f355ba58d', 'les_fd7e36d577a716', 6, 'practice', 'multiple_choice', 2, 'Which table could be described by a linear rule?', '{"choices":["$x$: 1, 2, 3, 4; $y$: 3, 6, 12, 24","$x$: 1, 2, 3, 4; $y$: 10, 7, 4, 1","$x$: 1, 2, 3, 4; $y$: 1, 4, 9, 16","$x$: 1, 2, 3, 4; $y$: 2, 3, 5, 8"],"answer":1}', '["Look for a constant difference in y."]', '10, 7, 4, 1 decreases by 3 each step: $y = -3x + 13$. The others have changing differences.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_870d34ac47e07a', 'les_fd7e36d577a716', 7, 'review', 'numeric', 3, 'Using $V = 40 + 15t$ for the pool, after how many minutes will it hold 250 liters?', '{"answer":14,"unit":"min"}', '["Solve $40 + 15t = 250$."]', '$15t = 210$, so $t = 14$ minutes.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_67d79e4caef3ff', 'subj_math', 'multiple-representations', 'Tables, graphs and equations', 'Three linked ways to show the same relationship between two variables.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_fd7e36d577a716', (SELECT id FROM concepts WHERE slug = 'multiple-representations'));

-- Lesson: two-way-frequency-tables
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_fbd93fca1bbf7f', 'two-way-frequency-tables', 'Two-way frequency tables', 'Organize two categorical variables in a two-way table, compute joint, marginal and conditional relative frequencies, and look for associations.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b651d73d9f7b57', 'les_fbd93fca1bbf7f', 1, 'Build a two-way frequency table and find marginal totals.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_10225c5b997c9a', 'les_fbd93fca1bbf7f', 2, 'Compute joint, marginal and conditional relative frequencies.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6de19b6e62c2ad', 'les_fbd93fca1bbf7f', 3, 'Use conditional relative frequencies to decide whether two categorical variables are associated.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b651d73d9f7b57', 'les_fbd93fca1bbf7f', 'learn', 1, 'text', '{"body":"Some data are categories, not numbers: grade level, favorite sport, yes or no. To study two categorical variables at once, count how many individuals fall in each combination and arrange the counts in a grid."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_10225c5b997c9a', 'les_fbd93fca1bbf7f', 'learn', 2, 'worked_example', '{"title":"A survey of 200 students: do they play a sport, and do they prefer morning or evening classes?","steps":[{"latex":"\\begin{array}{l|cc|c} & \\text{Morning} & \\text{Evening} & \\text{Total} \\\\ \\hline \\text{Sport} & 54 & 66 & 120 \\\\ \\text{No sport} & 26 & 54 & 80 \\\\ \\hline \\text{Total} & 80 & 120 & 200 \\end{array}","explanation":"Inner cells are joint frequencies; the totals are marginal frequencies."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6de19b6e62c2ad', 'les_fbd93fca1bbf7f', 'learn', 3, 'definition', '{"term":"Relative frequencies","body":"Joint: a cell divided by the grand total ($\\frac{54}{200} = 27\\%$ play a sport and prefer mornings). Marginal: a row or column total divided by the grand total ($\\frac{120}{200} = 60\\%$ play a sport). Conditional: a cell divided by its row or column total ($\\frac{54}{120} = 45\\%$ of athletes prefer mornings)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c469f49fe28dba', 'les_fbd93fca1bbf7f', 'learn', 4, 'text', '{"body":"Conditional relative frequencies answer \"among this group, what fraction…?\" They are the key to spotting an association. If the variables were unrelated, athletes and non-athletes would prefer mornings at about the same rate."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f943553885c4b9', 'les_fbd93fca1bbf7f', 'learn', 5, 'worked_example', '{"title":"Is there an association between playing a sport and class-time preference?","steps":[{"latex":"P(\\text{morning} \\mid \\text{sport}) = \\tfrac{54}{120} = 45\\%","explanation":"Among athletes."},{"latex":"P(\\text{morning} \\mid \\text{no sport}) = \\tfrac{26}{80} = 32.5\\%","explanation":"Among non-athletes."},{"latex":"45\\% \\ne 32.5\\%","explanation":"Athletes are more likely to prefer mornings, so there is an association in this sample."}],"check":"An association doesn''t prove that playing a sport causes the preference."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_131f3f84f91e3d', 'les_fbd93fca1bbf7f', 'learn', 6, 'callout', '{"tone":"warning","title":"Which total?","body":"\"What percent of athletes prefer mornings?\" divides by the athletes'' total (120). \"What percent of morning-preferring students are athletes?\" divides by the morning total (80): $\\frac{54}{80} = 67.5\\%$. The wording decides the denominator."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7aefd29be4bace', 'les_fbd93fca1bbf7f', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Medical studies compare outcome rates for treated and untreated groups, marketers compare purchase rates across age groups, and schools compare course choices by grade, all with two-way tables."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b651d73d9f7b57', 'les_fbd93fca1bbf7f', 1, 'practice', 'numeric', 1, 'Using the survey table, how many students prefer evening classes?', '{"answer":120}', '["Look at the column total."]', '120.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_10225c5b997c9a', 'les_fbd93fca1bbf7f', 2, 'practice', 'numeric', 2, 'What percent of all students do not play a sport and prefer evening classes? Enter just the number.', '{"answer":27,"unit":"%"}', '["$\\frac{54}{200}$."]', '$54 \div 200 = 0.27 = 27\%$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6de19b6e62c2ad', 'les_fbd93fca1bbf7f', 3, 'practice', 'numeric', 2, 'What percent of non-athletes prefer evening classes? Enter just the number.', '{"answer":67.5,"unit":"%"}', '["Divide by the non-athletes'' total, 80."]', '$54 \div 80 = 67.5\%$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c469f49fe28dba', 'les_fbd93fca1bbf7f', 4, 'practice', 'numeric', 2, 'What percent of students who prefer evening classes play a sport? Enter just the number.', '{"answer":55,"unit":"%"}', '["Divide by the evening total, 120."]', '$66 \div 120 = 55\%$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f943553885c4b9', 'les_fbd93fca1bbf7f', 5, 'review', 'multiple_choice', 3, 'In a survey, 30% of 7th graders and 31% of 8th graders chose soccer as their favorite sport. What does this suggest?', '{"choices":["A strong association between grade and choosing soccer","Little or no association between grade and choosing soccer","8th grade causes soccer preference","The survey is wrong"],"answer":1}', '["Compare the conditional percentages."]', 'The conditional percentages are nearly equal, so grade and choosing soccer appear unrelated in this sample.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_131f3f84f91e3d', 'les_fbd93fca1bbf7f', 6, 'review', 'numeric', 3, 'In a group, 40 of 100 adults own a cat. Of the cat owners, 25 also own a dog; of the others, 30 own a dog. What percent of dog owners also own a cat? Round to the nearest tenth.', '{"answer":45.5,"unit":"%","tolerance":0.05}', '["Dog owners: 25 + 30 = 55.","Divide the 25 cat-and-dog owners by 55."]', '$25 \div 55 \approx 45.5\%$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_3e508a972ac4cd', 'subj_math', 'two-way-tables', 'Two-way tables', 'Tables that summarize two categorical variables and their relationship.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_fbd93fca1bbf7f', (SELECT id FROM concepts WHERE slug = 'two-way-tables'));

-- Lesson: unit-rates
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_966bed718638c0', 'unit-rates', 'Unit rates and unit pricing', 'Find unit rates, including rates with fractions, and use unit prices to compare deals.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0060ac37639d0c', 'les_966bed718638c0', 1, 'Distinguish a rate from a ratio and find a unit rate.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a180f818613a20', 'les_966bed718638c0', 2, 'Compute unit rates involving fractions and decimals.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b24ecec3ace2f9', 'les_966bed718638c0', 3, 'Use unit prices to decide which option is the better buy.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0060ac37639d0c', 'les_966bed718638c0', 'learn', 1, 'definition', '{"term":"Rate","body":"A ratio that compares two quantities measured in different units, such as 150 miles per 3 hours or 4 dollars for 5 pounds."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a180f818613a20', 'les_966bed718638c0', 'learn', 2, 'definition', '{"term":"Unit rate","body":"A rate with a denominator of 1 unit. Divide the first quantity by the second: $\\frac{150 \\text{ mi}}{3 \\text{ h}} = 50$ miles per hour."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b24ecec3ace2f9', 'les_966bed718638c0', 'learn', 3, 'text', '{"body":"Unit rates make comparisons easy because everything is measured \"per one.\" Unit price, the cost per ounce or per item, is the unit rate stores use to compare packages of different sizes."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_39d65b076549c6', 'les_966bed718638c0', 'learn', 4, 'worked_example', '{"title":"Which is the better buy: 18 oz of cereal for 4.29 dollars, or 26 oz for 5.99 dollars?","steps":[{"latex":"\\frac{4.29}{18} \\approx 0.238 \\text{ dollars/oz}","explanation":"Unit price of the small box."},{"latex":"\\frac{5.99}{26} \\approx 0.230 \\text{ dollars/oz}","explanation":"Unit price of the large box."},{"latex":"0.230 < 0.238","explanation":"The 26-oz box costs less per ounce."}],"check":"The large box is the better buy by about 0.8 cents per ounce, as long as you will use it all."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_69c14d4a623b68', 'les_966bed718638c0', 'learn', 5, 'worked_example', '{"title":"A painter covers $\\frac{3}{4}$ of a wall in $\\frac{1}{2}$ hour. How much wall does she paint per hour?","steps":[{"latex":"\\frac{3/4}{1/2} = \\frac{3}{4} \\div \\frac{1}{2}","explanation":"Divide the amount of wall by the time."},{"latex":"= \\frac{3}{4} \\cdot 2 = \\frac{3}{2}","explanation":"Multiply by the reciprocal."},{"latex":"1\\tfrac{1}{2} \\text{ walls per hour}","explanation":""}],"check":"Check: in half an hour she would paint half of $1\\frac{1}{2}$, which is $\\frac{3}{4}$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_010abda6e1763e', 'les_966bed718638c0', 'experiment', 6, 'activity', '{"activity":"ratio-line","title":"Read a unit rate","params":{"a":4,"b":10,"k":0.25}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3552a8e7304e64', 'les_966bed718638c0', 'experiment', 7, 'callout', '{"tone":"tip","title":"Try this","body":"The base ratio is 4 pounds for 10 dollars. Slide the scale factor to 0.25. What price goes with 1 pound? That is the unit price. Now find the price of 7 pounds."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_601e2b53795f66', 'les_966bed718638c0', 'learn', 8, 'callout', '{"tone":"warning","title":"Which way to divide?","body":"\"Dollars per pound\" means dollars ÷ pounds. \"Pounds per dollar\" means pounds ÷ dollars. Both are unit rates, but they answer different questions. Read the units in the question."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a81795fa1f8595', 'les_966bed718638c0', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Speed (miles per hour), fuel economy (miles per gallon), wages (dollars per hour), heart rate (beats per minute) and data plans (dollars per gigabyte) are all unit rates."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0060ac37639d0c', 'les_966bed718638c0', 1, 'practice', 'numeric', 1, 'A car travels 210 miles in 3.5 hours. What is its average speed in miles per hour?', '{"answer":60,"unit":"mph"}', '["Divide miles by hours."]', '$210 \div 3.5 = 60$ mph.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a180f818613a20', 'les_966bed718638c0', 2, 'practice', 'numeric', 1, 'A 12-pack of water costs 4.20 dollars. What is the price per bottle, in dollars?', '{"answer":0.35,"unit":"dollars"}', '["Divide the cost by 12."]', '$4.20 \div 12 = 0.35$ dollars.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b24ecec3ace2f9', 'les_966bed718638c0', 3, 'practice', 'multiple_choice', 2, 'Which is the better buy?', '{"choices":["5 lb of apples for 6.45 dollars","3 lb of apples for 3.99 dollars","They cost the same per pound","Not enough information"],"answer":0}', '["Find the price per pound for each."]', '$6.45 \div 5 = 1.29$ and $3.99 \div 3 = 1.33$ dollars per pound. The 5-lb bag is cheaper per pound.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_39d65b076549c6', 'les_966bed718638c0', 4, 'practice', 'numeric', 2, 'Maria earns 93.50 dollars for 8.5 hours of work. What is her hourly wage, in dollars?', '{"answer":11,"unit":"dollars/h"}', '["Divide pay by hours."]', '$93.50 \div 8.5 = 11$ dollars per hour.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_69c14d4a623b68', 'les_966bed718638c0', 5, 'practice', 'numeric', 2, 'A snail moves $\frac{2}{5}$ of a meter in $\frac{2}{3}$ of a minute. What is its speed in meters per minute? Enter a decimal or a fraction.', '{"answer":0.6}', '["$\\frac{2}{5} \\div \\frac{2}{3}$."]', '$\frac{2}{5} \cdot \frac{3}{2} = \frac{6}{10} = \frac{3}{5} = 0.6$ m per minute.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_010abda6e1763e', 'les_966bed718638c0', 6, 'practice', 'numeric', 2, 'A printer prints 45 pages in 3 minutes. At that rate, how many pages does it print in 20 minutes?', '{"answer":300}', '["Find pages per minute first."]', '$45 \div 3 = 15$ pages per minute, and $15 \times 20 = 300$ pages.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3552a8e7304e64', 'les_966bed718638c0', 7, 'review', 'numeric', 3, 'A 64-oz jug of juice costs 3.84 dollars and a 48-oz jug costs 3.12 dollars. How many cents per ounce do you save by buying the 64-oz jug?', '{"answer":0.5,"unit":"cents"}', '["Find each unit price in cents.","$384 \\div 64$ and $312 \\div 48$."]', '$384 \div 64 = 6$ cents/oz and $312 \div 48 = 6.5$ cents/oz. You save $0.5$ cents per ounce.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_601e2b53795f66', 'les_966bed718638c0', 8, 'review', 'numeric', 3, 'A faucet fills a 5-gallon bucket in 1 minute 15 seconds. What is the flow rate in gallons per minute?', '{"answer":4,"unit":"gal/min"}', '["1 minute 15 seconds is 1.25 minutes."]', '$5 \div 1.25 = 4$ gallons per minute.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9f864f42cd5917', 'subj_math', 'unit-rate', 'Unit rate', 'A rate expressed per one unit of the second quantity.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_966bed718638c0', (SELECT id FROM concepts WHERE slug = 'unit-rate'));

-- Lesson: volume-prisms-cylinders
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0b89e3b7911f41', 'volume-prisms-cylinders', 'Volume of prisms and cylinders', 'Find the volume of prisms and cylinders as base area times height, find surface area, and solve for a missing dimension.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5b0a5c531c994e', 'les_0b89e3b7911f41', 1, 'Explain volume as layers of unit cubes and use V = Bh.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3ba2d9b39d51b3', 'les_0b89e3b7911f41', 2, 'Find the volume and surface area of rectangular prisms, triangular prisms and cylinders.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7b07e583215091', 'les_0b89e3b7911f41', 3, 'Solve for a missing dimension and convert between capacity units.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5b0a5c531c994e', 'les_0b89e3b7911f41', 'learn', 1, 'definition', '{"term":"Volume","body":"The amount of space a solid occupies, measured in cubic units such as cm³ or ft³."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3ba2d9b39d51b3', 'les_0b89e3b7911f41', 'learn', 2, 'text', '{"body":"A prism has two identical parallel bases joined by flat sides. Fill the bottom with one layer of unit cubes: the number of cubes in the layer equals the base area $B$. Stack $h$ layers to reach the top, and the volume is $V = Bh$. A cylinder works the same way with a circular base, so $V = \\pi r^2 h$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7b07e583215091', 'les_0b89e3b7911f41', 'experiment', 3, 'activity', '{"activity":"area-volume","title":"Volume of a prism","params":{"shape":"prism"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9158db59188365', 'les_0b89e3b7911f41', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Double the height of the prism. What happens to the volume? Now double the width instead. Then switch to the cylinder and double the radius. Why does that change the volume more?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fdff54cae2d2ec', 'les_0b89e3b7911f41', 'learn', 5, 'worked_example', '{"title":"A rectangular prism is 8 cm long, 5 cm wide and 3 cm tall. Find its volume and surface area.","steps":[{"latex":"V = 8 \\cdot 5 \\cdot 3 = 120 \\text{ cm}^3","explanation":"Base area 40 times height 3."},{"latex":"S = 2(8 \\cdot 5) + 2(8 \\cdot 3) + 2(5 \\cdot 3)","explanation":"Surface area: six faces in three matching pairs."},{"latex":"S = 80 + 48 + 30 = 158 \\text{ cm}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e53902fb145113', 'les_0b89e3b7911f41', 'learn', 6, 'worked_example', '{"title":"A triangular prism has a right-triangle base with legs 6 in and 8 in, and the prism is 10 in long. Find its volume.","steps":[{"latex":"B = \\tfrac{1}{2}(6)(8) = 24 \\text{ in}^2","explanation":"The base is the triangle."},{"latex":"V = Bh = 24 \\cdot 10 = 240 \\text{ in}^3","explanation":"The ''height'' of the prism is its length between the triangles."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_74123b141df3c3', 'les_0b89e3b7911f41', 'learn', 7, 'worked_example', '{"title":"A cylindrical can has radius 4 cm and height 12 cm. Find its volume and how many milliliters it holds.","steps":[{"latex":"V = \\pi(4)^2(12) = 192\\pi \\approx 603.19 \\text{ cm}^3","explanation":""},{"latex":"1 \\text{ cm}^3 = 1 \\text{ mL} \\Rightarrow \\approx 603 \\text{ mL}","explanation":"Metric volume and capacity line up neatly."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c9b13b7abdba5c', 'les_0b89e3b7911f41', 'learn', 8, 'worked_example', '{"title":"A cylinder has volume $500\\pi$ m³ and radius 5 m. Find its height.","steps":[{"latex":"500\\pi = \\pi(5)^2 h = 25\\pi h","explanation":""},{"latex":"h = 500\\pi \\div 25\\pi = 20 \\text{ m}","explanation":"Divide both sides by 25π."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e5fcc0864105c3', 'les_0b89e3b7911f41', 'learn', 9, 'callout', '{"tone":"warning","title":"Square units vs cubic units","body":"Surface area covers the outside and is measured in square units. Volume fills the inside and is measured in cubic units. Doubling every dimension multiplies surface area by 4 and volume by 8."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7743dfda50ce45', 'les_0b89e3b7911f41', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Shipping boxes, fish tanks (1 L = 1000 cm³), concrete for a patio (ordered in cubic yards), water tanks and soda cans all use these formulas."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5b0a5c531c994e', 'les_0b89e3b7911f41', 1, 'practice', 'numeric', 1, 'Find the volume of a box 6 in by 4 in by 10 in.', '{"answer":240,"unit":"in³"}', '["Multiply the three dimensions."]', '$6 \cdot 4 \cdot 10 = 240$ in³.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3ba2d9b39d51b3', 'les_0b89e3b7911f41', 2, 'practice', 'numeric', 1, 'A prism has base area 18 cm² and height 7 cm. What is its volume?', '{"answer":126,"unit":"cm³"}', '["$V = Bh$."]', '$18 \cdot 7 = 126$ cm³.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7b07e583215091', 'les_0b89e3b7911f41', 3, 'practice', 'numeric', 2, 'Find the volume of a cylinder with radius 3 ft and height 5 ft. Round to the nearest hundredth.', '{"answer":141.37,"unit":"ft³","tolerance":0.01}', '["$\\pi(3)^2(5) = 45\\pi$."]', '$45\pi \approx 141.37$ ft³.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9158db59188365', 'les_0b89e3b7911f41', 4, 'practice', 'numeric', 2, 'Find the surface area of a cube with edge 5 m.', '{"answer":150,"unit":"m²"}', '["A cube has six square faces."]', '$6 \cdot 5^2 = 150$ m².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fdff54cae2d2ec', 'les_0b89e3b7911f41', 5, 'practice', 'numeric', 2, 'A fish tank is 60 cm long, 30 cm wide and 40 cm tall. How many liters does it hold? (1 L = 1000 cm³)', '{"answer":72,"unit":"L"}', '["Find the volume in cm³ first."]', '$60 \cdot 30 \cdot 40 = 72{,}000$ cm³ $= 72$ L.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e53902fb145113', 'les_0b89e3b7911f41', 6, 'practice', 'numeric', 3, 'A rectangular prism has volume 336 cm³, length 8 cm and width 6 cm. What is its height?', '{"answer":7,"unit":"cm"}', '["$336 = 8 \\cdot 6 \\cdot h$."]', '$48h = 336$, so $h = 7$ cm.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_74123b141df3c3', 'les_0b89e3b7911f41', 7, 'review', 'multiple_choice', 3, 'Cylinder A has radius 2 and height 6. Cylinder B has radius 3 and height 3. Which holds more?', '{"choices":["A","B","They are equal","Not enough information"],"answer":1}', '["Compute $\\pi r^2 h$ for each."]', 'A: $\pi \cdot 4 \cdot 6 = 24\pi$. B: $\pi \cdot 9 \cdot 3 = 27\pi$. B holds more, because the radius is squared.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c9b13b7abdba5c', 'les_0b89e3b7911f41', 8, 'review', 'numeric', 3, 'A triangular prism has a triangular base with base 5 m and height 4 m. The prism is 9 m long. Find its volume.', '{"answer":90,"unit":"m³"}', '["$B = \\frac{1}{2}(5)(4)$."]', '$B = 10$ m², so $V = 10 \cdot 9 = 90$ m³.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d387fc8d57b2e3', 'subj_math', 'volume', 'Volume', 'The number of unit cubes needed to fill a solid.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0b89e3b7911f41', (SELECT id FROM concepts WHERE slug = 'volume'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0b89e3b7911f41', (SELECT id FROM formulas WHERE slug = 'prism-cylinder-volume'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0b89e3b7911f41', (SELECT id FROM formulas WHERE slug = 'circle-area'), 2);

-- Lesson: writing-graphing-inequalities
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7b9054216b197c', 'writing-graphing-inequalities', 'Writing and graphing inequalities', 'Translate situations into inequalities, graph them on a number line with open and closed circles, and test whether values are solutions.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e242b68d904241', 'les_7b9054216b197c', 1, 'Read and write the symbols <, >, ≤ and ≥ and translate phrases such as ''at least'' and ''no more than''.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6587233f502cf6', 'les_7b9054216b197c', 2, 'Graph an inequality on a number line using an open or closed circle and a ray.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8331f4d82aea4f', 'les_7b9054216b197c', 3, 'Decide whether a value is a solution by substitution.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e242b68d904241', 'les_7b9054216b197c', 'learn', 1, 'text', '{"body":"An equation like $x = 3$ has one solution. But many situations allow a whole range of values: you must be at least 48 inches tall to ride, or a bag can hold no more than 23 kg. An inequality describes a range like this, and it usually has infinitely many solutions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6587233f502cf6', 'les_7b9054216b197c', 'learn', 2, 'definition', '{"term":"Inequality symbols","body":"$x < a$: $x$ is less than $a$. $x > a$: greater than. $x \\le a$: less than or equal to (at most, no more than). $x \\ge a$: greater than or equal to (at least, no less than)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8331f4d82aea4f', 'les_7b9054216b197c', 'learn', 3, 'text', '{"body":"To graph an inequality, draw a circle at the boundary value and shade the side that contains the solutions. An open circle means the boundary is not included ($<$ or $>$). A closed, filled-in circle means it is included ($\\le$ or $\\ge$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_468dd567668678', 'les_7b9054216b197c', 'experiment', 4, 'activity', '{"activity":"inequality-line","title":"Graph an inequality","params":{"rel":"≥","c":-2,"mode":"single"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bf26c73daaa6ea', 'les_7b9054216b197c', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Switch between $\\ge$ and $>$ and watch the circle at the boundary. Then move the test value to the boundary itself. When is the boundary a solution?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_327e4d61de0981', 'les_7b9054216b197c', 'learn', 6, 'worked_example', '{"title":"Write and graph: \"You must be at least 16 to drive.\"","steps":[{"latex":"a \\ge 16","explanation":"At least means 16 or more, so the boundary is included."},{"latex":"\\text{closed circle at 16, shade right}","explanation":"All ages 16 and up."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_226ad41a2db995', 'les_7b9054216b197c', 'learn', 7, 'worked_example', '{"title":"Is $x = -3$ a solution of $2x + 5 < 0$?","steps":[{"latex":"2(-3) + 5 = -1","explanation":"Substitute."},{"latex":"-1 < 0 \\text{ is true}","explanation":"So −3 is a solution."}],"check":"Try $x = 0$: $5 < 0$ is false, so 0 is not a solution."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a87d0a6c726f7e', 'les_7b9054216b197c', 'learn', 8, 'callout', '{"tone":"warning","title":"Reading inequalities backwards","body":"$5 > x$ means the same as $x < 5$. Read the inequality with the variable first to see which way to shade: the symbol always points to the smaller side."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1b2ea1c191bc76', 'les_7b9054216b197c', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Speed limits ($s \\le 65$), elevator capacity, minimum order amounts for free shipping ($c \\ge 35$), and safe temperature ranges are all inequalities."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e242b68d904241', 'les_7b9054216b197c', 1, 'practice', 'multiple_choice', 1, 'Which inequality means "$x$ is no more than 12"?', '{"choices":["$x < 12$","$x \\le 12$","$x > 12$","$x \\ge 12$"],"answer":1}', '["\"No more than\" allows 12 itself."]', '$x \le 12$: twelve or less.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6587233f502cf6', 'les_7b9054216b197c', 2, 'practice', 'multiple_choice', 1, 'A graph shows an open circle at 4 with shading to the left. Which inequality does it show?', '{"choices":["$x \\le 4$","$x > 4$","$x < 4$","$x \\ge 4$"],"answer":2}', '["An open circle excludes the boundary.","Left means smaller values."]', '$x < 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8331f4d82aea4f', 'les_7b9054216b197c', 3, 'practice', 'multiple_choice', 2, 'Which value is a solution of $x \ge -1.5$?', '{"choices":["$-2$","$-1.6$","$-1.5$","$-3$"],"answer":2}', '["Is the boundary included?"]', '$\ge$ includes the boundary, so $-1.5$ is a solution. The others are less than $-1.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_468dd567668678', 'les_7b9054216b197c', 4, 'practice', 'short_text', 2, 'Write an inequality: "A suitcase must weigh less than 50 pounds." Use w for weight.', '{"accept":["w<50","50>w"]}', '["Less than does not include 50."]', '$w < 50$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bf26c73daaa6ea', 'les_7b9054216b197c', 5, 'practice', 'short_text', 2, 'Write an inequality: "You need at least 85 points to earn an A." Use p for points.', '{"accept":["p>=85","p≥85","85<=p","85≤p"]}', '["At least includes 85."]', '$p \ge 85$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_327e4d61de0981', 'les_7b9054216b197c', 6, 'practice', 'multiple_choice', 2, 'Is $x = 4$ a solution of $3x - 7 > 5$?', '{"choices":["Yes, because 3(4) − 7 = 5 and 5 > 5","No, because 5 > 5 is false","Yes, because 4 > 5","No, because 3(4) − 7 = 19"],"answer":1}', '["Substitute and decide whether the statement is true."]', '$3(4) - 7 = 5$, and $5 > 5$ is false, so 4 is not a solution. (It would be a solution of $3x - 7 \ge 5$.)');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_226ad41a2db995', 'les_7b9054216b197c', 7, 'review', 'short_text', 3, 'Rewrite $-7 \le x$ with $x$ on the left.', '{"accept":["x>=-7","x≥-7"]}', '["Flip the whole statement around, including the symbol."]', '$x \ge -7$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_19625de39ac5f9', 'subj_math', 'inequalities', 'Inequalities', 'Statements that compare quantities using <, >, ≤ or ≥.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7b9054216b197c', (SELECT id FROM concepts WHERE slug = 'inequalities'));

-- Lesson: zero-negative-exponents
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0eb0d9839934bb', 'zero-negative-exponents', 'Zero and negative exponents', 'Understand why a⁰ = 1 and a⁻ⁿ = 1/aⁿ, simplify expressions with negative exponents, and write small numbers in scientific notation.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_727ed6164549b3', 'les_0eb0d9839934bb', 1, 'Justify the definitions of zero and negative exponents using the quotient rule and patterns.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d2c8ff515d28d4', 'les_0eb0d9839934bb', 2, 'Rewrite expressions with only positive exponents.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_89a1b7f6fec5db', 'les_0eb0d9839934bb', 3, 'Use negative exponents in scientific notation for very small numbers.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_727ed6164549b3', 'les_0eb0d9839934bb', 'learn', 1, 'text', '{"body":"What should $5^0$ mean? You can''t multiply zero 5s together. Look at a pattern instead: $5^3 = 125$, $5^2 = 25$, $5^1 = 5$. Each time the exponent drops by 1 you divide by 5. Continuing gives $5^0 = 1$, $5^{-1} = \\frac{1}{5}$ and $5^{-2} = \\frac{1}{25}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d2c8ff515d28d4', 'les_0eb0d9839934bb', 'learn', 2, 'text', '{"body":"The quotient rule agrees. $\\frac{x^4}{x^4} = 1$, and also $\\frac{x^4}{x^4} = x^{4-4} = x^0$, so $x^0 = 1$. Likewise $\\frac{x^2}{x^5} = \\frac{1}{x^3}$, and the rule gives $x^{2-5} = x^{-3}$, so $x^{-3} = \\frac{1}{x^3}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_89a1b7f6fec5db', 'les_0eb0d9839934bb', 'learn', 3, 'definition', '{"term":"Zero exponent","body":"$a^0 = 1$ for any $a \\ne 0$. ($0^0$ is left undefined in algebra.)"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7afd6388eb53ea', 'les_0eb0d9839934bb', 'learn', 4, 'definition', '{"term":"Negative exponent","body":"$a^{-n} = \\dfrac{1}{a^n}$ and $\\dfrac{1}{a^{-n}} = a^n$ for $a \\ne 0$. A negative exponent means reciprocal, not a negative number."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_158eefb03d1cf7', 'les_0eb0d9839934bb', 'learn', 5, 'worked_example', '{"title":"Evaluate $4^{-2}$, $(-2)^{-3}$ and $\\left(\\frac{2}{3}\\right)^{-2}$","steps":[{"latex":"4^{-2} = \\tfrac{1}{16}","explanation":""},{"latex":"(-2)^{-3} = \\tfrac{1}{(-2)^3} = -\\tfrac{1}{8}","explanation":"The sign comes from the base, not the exponent."},{"latex":"\\left(\\tfrac{2}{3}\\right)^{-2} = \\left(\\tfrac{3}{2}\\right)^2 = \\tfrac{9}{4}","explanation":"Flip the fraction and make the exponent positive."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6fe5827435b5e2', 'les_0eb0d9839934bb', 'learn', 6, 'worked_example', '{"title":"Simplify $\\dfrac{6x^{-2}y^3}{2x^4y^{-1}}$ with positive exponents","steps":[{"latex":"3x^{-2-4}y^{3-(-1)}","explanation":"Divide coefficients and subtract exponents."},{"latex":"3x^{-6}y^4 = \\dfrac{3y^4}{x^6}","explanation":"Only x⁻⁶ moves to the denominator; the 3 stays."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_82a5aff8af4f7a', 'les_0eb0d9839934bb', 'learn', 7, 'callout', '{"tone":"warning","title":"What moves?","body":"In $3x^{-2}$, only $x$ has the negative exponent: $3x^{-2} = \\frac{3}{x^2}$. But $(3x)^{-2} = \\frac{1}{9x^2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4b35661b4658ad', 'les_0eb0d9839934bb', 'learn', 8, 'worked_example', '{"title":"Write 0.000 042 in scientific notation","steps":[{"latex":"4.2 \\times 10^{-5}","explanation":"Move the decimal 5 places right to get 4.2; the number is small, so the exponent is negative."}],"check":"Check: $4.2 \\times 10^{-5} = 4.2 \\times \\frac{1}{100{,}000} = 0.000042$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_071b4c3e9c432b', 'les_0eb0d9839934bb', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"A red blood cell is about $8 \\times 10^{-6}$ m across and a hydrogen atom about $1 \\times 10^{-10}$ m. Computer memory uses powers of 2, and decibels and pH use negative powers of 10."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_727ed6164549b3', 'les_0eb0d9839934bb', 1, 'practice', 'numeric', 1, 'Evaluate $7^0$.', '{"answer":1}', '["Any nonzero number to the zero power."]', '$7^0 = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d2c8ff515d28d4', 'les_0eb0d9839934bb', 2, 'practice', 'numeric', 1, 'Evaluate $2^{-3}$. Enter a fraction or decimal.', '{"answer":0.125}', '["$2^{-3} = \\frac{1}{2^3}$."]', '$\frac{1}{8} = 0.125$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_89a1b7f6fec5db', 'les_0eb0d9839934bb', 3, 'practice', 'numeric', 2, 'Evaluate $\left(\frac{1}{5}\right)^{-2}$.', '{"answer":25}', '["Flip the base."]', '$5^2 = 25$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7afd6388eb53ea', 'les_0eb0d9839934bb', 4, 'practice', 'short_text', 2, 'Write $x^{-4}y^2$ with positive exponents. Use the format y^2/x^4.', '{"accept":["y^2/x^4"]}', '["Only $x^{-4}$ moves."]', '$\frac{y^2}{x^4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_158eefb03d1cf7', 'les_0eb0d9839934bb', 5, 'practice', 'short_text', 2, 'Simplify $\dfrac{a^3}{a^{-2}}$.', '{"accept":["a^5"]}', '["$3 - (-2) = 5$."]', '$a^5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6fe5827435b5e2', 'les_0eb0d9839934bb', 6, 'practice', 'multiple_choice', 2, 'Which is equal to $5x^{-3}$?', '{"choices":["$\\frac{1}{5x^3}$","$\\frac{5}{x^3}$","$-5x^3$","$-15x$"],"answer":1}', '["Only x has the negative exponent."]', '$\frac{5}{x^3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_82a5aff8af4f7a', 'les_0eb0d9839934bb', 7, 'practice', 'numeric', 2, 'Write $3.7 \times 10^{-4}$ in standard form.', '{"answer":0.00037,"relative":true,"tolerance":1e-9}', '["Move the decimal 4 places left."]', '$0.00037$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4b35661b4658ad', 'les_0eb0d9839934bb', 8, 'review', 'short_text', 3, 'Simplify $(2m^{-3}n^2)^{-2}$ with positive exponents. Use the format m^6/(4n^4).', '{"accept":["m^6/(4n^4)","m^6/4n^4"]}', '["Multiply each exponent by −2: $2^{-2}m^6n^{-4}$."]', '$\frac{m^6}{4n^4}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1f00e6e426f079', 'subj_math', 'exponent-rules', 'Exponent rules', 'Product, quotient and power rules for simplifying powers.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0eb0d9839934bb', (SELECT id FROM concepts WHERE slug = 'exponent-rules'));
